window.APP_DATA = window.APP_DATA || {};
window.APP_DATA.idioms = [
  // Grade 1-6 (70條 — 低年級常用，淺白易懂)
  { id: "i001", grade: 1, term: "一心一意", zhuyin: "ㄧ ㄒㄧㄣ ㄧ ㄧˋ", pinyin: "yī xīn yī yì", meaning: "心思專注不變，完全投入。", example: "他一心一意要成為籃球選手。", misuse: "不是指只有一顆心。" , wordExp: "一心＝一個心思；一意＝一個念頭。心思念頭都只有一個，就是專注。",deep:"典故由來：由字面組合而成，無特定典故；「一心」「一意」都指同一個心思。\n字面意思：一個心、一個念頭。\n引申意思：心思專注不變、全心投入（如：他一心一意準備比賽）。褒義；相對詞是「三心二意」。" },
  { id: "i002", grade: 1, term: "千里馬", zhuyin: "ㄑㄧㄢ ㄌㄧˇ ㄇㄚˇ", pinyin: "qiān lǐ mǎ", meaning: "比喻有才能的人。", example: "他是家族的千里馬，前途無限。" , wordExp: "千里＝一天能跑千里；馬＝良馬。跑得極遠的好馬，借指難得的人才。",deep:"典故由來：出自韓愈〈馬說〉：「世有伯樂，然後有千里馬。千里馬常有，而伯樂不常有。」另《戰國策．燕策》有燕昭王「千金買馬骨」求千里馬的故事。\n字面意思：一天能跑千里的良馬。\n引申意思：比喻有才能的人（如：他是公司裡的千里馬）；常與「伯樂」（善於發掘人才的人）連用。" },
  { id: "i003", grade: 1, term: "兩手空空", zhuyin: "ㄌㄧㄤˇ ㄕㄡˇ ㄎㄨㄥ ㄎㄨㄥ", pinyin: "liǎng shǒu kōng kōng", meaning: "指什麼都沒有，一無所有。", example: "他離開公司時兩手空空，什麼都沒帶走。" , wordExp: "兩手＝雙手；空空＝什麼都沒有。雙手空無一物。",deep:"典故由來：由字面組合而成，無特定典故。\n字面意思：兩隻手裡什麼都沒有。\n引申意思：一無所有，或沒帶任何東西（如：他兩手空空地回來了）。可指沒錢財，也可指沒成果。" },
  { id: "i004", grade: 1, term: "三心二意", zhuyin: "ㄙㄢ ㄒㄧㄣ ㄦˋ ㄧˋ", pinyin: "sān xīn èr yì", meaning: "心思不定，搖擺不決。", example: "讀書時不要三心二意，要專心。", misuse: "常被誤解為只是不認真而非猶豫不決。" , wordExp: "三、二＝形容多而雜；心、意＝心思念頭。心思一下三個一下兩個，拿不定主意。",deep:"典故由來：元曲中已常見的口語成語，由字面組合而成。\n字面意思：三個心、兩個意，心思分成好幾份。\n引申意思：心思不定、猶豫不決，或做事不專心（如：上課三心二意，什麼都學不好）。貶義；相對詞是「一心一意」。" },
  { id: "i005", grade: 1, term: "十全十美", zhuyin: "ㄕˊ ㄑㄩㄢˊ ㄕˊ ㄇㄟˇ", pinyin: "shí quán shí měi", meaning: "完美無缺，沒有任何缺點。", example: "這部電影十全十美，獲得許多大獎。" , wordExp: "十全＝十分完備；十美＝十分美好。樣樣齊全、樣樣美好。",deep:"典故由來：「十全」出自《周禮．天官》：醫師治病「十全為上」，十次全治好是最高等的醫術。\n字面意思：十項全部完美。\n引申意思：完美無缺，沒有任何缺點（如：世上沒有十全十美的人）。常用於提醒不必苛求完美。" },
  { id: "i006", grade: 1, term: "大同小異", zhuyin: "ㄉㄚˋ ㄊㄨㄥˊ ㄒㄧㄠˇ ㄧˋ", pinyin: "dà tóng xiǎo yì", meaning: "差不多，只有細微差別。", example: "各家的做法大同小異，效果都不錯。" , wordExp: "大同＝大部分相同；小異＝小部分不同。大體一樣，只差一點點。",deep:"典故由來：出自《莊子．天下》：「大同而與小同異，此之謂小同異。」原是名家惠施討論事物同異的命題。\n字面意思：大部分相同，小部分有差異。\n引申意思：兩件事物差不多、沒有本質差別（如：這兩個方案大同小異）。" },
  { id: "i007", grade: 1, term: "火冒三丈", zhuyin: "ㄏㄨㄛˇ ㄇㄠˋ ㄙㄢ ㄓㄤˋ", pinyin: "huǒ mào sān zhàng", meaning: "非常生氣，怒火中燒。", example: "聽到這個消息，他氣得火冒三丈。", misuse: "不是真的冒火，是比喻非常生氣。" , wordExp: "火冒＝怒火往上冒；三丈＝約九公尺高。怒氣像火一樣冒到三丈高。",deep:"典故由來：近代口語組合成語，無特定典故；「三丈」極言火氣之高。\n字面意思：怒火往上冒了三丈高。\n引申意思：形容非常生氣（如：聽到謊話，他氣得火冒三丈）。" },
  { id: "i008", grade: 1, term: "畫龍點睛", zhuyin: "ㄏㄨㄚˋ ㄌㄨㄥˊ ㄉㄧㄢˇ ㄐㄧㄥ", pinyin: "huà lóng diǎn jīng", meaning: "比喻最後加上關鍵部分，使事物完美。", example: "你的建議畫龍點睛，解決了我們的難題。" , wordExp: "畫龍＝畫一條龍；點睛＝點上眼睛。龍畫好了，最後點眼睛才活起來，指最關鍵的一筆。",deep:"典故由來：出自唐．張彥遠《歷代名畫記》：南朝梁畫家張僧繇在金陵安樂寺牆上畫四條龍都不點眼睛，說「點睛即飛去」，眾人不信，他一點睛，雷電破壁，龍乘雲飛去。\n字面意思：畫龍最後點上眼睛。\n引申意思：在關鍵處加上一筆，使整體立刻生動完美（如：這句結語畫龍點睛）。褒義；相對詞是「畫蛇添足」。" },
  { id: "i009", grade: 1, term: "畫蛇添足", zhuyin: "ㄏㄨㄚˋ ㄕㄜˊ ㄊㄧㄢ ㄗㄨˊ", pinyin: "huà shé tiān zú", meaning: "比喻多此一舉，反而壞事。", example: "報告已經很完整，再加附錄反而畫蛇添足。", misuse: "不是指畫技高超。" , wordExp: "畫蛇＝畫一條蛇；添足＝多畫了腳。蛇本來沒有腳，畫了反而輸掉比賽，指多此一舉。",deep:"典故由來：出自《戰國策．齊策》：楚國人比賽畫蛇，先畫完的人可得酒；有人先畫好，卻又替蛇添上腳，結果蛇本無腳，酒被別人拿走。\n字面意思：畫好了蛇，又多畫上腳。\n引申意思：比喻多此一舉，反而弄巧成拙（如：文章已完整，再加一段就是畫蛇添足）。貶義。" },
  { id: "i010", grade: 1, term: "百聞不如一見", zhuyin: "ㄅㄞˇ ㄨㄣˊ ㄅㄨˋ ㄖㄨˊ ㄧ ㄐㄧㄢˋ", pinyin: "bǎi wén bù rú yī jiàn", meaning: "親眼看到比聽別人說更確實。", example: "百聞不如一見，我親自去看了才相信。" , wordExp: "百聞＝聽一百次；不如＝比不上；一見＝親眼看一次。聽再多次也不如親眼看一次。",deep:"典故由來：出自《漢書．趙充國傳》：漢宣帝問老將趙充國平羌需多少兵力，他答「百聞不如一見」，請求親自到前線觀察再定計。\n字面意思：聽一百次，不如親眼看一次。\n引申意思：親身見聞比傳聞可靠（如：這裡的風景，百聞不如一見）。" },
  { id: "i011", grade: 1, term: "千變萬化", zhuyin: "ㄑㄧㄢ ㄅㄧㄢˋ ㄨㄢˋ ㄏㄨㄚˋ", pinyin: "qiān biàn wàn huà", meaning: "形容變化極多，難以預測。", example: "天氣千變萬化，出門要帶雨具。" , wordExp: "千、萬＝形容極多；變、化＝改變。變化極多。",deep:"典故由來：語出《列子》：周穆王時巧匠偃師造出會歌舞的人偶，「千變萬化，惟意所適」。\n字面意思：千種變化、萬種變化。\n引申意思：形容變化極多、難以捉摸（如：山區天氣千變萬化）。" },
  { id: "i012", grade: 1, term: "五光十色", zhuyin: "ㄨˇ ㄍㄨㄤ ㄕˊ ㄙㄜˋ", pinyin: "wǔ guāng shí sè", meaning: "色彩繽紛，五彩繽紛。", example: "煙火晚會五光十色，美不勝收。" , wordExp: "五、十＝形容多；光＝光澤；色＝顏色。光澤顏色繁多，繽紛奪目。",deep:"典故由來：語本南朝梁．江淹〈麗色賦〉：「五光徘徊，十色陸離。」\n字面意思：五種光芒、十種顏色。\n引申意思：色彩繽紛絢麗（如：夜市霓虹五光十色）；也形容事物繁多耀眼、景象繁華。" },
  { id: "i013", grade: 1, term: "四面楚歌", zhuyin: "ㄙˋ ㄇㄧㄢˋ ㄔㄨˇ ㄍㄜ", pinyin: "sì miàn chǔ gē", meaning: "處於四面受敵的困境。", example: "公司面臨四面楚歌的局面，瀕臨倒閉。", misuse: "常被誤用為指戰爭場景而非困境。" , wordExp: "四面＝四周；楚歌＝楚國的歌。項羽被包圍時四周都是楚歌，以為楚地盡失，指四面受敵。",
    deep: "典故由來：出自《史記．項羽本紀》：楚漢相爭末期，項羽被劉邦大軍圍困於垓下，夜裡聽見漢軍四面都唱起楚地的歌謠，以為楚地已全被漢軍占領，軍心潰散，最後突圍至烏江自刎。\n字面意思：四周都響起楚國的歌聲。\n引申意思：比喻四面受敵、孤立無援的困境（如：他在會議上遭各部門反對，陷入四面楚歌）。使用時著重「處境孤立」，不是描寫戰爭場面本身。" },
  { id: "i014", grade: 1, term: "龍騰虎躍", zhuyin: "ㄌㄨㄥˊ ㄊㄥˊ ㄏㄨˇ ㄩㄝˋ", pinyin: "lóng téng hǔ yuè", meaning: "形容生龍活虎，充滿活力。", example: "運動會上同學們龍騰虎躍，奮力拼搏。" , wordExp: "龍騰＝龍飛騰；虎躍＝虎跳躍。像龍虎般活躍有生氣。",deep:"典故由來：由「龍」「虎」兩種象徵力量的動物組合而成的常用語。\n字面意思：像龍飛騰、像虎跳躍。\n引申意思：形容充滿活力、氣勢奔放的景象（如：運動場上龍騰虎躍）。褒義。" },
  { id: "i015", grade: 1, term: "虎頭蛇尾", zhuyin: "ㄏㄨˇ ㄊㄡˊ ㄕㄜˊ ㄨㄟˇ", pinyin: "hǔ tóu shé wěi", meaning: "開始猛烈，後來無力，不夠堅持。", example: "做事要堅持到底，不能虎頭蛇尾。", misuse: "不是指真的老虎和蛇。" , wordExp: "虎頭＝老虎的頭（大而威）；蛇尾＝蛇的尾巴（細而小）。開頭盛大，結尾草率。",deep:"典故由來：出自元．康進之雜劇《李逵負荊》：「這廝敢狗行狼心，虎頭蛇尾。」\n字面意思：老虎的頭、蛇的尾巴——開頭壯大，結尾細小。\n引申意思：做事有始無終、起初聲勢大後來草草了事（如：計畫執行不能虎頭蛇尾）。貶義；相對詞是「有始有終」。" },
  { id: "i016", grade: 1, term: "目不轉睛", zhuyin: "ㄇㄨˋ ㄅㄨˋ ㄓㄨㄢˇ ㄐㄧㄥ", pinyin: "mù bù zhuǎn jīng", meaning: "眼睛緊盯著，不移開視線。", example: "他目不轉睛地看著舞台上的表演。" , wordExp: "目＝眼睛；不轉睛＝眼珠不轉動。眼睛盯著看，一動也不動。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：眼珠一動也不動。\n引申意思：注視得非常專心（如：孩子目不轉睛地看著魔術表演）。" },
  { id: "i017", grade: 1, term: "聲名狼藉", zhuyin: "ㄕㄥ ㄇㄧㄥˊ ㄌㄤˊ ㄐㄧˊ", pinyin: "shēng míng láng jí", meaning: "名聲很壞，惡名昭著。", example: "那個詐騙犯聲名狼藉，人人都知道。" , wordExp: "聲名＝名聲；狼藉＝像狼窩的草一樣散亂。名聲壞到一塌糊塗。",deep:"典故由來：出自《史記．蒙恬列傳》：「惡聲狼籍，布於諸國。」「狼藉」原指狼群睡臥後草地凌亂的樣子。\n字面意思：名聲像狼窩的草一樣亂七八糟。\n引申意思：名聲敗壞到極點（如：他因詐欺而聲名狼藉）。貶義；注意「藉」不寫作「籍」（今通行寫法）。" },
  { id: "i018", grade: 1, term: "奮力直追", zhuyin: "ㄈㄣˋ ㄌㄧˋ ㄓˊ ㄓㄨㄟ", pinyin: "fèn lì zhí zhuī", meaning: "用力追趕，努力追上。", example: "落後的運動員奮力直追，最後反超。" , wordExp: "奮力＝使盡力氣；直追＝一直追趕。用盡全力追上去。",deep:"典故由來：由「奮起直追」演變的組合語，無特定典故。\n字面意思：鼓起力氣一直追趕。\n引申意思：落後時努力追上（如：下半場球隊奮力直追）。褒義，強調不放棄。" },
  { id: "i019", grade: 2, term: "生龍活虎", zhuyin: "ㄕㄥ ㄌㄨㄥˊ ㄏㄨㄛˊ ㄏㄨˇ", pinyin: "shēng lóng huó hǔ", meaning: "精力充沛，充滿活力。", example: "這個小朋友生龍活虎，整天跑來跑去。" , wordExp: "生龍＝活生生的龍；活虎＝生猛的虎。像龍虎一樣精力旺盛。",deep:"典故由來：語見宋．《朱子語類》：形容人「如生龍活虎」般有生氣。\n字面意思：像活生生的龍和虎。\n引申意思：精力充沛、活蹦亂跳（如：孩子們個個生龍活虎）。褒義。" },
  { id: "i020", grade: 2, term: "一帆風順", zhuyin: "ㄧ ㄈㄢ ㄈㄥ ㄕㄨㄣˋ", pinyin: "yī fān fēng shùn", meaning: "形容事情進行順利，沒有障礙。", example: "祝你升學考試一帆風順。" , wordExp: "一帆＝船帆一路張著；風順＝風向順利。船一路順風，比喻事事順利。",deep:"典故由來：由航海用語組合而成，無特定典故；帆滿風順則船行快。\n字面意思：船掛滿帆，一路順風。\n引申意思：事情進行順利沒有阻礙（如：祝你新工作一帆風順）。常用於祝福。" },
  { id: "i021", grade: 2, term: "百般刁難", zhuyin: "ㄅㄞˇ ㄅㄢ ㄉㄧㄠ ㄋㄢˊ", pinyin: "bǎi bān diāo nán", meaning: "用各種辦法故意困難，刁難別人。", example: "那個主管百般刁難新員工，讓人很不愉快。" , wordExp: "百般＝各種方法；刁難＝故意為難。用各種方式故意為難人。",deep:"典故由來：由字面組合而成的口語成語。\n字面意思：用上百種方法故意為難人。\n引申意思：想盡辦法刁難別人（如：他到處被百般刁難）。貶義。" },
  { id: "i022", grade: 2, term: "春暖花開", zhuyin: "ㄔㄨㄣ ㄋㄨㄢˇ ㄏㄨㄚ ㄎㄞ", pinyin: "chūn nuǎn huā kāi", meaning: "春天氣溫回暖，花朵綻放。", example: "春暖花開的季節，適合去郊外踏青。" , wordExp: "春暖＝春天回暖；花開＝花朵綻放。天氣轉暖、百花盛開的美好時節。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：春天暖和、花朵開放。\n引申意思：形容春天美好的景象（如：春暖花開時去郊遊）；也比喻情勢好轉、時機美好。" },
  { id: "i023", grade: 2, term: "齊頭並進", zhuyin: "ㄑㄧˊ ㄊㄡˊ ㄅㄧㄥˋ ㄐㄧㄣˋ", pinyin: "qí tóu bìng jìn", meaning: "同時向前進行，協調一致。", example: "學習和運動要齊頭並進，不能偏廢。" , wordExp: "齊頭＝頭並著頭；並進＝一起前進。不分先後、一起往前。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：頭對齊、一起前進。\n引申意思：幾件事同時進行、不分先後（如：課業與運動齊頭並進）。" },
  { id: "i024", grade: 2, term: "雨過天晴", zhuyin: "ㄩˇ ㄍㄨㄛˋ ㄊㄧㄢ ㄑㄧㄥˊ", pinyin: "yǔ guò tiān qíng", meaning: "雨停了天晴了，比喻困難過去了。", example: "經過一段困難時期，終於雨過天晴。" , wordExp: "雨過＝雨停了；天晴＝天放晴。困難過去，情況好轉。",deep:"典故由來：相傳後周世宗形容御用瓷器要如「雨過天青雲破處」的顏色，後演為常用語。\n字面意思：雨停了、天放晴。\n引申意思：比喻困難或不愉快過去，情況好轉（如：誤會解開，兩人雨過天晴）。" },
  { id: "i025", grade: 2, term: "七嘴八舌", zhuyin: "ㄑㄧ ㄗㄨㄟˇ ㄅㄚ ㄕㄜˊ", pinyin: "qī zuǐ bā shé", meaning: "許多人同時各說各的話，亂成一片。", example: "開會時大家七嘴八舌，主席難以主持。", misuse: "不是字面意思的嘴巴，是比喻講話人多。" , wordExp: "七嘴＝許多張嘴；八舌＝許多條舌頭。你一言我一語，亂成一片。",deep:"典故由來：明清白話小說常見的口語成語。\n字面意思：七張嘴、八條舌頭。\n引申意思：許多人搶著說話、意見紛雜（如：大家七嘴八舌地討論）。" },
  { id: "i026", grade: 2, term: "安居樂業", zhuyin: "ㄢ ㄐㄩ ㄌㄜˋ ㄧㄝˋ", pinyin: "ān jū lè yè", meaning: "住得安心，工作順利，生活滿足。", example: "改革開放後，人民安居樂業。" , wordExp: "安居＝安穩地居住；樂業＝快樂地工作。生活安定，工作愉快。",deep:"典故由來：語本《老子》「安其居，樂其俗」；《漢書．貨殖傳》作「各安其居而樂其業」。\n字面意思：安穩地居住，快樂地工作。\n引申意思：生活安定、對工作滿足（如：政治清明，人民安居樂業）。" },
  { id: "i027", grade: 2, term: "頑強不屈", zhuyin: "ㄨㄢˊ ㄑㄧㄤˊ ㄅㄨˋ ㄑㄩ", pinyin: "wán qiáng bù qū", meaning: "堅定不屈，不肯低頭認輸。", example: "運動員以頑強不屈的精神贏得比賽。" , wordExp: "頑強＝堅韌強硬；不屈＝不肯屈服。意志堅強，絕不低頭。",deep:"典故由來：由字面組合而成。\n字面意思：頑強堅定、不肯屈服。\n引申意思：意志堅強不低頭（如：選手頑強不屈地奮戰到底）。褒義。" },
  { id: "i028", grade: 2, term: "苦盡甘來", zhuyin: "ㄎㄨˇ ㄐㄧㄣˋ ㄍㄢ ㄌㄞˊ", pinyin: "kǔ jìn gān lái", meaning: "經過辛苦，最後得到甜蜜的回報。", example: "多年的努力，終於苦盡甘來。" , wordExp: "苦盡＝苦日子到了盡頭；甘來＝甜日子來了。熬過辛苦，迎來美好。",deep:"典故由來：元代戲曲中已常見（如《西廂記》）。\n字面意思：苦味吃盡，甘甜就來了。\n引申意思：艱苦的日子結束，美好的日子來臨（如：多年努力終於苦盡甘來）。相對詞：樂極生悲。" },
  { id: "i029", grade: 2, term: "欣欣向榮", zhuyin: "ㄒㄧㄣ ㄒㄧㄣ ㄒㄧㄤˋ ㄖㄨㄥˊ", pinyin: "xīn xīn xiàng róng", meaning: "興盛發展，蓬勃成長。", example: "公司業務欣欣向榮，員工深感驕傲。" , wordExp: "欣欣＝草木茂盛的樣子；向榮＝朝著繁榮生長。蓬勃發展的景象。",deep:"典故由來：出自晉．陶淵明〈歸去來兮辭〉：「木欣欣以向榮，泉涓涓而始流。」\n字面意思：草木茂盛地生長。\n引申意思：形容事業、景象蓬勃發展（如：市場欣欣向榮）。褒義。" },
  { id: "i030", grade: 2, term: "披荊斬棘", zhuyin: "ㄆㄧ ㄐㄧㄥ ㄓㄢˇ ㄐㄧˊ", pinyin: "pī jīng zhǎn jí", meaning: "克服困難，勇往直前開創局面。", example: "他披荊斬棘，開拓了新的市場。" , wordExp: "披＝撥開；荊、棘＝多刺的灌木；斬＝砍斷。撥開荊棘開路，比喻克服重重困難。",deep:"典故由來：出自《後漢書．馮異傳》：漢光武帝稱讚馮異「為吾披荊棘，定關中」。\n字面意思：撥開荊棘、砍斷雜刺往前走。\n引申意思：克服重重困難開創局面（如：創業者披荊斬棘）。褒義。" },
  { id: "i031", grade: 3, term: "守株待兔", zhuyin: "ㄕㄡˇ ㄓㄨ ㄉㄞˋ ㄊㄨˋ", pinyin: "shǒu zhū dài tù", meaning: "比喻坐以待斃，不思進取。", example: "光守株待兔是不行的，必須主動出擊。", misuse: "常被誤用為指等待或恪守原則。" , wordExp: "守＝守著；株＝樹樁；待＝等候；兔＝兔子。農夫守著樹樁等兔子再撞上來，指妄想不勞而獲。",deep:"典故由來：出自《韓非子．五蠹》：宋國農夫見兔子撞樹樁而死，白撿一隻，從此放下農具守著樹樁等兔子，結果再也沒等到，被全國人笑話。\n字面意思：守著樹樁等兔子。\n引申意思：不主動努力，妄想僥倖再得（如：守株待兔等機會，不如主動出擊）。貶義。" },
  { id: "i032", grade: 3, term: "亡羊補牢", zhuyin: "ㄨㄤˊ ㄧㄤˊ ㄅㄨˇ ㄌㄠˊ", pinyin: "wáng yáng bǔ láo", meaning: "失去後才懊悔補救，為時未晚。", example: "工程出了漏洞，亡羊補牢也能保住大局。" , wordExp: "亡＝丟失；羊＝羊隻；補＝修補；牢＝羊圈。羊跑了才修圈，及時補救還不算晚。",deep:"典故由來：出自《戰國策．楚策》：「亡羊而補牢，未為遲也。」莊辛勸楚襄王：羊跑了才修羊圈，還不算晚。\n字面意思：羊丟了才修補羊圈。\n引申意思：出了差錯及時補救，還來得及（如：這次考差了，亡羊補牢開始複習吧）。含勸勉意味。" },
  { id: "i033", grade: 3, term: "掩耳盜鈴", zhuyin: "ㄧㄢˇ ㄦˇ ㄉㄠˋ ㄌㄧㄥˊ", pinyin: "yǎn ěr dào líng", meaning: "自欺欺人，掩蓋事實。", example: "隱瞞問題就像掩耳盜鈴，遲早會暴露。", misuse: "不是真的盜竊，是比喻自欺欺人。" , wordExp: "掩＝摀住；耳＝自己的耳朵；盜＝偷；鈴＝鈴鐺。摀住耳朵偷鈴，以為別人也聽不見，自欺欺人。",deep:"典故由來：出自《呂氏春秋．自知》：有人偷大鐘，怕鐘聲被聽見，就摀住自己的耳朵去敲，以為自己聽不到別人也聽不到（原作「掩耳盜鐘」）。\n字面意思：摀著耳朵偷鈴鐺。\n引申意思：自欺欺人，明明掩蓋不了卻自以為能瞞住（如：抄襲還說是巧合，根本是掩耳盜鈴）。貶義。" },
  { id: "i034", grade: 3, term: "臨時抱佛腳", zhuyin: "ㄌㄧㄣˊ ㄕˊ ㄅㄠˋ ㄈㄛˊ ㄐㄧㄠˇ", pinyin: "lín shí bào fó jiǎo", meaning: "平時不努力，急時才臨陣磨槍。", example: "考試前才讀書，那是臨時抱佛腳。" , wordExp: "臨時＝事到眼前；抱佛腳＝抱著佛像的腳求救。平時不燒香，急了才求佛。",deep:"典故由來：語本唐代諺語「急來抱佛腳」：平時不燒香，事到臨頭才求佛。\n字面意思：事情臨頭才去抱佛的腳求保佑。\n引申意思：平時不準備，急時才匆忙應付（如：考前才臨時抱佛腳）。貶義。" },
  { id: "i035", grade: 3, term: "坐以待斃", zhuyin: "ㄗㄨㄛˋ ㄧˇ ㄉㄞˋ ㄅㄧˋ", pinyin: "zuò yǐ dài bì", meaning: "不主動行動，被動等待失敗。", example: "面對困難不能坐以待斃，要想辦法。" , wordExp: "坐＝坐著；以＝而；待＝等待；斃＝死亡。坐著等死，不想辦法自救。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：坐著等死。\n引申意思：面對危難不想辦法，被動等失敗來臨（如：與其坐以待斃，不如放手一搏）。貶義。" },
  { id: "i036", grade: 3, term: "臨危不懼", zhuyin: "ㄌㄧㄣˊ ㄨㄟ ㄅㄨˋ ㄐㄩˋ", pinyin: "lín wēi bù jù", meaning: "面臨危險不害怕，勇敢沉著。", example: "那個消防員臨危不懼，救出受困民眾。" , wordExp: "臨＝面對；危＝危險；不懼＝不害怕。面對危難毫不畏懼。",deep:"典故由來：語本《鄧析子》「臨難不懼」，後作「臨危不懼」。\n字面意思：面對危險不恐懼。\n引申意思：危急時刻沉著勇敢（如：消防員臨危不懼救人）。褒義。" },
  { id: "i037", grade: 3, term: "臨危授命", zhuyin: "ㄌㄧㄣˊ ㄨㄟ ㄕㄡˋ ㄇㄧㄥˋ", pinyin: "lín wēi shòu mìng", meaning: "在危急時刻接受重要職責。", example: "司令臨危授命，成功指揮了撤退。" , wordExp: "臨危＝國家危難之際；授命＝獻出生命／接受使命。危難時刻挺身承擔。",deep:"典故由來：語本《論語．憲問》：「見利思義，見危授命。」\n字面意思：面臨危難時交付出自己的生命。\n引申意思：危急關頭勇於承擔重任、不惜犧牲（如：亂世中臨危授命，扛起重擔）。褒義。" },
  { id: "i038", grade: 3, term: "明眼人", zhuyin: "ㄇㄧㄥˊ ㄧㄢˇ ㄖㄣˊ", pinyin: "míng yǎn rén", meaning: "有眼光、有見識的人。", example: "在場的明眼人都看出了他的真實意圖。" , wordExp: "明眼＝眼睛雪亮。看得清楚、有見識的人。",deep:"典故由來：宋代禪宗語錄常見「明眼人」一詞。\n字面意思：眼睛明亮的人。\n引申意思：有眼光、看得清事理的人（如：明眼人一看就知道問題出在哪）。" },
  { id: "i039", grade: 3, term: "走投無路", zhuyin: "ㄗㄡˇ ㄊㄡˊ ㄨˊ ㄌㄨˋ", pinyin: "zǒu tóu wú lù", meaning: "無處可去，陷入絕境。", example: "窮途潦倒的他走投無路。" , wordExp: "走投＝投奔；無路＝沒有路。想投靠都沒有地方，陷入絕境。",deep:"典故由來：出自元．楊顯之雜劇《瀟湘雨》：「淋的我走投無路。」\n字面意思：走到沒有路可投奔。\n引申意思：陷入絕境、無處求助（如：被債務逼得走投無路）。" },
  { id: "i040", grade: 3, term: "黃粱一夢", zhuyin: "ㄏㄨㄤˊ ㄌㄧㄤˊ ㄧ ㄇㄥˋ", pinyin: "huáng liáng yī mèng", meaning: "比喻美夢一場，虛幻不實。", example: "那些不切實際的計畫，不過黃粱一夢。", misuse: "不是指字面的黃粱米，是比喻空夢。" , wordExp: "黃粱＝小米飯；一夢＝一場夢。小米飯還沒煮熟，富貴一生的夢已醒，指虛幻的美夢。",deep:"典故由來：出自唐．沈既濟《枕中記》：盧生在邯鄲客店借道士枕頭入睡，夢中享盡榮華富貴，醒來時店家的黃粱飯還沒煮熟。\n字面意思：煮一鍋黃粱飯的時間做的一場夢。\n引申意思：比喻榮華富貴如夢一場、虛幻不實（如：發財計畫終成黃粱一夢）。" },
  { id: "i041", grade: 3, term: "庸人自擾", zhuyin: "ㄩㄥ ㄖㄣˊ ㄗˋ ㄖㄠˇ", pinyin: "yōng rén zì rǎo", meaning: "平庸的人自作聰明惹出麻煩。", example: "別庸人自擾，事情還沒發生呢。" , wordExp: "庸人＝平庸的人；自擾＝自己煩擾自己。本來沒事，自己嚇自己。",deep:"典故由來：出自《新唐書．陸象先傳》：「天下本無事，庸人擾之而煩耳。」\n字面意思：平庸的人自己騷擾自己。\n引申意思：本來沒事，自己瞎操心或自找麻煩（如：謠言別理會，庸人自擾罷了）。貶義。" },
  { id: "i042", grade: 3, term: "愚公移山", zhuyin: "ㄩˊ ㄍㄨㄥ ㄧˊ ㄕㄢ", pinyin: "yú gōng yí shān", meaning: "比喻意志堅強，終能成功。", example: "他用愚公移山的精神，終於克服了難題。" , wordExp: "愚公＝寓言中的老人；移山＝搬走大山。下定決心，再難的事也能完成。",deep:"典故由來：出自《列子．湯問》：九十歲的愚公要挖平擋路的太行、王屋二山，笑他的智叟被反問「子子孫孫無窮匱也，而山不加增」，天帝感其誠，命神背走二山。\n字面意思：愚公搬移大山。\n引申意思：意志堅定、不怕困難，終能成功（如：以愚公移山的精神治水）。褒義。" },
  { id: "i043", grade: 3, term: "南轅北轍", zhuyin: "ㄋㄢˊ ㄩㄢˊ ㄅㄟˇ ㄓㄜˊ", pinyin: "nán yuán běi zhé", meaning: "方向相反，目的相悖。", example: "你的做法與目標南轅北轍，必定失敗。", misuse: "不是指真的馬車方向。" , wordExp: "轅＝車前駕馬的直木（代指車行方向）；轍＝車輪痕跡。車往南、轍向北，行動和目標相反。",deep:"典故由來：出自《戰國策．魏策》：季梁勸魏王——有人要去南方楚國，車子卻往北走，說「馬好、錢多、車夫技術好」，但方向錯了，條件愈好離目的地愈遠。\n字面意思：車轅朝南，車轍卻向北。\n引申意思：行動與目標相反（如：方法與目的南轅北轍）。貶義。" },
  { id: "i044", grade: 3, term: "杯弓蛇影", zhuyin: "ㄅㄟ ㄍㄨㄥ ㄕㄜˊ ㄧㄥˇ", pinyin: "bēi gōng shé yǐng", meaning: "過度疑心，草木皆兵。", example: "別過於敏感，那只是杯弓蛇影。", misuse: "不是真有蛇，是比喻過度疑心。" , wordExp: "杯＝酒杯；弓＝掛著的弓；蛇影＝映在酒裡像蛇的影子。把弓影當成蛇，疑神疑鬼。",deep:"典故由來：出自《晉書．樂廣傳》：客人見酒杯中似有小蛇，喝後疑心成病；樂廣發現是牆上掛弓映在酒中的影子，說明後客人的病立刻好了。\n字面意思：把杯中弓影當成蛇。\n引申意思：疑神疑鬼、自相驚擾（如：一朝被蛇咬，處處杯弓蛇影）。貶義。" },
  { id: "i045", grade: 3, term: "唇亡齒寒", zhuyin: "ㄔㄨㄣˊ ㄨㄤˊ ㄔˇ ㄏㄢˊ", pinyin: "chún wáng chǐ hán", meaning: "利益相關，禍福相連。", example: "我們的命運唇亡齒寒，必須團結。" , wordExp: "唇＝嘴唇；亡＝失去；齒＝牙齒；寒＝受凍。嘴唇沒了牙齒就受寒，關係密切、互相依存。",deep:"典故由來：出自《左傳．僖公五年》：晉國向虞國借道攻打虢國，宮之奇勸虞公：「輔車相依，唇亡齒寒」，虞虢相鄰，虢亡虞必亡。虞公不聽，果然亡國。\n字面意思：嘴唇沒了，牙齒就會寒冷。\n引申意思：雙方關係密切、利害相連（如：兩國唇亡齒寒，必須合作）。" },
  { id: "i046", grade: 3, term: "樂不思蜀", zhuyin: "ㄌㄜˋ ㄅㄨˋ ㄙ ㄕㄨˇ", pinyin: "lè bù sī shǔ", meaning: "沉溺於享樂，忘記故鄉。", example: "他到了都市樂不思蜀，回家次數越來越少。" , wordExp: "樂＝快樂得；不思＝不想念；蜀＝蜀國（劉禪的故國）。玩樂到忘了故國，樂而忘返。",deep:"典故由來：出自《三國志》裴注引《漢晉春秋》：蜀漢亡後，後主劉禪被遷到洛陽，司馬昭問他想不想蜀地，他答「此間樂，不思蜀」。\n字面意思：快樂得不想念蜀國。\n引申意思：沉迷眼前享樂，忘了故土或本分（如：出國玩到樂不思蜀）。貶義。" },
  { id: "i047", grade: 3, term: "分道揚鑣", zhuyin: "ㄈㄣ ㄉㄠˋ ㄧㄤˊ ㄅㄧㄠ", pinyin: "fēn dào yáng biāo", meaning: "各走各的路，分手各奔前程。", example: "合作不愉快，最後只好分道揚鑣。" , wordExp: "分道＝各走一條路；揚鑣＝提起馬嚼子驅馬。各奔前程，不再同行。",deep:"典故由來：出自《魏書》：元志與李彪在路上爭道，孝文帝裁定「自應分路揚鑣」——各走一半路。鑣是馬嚼子兩旁的鐵環。\n字面意思：分開道路，各自揚鞭驅馬。\n引申意思：因目標、志趣不同而各走各的路（如：合作多年後分道揚鑣）。" },
  { id: "i048", grade: 3, term: "汗牛充棟", zhuyin: "ㄏㄢˋ ㄋㄧㄡˊ ㄔㄨㄥ ㄉㄨㄥˋ", pinyin: "hàn niú chōng dòng", meaning: "形容書籍極多，堆滿房屋。", example: "他的藏書汗牛充棟，是個真正的書迷。" , wordExp: "汗牛＝搬運時牛累得流汗；充棟＝堆滿屋梁。形容藏書極多。",deep:"典故由來：出自唐．柳宗元〈陸文通先生墓表〉：形容藏書「處則充棟宇，出則汗牛馬」——放著堆滿屋子，搬運累得牛馬流汗。\n字面意思：搬書累得牛出汗，堆書塞滿屋棟。\n引申意思：形容書籍極多（如：他家藏書汗牛充棟）。只形容書多，不能形容其他東西多。" },
  { id: "i049", grade: 3, term: "鳳毛麟角", zhuyin: "ㄈㄥˋ ㄇㄠˊ ㄌㄧㄣˊ ㄐㄧㄠˇ", pinyin: "fèng máo lín jiǎo", meaning: "極為罕見，稀有難得。", example: "這樣的天才是鳳毛麟角，百年難見。" , wordExp: "鳳毛＝鳳凰的羽毛；麟角＝麒麟的角。珍稀之物，極為難得。",deep:"典故由來：語本《南史．謝超宗傳》：帝讚謝超宗文才「殊有鳳毛」；「麟角」則見《北史》「學者如牛毛，成者如麟角」。\n字面意思：鳳凰的羽毛、麒麟的角。\n引申意思：極稀少珍貴的人或物（如：這種人才是鳳毛麟角）。褒義。" },
  { id: "i050", grade: 4, term: "狐假虎威", zhuyin: "ㄏㄨˊ ㄐㄧㄚˇ ㄏㄨˇ ㄨㄟ", pinyin: "hú jiǎ hǔ wēi", meaning: "借勢欺人，假借權勢。", example: "他狐假虎威，利用上司的名義欺騙同事。", misuse: "不是指狐狸和老虎真的在一起。" , wordExp: "狐＝狐狸；假＝借用；虎威＝老虎的威風。狐狸借老虎的威風嚇人，仗勢欺人。",deep:"典故由來：出自《戰國策．楚策》：老虎抓到狐狸，狐狸說「天帝派我當百獸之王，不信你跟在我後面走」；百獸看見都逃跑，老虎不知道牠們怕的是自己，以為真怕狐狸。\n字面意思：狐狸借老虎的威風。\n引申意思：倚仗別人的權勢欺壓人（如：他狐假虎威，仗著主管的名號使喚同事）。貶義。" },
  { id: "i051", grade: 4, term: "老馬識途", zhuyin: "ㄌㄠˇ ㄇㄚˇ ㄕˊ ㄊㄨˊ", pinyin: "lǎo mǎ shí tú", meaning: "比喻經驗豐富的人有能力解決問題。", example: "請老馬識途的前輩指導我們。" , wordExp: "老馬＝經驗豐富的馬；識途＝認得路。老馬認得走過的路，指有經驗的人可靠。",deep:"典故由來：出自《韓非子．說林上》：齊桓公伐孤竹返程迷路，管仲說「老馬之智可用也」，放老馬前行，果然找到歸路。\n字面意思：老馬認得走過的路。\n引申意思：經驗豐富的人熟悉情況、能引導解決問題（如：這件事請教老馬識途的前輩準沒錯）。褒義。" },
  { id: "i052", grade: 4, term: "披著羊皮的狼", zhuyin: "ㄆㄧ ㄓㄠˊ ㄧㄤˊ ㄆㄧˊ ㄉㄜ ㄌㄤˊ", pinyin: "pī zháo yáng pí de láng", meaning: "外表善良，實則狡詐，偽裝者。", example: "他披著羊皮的狼，表面謙虛其實很狡詐。" , wordExp: "披＝披掛；羊皮＝溫馴的偽裝；狼＝凶狠的本性。外表善良、內心險惡的人。",deep:"典故由來：出自《伊索寓言》：狼披上羊皮混進羊群，伺機吃羊。\n字面意思：披著羊皮偽裝成羊的狼。\n引申意思：外表偽善、內心狡詐的人（如：小心那些披著羊皮的狼）。貶義。" },
  { id: "i053", grade: 4, term: "千篇一律", zhuyin: "ㄑㄧㄢ ㄆㄧㄢ ㄧ ㄌㄩˋ", pinyin: "qiān piān yī lǜ", meaning: "全部一樣，毫無變化。", example: "每家店的裝潢千篇一律，沒有特色。" , wordExp: "千篇＝上千篇文章；一律＝同一個樣子。全都一個樣，毫無變化。",deep:"典故由來：由字面組合而成，明代文評已見。\n字面意思：一千篇文章都是同一個格律。\n引申意思：事物呆板重複、毫無變化（如：文章內容千篇一律）。貶義。" },
  { id: "i054", grade: 4, term: "無可厚非", zhuyin: "ㄨˊ ㄎㄜˇ ㄏㄡˋ ㄈㄟ", pinyin: "wú kě hòu fēi", meaning: "沒有什麼過分的地方，可以理解。", example: "他的決定無可厚非，是最合理的選擇。" , wordExp: "無可＝沒有什麼可以；厚＝過分；非＝責備。雖有小缺點，但情有可原，不必苛責。",deep:"典故由來：語本《漢書．王莽傳》：王莽事後醒悟說「英亦未可厚非」——馮英並沒有什麼可以過分責備的。\n字面意思：不可以過分責備。\n引申意思：雖有缺點但情有可原（如：他的做法無可厚非）。注意：不寫作「無可厚非議」，也別與「無可非議」（完全沒錯）混用。" },
  { id: "i055", grade: 4, term: "禍在眼前", zhuyin: "ㄏㄨㄛˋ ㄗㄞˋ ㄧㄢˇ ㄑㄧㄢˊ", pinyin: "huò zài yǎn qián", meaning: "危險就在眼前，迫在眉睫。", example: "再不悔改，禍在眼前。" , wordExp: "禍＝災禍；在眼前＝就在面前。災難迫近。",deep:"典故由來：由字面組合而成。\n字面意思：災禍就在眼前。\n引申意思：危險迫在眉睫（如：再不撤離就禍在眼前）。" },
  { id: "i056", grade: 4, term: "未雨綢繆", zhuyin: "ㄨㄟˋ ㄩˇ ㄔㄡˊ ㄇㄡˊ", pinyin: "wèi yǔ chóu móu", meaning: "提前預備，未雨先防。", example: "保險就是未雨綢繆的做法。" , wordExp: "未雨＝還沒下雨；綢繆＝纏繞修補（門窗）。趁天晴先修屋，事先做好準備。",deep:"典故由來：出自《詩經．豳風．鴟鴞》：「迨天之未陰雨，徹彼桑土，綢繆牖戶。」鳥兒趁天未下雨，先取桑根修補巢穴。\n字面意思：趁還沒下雨，先纏緊門窗（綢繆＝緊密纏縛）。\n引申意思：事先做好準備（如：颱風來前未雨綢繆，備妥物資）。褒義；相對詞：臨渴掘井。" },
  { id: "i057", grade: 4, term: "揠苗助長", zhuyin: "ㄧㄚˋ ㄇㄧㄠˊ ㄓㄨˋ ㄓㄤˇ", pinyin: "yà miáo zhù zhǎng", meaning: "急功近利，反而壞事。", example: "教育孩子不能揠苗助長，要順其自然。", misuse: "不是真的拔苗，是比喻欲速則不達。" , wordExp: "揠＝拔高；苗＝禾苗；助長＝幫助生長。把苗拔高反而害它枯死，急於求成反壞事。",deep:"典故由來：出自《孟子．公孫丑上》：宋國人嫌禾苗長太慢，把苗一株株拔高，回家誇口「今天幫苗長大了」，兒子跑去一看，苗全枯死了。\n字面意思：把苗拔高幫它生長。\n引申意思：違反事物規律、急於求成反而壞事（如：逼幼兒超前學習，無異揠苗助長）。貶義；也作「拔苗助長」。" },
  { id: "i058", grade: 4, term: "豐功偉績", zhuyin: "ㄈㄥ ㄍㄨㄥ ㄨㄟˇ ㄐㄧˋ", pinyin: "fēng gōng wěi jì", meaning: "偉大的功績和成就。", example: "先賢們創造了豐功偉績，值得後人銘記。" , wordExp: "豐＝豐厚；功＝功勞；偉＝偉大；績＝成就。偉大的功勞成就。",deep:"典故由來：宋代文獻已見的組合語。\n字面意思：豐厚的功勞、偉大的業績。\n引申意思：偉大的成就（如：先賢的豐功偉績）。褒義。" },
  { id: "i059", grade: 4, term: "大器晚成", zhuyin: "ㄉㄚˋ ㄑㄧˋ ㄨㄢˇ ㄔㄥˊ", pinyin: "dà qì wǎn chéng", meaning: "大才的人成就來得較晚。", example: "林老師雖然大器晚成，但成就卓越。" , wordExp: "大器＝貴重的器物（喻大才）；晚成＝較晚完成。大才往往成就得晚。",deep:"典故由來：出自《老子》：「大方無隅，大器晚成，大音希聲。」貴重的器物需要長時間才能完成。\n字面意思：大的器物最晚完成。\n引申意思：有大才能的人成名往往較晚（如：他四十歲才成名，是大器晚成）。褒義，常用來勉勵人。" },
  { id: "i060", grade: 4, term: "蛛絲馬跡", zhuyin: "ㄓㄨ ㄙ ㄇㄚˇ ㄐㄧˋ", pinyin: "zhū sī mǎ jì", meaning: "極微小的痕跡，可作為線索。", example: "警察從蛛絲馬跡中找到了關鍵證據。" , wordExp: "蛛絲＝蜘蛛的細絲；馬跡＝馬蹄的痕跡。隱約可尋的線索。",deep:"典故由來：清代文獻已見；蜘蛛留絲、馬蹄留印，皆隱約可尋。\n字面意思：蜘蛛的細絲、馬蹄的痕跡。\n引申意思：隱約可尋的線索（如：警方從蛛絲馬跡查出真相）。" },
  { id: "i061", grade: 4, term: "水落石出", zhuyin: "ㄕㄨㄟˇ ㄌㄨㄛˋ ㄕˊ ㄔㄨ", pinyin: "shuǐ luò shí chū", meaning: "事實真相終於顯露。", example: "調查到底，真相終將水落石出。" , wordExp: "水落＝水位退下；石出＝石頭露出。水退石現，真相大白。",deep:"典故由來：出自宋．蘇軾〈後赤壁賦〉：「山高月小，水落石出。」歐陽修〈醉翁亭記〉亦有「水落而石出者」。\n字面意思：水位下降，石頭露出來。\n引申意思：真相終於大白（如：案情終將水落石出）。" },
  { id: "i062", grade: 4, term: "眾所周知", zhuyin: "ㄓㄨㄥˋ ㄙㄨㄛˇ ㄓㄡ ㄓ", pinyin: "zhòng suǒ zhōu zhī", meaning: "大家都知道，是公開的事實。", example: "眾所周知，健康飲食對身體很重要。" , wordExp: "眾＝大家；所＝所～的；周知＝全都知道。人人皆知。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：眾人所普遍知道。\n引申意思：大家都知道的事（如：眾所周知，運動有益健康）。" },
  { id: "i063", grade: 4, term: "十年磨劍", zhuyin: "ㄕˊ ㄋㄧㄢˊ ㄇㄛˊ ㄐㄧㄢˋ", pinyin: "shí nián mó jiàn", meaning: "花費多年時間準備，一鳴驚人。", example: "他十年磨劍，終於在比賽中大放異彩。" , wordExp: "十年＝長時間；磨劍＝磨一把劍。長期苦練，等待一展身手。",deep:"典故由來：出自唐．賈島〈劍客〉詩：「十年磨一劍，霜刃未曾試。」\n字面意思：花十年磨一把劍。\n引申意思：長期刻苦鍛鍊、蓄勢待發（如：十年磨劍，一朝奪冠）。褒義。" },
  { id: "i064", grade: 4, term: "卧虎藏龍", zhuyin: "ㄨㄛˋ ㄏㄨˇ ㄘㄤˊ ㄌㄨㄥˊ", pinyin: "wò hǔ cáng lóng", meaning: "比喻隱伏著德才兼備的人。", example: "這個小鎮臥虎藏龍，出過許多人才。" , wordExp: "卧虎＝躺著的虎；藏龍＝隱藏的龍。潛藏著未被發現的人才。",deep:"典故由來：語本北周．庾信詩：「暗石疑藏虎，盤根似臥龍。」\n字面意思：躺著的虎、隱藏的龍。\n引申意思：隱藏著未被發現的人才（如：民間卧虎藏龍）。褒義。" },
  { id: "i065", grade: 4, term: "柳暗花明", zhuyin: "ㄌㄧㄡˇ ㄢˋ ㄏㄨㄚ ㄇㄧㄥˊ", pinyin: "liǔ àn huā míng", meaning: "陰暗之處豁然開朗，喻絕處逢生。", example: "問題終於柳暗花明，找到了解決方案。" , wordExp: "柳暗＝柳蔭深綠；花明＝花色明豔。山窮水盡處忽見村落，絕處逢生。",deep:"典故由來：出自宋．陸游〈遊山西村〉：「山重水複疑無路，柳暗花明又一村。」\n字面意思：柳蔭深暗處，忽見花明景色。\n引申意思：絕境中出現轉機（如：事情陷入僵局，沒想到柳暗花明）。" },
  { id: "i066", grade: 4, term: "峰迴路轉", zhuyin: "ㄈㄥ ㄏㄨㄟˊ ㄌㄨˋ ㄓㄨㄢˇ", pinyin: "fēng huí lù zhuǎn", meaning: "山路迂迴曲折，比喻柳暗花明又一村。", example: "經過多次失敗，終於峰迴路轉，成功在望。" , wordExp: "峰＝山峰；迴＝迂迴；路轉＝道路轉彎。山路迂迴後豁然開朗，情勢好轉。",deep:"典故由來：語本宋．歐陽修〈醉翁亭記〉：「峰迴路轉，有亭翼然臨於泉上者。」\n字面意思：山峰迴繞、道路轉彎。\n引申意思：事情經曲折後出現轉機（如：談判峰迴路轉，終於達成協議）。" },
  { id: "i067", grade: 5, term: "一鳴驚人", zhuyin: "ㄧ ㄇㄧㄥˊ ㄐㄧㄥ ㄖㄣˊ", pinyin: "yī míng jīng rén", meaning: "初次發聲就引起驚人注意。", example: "他以一鳴驚人之勢，贏得了全國冠軍。" , wordExp: "一鳴＝叫一聲；驚人＝震驚眾人。不叫則已，一叫驚人，平時不顯眼、一出手就轟動。",deep:"典故由來：出自《史記．滑稽列傳》：齊威王沉迷享樂三年不理政事，淳于髡以謎語問「有鳥三年不飛不鳴」，威王答：「此鳥不飛則已，一飛沖天；不鳴則已，一鳴驚人。」從此發憤圖強。\n字面意思：一叫出聲就使人震驚。\n引申意思：平時默默無聞，一有表現就震驚眾人（如：新人首場比賽一鳴驚人）。褒義。" },
  { id: "i068", grade: 5, term: "厚積薄發", zhuyin: "ㄏㄡˋ ㄐㄧ ㄅㄠˊ ㄈㄚ", pinyin: "hòu jī báo fā", meaning: "長期累積，爆發時力量強大。", example: "他的成功源於厚積薄發的準備。" , wordExp: "厚積＝深厚地累積；薄發＝少量地釋放。累積深厚，才能從容發揮。",deep:"典故由來：出自宋．蘇軾〈稼說送張琥〉：「博觀而約取，厚積而薄發。」\n字面意思：厚厚地累積，慢慢地釋放。\n引申意思：長期充分準備，發揮時才有強大力量（如：他厚積薄發，中年後成就非凡）。褒義。" },
  { id: "i069", grade: 5, term: "海納百川", zhuyin: "ㄏㄞˇ ㄋㄚˋ ㄅㄞˇ ㄔㄨㄢ", pinyin: "hǎi nà bǎi chuān", meaning: "寬容開放，包容各種意見。", example: "優秀的領導者應該海納百川。" , wordExp: "海＝大海；納＝容納；百川＝眾多河流。大海容得下百川，胸襟寬廣。",deep:"典故由來：語本林則徐自勉聯：「海納百川，有容乃大；壁立千仞，無欲則剛。」\n字面意思：大海容納千百條江河。\n引申意思：心胸寬廣，能包容各方意見（如：主管海納百川，廣聽建言）。褒義。" },
  { id: "i070", grade: 5, term: "百尺竿頭", zhuyin: "ㄅㄞˇ ㄔˇ ㄍㄢ ㄊㄡˊ", pinyin: "bǎi chǐ gān tóu", meaning: "已達最高點，還要更進一步。", example: "在百尺竿頭的境界，還要繼續精進。" , wordExp: "百尺＝百尺高；竿頭＝竹竿頂端。已到竿頂仍要更進一步，好上加好。",deep:"典故由來：出自宋．《景德傳燈錄》：招賢大師偈語「百尺竿頭須進步，十方世界是全身」。\n字面意思：百尺高竿的頂端。\n引申意思：成就已高，仍要努力向上（常說「百尺竿頭，更進一步」）。褒義。" },
  // Grade 7-9 (80條 — 中學程度)
  { id: "i071", grade: 7, term: "不言而喻", zhuyin: "ㄅㄨˋ ㄧㄢˊ ㄦˊ ㄩˋ", pinyin: "bù yán ér yù", meaning: "不用說就能理解，不言自明。", example: "這個道理不言而喻，不需要多解釋。" , wordExp: "不言＝不必說；而喻＝就明白。道理明顯，不用說也懂。",deep:"典故由來：語本《孟子．盡心上》：「施於四體，四體不言而喻。」\n字面意思：不必說就明白。\n引申意思：道理明顯，無須解釋（如：他的用心不言而喻）。" },
  { id: "i072", grade: 7, term: "才高八斗", zhuyin: "ㄘㄞˊ ㄍㄠ ㄅㄚ ㄉㄡˇ", pinyin: "cái gāo bā dǒu", meaning: "才華橫溢，聰慧傑出。", example: "這位作家才高八斗，著作等身。", misuse: "不是真的有八斗多才華。" , wordExp: "才＝才華；高＝高達；八斗＝十分之八。天下才共一石，曹植獨占八斗，才華蓋世。",deep:"典故由來：南朝宋．謝靈運自評：「天下才有一石，曹子建（曹植）獨占八斗，我得一斗，天下共分一斗。」\n字面意思：才華占了八斗（一石為十斗）。\n引申意思：才學極高（如：他才高八斗，出口成章）。褒義。" },
  { id: "i073", grade: 7, term: "差強人意", zhuyin: "ㄔㄚˋ ㄑㄧㄤˇ ㄖㄣˊ ㄧˋ", pinyin: "chà qiǎng rén yì", meaning: "基本令人滿意，雖有不足但尚可。", example: "他的表現差強人意，勉強及格。", misuse: "常被誤用為表示不夠滿意。" , wordExp: "差＝稍微、大致；強＝振奮；人意＝人的心意。大體上還能讓人滿意。",deep:"典故由來：出自《後漢書．吳漢傳》：光武帝讚吳漢每逢戰事仍整兵備戰，說「吳公差強人意」——大體上還能振奮人意。\n字面意思：大致上還能使人滿意（差＝稍微、大致）。\n引申意思：勉強令人滿意（如：成績差強人意）。注意：不是「令人不滿意」，是「還過得去」，常被誤用。" },
  { id: "i074", grade: 7, term: "緣木求魚", zhuyin: "ㄩㄢˊ ㄇㄨˋ ㄑㄧㄡˊ ㄩˊ", pinyin: "yuán mù qiú yú", meaning: "方法根本錯誤，不可能成功。", example: "用這種方法去解決問題就像緣木求魚。", misuse: "不是真的在樹上找魚。" , wordExp: "緣＝攀爬；木＝樹；求＝找；魚＝魚。爬到樹上找魚，方向方法全錯。",deep:"典故由來：出自《孟子．梁惠王上》：孟子勸梁惠王，以武力求霸「猶緣木而求魚也」。\n字面意思：爬到樹上找魚。\n引申意思：方向方法錯誤，絕不可能達到目的（如：不讀書想考好，無異緣木求魚）。貶義。" },
  { id: "i075", grade: 7, term: "萬古長青", zhuyin: "ㄨㄢˋ ㄍㄨˇ ㄔㄤˊ ㄑㄧㄥ", pinyin: "wàn gǔ cháng qīng", meaning: "永遠不衰，常青不朽。", example: "偉人的精神永遠萬古長青。" , wordExp: "萬古＝千秋萬代；長青＝永遠常綠。永不衰老凋零。",deep:"典故由來：由字面組合而成；松柏長青的意象。\n字面意思：萬年長久，永遠青翠。\n引申意思：精神事業永不衰退（如：願友誼萬古長青）。褒義。" },
  { id: "i076", grade: 7, term: "文質彬彬", zhuyin: "ㄨㄣˊ ㄓˋ ㄅㄧㄣ ㄅㄧㄣ", pinyin: "wén zhì bīn bīn", meaning: "文雅、溫和、有禮貌。", example: "他言談舉止文質彬彬，很有修養。" , wordExp: "文＝文采；質＝本質；彬彬＝配合均勻。文雅與樸實兼備，謙和有禮。",deep:"典故由來：出自《論語．雍也》：「質勝文則野，文勝質則史。文質彬彬，然後君子。」\n字面意思：文采與質樸配合得宜（彬彬＝相雜適中）。\n引申意思：形容人溫文有禮（如：他文質彬彬，談吐斯文）。褒義。" },
  { id: "i077", grade: 7, term: "韋編三絕", zhuyin: "ㄨㄟˊ ㄅㄧㄢ ㄙㄢ ㄐㄩㄝˊ", pinyin: "wéi biān sān jué", meaning: "比喻勤奮讀書，愛護書籍。", example: "孔子韋編三絕，展現對學問的執著。" , wordExp: "韋＝熟牛皮繩；編＝串連竹簡；三絕＝斷了三次。孔子讀易，皮繩都翻斷三次，勤讀不倦。",deep:"典故由來：出自《史記．孔子世家》：孔子晚年喜讀《易經》，翻閱太勤，串竹簡的皮繩斷了三次。\n字面意思：皮繩斷了三次（韋＝熟牛皮繩）。\n引申意思：讀書勤奮刻苦（如：韋編三絕的精神值得學習）。褒義。" },
  { id: "i078", grade: 7, term: "德高望重", zhuyin: "ㄉㄜˊ ㄍㄠ ㄨㄤˋ ㄓㄨㄥˋ", pinyin: "dé gāo wàng zhòng", meaning: "道德高尚，聲望很高。", example: "敬重的老師是德高望重的典範。" , wordExp: "德＝品德；高＝崇高；望＝聲望；重＝厚重。品德聲望都令人敬重。",deep:"典故由來：語本《晉書》「德隆望重」。\n字面意思：品德崇高、聲望隆重。\n引申意思：德行聲望俱高的長者（如：德高望重的老校長）。褒義。" },
  { id: "i079", grade: 7, term: "志在千里", zhuyin: "ㄓˋ ㄗㄞˋ ㄑㄧㄢ ㄌㄧˇ", pinyin: "zhì zài qiān lǐ", meaning: "志向遠大，抱負不凡。", example: "他年紀輕輕已志在千里。" , wordExp: "志＝志向；在千里＝在千里之外。老驥伏櫪仍志在千里，抱負遠大。",deep:"典故由來：出自曹操〈龜雖壽〉：「老驥伏櫪，志在千里；烈士暮年，壯心不已。」\n字面意思：（老馬）志向仍在千里之外。\n引申意思：抱負遠大（如：他年過六十仍志在千里）。褒義。" },
  { id: "i080", grade: 7, term: "初出茅廬", zhuyin: "ㄔㄨ ㄔㄨ ㄇㄠˊ ㄌㄨˊ", pinyin: "chū chū máo lú", meaning: "初入社會，初涉人世，經驗不足。", example: "他初出茅廬就獲得了重用。" , wordExp: "初＝初次；出＝走出；茅廬＝草屋。諸葛亮初出草廬，剛踏入社會、缺乏歷練。",deep:"典故由來：出自《三國演義》：諸葛亮出山後首戰火燒博望坡，詩讚「直須驚破曹公膽，初出茅廬第一功」。\n字面意思：剛走出草廬。\n引申意思：剛進入社會、缺乏經驗（如：初出茅廬的新鮮人）。也可指初試身手。" },
  { id: "i081", grade: 7, term: "乘風破浪", zhuyin: "ㄔㄥˊ ㄈㄥ ㄆㄛˋ ㄌㄤˋ", pinyin: "chéng fēng pò làng", meaning: "比喻乘勢前進，勇往直前。", example: "青年人應該乘風破浪，開創新局。" , wordExp: "乘＝駕著；風＝長風；破＝衝破；浪＝巨浪。乘長風破萬里浪，志向遠大、勇往直前。",deep:"典故由來：出自《宋書．宗慤傳》：宗慤少年時言志：「願乘長風破萬里浪。」\n字面意思：駕著長風衝破巨浪。\n引申意思：不畏艱險、奮勇前進（如：乘風破浪開創事業）。褒義。" },
  { id: "i082", grade: 7, term: "志同道合", zhuyin: "ㄓˋ ㄊㄨㄥˊ ㄉㄠˋ ㄏㄜˊ", pinyin: "zhì tóng dào hé", meaning: "目標相同，理想一致。", example: "兩人志同道合，決定一起創業。" , wordExp: "志＝志向；同＝相同；道＝理念；合＝契合。志向理念一致。",deep:"典故由來：語本《三國志》「志同道合」的用例。\n字面意思：志向相同、道路一致。\n引申意思：理想目標一致（如：一群志同道合的朋友）。褒義。" },
  { id: "i083", grade: 7, term: "任重道遠", zhuyin: "ㄖㄣˋ ㄓㄨㄥˋ ㄉㄠˋ ㄩㄢˇ", pinyin: "rèn zhòng dào yuǎn", meaning: "責任重大，路途遠長。", example: "改革開放的事業任重道遠。" , wordExp: "任＝責任；重＝沉重；道＝路途；遠＝遙遠。擔子重、路途遠，責任重大。",deep:"典故由來：出自《論語．泰伯》：曾子曰：「士不可以不弘毅，任重而道遠。仁以為己任，不亦重乎？死而後已，不亦遠乎？」\n字面意思：擔子沉重，路途遙遠。\n引申意思：責任重大且須長期努力（如：環保工作任重道遠）。" },
  { id: "i084", grade: 7, term: "卓爾不群", zhuyin: "ㄓㄨㄛˊ ㄦˇ ㄅㄨˋ ㄑㄩㄣˊ", pinyin: "zhuó ěr bù qún", meaning: "傑出優秀，與眾不同。", example: "他的才能卓爾不群，令人印象深刻。" , wordExp: "卓爾＝高高直立的樣子；不群＝不同於眾。才德超群出眾。",deep:"典故由來：出自《漢書．景十三王傳贊》：「夫唯大雅，卓爾不群。」\n字面意思：高高特立，不與眾人相同。\n引申意思：才德超群出眾（如：見解卓爾不群）。褒義。" },
  { id: "i085", grade: 7, term: "胸有成竹", zhuyin: "ㄒㄩㄥ ㄧㄡˇ ㄔㄥˊ ㄓㄨˊ", pinyin: "xiōng yǒu chéng zhú", meaning: "做事很有把握，心中早有計畫。", example: "他上台演講前胸有成竹，表現完美。" , wordExp: "胸＝心中；有＝已有；成竹＝完整的竹子。畫竹前心中已有竹形，事先已有把握。",deep:"典故由來：出自宋．蘇軾〈文與可畫篔簹谷偃竹記〉：「故畫竹必先得成竹於胸中。」畫家文同畫竹前，心中已有完整竹形。\n字面意思：胸中已有畫成的竹子。\n引申意思：做事前已有完整把握（如：他胸有成竹地走上台）。褒義。" },
  { id: "i086", grade: 7, term: "千錘百煉", zhuyin: "ㄑㄧㄢ ㄔㄨㄟˊ ㄅㄞˇ ㄌㄧㄢˋ", pinyin: "qiān chuí bǎi liàn", meaning: "經過多次反覆錘煉，使成完美。", example: "這部作品千錘百煉，達到完美。" , wordExp: "千、百＝多次；錘＝錘打；煉＝冶煉。反覆錘打冶煉，久經磨練。",deep:"典故由來：源自冶金鍛造：金屬須千百次錘打提煉才成利器。\n字面意思：千次錘打、百次冶煉。\n引申意思：經歷多次磨練考驗而成熟完美（如：千錘百煉的文筆）。褒義。" },
  { id: "i087", grade: 7, term: "自強不息", zhuyin: "ㄗˋ ㄑㄧㄤˊ ㄅㄨˋ ㄒㄧ", pinyin: "zì qiáng bù xī", meaning: "自我奮鬥，不懈努力。", example: "民族要自強不息，才能興盛。" , wordExp: "自強＝自己奮發圖強；不息＝不停止。不斷努力，永不鬆懈。",deep:"典故由來：出自《易經．乾卦》：「天行健，君子以自強不息。」\n字面意思：自己努力向上，永不停息。\n引申意思：不斷奮發進取（如：自強不息的精神）。褒義。" },
  { id: "i088", grade: 7, term: "厚德載物", zhuyin: "ㄏㄡˋ ㄉㄜˊ ㄗㄞˋ ㄨˋ", pinyin: "hòu dé zài wù", meaning: "道德高尚，能承載萬物。", example: "君子應有厚德載物的胸懷。" , wordExp: "厚＝深厚；德＝德行；載＝承載；物＝萬物。以深厚德行容載萬物。",deep:"典故由來：出自《易經．坤卦》：「地勢坤，君子以厚德載物。」\n字面意思：以深厚的德行承載萬物。\n引申意思：品德寬厚能包容一切（如：厚德載物是他的座右銘）。褒義。" },
  { id: "i089", grade: 7, term: "寧靜致遠", zhuyin: "ㄋㄧㄥˊ ㄐㄧㄥˋ ㄓˋ ㄩㄢˇ", pinyin: "níng jìng zhì yuǎn", meaning: "淡泊寧靜才能達到遠大志向。", example: "成功需要寧靜致遠的心態。" , wordExp: "寧靜＝安寧清靜；致遠＝達到遠大目標。心境澄靜才能成就深遠。",deep:"典故由來：出自諸葛亮〈誡子書〉：「非淡泊無以明志，非寧靜無以致遠。」（語本《淮南子》）\n字面意思：心境寧靜才能到達遠大目標。\n引申意思：不浮躁才能成就大志（如：寧靜致遠，沉住氣做學問）。褒義。" },
  { id: "i090", grade: 7, term: "明德格物", zhuyin: "ㄇㄧㄥˊ ㄉㄜˊ ㄍㄜˊ ㄨˋ", pinyin: "míng dé gé wù", meaning: "闡明品德，窮究事物。", example: "儒家強調明德格物的修養。" , wordExp: "明德＝彰明德性；格物＝推究事物之理。修明德行、探究事理。",deep:"典故由來：語本《禮記．大學》：「大學之道，在明明德」「致知在格物」。\n字面意思：彰明德性、窮究事理。\n引申意思：修養品德、探究學問的治學理想（多用於校訓）。褒義。" },
  { id: "i091", grade: 7, term: "修身齊家", zhuyin: "ㄒㄧㄡ ㄕㄣ ㄑㄧˊ ㄐㄧㄚ", pinyin: "xiū shēn qí jiā", meaning: "先修養自己，再管理家庭。", example: "儒家重視修身齊家的次序。" , wordExp: "修身＝修養自身；齊家＝治理家庭。先修己再治家，儒家進德次第。",deep:"典故由來：出自《禮記．大學》：「修身、齊家、治國、平天下。」\n字面意思：修養自身、整治家庭。\n引申意思：先充實自己再承擔更大責任（如：修身齊家是成事的根本）。褒義。" },
  { id: "i092", grade: 7, term: "立德立功", zhuyin: "ㄌㄧˋ ㄉㄜˊ ㄌㄧˋ ㄍㄨㄥ", pinyin: "lì dé lì gōng", meaning: "建立品德和功績。", example: "人生應該立德立功立言。" , wordExp: "立德＝樹立德行；立功＝建立功業。古人三不朽的前兩項。",deep:"典故由來：出自《左傳．襄公二十四年》「三不朽」：「太上有立德，其次有立功，其次有立言。」\n字面意思：建立德行、建立功業。\n引申意思：德業兼修、有所建樹（如：立德立功，留名後世）。褒義。" },
  { id: "i093", grade: 7, term: "發奮圖強", zhuyin: "ㄈㄚ ㄈㄣˋ ㄊㄨˊ ㄑㄧㄤˊ", pinyin: "fā fèn tú qiáng", meaning: "努力奮鬥，力求進步。", example: "國家發奮圖強，要靠全民共同努力。" , wordExp: "發奮＝振作起來；圖＝謀求；強＝強盛。振作精神，力求強盛。",deep:"典故由來：近代組合成語，與「發憤圖強」同義並用。\n字面意思：振奮精神，謀求強盛。\n引申意思：下決心努力求進步（如：發奮圖強，迎頭趕上）。褒義。" },
  { id: "i094", grade: 7, term: "孜孜不倦", zhuyin: "ㄗ ㄗ ㄅㄨˋ ㄐㄩㄢˋ", pinyin: "zī zī bù juàn", meaning: "辛勤工作，毫不懈怠。", example: "教師孜孜不倦地傳授知識。" , wordExp: "孜孜＝勤勉不懈的樣子；不倦＝不知疲倦。勤奮努力不休息。",deep:"典故由來：語本《尚書》：「惟日孜孜，無敢逸豫。」\n字面意思：勤勉不知疲倦（孜孜＝勤勉不懈）。\n引申意思：勤奮不懈（如：孜孜不倦地研究）。褒義。" },
  { id: "i095", grade: 7, term: "奮發有為", zhuyin: "ㄈㄣˋ ㄈㄚ ㄧㄡˇ ㄨㄟˊ", pinyin: "fèn fā yǒu wéi", meaning: "努力進取，大有作為。", example: "年輕人應該奮發有為，實現夢想。" , wordExp: "奮發＝振奮昂揚；有為＝有作為。精神振作，有一番作為。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：振奮而起，有所作為。\n引申意思：積極進取、能成大事（如：奮發有為的青年）。褒義。" },
  { id: "i096", grade: 7, term: "韜光養晦", zhuyin: "ㄊㄠ ㄍㄨㄤ ㄧㄤˇ ㄏㄨㄟˋ", pinyin: "tāo guāng yǎng huì", meaning: "隱藏才能，蓄勢待發。", example: "他採取韜光養晦的策略，等待機會。" , wordExp: "韜＝收藏（弓袋）；光＝鋒芒；養晦＝隱晦自處。收斂鋒芒，隱藏才能等待時機。",deep:"典故由來：語本「韜光」（收藏光芒，《晉書》有「韜光遁世」）；韜是劍袋，引申為收藏。\n字面意思：收起光芒，在暗處修養。\n引申意思：隱藏才能、暫不出頭，等待時機（如：他韜光養晦多年，一出手便不同凡響）。" },
  { id: "i097", grade: 7, term: "寶貴難求", zhuyin: "ㄅㄠˇ ㄍㄨㄟˋ ㄋㄢˊ ㄑㄧㄡˊ", pinyin: "bǎo guì nán qiú", meaning: "珍貴的東西難以求得，比喻人才難遇。", example: "像他這樣的人才寶貴難求。" , wordExp: "寶貴＝珍貴之物；難求＝難以求得。珍稀難得。",deep:"典故由來：由字面組合而成。\n字面意思：珍貴而難以求得。\n引申意思：珍稀難得（如：這樣的人才寶貴難求）。" },
  { id: "i098", grade: 7, term: "矢志不移", zhuyin: "ㄕˇ ㄓˋ ㄅㄨˋ ㄧˊ", pinyin: "shǐ zhì bù yí", meaning: "誓願堅定，決心不變。", example: "他矢志不移地追求音樂夢想。" , wordExp: "矢＝發誓；志＝志向；不移＝不改變。立誓不改其志。",deep:"典故由來：由字面組合而成；「矢」通「誓」。\n字面意思：立誓的志向不改變。\n引申意思：意志堅定不移（如：矢志不移地追求理想）。褒義。" },
  { id: "i099", grade: 7, term: "發憤圖強", zhuyin: "ㄈㄚ ㄈㄣˋ ㄊㄨˊ ㄑㄧㄤˊ", pinyin: "fā fèn tú qiáng", meaning: "下定決心，努力進取。", example: "面對挑戰，他決定發憤圖強。" , wordExp: "發憤＝下定決心；圖強＝謀求富強。決心奮鬥求進步。",deep:"典故由來：語本《論語．述而》：孔子自述「發憤忘食，樂以忘憂」。\n字面意思：下定決心，謀求強盛。\n引申意思：決心奮鬥求進步（如：戰後全國發憤圖強）。褒義。" },
  { id: "i100", grade: 8, term: "舍本逐末", zhuyin: "ㄕㄜˇ ㄅㄣˇ ㄓㄨˊ ㄇㄛˋ", pinyin: "shě běn zhú mò", meaning: "放棄根本，追求末節。", example: "讀書不能舍本逐末，要抓住核心。", misuse: "不是字面的本和末。",deep:"典故由來：語本《呂氏春秋．上農》論治國「舍本而事末」；本指農業，末指工商。\n字面意思：捨棄根本，追逐枝末。\n引申意思：忽略根本要務，只顧細枝末節（如：只背題不懂原理是舍本逐末）。貶義。" },
  { id: "i101", grade: 8, term: "歷久彌新", zhuyin: "ㄌㄧˋ ㄐㄧㄡˇ ㄇㄧˊ ㄒㄧㄣ", pinyin: "lì jiǔ mí xīn", meaning: "經久不衰，越來越新鮮。", example: "古典文學歷久彌新，魅力永恆。",deep:"典故由來：由字面組合而成；「彌」是更加。\n字面意思：經歷長久反而更新。\n引申意思：長久流傳而不失新意（如：經典作品歷久彌新）。褒義。" },
  { id: "i102", grade: 8, term: "與時俱進", zhuyin: "ㄩˇ ㄕˊ ㄐㄩˋ ㄐㄧㄣˋ", pinyin: "yǔ shí jù jìn", meaning: "跟隨時代進步，不斷創新。", example: "企業必須與時俱進，才能競爭。",deep:"典故由來：近代用語（蔡元培等人文章已見）。\n字面意思：跟著時代一起前進。\n引申意思：隨時代進步不斷更新（如：教學方法要與時俱進）。褒義。" },
  { id: "i103", grade: 8, term: "因人而異", zhuyin: "ㄧㄣ ㄖㄣˊ ㄦˊ ㄧˋ", pinyin: "yīn rén ér yì", meaning: "根據人的不同特點而有所區別。", example: "教育應該因人而異，注重個性發展。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：因為人不同而有差異。\n引申意思：依各人情況而不同（如：學習成效因人而異）。" },
  { id: "i104", grade: 8, term: "錦上添花", zhuyin: "ㄐㄧㄣˇ ㄕㄤˋ ㄊㄧㄢ ㄏㄨㄚ", pinyin: "jǐn shàng tiān huā", meaning: "在好的基礎上再加美妙。", example: "你的建議是錦上添花，使計劃更完美。",deep:"典故由來：語本宋．王安石〈即事〉詩：「麗唱仍添錦上花。」\n字面意思：在錦緞上再繡花。\n引申意思：好上加好（如：球隊奪冠，明星加盟更是錦上添花）。常與「雪中送炭」對舉。" },
  { id: "i105", grade: 8, term: "雪中送炭", zhuyin: "ㄒㄩㄝˇ ㄓㄨㄥ ㄙㄨㄥˋ ㄊㄢˋ", pinyin: "xuě zhōng sòng tàn", meaning: "在困難時刻提供幫助。", example: "朋友的幫助是雪中送炭，我永遠感激。",deep:"典故由來：語本宋．范成大詩：「不是雪中須送炭，聊裝風景要詩來。」宋太宗雪天賜炭給貧民的記載亦傳為典源。\n字面意思：下雪天送炭火給人取暖。\n引申意思：在別人急難時給予幫助（如：這筆捐款是雪中送炭）。褒義；相對詞：錦上添花、落井下石。" },
  { id: "i106", grade: 8, term: "瓜田李下", zhuyin: "ㄍㄨㄚ ㄊㄧㄢˊ ㄌㄧˇ ㄒㄧㄚˋ", pinyin: "guā tián lǐ xià", meaning: "會引起誤會的地方要避開，防患於未然。", example: "做人要瓜田李下，不給人閒話的機會。", misuse: "不是真的在瓜田裡。",deep:"典故由來：出自古樂府〈君子行〉：「瓜田不納履，李下不正冠。」在瓜田不彎腰提鞋、李樹下不舉手整帽，免被疑偷瓜摘李。\n字面意思：瓜田裡、李樹下。\n引申意思：容易引起嫌疑的場合要避開（如：身為出納避免瓜田李下，帳目全程公開）。" },
  { id: "i107", grade: 8, term: "勞而無功", zhuyin: "ㄌㄠˊ ㄦˊ ㄨˊ ㄍㄨㄥ", pinyin: "láo ér wú gōng", meaning: "費力但沒有成就。", example: "用錯方法，再努力也勞而無功。",deep:"典故由來：出自《管子．形勢》：「與不可，強不能，告不知，謂之勞而無功。」\n字面意思：辛勞卻沒有功效。\n引申意思：白費力氣（如：方向錯了，再努力也勞而無功）。貶義。" },
  { id: "i108", grade: 8, term: "囊螢映雪", zhuyin: "ㄋㄤˊ ㄧㄥˊ ㄧㄥˋ ㄒㄩㄝˇ", pinyin: "náng yíng yìng xuě", meaning: "古人刻苦讀書的典故，比喻勤奮。", example: "古人囊螢映雪，為我們樹立了好榜樣。",deep:"典故由來：《晉書．車胤傳》：車胤家貧無油，夏夜捕螢火蟲裝入囊中照書；孫康冬夜映著雪光讀書。\n字面意思：用袋裝螢火蟲、映著雪光（讀書）。\n引申意思：家貧而刻苦勤學（如：囊螢映雪的精神）。褒義。" },
  { id: "i109", grade: 8, term: "鑿壁偷光", zhuyin: "ㄗㄠˊ ㄅㄧˋ ㄊㄡ ㄍㄨㄤ", pinyin: "záo bì tōu guāng", meaning: "比喻窮困而勤奮讀書。", example: "他鑿壁偷光的精神感動了所有人。",deep:"典故由來：出自《西京雜記》：匡衡家貧，鑿穿牆壁引鄰家燭光讀書，後成大學問家。\n字面意思：鑿開牆壁偷借燭光。\n引申意思：克服困境勤奮向學（如：鑿壁偷光的苦讀故事）。褒義。" },
  { id: "i110", grade: 8, term: "刻苦銘心", zhuyin: "ㄎㄜˋ ㄎㄨˇ ㄇㄧㄥˊ ㄒㄧㄣ", pinyin: "kè kǔ míng xīn", meaning: "牢牢記在心裡，永遠不忘。", example: "這次教訓刻苦銘心，我永遠不會再犯。",deep:"典故由來：語本李白〈上安州李長史書〉「銘刻心骨」；今多作「刻骨銘心」。\n字面意思：刻進骨頭、銘記於心。\n引申意思：感受或恩情深刻難忘（如：這個教訓刻苦銘心）。" },
  { id: "i111", grade: 8, term: "一葉知秋", zhuyin: "ㄧ ㄧㄝˋ ㄓ ㄑㄧㄡ", pinyin: "yī yè zhī qiū", meaning: "從一片落葉看出秋天到了，比喻知微見著。", example: "從這件小事可以一葉知秋，看出大問題。",deep:"典故由來：語本《淮南子．說山訓》：「見一葉落而知歲之將暮。」\n字面意思：看見一片葉子落下，就知道秋天來了。\n引申意思：由細微跡象推知整體趨勢（如：銷量下滑是一葉知秋的警訊）。" },
  { id: "i112", grade: 8, term: "由淺入深", zhuyin: "ㄧㄡˊ ㄑㄧㄢˇ ㄖㄨˋ ㄕㄣ", pinyin: "yóu qiǎn rù shēn", meaning: "從簡單的開始，逐漸深入。", example: "教學應該由淺入深，循序漸進。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：從淺處進入深處。\n引申意思：循序漸進（如：課程由淺入深）。褒義。" },
  { id: "i113", grade: 8, term: "聞雞起舞", zhuyin: "ㄨㄣˊ ㄐㄧ ㄑㄧˇ ㄨˇ", pinyin: "wén jī qǐ wǔ", meaning: "一聽到雞叫就起身練習，比喻立志發奮。", example: "他學習祖逖聞雞起舞的精神。",deep:"典故由來：出自《晉書．祖逖傳》：祖逖與劉琨共被同寢，半夜聽到雞鳴，踢醒劉琨說「此非惡聲也」，起身舞劍鍛鍊，後皆成名將。\n字面意思：聽到雞叫就起來舞劍。\n引申意思：及時奮發、立志勤練（如：聞雞起舞，每天晨跑）。褒義。" },
  { id: "i114", grade: 8, term: "廢寢忘食", zhuyin: "ㄈㄟˋ ㄑㄧㄣˇ ㄨㄤˋ ㄕˊ", pinyin: "fèi qǐn wàng shí", meaning: "因為全心投入而忘記睡眠和進食。", example: "他為研究項目廢寢忘食。",deep:"典故由來：語本《論語．述而》「發憤忘食」；南朝以後凝為「廢寢忘食」。\n字面意思：不睡覺、忘了吃飯。\n引申意思：專心努力到顧不上生活作息（如：廢寢忘食地趕實驗）。褒義。" },
  { id: "i115", grade: 8, term: "見風轉舵", zhuyin: "ㄐㄧㄢˋ ㄈㄥ ㄓㄨㄢˇ ㄉㄨㄛˋ", pinyin: "jiàn fēng zhuǎn duò", meaning: "看勢頭轉變立場，善於投機。", example: "這個商人見風轉舵，從不講原則。", misuse: "常被誤用為靈活適應。",deep:"典故由來：語本宋．《五燈會元》「看風使舵」。\n字面意思：看風向轉動船舵。\n引申意思：隨情勢改變立場，投機取巧（如：他見風轉舵，立刻改口）。貶義。" },
  { id: "i116", grade: 8, term: "臨陣退縮", zhuyin: "ㄌㄧㄣˊ ㄓㄣˋ ㄊㄨㄟˋ ㄙㄨㄛ", pinyin: "lín zhèn tuì suō", meaning: "在戰鬥前害怕退縮，比喻臨時逃避。", example: "做事不能臨陣退縮，要堅持到底。",deep:"典故由來：由字面組合而成；臨陣＝到了陣前。\n字面意思：到了陣前卻退縮。\n引申意思：關鍵時刻膽怯逃避（如：不能臨陣退縮）。貶義。" },
  { id: "i117", grade: 8, term: "背水一戰", zhuyin: "ㄅㄟˋ ㄕㄨㄟˇ ㄧ ㄓㄢˋ", pinyin: "bèi shuǐ yī zhàn", meaning: "背靠河水陣營，沒有退路，必須全力作戰。", example: "這次考試是背水一戰，非考不可。",deep:"典故由來：出自《史記．淮陰侯列傳》：韓信攻趙，背著河水布陣，士兵無路可退，人人死戰，大破趙軍——「陷之死地而後生」。\n字面意思：背靠河水作戰。\n引申意思：抱著決一死戰的心全力一搏（如：這場比賽是背水一戰）。" },
  { id: "i118", grade: 8, term: "十年寒窗", zhuyin: "ㄕˊ ㄋㄧㄢˊ ㄏㄢˊ ㄔㄨㄤ", pinyin: "shí nián hán chuāng", meaning: "長期寒苦讀書，比喻勤奮。", example: "十年寒窗終於換來成功。",deep:"典故由來：語本元．劉祁《歸潛志》：「古人謂十年窗下無人問，一舉成名天下知。」\n字面意思：十年在寒冷窗下苦讀。\n引申意思：長年刻苦讀書（如：十年寒窗，終於金榜題名）。" },
  { id: "i119", grade: 8, term: "棄甲曳兵", zhuyin: "ㄑㄧˋ ㄐㄧㄚˇ ㄧㄝˋ ㄅㄧㄥ", pinyin: "qì jiǎ yè bīng", meaning: "拋棄武器逃跑，比喻潰不成軍。", example: "敵軍棄甲曳兵，我軍乘勝追擊。",deep:"典故由來：出自《孟子．梁惠王上》：戰敗士兵「棄甲曳兵而走，或百步而後止」。\n字面意思：丟掉鎧甲、拖著兵器逃跑。\n引申意思：打敗仗狼狽逃散（如：敵軍棄甲曳兵而逃）。貶義。" },
  { id: "i120", grade: 9, term: "不知所云", zhuyin: "ㄅㄨˋ ㄓ ㄙㄨㄛˇ ㄩㄣˊ", pinyin: "bù zhī suǒ yún", meaning: "不知道在說什麼，言辭不清。", example: "他的說法不知所云，讓人困惑。",deep:"典故由來：出自諸葛亮〈出師表〉：「臨表涕零，不知所云。」原是謙詞，說自己激動得不知說了什麼。\n字面意思：不知道說的是什麼。\n引申意思：今多批評別人言語混亂、抓不到重點（如：這篇文章不知所云）。貶義；注意與原典謙詞用法不同。" },
  { id: "i121", grade: 9, term: "莫衷一是", zhuyin: "ㄇㄛˋ ㄓㄨㄥ ㄧ ㄕˋ", pinyin: "mò zhōng yī shì", meaning: "各有各的看法，不能一致。", example: "對於這個問題，大家莫衷一是。",deep:"典故由來：清代文獻常見；「衷」是折中定論。\n字面意思：無法折中出一個定論。\n引申意思：眾說紛紜、意見無法一致（如：專家看法莫衷一是）。" },
  { id: "i122", grade: 9, term: "殫精竭慮", zhuyin: "ㄉㄢ ㄐㄧㄥ ㄐㄧㄝˊ ㄌㄩˋ", pinyin: "dān jīng jié lǜ", meaning: "費盡心力，用盡思慮。", example: "他殫精竭慮地為公司解決問題。",deep:"典故由來：語本唐．白居易〈策林〉「殫思極慮」；殫、竭都是用盡。\n字面意思：用盡精力、竭盡思慮。\n引申意思：費盡心思（如：殫精竭慮規劃改革）。褒義。" },
  { id: "i123", grade: 9, term: "語無倫次", zhuyin: "ㄩˇ ㄨˊ ㄌㄨㄣˊ ㄘˋ", pinyin: "yǔ wú lún cì", meaning: "說話沒有次序，言辭混亂。", example: "緊張時他常語無倫次。",deep:"典故由來：宋代文獻已見；「倫次」是條理次序。\n字面意思：說話沒有條理次序。\n引申意思：言辭混亂（如：他嚇得語無倫次）。貶義。" },
  { id: "i124", grade: 9, term: "含英咀華", zhuyin: "ㄏㄢˊ ㄧㄥ ㄐㄩˇ ㄏㄨㄚˊ", pinyin: "hán yīng jǔ huá", meaning: "品味文章精華，細心品賞。", example: "讀古詩要含英咀華，體會其妙。",deep:"典故由來：出自唐．韓愈〈進學解〉：「沉浸醲郁，含英咀華。」\n字面意思：口中含著花朵、細嚼花的精華。\n引申意思：細細品味詩文的精華（如：讀古文要含英咀華）。褒義。" },
  { id: "i125", grade: 9, term: "文風不動", zhuyin: "ㄨㄣˊ ㄈㄥ ㄅㄨˋ ㄉㄨㄥˋ", pinyin: "wén fēng bù dòng", meaning: "衣服沒有被吹動，比喻穩定沉著。", example: "他面對危急文風不動，毫不驚惶。",deep:"典故由來：明清小說常見的口語成語（《紅樓夢》等）。\n字面意思：連一絲風都吹不動。\n引申意思：絲毫不動、非常穩固（如：任人搖晃，櫃子文風不動）。" },
  { id: "i126", grade: 9, term: "談笑自若", zhuyin: "ㄊㄢˊ ㄒㄧㄠˋ ㄗˋ ㄖㄨㄛˋ", pinyin: "tán xiào zì ruò", meaning: "談笑間很自然，比喻從容不迫。", example: "他談笑自若地處理了這個危機。",deep:"典故由來：語本《三國志》等史書「談笑自若」：大將臨敵仍談笑如常。\n字面意思：談笑如同平常一樣。\n引申意思：危急中依然鎮定（如：面對質問，他談笑自若）。褒義。" },
  { id: "i127", grade: 9, term: "廣場無垢", zhuyin: "ㄍㄨㄤˇ ㄔㄤˇ ㄨˊ ㄍㄡˋ", pinyin: "guǎng chǎng wú gòu", meaning: "廣大的心胸無有瑕疵，品德無缺陷。", example: "他以廣場無垢的胸懷對待每個人。",deep:"典故由來：由字面組合而成的語句。\n字面意思：廣闊的場地沒有汙垢。\n引申意思：比喻心胸坦蕩、品德沒有瑕疵（如：他一生廣場無垢）。褒義。" },
  { id: "i128", grade: 9, term: "坦蕩蕩", zhuyin: "ㄊㄢˇ ㄉㄤˋ ㄉㄤˋ", pinyin: "tǎn dàng dàng", meaning: "光明正大，心胸開闊。", example: "君子應該坦蕩蕩，無所隱瞞。",deep:"典故由來：出自《論語．述而》：「君子坦蕩蕩，小人長戚戚。」\n字面意思：平坦寬廣的樣子。\n引申意思：心胸開闊、光明磊落（如：做人坦蕩蕩）。褒義。" },
  { id: "i129", grade: 9, term: "芒刺在背", zhuyin: "ㄇㄤˊ ㄘˋ ㄗㄞˋ ㄅㄟˋ", pinyin: "máng cì zài bèi", meaning: "感覺被扎著，比喻坐立不安。", example: "他做了錯事，感覺芒刺在背。",deep:"典故由來：出自《漢書．霍光傳》：漢宣帝初即位，與權臣霍光同車，「若有芒刺在背」，渾身不自在。\n字面意思：像有草木細刺扎在背上。\n引申意思：因畏忌而坐立難安（如：被上司盯著，如芒刺在背）。" },
  { id: "i130", grade: 9, term: "狼狽不堪", zhuyin: "ㄌㄤˊ ㄅㄟˋ ㄅㄨˋ ㄎㄢ", pinyin: "láng bèi bù kān", meaning: "非常狼狽，非常狼狽難堪。", example: "他被批評得狼狽不堪。", misuse: "不是真的狼和狽。",deep:"典故由來：「狼狽」為傳說中兩獸相依而行，一離開就跌倒；唐段成式《酉陽雜俎》有載。\n字面意思：狼狽得不能忍受。\n引申意思：處境窘迫難堪（如：淋成落湯雞，狼狽不堪）。貶義。" },
  { id: "i131", grade: 9, term: "鶴立雞群", zhuyin: "ㄏㄜˋ ㄌㄧˋ ㄐㄧ ㄑㄩㄣˊ", pinyin: "hè lì jī qún", meaning: "比喻傑出超群，與眾不同。", example: "他的才華在同學中鶴立雞群。",deep:"典故由來：出自《世說新語．容止》：有人見嵇紹「昂昂然如野鶴之在雞群」。\n字面意思：鶴站在雞群之中。\n引申意思：儀表或才能出眾（如：他身材高大，人群中鶴立雞群）。褒義。" },
  { id: "i132", grade: 9, term: "峨眉山月", zhuyin: "ㄜˊ ㄇㄟˊ ㄕㄢ ㄩㄝˋ", pinyin: "é méi shān yuè", meaning: "形容月色美麗，引發思愁。", example: "詩人看著峨眉山月，思鄉之情油然而生。",deep:"典故由來：出自唐．李白〈峨眉山月歌〉：「峨眉山月半輪秋，影入平羌江水流。」\n字面意思：峨眉山上的月亮。\n引申意思：形容月色清美、引人思鄉懷友（如：峨眉山月般的鄉愁）。" },
  { id: "i133", grade: 9, term: "月朦朧", zhuyin: "ㄩㄝˋ ㄇㄥˊ ㄌㄨㄥˊ", pinyin: "yuè méng lóng", meaning: "月色朦朧，比喻景象模糊。", example: "月朦朧的夜晚，景色格外迷幻。",deep:"典故由來：古典詩詞常見意象（「月朦朧，鳥朦朧」）。\n字面意思：月色迷濛不清。\n引申意思：景象柔和模糊（如：月朦朧的夜色）。" },
  { id: "i134", grade: 9, term: "清風明月", zhuyin: "ㄑㄧㄥ ㄈㄥ ㄇㄧㄥˊ ㄩㄝˋ", pinyin: "qīng fēng míng yuè", meaning: "清爽的風和皎潔的月，比喻高潔品格。", example: "他秉持清風明月般的高潔。",deep:"典故由來：語本《南史．謝譓傳》：「入吾室者，但有清風；對吾飲者，唯當明月。」蘇軾〈赤壁賦〉亦以清風明月為寶。\n字面意思：清涼的風、明亮的月。\n引申意思：自然美景；也比喻高潔的品格（如：清風明月的襟懷）。褒義。" },
  { id: "i135", grade: 9, term: "白雲蒼狗", zhuyin: "ㄅㄞˊ ㄩㄣˊ ㄘㄤ ㄍㄡˇ", pinyin: "bái yún cāng gǒu", meaning: "白雲變黑狗，比喻世事變幻無常。", example: "人生如白雲蒼狗，變化不定。",deep:"典故由來：出自唐．杜甫〈可嘆〉：「天上浮雲如白衣，斯須改變如蒼狗。」\n字面意思：白雲片刻變成灰狗的形狀。\n引申意思：世事變化無常（如：世事白雲蒼狗，難以預料）。" },
  { id: "i136", grade: 9, term: "風雨飄搖", zhuyin: "ㄈㄥ ㄩˇ ㄆㄧㄠ ㄧㄠˊ", pinyin: "fēng yǔ piāo yáo", meaning: "被風雨吹動搖晃，比喻局勢危險。", example: "公司經營狀況風雨飄搖。",deep:"典故由來：語本《詩經．豳風．鴟鴞》：「予室翹翹，風雨所漂搖。」\n字面意思：在風雨中飄蕩搖晃。\n引申意思：局勢動盪不安（如：公司財務風雨飄搖）。" },
  { id: "i137", grade: 9, term: "烈火烹油", zhuyin: "ㄌㄧㄝˋ ㄏㄨㄛˇ ㄆㄥ ㄧㄡˊ", pinyin: "liè huǒ pēng yóu", meaning: "用猛火燒油，比喻激烈的鬥爭。", example: "商戰如烈火烹油，激烈無比。",deep:"典故由來：出自《紅樓夢》：形容賈府「烈火烹油、鮮花著錦之盛」——極盛卻暗藏危機。\n字面意思：往烈火上澆油烹煮。\n引申意思：形容聲勢極盛（原意含盛極將衰的警惕）；也形容場面熱烈激烈。" },
  { id: "i138", grade: 9, term: "天搖地動", zhuyin: "ㄊㄧㄢ ㄧㄠˊ ㄉㄧˋ ㄉㄨㄥˋ", pinyin: "tiān yáo dì dòng", meaning: "天和地都在搖晃，比喻變化巨大。", example: "地震時天搖地動，嚇人極了。",deep:"典故由來：明清小說常見的誇飾語。\n字面意思：天在搖、地在動。\n引申意思：聲勢浩大或變動劇烈（如：炮聲天搖地動）。" },
  // Grade 10-12 (50條 — 高中程度，可含深文成語)
  { id: "i139", grade: 10, term: "罄竹難書", zhuyin: "ㄑㄧㄥˋ ㄓㄨˊ ㄋㄢˊ ㄕㄨ", pinyin: "qìng zhú nán shū", meaning: "用所有竹子也寫不完，比喻罪孽極多。", example: "他的罪行罄竹難書，令人髮指。",deep:"典故由來：出自《舊唐書．李密傳》：李密討隋煬帝檄文：「罄南山之竹，書罪未窮。」用盡南山的竹子做簡，也寫不完他的罪。\n字面意思：用盡竹子也寫不完（罄＝用盡）。\n引申意思：罪狀多得寫不完（如：惡行罄竹難書）。貶義；只能用於罪惡，不可形容好事多。" },
  { id: "i140", grade: 10, term: "篳路藍縷", zhuyin: "ㄅㄧˋ ㄌㄨˋ ㄌㄢˊ ㄌㄩˇ", pinyin: "bì lù lán lǚ", meaning: "穿著破衣，駕著柴車，比喻創業的艱辛。", example: "國父篳路藍縷，開創了共和。",deep:"典故由來：出自《左傳．宣公十二年》：「篳路藍縷，以啟山林。」楚國先人駕柴車、穿破衣開闢山林。\n字面意思：駕柴車、穿破衣（篳路＝柴車；藍縷＝破衣）。\n引申意思：創業艱辛（如：先民篳路藍縷，以啟山林）。褒義。" },
  { id: "i141", grade: 10, term: "磊落光明", zhuyin: "ㄌㄟˇ ㄌㄨㄛˋ ㄍㄨㄤ ㄇㄧㄥˊ", pinyin: "lěi luò guāng míng", meaning: "品德磊落，光明正大。", example: "他為人磊落光明，獲得眾人敬重。",deep:"典故由來：「磊落」形容石頭分明，語出古詩文；此為「光明磊落」的變序。\n字面意思：胸中如石塊分明，光明正大。\n引申意思：品行坦蕩無私（如：他一生磊落光明）。褒義。" },
  { id: "i142", grade: 10, term: "寶劍出鞘", zhuyin: "ㄅㄠˇ ㄐㄧㄢˋ ㄔㄨ ㄓㄠˋ", pinyin: "bǎo jiàn chū zhào", meaning: "寶劍從鞘裡拔出，比喻人才被發現任用。", example: "經過多年磨練，他終於寶劍出鞘。",deep:"典故由來：由字面組合而成；寶劍藏鞘喻懷才，出鞘喻施展。\n字面意思：寶劍從劍鞘中拔出。\n引申意思：人才得到施展的機會（如：新人終於寶劍出鞘）。褒義。" },
  { id: "i143", grade: 10, term: "馬到成功", zhuyin: "ㄇㄚˇ ㄉㄠˋ ㄔㄥˊ ㄍㄨㄥ", pinyin: "mǎ dào chéng gōng", meaning: "戰馬一到就取得勝利，比喻立即成功。", example: "他的計畫馬到成功，超越了所有預期。",deep:"典故由來：元代戲曲常見「旗開得勝，馬到成功」。\n字面意思：戰馬一到便獲成功。\n引申意思：迅速取得成功（如：祝你馬到成功）。褒義，多用於祝福。" },
  { id: "i144", grade: 10, term: "層峰迭起", zhuyin: "ㄘㄥˊ ㄈㄥ ㄉㄧㄝˊ ㄑㄧˇ", pinyin: "céng fēng dié qǐ", meaning: "高峰一個接一個，比喻傑出人物層出不窮。", example: "科技界層峰迭起，新星不斷涌現。",deep:"典故由來：由字面組合而成；「迭」是接連。\n字面意思：高峰一座接一座出現。\n引申意思：高潮或傑出人物接連出現（如：好戲層峰迭起）。" },
  { id: "i145", grade: 10, term: "高山仰止", zhuyin: "ㄍㄠ ㄕㄢ ㄧㄤˇ ㄓˇ", pinyin: "gāo shān yǎng zhǐ", meaning: "高山值得仰望，比喻敬仰。", example: "他的成就令我高山仰止。",deep:"典故由來：出自《詩經．小雅．車舝》：「高山仰止，景行行止。」司馬遷以之讚孔子。\n字面意思：崇高的山令人仰望。\n引申意思：對偉大人格的敬仰（如：先生之風，高山仰止）。褒義。" },
  { id: "i146", grade: 10, term: "翼翼小心", zhuyin: "ㄧˋ ㄧˋ ㄒㄧㄠˇ ㄒㄧㄣ", pinyin: "yì yì xiǎo xīn", meaning: "小心翼翼，謹慎小心。", example: "他翼翼小心地處理這個敏感問題。",deep:"典故由來：語出《詩經．大雅．大明》「小心翼翼」的變序。\n字面意思：恭敬謹慎的樣子。\n引申意思：非常謹慎（如：他翼翼小心地捧著古董）。" },
  { id: "i147", grade: 10, term: "枝葉扶蘇", zhuyin: "ㄓ ㄧㄝˋ ㄈㄨˊ ㄙㄨ", pinyin: "zhī yè fú sū", meaning: "樹木枝葉繁茂，比喻事業興旺。", example: "公司業務枝葉扶蘇，欣欣向榮。",deep:"典故由來：「扶蘇」語出《詩經．鄭風》「山有扶蘇」，形容枝葉茂盛。\n字面意思：枝葉繁茂舒展。\n引申意思：家族或事業繁盛（如：家業枝葉扶蘇）。褒義。" },
  { id: "i148", grade: 10, term: "根深葉茂", zhuyin: "ㄍㄣ ㄕㄣ ㄧㄝˋ ㄇㄠˋ", pinyin: "gēn shēn yè mào", meaning: "根紮深了樹葉才茂盛，比喻基礎穩固。", example: "國家要根深葉茂，就要發展基層。",deep:"典故由來：語本唐．張九齡：「根深則葉茂。」\n字面意思：根紮得深，葉才長得茂盛。\n引申意思：基礎穩固才能興旺（如：企業根深葉茂）。褒義。" },
  { id: "i149", grade: 10, term: "勢如破竹", zhuyin: "ㄕˋ ㄖㄨˊ ㄆㄛˋ ㄓㄨˊ", pinyin: "shì rú pò zhú", meaning: "態勢就像劈竹子一樣一往無前。", example: "我隊勢如破竹，連贏五場比賽。",deep:"典故由來：出自《晉書．杜預傳》：杜預伐吳曰：「今兵威已振，譬如破竹，數節之後，皆迎刃而解。」\n字面意思：形勢像劈竹子，劈開幾節後便一路裂開。\n引申意思：節節勝利、毫無阻礙（如：我軍勢如破竹）。褒義。" },
  { id: "i150", grade: 10, term: "所向披靡", zhuyin: "ㄙㄨㄛˇ ㄒㄧㄤˋ ㄆㄧ ㄇㄧˇ", pinyin: "suǒ xiàng pī mǐ", meaning: "凡是進攻之處都能成功。", example: "新產品上市所向披靡，銷售火爆。",deep:"典故由來：出自《史記．項羽本紀》：項羽垓下突圍，「於是項王大呼馳下，漢軍皆披靡」。\n字面意思：所指向之處草木隨風倒伏（披靡＝倒伏）。\n引申意思：力量所到之處無人能擋（如：球隊所向披靡）。褒義。" },
  { id: "i151", grade: 10, term: "旭日東昇", zhuyin: "ㄓㄠˋ ㄖˋ ㄉㄨㄥ ㄕㄥ", pinyin: "zhào rì dōng shēng", meaning: "太陽從東方升起，比喻前途光明。", example: "國家旭日東昇，希望無限。",deep:"典故由來：語本《詩經．邶風》「旭日始旦」。\n字面意思：朝陽從東方升起。\n引申意思：充滿朝氣、前途光明（如：國勢如旭日東昇）。褒義。" },
  { id: "i152", grade: 10, term: "滄桑歲月", zhuyin: "ㄘㄤ ㄙㄤ ㄙㄨㄟˋ ㄩㄝˋ", pinyin: "cāng sāng suì yuè", meaning: "歲月變幻，世事滄桑。", example: "滄桑歲月改變了他的人生。",deep:"典故由來：「滄桑」是「滄海桑田」的縮語（見晉．葛洪《神仙傳》）。\n字面意思：如滄海變桑田般的歲月。\n引申意思：經歷許多世事變遷的歲月（如：走過滄桑歲月）。" },
  { id: "i153", grade: 10, term: "蒼涼悲壯", zhuyin: "ㄘㄤ ㄌㄧㄤˊ ㄅㄟ ㄓㄨㄤˋ", pinyin: "cāng liáng bēi zhuàng", meaning: "蒼涼而悲壯，感情深沉。", example: "那首歌曲唱出了蒼涼悲壯的情感。",deep:"典故由來：由字面組合而成的文學用語。\n字面意思：淒涼而悲壯。\n引申意思：情調沉鬱而激昂（如：邊塞詩蒼涼悲壯）。" },
  { id: "i154", grade: 10, term: "惟妙惟肖", zhuyin: "ㄨㄟˊ ㄇㄧㄠˋ ㄨㄟˊ ㄒㄧㄠˋ", pinyin: "wéi miào wéi xiào", meaning: "描繪得極為生動逼真。", example: "這幅畫把主人公畫得惟妙惟肖。",deep:"典故由來：清代文評用語，同「維妙維肖」。\n字面意思：極其精妙、極其相似。\n引申意思：描繪模仿得逼真（如：畫中人物惟妙惟肖）。褒義。" },
  { id: "i155", grade: 10, term: "栩栩如生", zhuyin: "ㄒㄨˇ ㄒㄨˇ ㄖㄨˊ ㄕㄥ", pinyin: "xǔ xǔ rú shēng", meaning: "形容非常生動，像活著的一樣。", example: "雕塑家的作品栩栩如生。",deep:"典故由來：語本《莊子．齊物論》：莊周夢蝶「栩栩然胡蝶也」。栩栩＝生動活潑的樣子。\n字面意思：生動得像活的一樣。\n引申意思：藝術形象逼真傳神（如：雕像栩栩如生）。褒義。" },
  { id: "i156", grade: 10, term: "笑靨如花", zhuyin: "ㄒㄧㄠˋ ㄧㄢˋ ㄖㄨˊ ㄏㄨㄚ", pinyin: "xiào yàn rú huā", meaning: "笑容美麗如花，比喻女性笑容迷人。", example: "她笑靨如花，令人難忘。",deep:"典故由來：詩詞常見意象；「靨」是酒窩。\n字面意思：笑起來面靨如花綻放。\n引申意思：笑容嬌美動人（如：新娘笑靨如花）。褒義。" },
  { id: "i157", grade: 10, term: "傾國傾城", zhuyin: "ㄑㄧㄥ ㄍㄨㄛˊ ㄑㄧㄥ ㄔㄥˊ", pinyin: "qīng guó qīng chéng", meaning: "指美女傾倒眾人。", example: "她貌若傾國傾城，美豔動人。",deep:"典故由來：出自《漢書．外戚傳》：李延年歌「北方有佳人，絕世而獨立，一顧傾人城，再顧傾人國」。\n字面意思：使全城全國的人都為之傾倒。\n引申意思：女子容貌極美（如：傾國傾城之貌）。" },
  { id: "i158", grade: 10, term: "冰清玉潔", zhuyin: "ㄅㄧㄥ ㄑㄧㄥ ㄩˋ ㄐㄧㄝˊ", pinyin: "bīng qīng yù jié", meaning: "潔淨高尚，品德高潔。", example: "她為人冰清玉潔，受人尊敬。",deep:"典故由來：語本漢代書信「冰清玉潔」：像冰一樣清澈、玉一樣純潔。\n字面意思：如冰之清、如玉之潔。\n引申意思：品行高潔（如：為官冰清玉潔）。褒義。" },
  { id: "i159", grade: 10, term: "玲瓏剔透", zhuyin: "ㄌㄧㄥˊ ㄌㄨㄥˊ ㄊㄧ ㄊㄡˋ", pinyin: "líng lóng tī tòu", meaning: "精巧細緻，清晰透徹。", example: "這件藝術品玲瓏剔透，令人驚嘆。",deep:"典故由來：元代戲曲常見；「玲瓏」是玉聲、精巧貌。\n字面意思：精巧透亮。\n引申意思：器物精緻透明，或人聰慧靈巧（如：這件玉雕玲瓏剔透）。褒義。" },
  { id: "i160", grade: 10, term: "超塵拔俗", zhuyin: "ㄔㄠ ㄔㄣˊ ㄅㄠˊ ㄙㄨˊ", pinyin: "chāo chén báo sú", meaning: "超越俗氣，品格高尚。", example: "他的品味超塵拔俗，與眾不同。",deep:"典故由來：宋代文獻已見「超塵拔俗」。\n字面意思：超出塵世、拔離凡俗。\n引申意思：品格才識遠超常人（如：氣質超塵拔俗）。褒義。" },
  { id: "i161", grade: 11, term: "生死相許", zhuyin: "ㄕㄥ ㄙˇ ㄒㄧㄤ ㄒㄩˇ", pinyin: "shēng sǐ xiāng xǔ", meaning: "願意共赴生死，比喻忠貞不二。", example: "他們生死相許，終身不渝。",deep:"典故由來：出自金．元好問〈摸魚兒〉：「問世間，情是何物，直教生死相許。」詠大雁殉情。\n字面意思：以生死互相許諾。\n引申意思：感情忠貞不渝（如：一對生死相許的戀人）。" },
  { id: "i162", grade: 11, term: "海誓山盟", zhuyin: "ㄏㄞˇ ㄕˋ ㄕㄢ ㄇㄥˊ", pinyin: "hǎi shì shān méng", meaning: "以海山為盟，象徵永遠不變。", example: "他們海誓山盟，約定此生永不分離。",deep:"典故由來：元明戲曲常見；指著山海發誓。\n字面意思：像高山大海一樣（永恆）的誓言盟約。\n引申意思：堅定不變的愛情誓約（如：兩人海誓山盟）。" },
  { id: "i163", grade: 11, term: "矢志不渝", zhuyin: "ㄕˇ ㄓˋ ㄅㄨˋ ㄩˊ", pinyin: "shǐ zhì bù yú", meaning: "堅定的意志不改變。", example: "他矢志不渝地追求他的理想。",deep:"典故由來：由字面組合而成；「矢」通「誓」，「渝」是改變。\n字面意思：立誓的志向不改變。\n引申意思：志向堅定（如：矢志不渝地投入研究）。褒義。" },
  { id: "i164", grade: 11, term: "一往情深", zhuyin: "ㄧ ㄨㄤˇ ㄑㄧㄥˊ ㄕㄣ", pinyin: "yī wǎng qíng shēn", meaning: "感情深厚，執著不變。", example: "他對藝術的愛一往情深。",deep:"典故由來：出自《世說新語．任誕》：桓子野每聞清歌，輒喚「奈何」，謝安說他「一往有深情」。\n字面意思：一心向前，情意深厚。\n引申意思：感情專注深摯（如：他對音樂一往情深）。褒義。" },
  { id: "i165", grade: 11, term: "柔腸百結", zhuyin: "ㄖㄡˊ ㄔㄤˊ ㄅㄞˇ ㄐㄧㄝˊ", pinyin: "róu cháng bǎi jié", meaning: "心腸柔軟，思緒百般糾結。", example: "看著他離去，她柔腸百結。",deep:"典故由來：詩詞常見意象；柔腸打了上百個結。\n字面意思：柔軟的心腸糾成百結。\n引申意思：愁思鬱結、百感糾纏（如：離別在即，柔腸百結）。" },
  { id: "i166", grade: 11, term: "傷心欲絕", zhuyin: "ㄕㄤ ㄒㄧㄣ ㄩˋ ㄐㄩㄝˊ", pinyin: "shāng xīn yù jué", meaning: "傷心到極點，幾乎要死。", example: "聞訊他死亡，家人傷心欲絕。",deep:"典故由來：由字面組合而成。\n字面意思：傷心到快要氣絕。\n引申意思：悲痛至極（如：噩耗傳來，她傷心欲絕）。" },
  { id: "i167", grade: 11, term: "相思成災", zhuyin: "ㄒㄧㄤ ㄙ ㄔㄥˊ ㄗㄞ", pinyin: "xiāng sī chéng zāi", meaning: "相思之情成了禍患。", example: "她遠方的相思成了災。",deep:"典故由來：現代文學用語。\n字面意思：相思深重成了災難。\n引申意思：思念之情深重難解（如：分隔兩地，相思成災）。" },
  { id: "i168", grade: 11, term: "萬千思緒", zhuyin: "ㄨㄢˋ ㄑㄧㄢ ㄙ ㄒㄩˋ", pinyin: "wàn qiān sī xù", meaning: "思想複雜，有無數的思緒。", example: "她心中有萬千思緒，無言以對。",deep:"典故由來：由字面組合而成。\n字面意思：上萬千條思緒。\n引申意思：心緒紛繁（如：夜深人靜，萬千思緒湧上心頭）。" },
  { id: "i169", grade: 11, term: "春風化雨", zhuyin: "ㄔㄨㄣ ㄈㄥ ㄏㄨㄚˋ ㄩˇ", pinyin: "chūn fēng huà yǔ", meaning: "化育品格的細膩感化，如春風化雨。", example: "教師的春風化雨般的教育改變了他。",deep:"典故由來：語本《孟子．盡心上》：君子之教「有如時雨化之者」。\n字面意思：像春風與及時雨滋潤化育萬物。\n引申意思：良師良好教育的薰陶（如：老師春風化雨，作育英才）。褒義。" },
  { id: "i170", grade: 11, term: "暗送秋波", zhuyin: "ㄢˋ ㄙㄨㄥˋ ㄑㄧㄡ ㄅㄛ", pinyin: "àn sòng qiū bō", meaning: "用眼色傳遞情意，比喻暗戀。", example: "她一直在暗送秋波，但他沒有察覺。",deep:"典故由來：明清小說戲曲常見（如《三國演義》貂蟬對呂布眉目傳情）；「秋波」喻美目如秋水。\n字面意思：偷偷送出如秋水的眼神。\n引申意思：暗中眉目傳情；也指暗中示好討好（如：向對手陣營暗送秋波）。" },
  { id: "i171", grade: 11, term: "卿卿我我", zhuyin: "ㄑㄧㄥ ㄑㄧㄥ ㄨㄛˇ ㄨㄛˇ", pinyin: "qīng qīng wǒ wǒ", meaning: "互相親昵，甜蜜親密。", example: "新人洞房裡卿卿我我。",deep:"典故由來：出自《世說新語．惑溺》：王戎妻常以「卿」稱王戎，說「親卿愛卿，是以卿卿」。\n字面意思：你稱我卿、我稱你卿。\n引申意思：情侶親暱纏綿的樣子（如：兩人卿卿我我）。" },
  { id: "i172", grade: 11, term: "如膠似漆", zhuyin: "ㄖㄨˊ ㄐㄧㄠ ㄙˋ ㄑㄧ", pinyin: "rú jiāo sì qī", meaning: "親密得像膠漆一樣，難以分開。", example: "他們兩人如膠似漆，形影不離。",deep:"典故由來：語本〈古詩十九首〉：「以膠投漆中，誰能別離此。」\n字面意思：像膠和漆黏合在一起。\n引申意思：感情親密難分（如：新婚夫妻如膠似漆）。" },
  { id: "i173", grade: 11, term: "魂牽夢縈", zhuyin: "ㄏㄨㄣˊ ㄑㄧㄢ ㄇㄥˋ ㄧㄥˊ", pinyin: "hún qiān mèng yíng", meaning: "思念使靈魂被牽住，夢中常被纏縛。", example: "故鄉的景象一直魂牽夢縈。",deep:"典故由來：出自宋．劉過〈醉太平〉：「思君憶君，魂牽夢縈。」\n字面意思：靈魂被牽引、夢中被縈繞。\n引申意思：思念深切（如：魂牽夢縈的故鄉）。" },
  { id: "i174", grade: 11, term: "惴惴不安", zhuyin: "ㄓㄨㄟˋ ㄓㄨㄟˋ ㄅㄨˋ ㄢ", pinyin: "zhuì zhuì bù ān", meaning: "心中不安，擔心害怕。", example: "他聽到消息後惴惴不安。",deep:"典故由來：出自《詩經．秦風．黃鳥》：「臨其穴，惴惴其慄。」\n字面意思：憂懼不安的樣子（惴惴＝發抖害怕）。\n引申意思：提心吊膽（如：等待判決，惴惴不安）。" },
  { id: "i175", grade: 11, term: "楚楚可憐", zhuyin: "ㄔㄨˇ ㄔㄨˇ ㄎㄜˇ ㄌㄧㄢˊ", pinyin: "chǔ chǔ kě lián", meaning: "形容女性嬌弱可愛，令人憐惜。", example: "她楚楚可憐的樣子令人心疼。", misuse: "常被誤用為形容男性。",deep:"典故由來：出自《世說新語．言語》：孫綽植松，桓溫稱「楚楚可憐」——鮮明可愛。\n字面意思：嬌柔鮮明，惹人愛憐。\n引申意思：（多指女子）纖弱動人（如：她哭得楚楚可憐）。" },
  { id: "i176", grade: 12, term: "蝸牛角上爭何事", zhuyin: "ㄨㄛ ㄋㄧㄡˊ ㄐㄧㄠˇ ㄕㄤˋ ㄓㄥ ㄏㄜˊ ㄕˋ", pinyin: "wō niú jiǎo shàng zhēng hé shì", meaning: "像蝸牛角那麼小的地方爭什麼，比喻不值一爭。", example: "這點小事不值得爭，蝸牛角上爭何事。",deep:"典故由來：出自唐．白居易〈對酒〉：「蝸牛角上爭何事，石火光中寄此身。」語本《莊子．則陽》蝸角上蠻觸二國相爭的寓言。\n字面意思：在蝸牛角那麼小的地方爭什麼。\n引申意思：所爭極其渺小、不值得計較（如：同事間蝸牛角上爭何事）。" },
  { id: "i177", grade: 12, term: "滄海遺珠", zhuyin: "ㄘㄤ ㄏㄞˇ ㄧˊ ㄓㄨ", pinyin: "cāng hǎi yí zhū", meaning: "在滄海裡遺落的珍珠，比喻埋沒的人才。", example: "許多滄海遺珠在社會底層未被發現。",deep:"典故由來：出自《新唐書．狄仁傑傳》：閻立本稱狄仁傑為「滄海遺珠」——大海裡採珠人遺漏的珍珠。\n字面意思：大海中被遺漏的珍珠。\n引申意思：被埋沒的人才（如：選秀落榜者不乏滄海遺珠）。" },
  { id: "i178", grade: 12, term: "木秀於林", zhuyin: "ㄇㄨˋ ㄒㄧㄡˋ ㄩˊ ㄌㄧㄣˊ", pinyin: "mù xiù yú lín", meaning: "樹木高出林子，比喻才能超群。", example: "他年輕就木秀於林，成就卓越。",deep:"典故由來：出自三國魏．李康〈運命論〉：「木秀於林，風必摧之。」\n字面意思：樹木高出樹林（風必吹折它）。\n引申意思：才能出眾易遭嫉妒打擊（如：木秀於林，他遭人排擠）。" },
  { id: "i179", grade: 12, term: "堆垛如山", zhuyin: "ㄉㄨㄟ ㄉㄨㄛˋ ㄖㄨˊ ㄕㄢ", pinyin: "duī duò rú shān", meaning: "堆積如同山一樣高，比喻非常多。", example: "書籍堆垛如山，他是位真正的書迷。",deep:"典故由來：由字面組合而成。\n字面意思：堆疊得像山一樣高。\n引申意思：數量極多（如：文件堆垛如山）。" },
  { id: "i180", grade: 12, term: "寸寸肝腸", zhuyin: "ㄘㄨㄣˋ ㄘㄨㄣˋ ㄍㄢ ㄔㄤˊ", pinyin: "cùn cùn gān cháng", meaning: "肝腸寸寸，比喻極度悲痛。", example: "得知噩耗，她寸寸肝腸俱裂。",deep:"典故由來：詩詞常語；肝腸似寸寸斷裂。\n字面意思：肝腸一寸寸（斷）。\n引申意思：極度悲痛（如：聞噩耗寸寸肝腸）。" },
  { id: "i181", grade: 12, term: "涕零如麻", zhuyin: "ㄊㄧˋ ㄌㄧㄥˊ ㄖㄨˊ ㄇㄚˊ", pinyin: "tì líng rú má", meaning: "眼淚紛紛落下如麻，比喻哭得很傷心。", example: "聽著他的傷心往事，她涕零如麻。",deep:"典故由來：語本古詩文「涕零如雨」的變化；「零」是落下。\n字面意思：眼淚紛紛落下如亂麻。\n引申意思：哭得極傷心（如：靈前涕零如麻）。" },
  { id: "i182", grade: 12, term: "肝膽相照", zhuyin: "ㄍㄢ ㄉㄢˇ ㄒㄧㄤ ㄓㄠˋ", pinyin: "gān dǎn xiāng zhào", meaning: "肝膽相照，比喻赤誠相待。", example: "朋友間應該肝膽相照，互相信任。",deep:"典故由來：語本《史記．淮陰侯列傳》：「披腹心，輸肝膽。」\n字面意思：把肝膽掏出來互相照見。\n引申意思：以真心坦誠相待（如：兩人肝膽相照數十年）。褒義。" },
  { id: "i183", grade: 12, term: "骨肉之親", zhuyin: "ㄍㄨˇ ㄖㄡˋ ㄓ ㄑㄧㄣ", pinyin: "gǔ ròu zhī qīn", meaning: "親骨肉，最親密的親屬。", example: "骨肉之親是世上最寶貴的關係。",deep:"典故由來：古籍常語；骨肉相連喻至親。\n字面意思：骨和肉相連的親人。\n引申意思：父母子女兄弟等至親（如：骨肉之親，血濃於水）。" },
  { id: "i184", grade: 12, term: "親密無間", zhuyin: "ㄑㄧㄣ ㄇㄧˋ ㄨˊ ㄐㄧㄢˋ", pinyin: "qīn mì wú jiàn", meaning: "非常親密，沒有隔閡。", example: "他們兄弟親密無間，互相關愛。",deep:"典故由來：語本《漢書．蕭望之傳贊》：「可謂親暱亡（無）間。」\n字面意思：親密得沒有一點縫隙。\n引申意思：關係極親密（如：姊妹倆親密無間）。褒義。" },
  { id: "i185", grade: 12, term: "手足之情", zhuyin: "ㄕㄡˇ ㄗㄨˊ ㄓ ㄑㄧㄥˊ", pinyin: "shǒu zú zhī qíng", meaning: "像手足一樣的情誼，比喻極親密。", example: "我們有手足之情，永不背離。",deep:"典故由來：語本宋．蘇轍〈為兄軾下獄上書〉：「不勝手足之情。」\n字面意思：如手和腳一樣的情分。\n引申意思：兄弟姊妹間的情誼（如：手足之情深厚）。" },
  { id: "i186", grade: 12, term: "同舟共濟", zhuyin: "ㄊㄨㄥˊ ㄓㄡ ㄍㄨㄥˋ ㄐㄧˋ", pinyin: "tóng zhōu gòng jì", meaning: "在同一船上渡河，比喻共同面對困難。", example: "國家應該與民同舟共濟，度過難關。",deep:"典故由來：出自《孫子．九地》：吳人與越人素來相惡，「當其同舟而濟，遇風，其相救也如左右手」。\n字面意思：坐同一條船渡河。\n引申意思：利害相同、共渡難關（如：疫情中全民同舟共濟）。褒義。" },
  { id: "i187", grade: 12, term: "患難與共", zhuyin: "ㄏㄨㄢˋ ㄋㄢˋ ㄩˇ ㄍㄨㄥˋ", pinyin: "huàn nàn yǔ gòng", meaning: "在患難中也一起承受，比喻真誠友情。", example: "他們經歷患難與共，關係更深。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：患難一同承受。\n引申意思：共歷艱難、情義深厚（如：患難與共的老友）。褒義。" },
  { id: "i188", grade: 12, term: "秋毫無犯", zhuyin: "ㄑㄧㄡ ㄏㄠˊ ㄨˊ ㄈㄢˋ", pinyin: "qiū háo wú fàn", meaning: "連一根秋毫都不侵犯，比喻紀律嚴明。", example: "軍隊紀律嚴明，秋毫無犯。",deep:"典故由來：語本《史記．項羽本紀》樊噲語：「秋毫不敢有所近。」《後漢書》作「秋毫無犯」。\n字面意思：連秋天鳥獸的細毛都不侵犯。\n引申意思：軍紀嚴明、不擾百姓（如：部隊過境秋毫無犯）。褒義。" },
  { id: "i189", grade: 12, term: "廉潔奉公", zhuyin: "ㄌㄧㄢˊ ㄐㄧㄝˊ ㄈㄥˋ ㄍㄨㄥ", pinyin: "lián jié fèng gōng", meaning: "清廉正直，為公眾謀福利。", example: "官員應該廉潔奉公，不貪不瀆。",deep:"典故由來：由字面組合而成的現代常用語。\n字面意思：清廉自持，奉行公事。\n引申意思：清廉盡職（如：廉潔奉公的公務員）。褒義。" },
  { id: "i190", grade: 12, term: "兩袖清風", zhuyin: "ㄌㄧㄤˇ ㄒㄧㄡˋ ㄑㄧㄥ ㄈㄥ", pinyin: "liǎng xiù qīng fēng", meaning: "袖子裡只有清風，比喻官員清廉。", example: "好官員應該兩袖清風，廉潔奉公。",deep:"典故由來：語本明．于謙〈入京〉詩：「清風兩袖朝天去，免得閭閻話短長。」不帶土產進京，只有兩袖清風。\n字面意思：兩隻袖子裡只有清風。\n引申意思：為官清廉、一無所有（如：任官數十年，兩袖清風）。褒義。" },
  { id: "i191", grade: 12, term: "一塵不染", zhuyin: "ㄧ ㄔㄣˊ ㄅㄨˋ ㄖㄢˇ", pinyin: "yī chén bù rǎn", meaning: "連一粒塵埃都不沾，比喻清廉純潔。", example: "他為人一塵不染，廉潔自守。",deep:"典故由來：佛家語：不受色聲香味觸法「六塵」沾染。\n字面意思：一粒塵埃都不沾染。\n引申意思：環境極潔淨，或人品純潔清廉（如：屋內一塵不染／操守一塵不染）。褒義。" },
  { id: "i192", grade: 12, term: "鶴發童顏", zhuyin: "ㄏㄜˋ ㄈㄚ ㄊㄨㄥˊ ㄧㄢˊ", pinyin: "hè fā tóng yán", meaning: "白髮卻面容年輕，形容老而無衰。", example: "爺爺年已八十，卻鶴發童顏。",deep:"典故由來：唐代文獻已見「鶴髮童顏」。\n字面意思：白鶴般的頭髮、孩童般的面色。\n引申意思：年老而氣色紅潤健康（如：老先生鶴髮童顏）。褒義。" },
  { id: "i193", grade: 12, term: "蒼顏白髮", zhuyin: "ㄘㄤ ㄧㄢˊ ㄅㄞˊ ㄈㄚ", pinyin: "cāng yán bái fā", meaning: "臉色蒼白，頭髮花白，形容年老。", example: "他蒼顏白髮，一生操勞。",deep:"典故由來：出自宋．歐陽修〈醉翁亭記〉：「蒼顏白髮，頹然乎其間者，太守醉也。」\n字面意思：蒼老的容顏、花白的頭髮。\n引申意思：形容年老（如：重逢時已蒼顏白髮）。" },
  { id: "i194", grade: 12, term: "老態龍鍾", zhuyin: "ㄌㄠˇ ㄊㄞˋ ㄌㄨㄥˊ ㄓㄨㄥ", pinyin: "lǎo tài lóng zhōng", meaning: "年老無力，身體衰弱。", example: "他雖然老態龍鍾，精神依然矍鑠。", misuse: "不是真的龍鍾。",deep:"典故由來：見宋．陸游詩：「老態龍鍾疾未平。」龍鍾＝行動不靈便的樣子。\n字面意思：年老衰弱、行動遲緩的樣子。\n引申意思：衰老遲鈍（如：老態龍鍾的背影）。" },
  { id: "i195", grade: 12, term: "矍鑠有神", zhuyin: "ㄐㄩㄝˊ ㄕㄨㄛˋ ㄧㄡˇ ㄕㄣˊ", pinyin: "jué shuò yǒu shén", meaning: "眼睛有神，形容精神矍鑠。", example: "老人雖然年邁，但目光矍鑠有神。",deep:"典故由來：出自《後漢書．馬援傳》：馬援六十二歲仍請纓出征，據鞍顧盼，光武帝笑曰「矍鑠哉是翁也」。\n字面意思：目光炯炯、精神健旺。\n引申意思：老而強健有神（如：九旬長者矍鑠有神）。褒義。" },
  { id: "i196", grade: 12, term: "精神煥發", zhuyin: "ㄐㄧㄥ ㄕㄣˊ ㄏㄨㄢˋ ㄈㄚ", pinyin: "jīng shén huàn fā", meaning: "精神煥然一新，活力充沛。", example: "經過休息，他精神煥發。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：精神煥然一新。\n引申意思：精力充沛（如：休假歸來精神煥發）。褒義。" },
  { id: "i197", grade: 12, term: "容光煥發", zhuyin: "ㄖㄨㄥˊ ㄍㄨㄤ ㄏㄨㄢˋ ㄈㄚ", pinyin: "róng guāng huàn fā", meaning: "臉色光彩煥發，光彩照人。", example: "新娘容光煥發，美不勝收。",deep:"典故由來：清代小說常見。\n字面意思：臉上光彩四射。\n引申意思：氣色極好（如：喜事將近，容光煥發）。褒義。" },
  { id: "i198", grade: 12, term: "丰采奕奕", zhuyin: "ㄈㄥ ㄘㄞˇ ㄧˋ ㄧˋ", pinyin: "fēng cǎi yì yì", meaning: "神采飛揚，光彩熠熠。", example: "運動員丰采奕奕地站在領獎台上。",deep:"典故由來：由字面組合而成；「奕奕」是光明煥發的樣子。\n字面意思：風采神情光彩煥發。\n引申意思：神采飛揚（如：台上丰采奕奕）。褒義。" },
  { id: "i199", grade: 12, term: "眉清目秀", zhuyin: "ㄇㄟˊ ㄑㄧㄥ ㄇㄨˋ ㄒㄧㄡˋ", pinyin: "méi qīng mù xiù", meaning: "眉毛清秀，眼睛聰慧，形容長相秀氣。", example: "她眉清目秀，氣質優雅。",deep:"典故由來：元代戲曲常見。\n字面意思：眉毛清朗、眼睛秀麗。\n引申意思：面貌清秀（如：眉清目秀的少年）。褒義。" },
  { id: "i200", grade: 12, term: "傾城傾國", zhuyin: "ㄑㄧㄥ ㄔㄥˊ ㄑㄧㄥ ㄍㄨㄛˊ", pinyin: "qīng chéng qīng guó", meaning: "美貌動人，足以傾倒一城一國。", example: "古代四大美女傾城傾國，令人矚目。",deep:"典故由來：出自《漢書．外戚傳》李延年歌：「一顧傾人城，再顧傾人國。」\n字面意思：使全城全國為之傾倒。\n引申意思：女子容貌絕美（如：傾城傾國之姿）。" },
  // ---- 2026-08-02 擴充：i201-i250（國小低中年級） ----
  { id: "i201", grade: 1, term: "一舉兩得", zhuyin: "ㄧ ㄐㄩˇ ㄌㄧㄤˇ ㄉㄜˊ", pinyin: "yī jǔ liǎng dé", meaning: "做一件事同時獲得兩種好處。", example: "走路上學既省錢又能運動，真是一舉兩得。", syn: ["一石二鳥", "事半功倍"] , wordExp: "一舉＝一個動作；兩得＝兩種收穫。做一件事同時得到兩個好處。",deep:"典故由來：語本《史記．張儀列傳》：陳軫以「卞莊子刺虎」為喻——等兩虎相鬥、一死一傷再出手，一舉而有殺雙虎之名。\n字面意思：做一件事，得到兩種收穫。\n引申意思：一個行動同時達成兩個好處（如：騎車上學既運動又環保，一舉兩得）。近義：一石二鳥。" },
  { id: "i202", grade: 1, term: "自言自語", zhuyin: "ㄗˋ ㄧㄢˊ ㄗˋ ㄩˇ", pinyin: "zì yán zì yǔ", meaning: "自己對自己說話。", example: "弟弟一邊玩積木，一邊自言自語。" , wordExp: "自言、自語＝自己說、自己講。自己對自己說話。",deep:"典故由來：由字面組合而成，元明戲曲小說中已常見。\n字面意思：自己對自己說話。\n引申意思：獨自低聲說話（如：他邊算數學邊自言自語）。多為中性描寫。" },
  { id: "i203", grade: 1, term: "不知不覺", zhuyin: "ㄅㄨˋ ㄓ ㄅㄨˋ ㄐㄩㄝˊ", pinyin: "bù zhī bù jué", meaning: "沒有察覺、沒有意識到。", example: "故事太好聽了，不知不覺就到了睡覺時間。" , wordExp: "不知、不覺＝沒有察覺。不知道也沒感覺，形容自然而然。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：沒有知道、沒有察覺。\n引申意思：在無意間、不經意地（如：不知不覺天就黑了）。" },
  { id: "i204", grade: 1, term: "東張西望", zhuyin: "ㄉㄨㄥ ㄓㄤ ㄒㄧ ㄨㄤˋ", pinyin: "dōng zhāng xī wàng", meaning: "四處張望，形容心神不定或好奇觀看。", example: "上課要專心，不要東張西望。", syn: ["左顧右盼"] , wordExp: "東、西＝四處；張、望＝看。東看看西望望。",deep:"典故由來：明清白話小說常見的口語成語，由字面組合而成。\n字面意思：向東張望、向西張望。\n引申意思：四處張望，形容好奇、心不在焉或找東西（如：上課別東張西望）。" },
  { id: "i205", grade: 1, term: "大吃一驚", zhuyin: "ㄉㄚˋ ㄔ ㄧ ㄐㄧㄥ", pinyin: "dà chī yī jīng", meaning: "非常吃驚。", example: "看到成績單，媽媽大吃一驚。", syn: ["大驚失色"] , wordExp: "大吃＝大大受到；一驚＝一場驚嚇。非常吃驚。",deep:"典故由來：由字面組合而成，明清小說常見。\n字面意思：大大地吃了一驚。\n引申意思：非常吃驚（如：聽到消息，大家都大吃一驚）。" },
  { id: "i206", grade: 1, term: "依依不捨", zhuyin: "ㄧ ㄧ ㄅㄨˋ ㄕㄜˇ", pinyin: "yī yī bù shě", meaning: "非常留戀，捨不得分離。", example: "畢業那天，同學們依依不捨地道別。", syn: ["戀戀不捨"] , wordExp: "依依＝留戀的樣子；不捨＝捨不得。戀戀不捨的樣子。",deep:"典故由來：「依依」語出《詩經．小雅．采薇》：「昔我往矣，楊柳依依」，形容柳枝隨風輕柔擺動，引申為留戀。\n字面意思：戀戀不捨的樣子。\n引申意思：非常留戀、捨不得分開（如：畢業時同學們依依不捨）。" },
  { id: "i207", grade: 1, term: "興高采烈", zhuyin: "ㄒㄧㄥˋ ㄍㄠ ㄘㄞˇ ㄌㄧㄝˋ", pinyin: "xìng gāo cǎi liè", meaning: "興致高昂，情緒熱烈。", example: "全班興高采烈地討論校外教學的行程。", syn: ["歡天喜地", "興致勃勃"] , wordExp: "興＝興致；高＝高昂；采＝神采；烈＝熱烈。興致神采都很高昂熱烈。",deep:"典故由來：語本《文心雕龍．體性》：「叔夜俊俠，故興高而采烈。」原指嵇康文章興致高遠、辭采剛烈。\n字面意思：興致高、神采烈。\n引申意思：情緒高昂、非常開心（如：大家興高采烈地去遠足）。褒義。" },
  { id: "i208", grade: 1, term: "手忙腳亂", zhuyin: "ㄕㄡˇ ㄇㄤˊ ㄐㄧㄠˇ ㄌㄨㄢˋ", pinyin: "shǒu máng jiǎo luàn", meaning: "做事慌張忙亂，沒有條理。", example: "客人突然來訪，媽媽在廚房手忙腳亂。", syn: ["七手八腳"] , wordExp: "手舞、腳亂＝手忙著、腳亂了。手腳慌亂，沒了條理。",deep:"典故由來：宋代禪宗語錄已見「手忙腳亂」一語（《五燈會元》）。\n字面意思：手和腳都忙亂了。\n引申意思：做事慌張沒條理（如：客人突然來訪，他手忙腳亂地收拾）。貶義；相對詞是「有條不紊」。" },
  { id: "i209", grade: 1, term: "五顏六色", zhuyin: "ㄨˇ ㄧㄢˊ ㄌㄧㄡˋ ㄙㄜˋ", pinyin: "wǔ yán liù sè", meaning: "色彩繁多、繽紛美麗。", example: "公園裡開滿五顏六色的花朵。", syn: ["五彩繽紛", "五光十色"] , wordExp: "五、六＝形容多；顏、色＝顏色。顏色繁多。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：五、六種顏色，極言色彩多。\n引申意思：色彩繁多繽紛（如：花園裡五顏六色的花）。與「五光十色」近義，但「五光十色」多了光澤、繁華的意味。" },
  { id: "i210", grade: 1, term: "四面八方", zhuyin: "ㄙˋ ㄇㄧㄢˋ ㄅㄚ ㄈㄤ", pinyin: "sì miàn bā fāng", meaning: "各個方向、各個地方。", example: "遊客從四面八方湧進廟口夜市。" , wordExp: "四面＝東南西北；八方＝各個方向。所有方向、各個地方。",deep:"典故由來：由字面組合而成；「四面」指東南西北，「八方」再加四個斜角方向。\n字面意思：四個面、八個方向。\n引申意思：各個方向、到處（如：支援從四面八方湧來）。" },
  { id: "i211", grade: 2, term: "爭先恐後", zhuyin: "ㄓㄥ ㄒㄧㄢ ㄎㄨㄥˇ ㄏㄡˋ", pinyin: "zhēng xiān kǒng hòu", meaning: "爭著搶先，唯恐落後。", example: "下課鐘一響，大家爭先恐後地跑向操場。" , wordExp: "爭先＝搶著在前；恐後＝唯恐落後。搶著向前，深怕落在後面。",deep:"典故由來：由字面組合而成，明清常用。\n字面意思：爭著在前，唯恐落後。\n引申意思：搶著向前、不甘落後（如：同學們爭先恐後地舉手）。" },
  { id: "i212", grade: 2, term: "一模一樣", zhuyin: "ㄧ ㄇㄛˊ ㄧ ㄧㄤˋ", pinyin: "yī mó yī yàng", meaning: "完全相同，沒有差別。", example: "這對雙胞胎長得一模一樣。", syn: ["如出一轍"], misuse: "「模」在此讀ㄇㄛˊ，不讀ㄇㄨˊ。" , wordExp: "一模＝同一個模子；一樣＝相同。像同個模子印出來，完全相同。",deep:"典故由來：明清白話小說常見的口語成語。\n字面意思：同一個模子印出來的樣子。\n引申意思：完全相同（如：雙胞胎長得一模一樣）。" },
  { id: "i213", grade: 2, term: "半途而廢", zhuyin: "ㄅㄢˋ ㄊㄨˊ ㄦˊ ㄈㄟˋ", pinyin: "bàn tú ér fèi", meaning: "事情做到一半就放棄。", example: "學琴要有恆心，不能半途而廢。", syn: ["虎頭蛇尾", "有始無終"] , wordExp: "半途＝路走到一半；而廢＝就停止。事情做一半就放棄。",deep:"典故由來：語本《禮記．中庸》：「君子遵道而行，半塗而廢，吾弗能已矣。」\n字面意思：路走到一半就停止。\n引申意思：做事沒有恆心、中途放棄（如：學琴不可半途而廢）。貶義；相對詞：持之以恆。" },
  { id: "i214", grade: 2, term: "日積月累", zhuyin: "ㄖˋ ㄐㄧ ㄩㄝˋ ㄌㄟˇ", pinyin: "rì jī yuè lěi", meaning: "長時間一點一滴地累積。", example: "單字要日積月累地背，不能靠考前硬記。", syn: ["積少成多"] , wordExp: "日、月＝天天、月月；積、累＝累積。一天一月慢慢累積。",deep:"典故由來：由字面組合而成，宋代以來常用。\n字面意思：一天天累積、一月月堆疊。\n引申意思：長時間一點一滴累積（如：實力靠日積月累）。褒義。" },
  { id: "i215", grade: 2, term: "歡天喜地", zhuyin: "ㄏㄨㄢ ㄊㄧㄢ ㄒㄧˇ ㄉㄧˋ", pinyin: "huān tiān xǐ dì", meaning: "非常歡喜快樂。", example: "聽到要去動物園，孩子們歡天喜地。", syn: ["興高采烈", "喜出望外"] , wordExp: "歡、喜＝高興；天、地＝形容程度大。高興得連天地都在慶祝。",deep:"典故由來：元明戲曲小說常見的口語成語。\n字面意思：歡樂連天、喜悅滿地。\n引申意思：非常高興（如：全家歡天喜地過新年）。" },
  { id: "i216", grade: 2, term: "全神貫注", zhuyin: "ㄑㄩㄢˊ ㄕㄣˊ ㄍㄨㄢˋ ㄓㄨˋ", pinyin: "quán shén guàn zhù", meaning: "全部精神集中在一件事上。", example: "他全神貫注地組裝模型，連晚餐都忘了吃。", syn: ["聚精會神", "專心致志"] , wordExp: "全神＝全部精神；貫注＝集中投入。整個精神都灌注在一件事上。",deep:"典故由來：近代組合成語；「貫注」是集中灌入。\n字面意思：全部精神集中灌注在一處。\n引申意思：注意力高度集中（如：他全神貫注地做實驗）。近義：聚精會神。" },
  { id: "i217", grade: 2, term: "無憂無慮", zhuyin: "ㄨˊ ㄧㄡ ㄨˊ ㄌㄩˋ", pinyin: "wú yōu wú lǜ", meaning: "沒有煩惱和憂愁。", example: "爺爺退休後過著無憂無慮的生活。", syn: ["自由自在"] , wordExp: "無憂、無慮＝沒有擔憂、沒有掛慮。心裡沒有任何煩惱。",deep:"典故由來：由字面組合而成。\n字面意思：沒有憂愁、沒有掛慮。\n引申意思：心情輕鬆自在（如：無憂無慮的童年）。" },
  { id: "i218", grade: 2, term: "自由自在", zhuyin: "ㄗˋ ㄧㄡˊ ㄗˋ ㄗㄞˋ", pinyin: "zì yóu zì zài", meaning: "不受拘束、安然舒適的樣子。", example: "魚兒在水裡自由自在地游來游去。", syn: ["無拘無束"] , wordExp: "自由＝不受限制；自在＝安然舒適。無拘無束，輕鬆自得。",deep:"典故由來：禪宗語錄中已見的口語，後成常用語。\n字面意思：自己作主、安然自得。\n引申意思：不受拘束、輕鬆舒適（如：退休後自由自在）。" },
  { id: "i219", grade: 2, term: "理直氣壯", zhuyin: "ㄌㄧˇ ㄓˊ ㄑㄧˋ ㄓㄨㄤˋ", pinyin: "lǐ zhí qì zhuàng", meaning: "理由正當充分，說話有氣勢。", example: "他沒有做錯事，所以理直氣壯地說明原委。", misuse: "理虧卻大聲爭辯是「強詞奪理」，不是理直氣壯。" , wordExp: "理直＝道理站得住；氣壯＝氣勢就強。有理在手，說話自然有底氣。",deep:"典故由來：明清小說常見的口語成語。\n字面意思：道理正直，氣勢就壯。\n引申意思：理由充分、說話有底氣（如：他理直氣壯地反駁）。注意：「直」不寫作「值」。" },
  { id: "i220", grade: 2, term: "垂頭喪氣", zhuyin: "ㄔㄨㄟˊ ㄊㄡˊ ㄙㄤˋ ㄑㄧˋ", pinyin: "chuí tóu sàng qì", meaning: "低著頭無精打采，形容失意沮喪。", example: "比賽輸了，隊員們垂頭喪氣地走回休息區。", syn: ["無精打采", "灰心喪志"] , wordExp: "垂頭＝低著頭；喪氣＝失了精神。失意沮喪的樣子。",deep:"典故由來：出自唐．韓愈〈送窮文〉：「主人於是垂頭喪氣，上手稱謝。」\n字面意思：頭低垂、洩了氣。\n引申意思：失意沮喪、無精打采（如：輸了比賽垂頭喪氣）。相對詞：趾高氣揚。" },
  { id: "i221", grade: 2, term: "眉開眼笑", zhuyin: "ㄇㄟˊ ㄎㄞ ㄧㄢˇ ㄒㄧㄠˋ", pinyin: "méi kāi yǎn xiào", meaning: "眉眼舒展，滿臉笑容，形容高興的樣子。", example: "收到禮物，奶奶樂得眉開眼笑。", syn: ["喜笑顏開"] , wordExp: "眉開＝眉毛舒展；眼笑＝眼睛帶笑。滿臉笑意，非常開心。",deep:"典故由來：元明戲曲小說常見的口語成語。\n字面意思：眉毛舒展、眼睛含笑。\n引申意思：滿臉笑容、非常高興（如：收到禮物眉開眼笑）。" },
  { id: "i222", grade: 2, term: "異口同聲", zhuyin: "ㄧˋ ㄎㄡˇ ㄊㄨㄥˊ ㄕㄥ", pinyin: "yì kǒu tóng shēng", meaning: "大家不約而同說出同樣的話。", example: "問到想去哪裡玩，大家異口同聲說要去海邊。", syn: ["眾口一詞"] , wordExp: "異口＝不同的嘴；同聲＝同樣的話。大家不約而同說出一樣的話。",deep:"典故由來：由字面組合而成，漢代文獻已見「異口同音」。\n字面意思：不同的嘴說出相同的話。\n引申意思：大家不約而同說法一致（如：眾人異口同聲反對）。" },
  { id: "i223", grade: 2, term: "川流不息", zhuyin: "ㄔㄨㄢ ㄌㄧㄡˊ ㄅㄨˋ ㄒㄧˊ", pinyin: "chuān liú bù xí", meaning: "像河水一樣流動不停，形容人車往來不斷。", example: "站前的馬路上車輛川流不息。", misuse: "「息」讀ㄒㄧˊ。多用於人、車往來，不用於靜止的事物。" , wordExp: "川＝河流；流＝流動；不息＝不停。像河水一樣流個不停。",deep:"典故由來：出自《千字文》：「川流不息，淵澄取映。」\n字面意思：河水流動不停止。\n引申意思：行人、車馬像流水般連續不斷（如：街上車輛川流不息）。注意：形容「連續不斷」，不能用來形容靜止的擁擠。" },
  { id: "i224", grade: 2, term: "風和日麗", zhuyin: "ㄈㄥ ㄏㄜˊ ㄖˋ ㄌㄧˋ", pinyin: "fēng hé rì lì", meaning: "微風和暢，陽光明麗，形容天氣晴好。", example: "趁著風和日麗，全家到河濱公園野餐。" , wordExp: "風和＝風輕柔；日麗＝陽光明媚。天氣晴朗宜人。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：風柔和、太陽明麗。\n引申意思：天氣晴朗暖和（如：風和日麗的好天氣）。" },
  { id: "i225", grade: 3, term: "萬紫千紅", zhuyin: "ㄨㄢˋ ㄗˇ ㄑㄧㄢ ㄏㄨㄥˊ", pinyin: "wàn zǐ qiān hóng", meaning: "百花齊放，色彩絢麗，形容繁盛景象。", example: "春天的陽明山萬紫千紅，遊人如織。", syn: ["百花齊放"] , wordExp: "萬、千＝形容多；紫、紅＝各色花朵。百花齊放，繁華絢麗。",deep:"典故由來：出自宋．朱熹〈春日〉詩：「等閒識得東風面，萬紫千紅總是春。」\n字面意思：上萬的紫、上千的紅，百花齊放。\n引申意思：形容百花盛開、繁榮興旺的景象（如：花季時滿山萬紫千紅）。" },
  { id: "i226", grade: 3, term: "鳥語花香", zhuyin: "ㄋㄧㄠˇ ㄩˇ ㄏㄨㄚ ㄒㄧㄤ", pinyin: "niǎo yǔ huā xiāng", meaning: "鳥兒鳴唱，花朵飄香，形容春光明媚。", example: "清晨的步道鳥語花香，令人心曠神怡。" , wordExp: "鳥語＝鳥兒鳴叫如說話；花香＝花朵飄香。春光明媚的景象。",deep:"典故由來：宋代詩文常見的寫景語，由字面組合而成。\n字面意思：鳥兒鳴叫如語，花朵散發香氣。\n引申意思：形容春天明媚宜人的景象（如：郊外鳥語花香）。" },
  { id: "i227", grade: 3, term: "一絲不苟", zhuyin: "ㄧ ㄙ ㄅㄨˋ ㄍㄡˇ", pinyin: "yī sī bù gǒu", meaning: "做事認真仔細，一點也不馬虎。", example: "他抄寫筆記一絲不苟，連標點都不放過。", syn: ["精益求精"] , wordExp: "一絲＝一點點；不苟＝不隨便。連一絲一毫都不馬虎。",deep:"典故由來：見清．吳敬梓《儒林外史》：「一絲不苟，升遷就在指日。」\n字面意思：一根絲的小事也不馬虎。\n引申意思：做事極認真仔細（如：他做實驗一絲不苟）。褒義；「苟」是隨便之意，不寫作「狗」。" },
  { id: "i228", grade: 3, term: "井然有序", zhuyin: "ㄐㄧㄥˇ ㄖㄢˊ ㄧㄡˇ ㄒㄩˋ", pinyin: "jǐng rán yǒu xù", meaning: "整齊而有條理。", example: "圖書館的書籍分類擺放，井然有序。", syn: ["有條不紊"] , wordExp: "井然＝像井字一樣方正分明；有序＝有次序。整齊而有條理。",deep:"典故由來：由字面組合而成；「井然」形容像井字般方正整齊。\n字面意思：像井字一樣整齊有條理。\n引申意思：整齊有秩序（如：物品排列井然有序）。褒義。" },
  { id: "i229", grade: 3, term: "迫不及待", zhuyin: "ㄆㄛˋ ㄅㄨˋ ㄐㄧˊ ㄉㄞˋ", pinyin: "pò bù jí dài", meaning: "急切得不能再等待。", example: "新書一到，他就迫不及待地翻開來看。", syn: ["急不可待"] , wordExp: "迫＝急迫；不及＝來不及；待＝等待。急得一刻也等不了。",deep:"典故由來：清代小說常見的口語成語。\n字面意思：急迫得來不及等待。\n引申意思：非常急切（如：他迫不及待地拆開禮物）。" },
  { id: "i230", grade: 3, term: "恍然大悟", zhuyin: "ㄏㄨㄤˇ ㄖㄢˊ ㄉㄚˋ ㄨˋ", pinyin: "huǎng rán dà wù", meaning: "忽然完全明白過來。", example: "聽完老師講解，他才恍然大悟。", syn: ["茅塞頓開"] , wordExp: "恍然＝忽然清醒的樣子；大悟＝完全明白。一下子全懂了。",deep:"典故由來：宋代文獻已見；「恍然」是猛然醒悟的樣子。\n字面意思：猛然間完全明白。\n引申意思：突然醒悟（如：聽完解釋，我恍然大悟）。" },
  { id: "i231", grade: 3, term: "再接再厲", zhuyin: "ㄗㄞˋ ㄐㄧㄝ ㄗㄞˋ ㄌㄧˋ", pinyin: "zài jiē zài lì", meaning: "一次又一次地繼續努力。", example: "這次差一點得獎，明年再接再厲！", misuse: "「厲」不可寫成「勵」。" , wordExp: "再＝又一次；接＝接戰；厲＝磨利（兵器）。一次又一次繼續奮鬥。",deep:"典故由來：語本唐．韓愈、孟郊〈鬥雞聯句〉：「一噴一醒然，再接再礪乃」——鬥雞每次交鋒前再磨利嘴爪。「厲」通「礪」（磨刀石）。\n字面意思：一次次接戰、一次次磨利。\n引申意思：一次又一次繼續努力（如：這次沒得名，再接再厲）。褒義；注意是「厲」不是「勵」。" },
  { id: "i232", grade: 3, term: "精益求精", zhuyin: "ㄐㄧㄥ ㄧˋ ㄑㄧㄡˊ ㄐㄧㄥ", pinyin: "jīng yì qiú jīng", meaning: "已經很好，還要求更好。", example: "師傅對每道菜都精益求精，絕不隨便。", syn: ["一絲不苟"] , wordExp: "精＝已經精良；益＝更加；求＝追求。好了還要更好。",deep:"典故由來：語本朱熹《論語集注》：「治之已精，而益求其精也。」\n字面意思：已經精良，還要追求更精良。\n引申意思：不滿足於現有成果，追求更好（如：工藝精益求精）。褒義。" },
  { id: "i233", grade: 3, term: "對牛彈琴", zhuyin: "ㄉㄨㄟˋ ㄋㄧㄡˊ ㄊㄢˊ ㄑㄧㄣˊ", pinyin: "duì niú tán qín", meaning: "比喻對不懂道理的人講道理，白費脣舌。", example: "跟不想聽的人講再多，也是對牛彈琴。", misuse: "重點在「對象聽不進去」，不是罵人愚笨。" , wordExp: "對＝對著；牛＝聽不懂的牛；彈琴＝彈奏樂曲。對不懂的對象講道理，白費力氣。",deep:"典故由來：出自漢．牟融《理惑論》：公明儀對牛彈奏高雅琴曲，牛照樣低頭吃草，因為聽不懂。\n字面意思：對著牛彈琴。\n引申意思：對不懂道理的人講道理，白費工夫（如：跟他談藝術簡直對牛彈琴）。含譏諷；用時注意對象，易得罪人。" },
  { id: "i234", grade: 3, term: "如魚得水", zhuyin: "ㄖㄨˊ ㄩˊ ㄉㄜˊ ㄕㄨㄟˇ", pinyin: "rú yú dé shuǐ", meaning: "像魚回到水中，比喻得到契合的環境或夥伴。", example: "轉到美術班後，他如魚得水，進步神速。" , wordExp: "如＝好像；魚＝魚兒；得水＝回到水裡。得到最適合自己的環境。",deep:"典故由來：出自《三國志．諸葛亮傳》：劉備得諸葛亮後說：「孤之有孔明，猶魚之有水也。」\n字面意思：像魚回到水裡。\n引申意思：得到契合的環境或夥伴（如：他轉到新學校如魚得水）。褒義。" },
  { id: "i235", grade: 3, term: "井底之蛙", zhuyin: "ㄐㄧㄥˇ ㄉㄧˇ ㄓ ㄨㄚ", pinyin: "jǐng dǐ zhī wā", meaning: "比喻見識淺薄狹隘的人。", example: "多出去走走，別當井底之蛙。", syn: ["坐井觀天"] , wordExp: "井底＝水井底部；之＝的；蛙＝青蛙。只看得見井口天空的青蛙，見識狹小。",deep:"典故由來：出自《莊子．秋水》：住在淺井裡的青蛙向東海之鱉誇耀井中快樂，鱉告訴牠大海之大，青蛙才自慚渺小。\n字面意思：井底下的青蛙，只看得到井口大的天。\n引申意思：見識狹小的人（如：不出去看看世界，就像井底之蛙）。貶義。" },
  { id: "i236", grade: 3, term: "自相矛盾", zhuyin: "ㄗˋ ㄒㄧㄤ ㄇㄠˊ ㄉㄨㄣˋ", pinyin: "zì xiāng máo dùn", meaning: "言行前後牴觸，互相衝突。", example: "他一下說沒去過，一下又描述現場，自相矛盾。" , wordExp: "自相＝自己跟自己；矛＝攻擊的長矛；盾＝防禦的盾牌。賣矛又賣盾的人說詞互相牴觸。",deep:"典故由來：出自《韓非子．難一》：楚國人同時賣矛和盾，誇盾什麼都刺不破，又誇矛什麼都刺得破；有人問「用你的矛刺你的盾會怎樣」，他答不出來。\n字面意思：自己的矛戳自己的盾。\n引申意思：言行前後衝突（如：他的說詞自相矛盾）。貶義。" },
  { id: "i237", grade: 3, term: "濫竽充數", zhuyin: "ㄌㄢˋ ㄩˊ ㄔㄨㄥ ㄕㄨˋ", pinyin: "làn yú chōng shù", meaning: "沒有真本領的人混在行家中充數。", example: "他根本不會彈，只是在樂團裡濫竽充數。", syn: ["魚目混珠"], misuse: "也可自謙才能不足；不可寫成「爛芋充數」。" , wordExp: "濫＝不合格；竽＝竹製吹奏樂器；充數＝湊人數。不會吹竽混在樂隊裡充數。",deep:"典故由來：出自《韓非子．內儲說上》：齊宣王聽吹竽必三百人合奏，不會吹的南郭處士混在其中領俸祿；湣王繼位改要一個一個吹，南郭先生只好逃走。\n字面意思：不會吹竽的人混在樂隊裡湊人數。\n引申意思：沒有真本領卻混在行家中充數（如：我加入合唱團只是濫竽充數）；也可自謙。" },
  { id: "i238", grade: 3, term: "刻舟求劍", zhuyin: "ㄎㄜˋ ㄓㄡ ㄑㄧㄡˊ ㄐㄧㄢˋ", pinyin: "kè zhōu qiú jiàn", meaning: "比喻拘泥固執，不知隨情勢變通。", example: "市場早就變了，還用十年前的方法是刻舟求劍。", syn: ["守株待兔"] , wordExp: "刻＝刻記號；舟＝船；求＝找；劍＝掉落的劍。劍掉水裡卻在船上刻記號，不知變通。",deep:"典故由來：出自《呂氏春秋．察今》：楚國人渡江時劍掉入水中，他在船邊刻記號，說「我的劍是從這裡掉的」，等船靠岸才從記號處下水找劍，當然找不到。\n字面意思：在船上刻記號找落水的劍。\n引申意思：拘泥成法、不知變通（如：時代變了還用老方法，無異刻舟求劍）。貶義。" },
  { id: "i239", grade: 3, term: "朝三暮四", zhuyin: "ㄓㄠ ㄙㄢ ㄇㄨˋ ㄙˋ", pinyin: "zhāo sān mù sì", meaning: "本指用詐術欺人，後多比喻反覆無常。", example: "他對目標朝三暮四，難成大事。", misuse: "「朝」讀ㄓㄠ。與「朝秦暮楚」義近。" , wordExp: "朝＝早上；三、四＝橡實的數量；暮＝傍晚。早三顆晚四顆哄猴子，後指反覆無常。",deep:"典故由來：出自《莊子．齊物論》：養猴人分橡實，說「早上三顆晚上四顆」，猴子大怒；改說「早上四顆晚上三顆」，猴子大喜——總數其實一樣。\n字面意思：早上三個、傍晚四個。\n引申意思：原指用手段愚弄人，今多指主意反覆無常（如：他朝三暮四，一下要學琴一下要學畫）。貶義。" },
  { id: "i240", grade: 3, term: "半信半疑", zhuyin: "ㄅㄢˋ ㄒㄧㄣˋ ㄅㄢˋ ㄧˊ", pinyin: "bàn xìn bàn yí", meaning: "有點相信，又有點懷疑。", example: "聽到這個消息，大家都半信半疑。", syn: ["將信將疑"] , wordExp: "半信＝一半相信；半疑＝一半懷疑。信又不全信。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：一半相信、一半懷疑。\n引申意思：不能完全相信（如：對這消息大家半信半疑）。" },
  { id: "i241", grade: 3, term: "津津有味", zhuyin: "ㄐㄧㄣ ㄐㄧㄣ ㄧㄡˇ ㄨㄟˋ", pinyin: "jīn jīn yǒu wèi", meaning: "形容吃得很有滋味或聽得很有興致。", example: "弟弟捧著漫畫看得津津有味。" , wordExp: "津津＝滋味濃、興味濃的樣子；有味＝有滋味。吃得或聽得興味盎然。",deep:"典故由來：明清小說常見；「津津」是有滋味、有興味的樣子。\n字面意思：滋味濃厚。\n引申意思：吃得有滋味，或談得、聽得很有興致（如：津津有味地聽故事）。" },
  { id: "i242", grade: 3, term: "目瞪口呆", zhuyin: "ㄇㄨˋ ㄉㄥˋ ㄎㄡˇ ㄉㄞ", pinyin: "mù dèng kǒu dāi", meaning: "瞪大眼睛說不出話，形容受驚或驚訝的樣子。", example: "魔術師把汽車變不見，觀眾看得目瞪口呆。", syn: ["瞠目結舌"] , wordExp: "目瞪＝眼睛瞪大；口呆＝嘴巴發呆。驚訝得說不出話。",deep:"典故由來：元明戲曲小說常見的口語成語。\n字面意思：眼睛瞪大、嘴巴張著說不出話。\n引申意思：因吃驚或害怕而發呆（如：看到成績單，他目瞪口呆）。" },
  { id: "i243", grade: 4, term: "三顧茅廬", zhuyin: "ㄙㄢ ㄍㄨˋ ㄇㄠˊ ㄌㄨˊ", pinyin: "sān gù máo lú", meaning: "比喻誠心誠意一再邀請賢才。", example: "總教練三顧茅廬，終於請動名師出山。", misuse: "劉備請諸葛亮的典故，強調誠意與敬重，不用於一般拜訪。" , wordExp: "三＝三次；顧＝拜訪；茅廬＝草屋。劉備三次到草廬請諸葛亮，誠心求才。",deep:"典故由來：出自諸葛亮〈出師表〉：「先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中。」劉備三次親訪諸葛亮，請他出山相助。\n字面意思：三次拜訪茅草屋。\n引申意思：誠心誠意一再邀請賢才（如：老闆三顧茅廬請他出任要職）。褒義。" },
  { id: "i244", grade: 4, term: "名落孫山", zhuyin: "ㄇㄧㄥˊ ㄌㄨㄛˋ ㄙㄨㄣ ㄕㄢ", pinyin: "míng luò sūn shān", meaning: "考試或選拔沒有錄取。", example: "他第一年應試名落孫山，隔年捲土重來。" , wordExp: "名＝名字；落＝落在；孫山＝末名考生的名字。名字落在孫山之後，落榜了。",deep:"典故由來：出自宋．范公偁《過庭錄》：孫山考中最後一名，同鄉問兒子考況，孫山答：「解名盡處是孫山，賢郎更在孫山外。」\n字面意思：名次落在孫山之後。\n引申意思：考試沒有錄取（如：這次會考名落孫山，明年再戰）。" },
  { id: "i245", grade: 4, term: "塞翁失馬", zhuyin: "ㄙㄞˋ ㄨㄥ ㄕ ㄇㄚˇ", pinyin: "sài wēng shī mǎ", meaning: "比喻禍福無常，壞事也可能帶來好結果。", example: "班機取消反而躲過颱風，真是塞翁失馬。", misuse: "「塞」在此讀ㄙㄞˋ。後常接「焉知非福」。" , wordExp: "塞＝邊塞；翁＝老翁；失馬＝丟了馬。塞翁丟馬反得福，禍福難料。",deep:"典故由來：出自《淮南子．人間訓》：邊塞老翁丟了馬，人們安慰他，他說「未必不是福」；馬帶回駿馬，又說「未必不是禍」；兒子騎馬摔斷腿，戰爭爆發時反而免役保命。\n字面意思：邊塞老翁丟了馬。\n引申意思：禍福無常，壞事可能變好事（常說「塞翁失馬，焉知非福」）。" },
  { id: "i246", grade: 4, term: "東施效顰", zhuyin: "ㄉㄨㄥ ㄕ ㄒㄧㄠˋ ㄆㄧㄣˊ", pinyin: "dōng shī xiào pín", meaning: "盲目模仿別人，反而弄巧成拙。", example: "硬抄別人的風格卻學得四不像，無異於東施效顰。", syn: ["邯鄲學步"] , wordExp: "東施＝醜女；效＝模仿；顰＝皺眉。醜女模仿西施皺眉，弄巧成拙。",deep:"典故由來：出自《莊子．天運》：美女西施心痛皺眉更顯美麗，鄰家醜女東施模仿皺眉，反而讓人避走。\n字面意思：東施模仿西施皺眉。\n引申意思：盲目模仿反而出醜（如：抄襲別人的風格是東施效顰）。貶義。" },
  { id: "i247", grade: 4, term: "打草驚蛇", zhuyin: "ㄉㄚˇ ㄘㄠˇ ㄐㄧㄥ ㄕㄜˊ", pinyin: "dǎ cǎo jīng shé", meaning: "行動不密，讓對方有所警覺防備。", example: "先別聲張，免得打草驚蛇，讓嫌犯逃走。" , wordExp: "打＝拍打；草＝草叢；驚＝驚動；蛇＝蛇。打草把蛇驚跑了，行動不密使對方警覺。",deep:"典故由來：出自宋．鄭文寶《南唐近事》：縣令王魯貪汙，屬下被告發，他批「汝雖打草，吾已蛇驚」——你打草，我這條蛇已受驚。\n字面意思：打動草叢，驚動了藏在裡面的蛇。\n引申意思：行動不謹慎，讓對方警覺有備（如：先別聲張，以免打草驚蛇）。" },
  { id: "i248", grade: 4, term: "雪上加霜", zhuyin: "ㄒㄩㄝˇ ㄕㄤˋ ㄐㄧㄚ ㄕㄨㄤ", pinyin: "xuě shàng jiā shuāng", meaning: "災禍或困難接連而來，處境更加惡化。", example: "工廠失火又逢景氣低迷，真是雪上加霜。", syn: ["禍不單行"] , wordExp: "雪上＝積雪之上；加霜＝再落霜。災上加災，處境更糟。",deep:"典故由來：見宋．《景德傳燈錄》：「伊退步有分，猶較些子；若也不退，雪上加霜。」\n字面意思：雪上又加了一層霜。\n引申意思：災禍接連而來，處境更糟（如：失業又生病，真是雪上加霜）。相對詞：錦上添花。" },
  { id: "i249", grade: 4, term: "錦囊妙計", zhuyin: "ㄐㄧㄣˇ ㄋㄤˊ ㄇㄧㄠˋ ㄐㄧˋ", pinyin: "jǐn náng miào jì", meaning: "預先準備好的高明計策。", example: "教練賽前留了錦囊妙計，下半場果然逆轉。" , wordExp: "錦囊＝錦緞袋子；妙計＝高明的計策。裝在錦囊裡備用的好計策。",deep:"典故由來：出自《三國演義》：諸葛亮讓趙雲帶三個錦囊隨劉備入吳，危急時依次拆開，果然化險為夷。\n字面意思：錦緞袋子裡的神妙計策。\n引申意思：預先準備好的高明辦法（如：教練還有錦囊妙計）。褒義。" },
  { id: "i250", grade: 4, term: "舉一反三", zhuyin: "ㄐㄩˇ ㄧ ㄈㄢˇ ㄙㄢ", pinyin: "jǔ yī fǎn sān", meaning: "從一件事類推明白其他許多事。", example: "學會這題的解法，就能舉一反三解出同類題。", syn: ["觸類旁通"] , wordExp: "舉＝提出；一＝一個例子；反＝類推；三＝其他三個。從一件事類推出許多道理。",deep:"典故由來：出自《論語．述而》：「舉一隅不以三隅反，則不復也。」孔子要學生能由一個角落推想其他三個角落。\n字面意思：舉出一個，能推知其他三個。\n引申意思：由一件事類推許多事、觸類旁通（如：學習要能舉一反三）。褒義。" },
  // ---- i251-i300（國小中高年級） ----
  { id: "i251", grade: 4, term: "螳臂當車", zhuyin: "ㄊㄤˊ ㄅㄧˋ ㄉㄤ ㄔㄜ", pinyin: "táng bì dāng chē", meaning: "比喻不自量力，去做辦不到的事。", example: "以一人之力對抗大財團，難免螳臂當車。", misuse: "「當」在此讀ㄉㄤ，是阻擋的意思。" , wordExp: "螳＝螳螂；臂＝前臂；當＝阻擋；車＝車子。螳螂舉臂擋車，不自量力。",deep:"典故由來：出自《莊子．人間世》：螳螂舉起前臂想擋住車輪，不知道自己根本擋不住。\n字面意思：螳螂舉臂擋車。\n引申意思：不自量力去做辦不到的事（如：以一人之力對抗大企業，無異螳臂當車）。貶義。" },
  { id: "i252", grade: 4, term: "畫餅充飢", zhuyin: "ㄏㄨㄚˋ ㄅㄧㄥˇ ㄔㄨㄥ ㄐㄧ", pinyin: "huà bǐng chōng jī", meaning: "比喻用空想安慰自己，無濟於事。", example: "沒有行動，再美的計畫也只是畫餅充飢。", syn: ["望梅止渴"] , wordExp: "畫餅＝畫出來的餅；充飢＝填飽肚子。畫的餅不能吃，空想無濟於事。",deep:"典故由來：出自《三國志．魏書．盧毓傳》：魏明帝說選人不能只看名聲，「名如畫地作餅，不可啖也」——名聲像畫的餅，不能吃。\n字面意思：畫一張餅來解餓。\n引申意思：用空想安慰自己，於事無補（如：沒有行動，計畫只是畫餅充飢）。貶義。" },
  { id: "i253", grade: 4, term: "掩人耳目", zhuyin: "ㄧㄢˇ ㄖㄣˊ ㄦˇ ㄇㄨˋ", pinyin: "yǎn rén ěr mù", meaning: "遮蔽別人的視聽，隱瞞真相。", example: "他假裝加班，其實是掩人耳目，偷偷練舞準備驚喜。" , wordExp: "掩＝遮蔽；人＝別人的；耳目＝聽覺視覺。遮住別人耳目，隱瞞真相。",deep:"典故由來：由字面組合而成，宋代文獻已見。\n字面意思：遮住別人的耳朵和眼睛。\n引申意思：用假象欺瞞他人（如：布置假現場掩人耳目）。貶義。" },
  { id: "i254", grade: 4, term: "一箭雙鵰", zhuyin: "ㄧ ㄐㄧㄢˋ ㄕㄨㄤ ㄉㄧㄠ", pinyin: "yī jiàn shuāng diāo", meaning: "一次行動同時達到兩個目的。", example: "騎車上班既省油錢又能健身，一箭雙鵰。", syn: ["一舉兩得", "一石二鳥"] , wordExp: "一箭＝一支箭；雙鵰＝兩隻大鵰。一箭射中兩鵰，一舉兩得。",deep:"典故由來：出自《北史．長孫晟傳》：長孫晟見兩鵰爭肉，一箭同時射穿兩隻。\n字面意思：一支箭射下兩隻鵰。\n引申意思：一次行動達到兩個目的（如：這方案省錢又環保，一箭雙鵰）。近義：一舉兩得。" },
  { id: "i255", grade: 4, term: "見義勇為", zhuyin: "ㄐㄧㄢˋ ㄧˋ ㄩㄥˇ ㄨㄟˊ", pinyin: "jiàn yì yǒng wéi", meaning: "看到合乎正義的事就勇敢去做。", example: "他見義勇為，跳下月台救起跌落的旅客。", syn: ["拔刀相助"] , wordExp: "見＝見到；義＝正義的事；勇為＝勇敢去做。遇見該做的事挺身而出。",deep:"典故由來：語本《論語．為政》：「見義不為，無勇也。」\n字面意思：見到合乎正義的事就勇敢去做。\n引申意思：挺身而出做正義的事（如：他見義勇為救起落水的人）。褒義。" },
  { id: "i256", grade: 4, term: "樂善好施", zhuyin: "ㄌㄜˋ ㄕㄢˋ ㄏㄠˋ ㄕ", pinyin: "lè shàn hào shī", meaning: "樂於行善，喜歡施捨助人。", example: "老闆樂善好施，每年捐米給育幼院。", misuse: "「好」在此讀ㄏㄠˋ，喜好之意。" , wordExp: "樂＝樂於；善＝行善；好＝喜好；施＝施捨。樂於行善、喜歡助人。",deep:"典故由來：由「樂於為善、好行施惠」組合，漢代以來常用。\n字面意思：樂於做善事、喜歡施捨。\n引申意思：熱心行善助人（如：他樂善好施，常捐款救災）。褒義。" },
  { id: "i257", grade: 4, term: "專心致志", zhuyin: "ㄓㄨㄢ ㄒㄧㄣ ㄓˋ ㄓˋ", pinyin: "zhuān xīn zhì zhì", meaning: "心思專一，全神投入。", example: "他專心致志地準備比賽，婉拒所有邀約。", syn: ["全神貫注", "聚精會神"] , wordExp: "專心＝心思專一；致志＝集中意志。全副心思投入。",deep:"典故由來：出自《孟子．告子上》：弈秋教兩人下棋，一人專心致志，另一人想著射天鵝，成就大不相同。\n字面意思：心思專一、意志集中。\n引申意思：全心投入（如：專心致志地讀書）。褒義。" },
  { id: "i258", grade: 4, term: "聚精會神", zhuyin: "ㄐㄩˋ ㄐㄧㄥ ㄏㄨㄟˋ ㄕㄣˊ", pinyin: "jù jīng huì shén", meaning: "集中精神，專心一意。", example: "同學們聚精會神地看著實驗的變化。", syn: ["全神貫注", "目不轉睛"] , wordExp: "聚＝聚集；精＝精力；會＝集中；神＝精神。精神全部集中。",deep:"典故由來：出自漢．王褒〈聖主得賢臣頌〉：「聚精會神，相得益章。」\n字面意思：聚集精力、會合心神。\n引申意思：注意力高度集中（如：觀眾聚精會神地看表演）。褒義。" },
  { id: "i259", grade: 4, term: "突飛猛進", zhuyin: "ㄊㄨˊ ㄈㄟ ㄇㄥˇ ㄐㄧㄣˋ", pinyin: "tú fēi měng jìn", meaning: "進步非常快速。", example: "每天練琴一小時，他的琴藝突飛猛進。", syn: ["一日千里"] , wordExp: "突＝突然；飛＝飛躍；猛＝猛烈；進＝前進。進步飛快。",deep:"典故由來：近代組合成語。\n字面意思：像飛一樣突進、像猛獸一樣前進。\n引申意思：進步極快（如：成績突飛猛進）。褒義。" },
  { id: "i260", grade: 4, term: "一鼓作氣", zhuyin: "ㄧ ㄍㄨˇ ㄗㄨㄛˋ ㄑㄧˋ", pinyin: "yī gǔ zuò qì", meaning: "趁著勁頭一口氣把事情做完。", example: "趁記憶猶新，一鼓作氣把報告寫完。", misuse: "出自曹劌論戰「一鼓作氣，再而衰，三而竭」。" , wordExp: "一鼓＝第一通戰鼓；作氣＝鼓起勇氣。趁著初起的勁頭一口氣完成。",deep:"典故由來：出自《左傳．莊公十年》曹劌論戰：「夫戰，勇氣也。一鼓作氣，再而衰，三而竭。」第一通鼓最能振奮士氣。\n字面意思：擂第一通鼓時鼓足勇氣。\n引申意思：趁勁頭足一口氣完成（如：一鼓作氣把作業寫完）。注意是「作氣」不是「做氣」。" },
  { id: "i261", grade: 4, term: "千辛萬苦", zhuyin: "ㄑㄧㄢ ㄒㄧㄣ ㄨㄢˋ ㄎㄨˇ", pinyin: "qiān xīn wàn kǔ", meaning: "形容經歷極多的艱難困苦。", example: "登山隊歷經千辛萬苦，終於攻頂成功。", syn: ["含辛茹苦"] , wordExp: "千、萬＝形容多；辛、苦＝辛勞苦難。歷盡各種艱辛。",deep:"典故由來：元代戲曲中已常見。\n字面意思：一千種辛勞、一萬種苦楚。\n引申意思：極多的艱難困苦（如：歷經千辛萬苦才成功）。" },
  { id: "i262", grade: 4, term: "不屈不撓", zhuyin: "ㄅㄨˋ ㄑㄩ ㄅㄨˋ ㄋㄠˊ", pinyin: "bù qū bù náo", meaning: "意志堅定，遇挫折也不屈服。", example: "她不屈不撓地復健，終於重新站上舞台。", syn: ["百折不撓", "堅忍不拔"] , wordExp: "不屈＝不屈服；不撓＝不彎曲。意志堅定，永不低頭。",deep:"典故由來：語本《漢書．敘傳》：「樂昌篤實，不橈不詘。」（橈＝撓，彎曲）\n字面意思：不彎曲、不屈服。\n引申意思：意志堅強，遇挫折不低頭（如：不屈不撓地奮鬥）。褒義。" },
  { id: "i263", grade: 5, term: "臥薪嘗膽", zhuyin: "ㄨㄛˋ ㄒㄧㄣ ㄔㄤˊ ㄉㄢˇ", pinyin: "wò xīn cháng dǎn", meaning: "刻苦自勵，發憤圖強，不忘雪恥。", example: "球隊去年慘敗後臥薪嘗膽，今年奪回冠軍。", misuse: "越王句踐復國的典故。" , wordExp: "臥＝睡在；薪＝柴草；嘗＝品嘗；膽＝苦膽。句踐睡柴嘗膽不忘國恥，刻苦自勵。",deep:"典故由來：出自《史記．越王句踐世家》：越王句踐兵敗於吳，回國後睡在柴薪上、懸苦膽時時嘗之，提醒自己不忘恥辱，最後滅吳雪恥。\n字面意思：睡在柴薪上、品嘗苦膽。\n引申意思：刻苦自勵、發憤圖強（如：球隊臥薪嘗膽一年，終於奪回冠軍）。褒義。" },
  { id: "i264", grade: 5, term: "負荊請罪", zhuyin: "ㄈㄨˋ ㄐㄧㄥ ㄑㄧㄥˇ ㄗㄨㄟˋ", pinyin: "fù jīng qǐng zuì", meaning: "背著荊條請罪，表示誠心認錯。", example: "他知道錯怪了同事，便登門負荊請罪。", misuse: "廉頗向藺相如謝罪的典故。" , wordExp: "負＝背著；荊＝荊條（可作刑杖）；請罪＝請求責罰。背荊條登門認錯，誠心謝罪。",deep:"典故由來：出自《史記．廉頗藺相如列傳》：廉頗不服藺相如位居其上，處處挑釁；相如以國家為重處處退讓。廉頗得知後羞愧，裸背背著荊條到相如府上請罪，兩人結為刎頸之交。\n字面意思：背著荊條請求責罰。\n引申意思：誠心誠意認錯賠罪（如：他負荊請罪，請求原諒）。" },
  { id: "i265", grade: 5, term: "完璧歸趙", zhuyin: "ㄨㄢˊ ㄅㄧˋ ㄍㄨㄟ ㄓㄠˋ", pinyin: "wán bì guī zhào", meaning: "把原物完好無缺地歸還本人。", example: "撿到的相機已完璧歸趙，物主連聲道謝。", misuse: "藺相如奉璧使秦的典故。" , wordExp: "完＝完好；璧＝寶玉；歸＝送回；趙＝趙國。藺相如把和氏璧完整送回趙國，物歸原主。",deep:"典故由來：出自《史記．廉頗藺相如列傳》：藺相如帶和氏璧出使秦國，識破秦王無意以城換璧，機智周旋，終於把璧完好地送回趙國。\n字面意思：把和氏璧完整歸還趙國。\n引申意思：把原物完好無缺地歸還（如：借的書我一定完璧歸趙）。" },
  { id: "i266", grade: 5, term: "毛遂自薦", zhuyin: "ㄇㄠˊ ㄙㄨㄟˋ ㄗˋ ㄐㄧㄢˋ", pinyin: "máo suì zì jiàn", meaning: "自我推薦，主動請求任務。", example: "缺少主持人時，她毛遂自薦扛下重任。" , wordExp: "毛遂＝人名；自薦＝自我推薦。毛遂自己推薦自己出使，勇於自我爭取。",deep:"典故由來：出自《史記．平原君列傳》：秦圍邯鄲，平原君選門客赴楚求救，毛遂主動自薦隨行，並在楚廷按劍直言，促成楚趙合縱。\n字面意思：毛遂自己推薦自己。\n引申意思：主動推薦自己承擔任務（如：他毛遂自薦擔任隊長）。" },
  { id: "i267", grade: 5, term: "紙上談兵", zhuyin: "ㄓˇ ㄕㄤˋ ㄊㄢˊ ㄅㄧㄥ", pinyin: "zhǐ shàng tán bīng", meaning: "空談理論，不能解決實際問題。", example: "沒下過廚就開餐廳，恐怕是紙上談兵。", syn: ["坐而論道"], misuse: "趙括空談兵法致敗的典故。" , wordExp: "紙上＝在紙面上；談兵＝談論用兵。趙括只會書上談兵而大敗，空談理論。",deep:"典故由來：出自《史記．廉頗藺相如列傳》：趙括自幼熟讀兵書、談兵頭頭是道，實戰卻不知變通；長平之戰代廉頗為將，四十萬趙軍被秦坑殺。\n字面意思：在紙面上談論用兵。\n引申意思：空談理論、不能解決實際問題（如：沒做過就別紙上談兵）。貶義。" },
  { id: "i268", grade: 5, term: "破釜沉舟", zhuyin: "ㄆㄛˋ ㄈㄨˇ ㄔㄣˊ ㄓㄡ", pinyin: "pò fǔ chén zhōu", meaning: "下定決心，不留退路地拚到底。", example: "他辭掉工作破釜沉舟，全心準備國考。", syn: ["背水一戰"] , wordExp: "破＝打破；釜＝鍋子；沉＝鑿沉；舟＝船。項羽破鍋沉船斷退路，決一死戰。",deep:"典故由來：出自《史記．項羽本紀》：項羽率軍渡河救鉅鹿，過河後鑿沉船隻、打破炊具，只帶三日糧，示士卒必死無退，遂九戰九勝大破秦軍。\n字面意思：打破鍋子、鑿沉渡船。\n引申意思：下定決心、不留退路地拚到底（如：破釜沉舟，全力備考）。褒義。" },
  { id: "i269", grade: 5, term: "四通八達", zhuyin: "ㄙˋ ㄊㄨㄥ ㄅㄚ ㄉㄚˊ", pinyin: "sì tōng bā dá", meaning: "交通便利，各方通行無阻。", example: "台北捷運四通八達，出門十分方便。" , wordExp: "四通＝四方通達；八達＝八方到達。道路網四面八方都相通。",deep:"典故由來：由字面組合而成；四方八面都通達。\n字面意思：四面八方都有路相通。\n引申意思：交通極為便利（如：高鐵讓城市四通八達）。" },
  { id: "i270", grade: 5, term: "五花八門", zhuyin: "ㄨˇ ㄏㄨㄚ ㄅㄚ ㄇㄣˊ", pinyin: "wǔ huā bā mén", meaning: "花樣繁多，變化多端。", example: "夜市小吃五花八門，讓人眼花撩亂。", syn: ["形形色色", "琳瑯滿目"] , wordExp: "五花＝五行陣；八門＝八門陣（皆古陣名）。花樣繁多，變化多端。",deep:"典故由來：語本古代陣法「五花陣」「八門陣」，變化多端。\n字面意思：五種花樣、八種門類。\n引申意思：花樣繁多（如：夜市小吃五花八門）。" },
  { id: "i271", grade: 5, term: "六神無主", zhuyin: "ㄌㄧㄡˋ ㄕㄣˊ ㄨˊ ㄓㄨˇ", pinyin: "liù shén wú zhǔ", meaning: "驚慌失措，拿不定主意。", example: "聽到火警警報，他一時六神無主。", syn: ["手足無措", "驚慌失措"] , wordExp: "六神＝道家指主宰臟腑的六位神；無主＝失了主張。驚慌得沒了主意。",deep:"典故由來：道家以心、肺、肝、腎、脾、膽各有神明主宰，合稱六神。\n字面意思：六位神明都失去了主張。\n引申意思：驚慌失措、拿不定主意（如：突聞噩耗，他六神無主）。" },
  { id: "i272", grade: 5, term: "七上八下", zhuyin: "ㄑㄧ ㄕㄤˋ ㄅㄚ ㄒㄧㄚˋ", pinyin: "qī shàng bā xià", meaning: "心裡忐忑不安。", example: "成績公布前，他心裡七上八下。", syn: ["忐忑不安"] , wordExp: "七上＝七個往上；八下＝八個往下。心裡像吊桶七上八下，忐忑不安。",deep:"典故由來：見宋代禪宗語錄，形容心緒不定如「一似十五個吊桶打水，七上八下」。\n字面意思：七個上、八個下，懸著不定。\n引申意思：心神不寧（如：等成績時心裡七上八下）。" },
  { id: "i273", grade: 5, term: "九牛一毛", zhuyin: "ㄐㄧㄡˇ ㄋㄧㄡˊ ㄧ ㄇㄠˊ", pinyin: "jiǔ niú yī máo", meaning: "極大數量中微不足道的一部分。", example: "這筆罰款對富豪而言只是九牛一毛。", syn: ["滄海一粟"] , wordExp: "九牛＝九頭牛；一毛＝一根毛。九頭牛身上的一根毛，微不足道。",deep:"典故由來：出自漢．司馬遷〈報任少卿書〉：「假令僕伏法受誅，若九牛亡一毛，與螻蟻何以異？」\n字面意思：九頭牛身上掉一根毛。\n引申意思：極大數量中微不足道的一點（如：這筆錢對富豪只是九牛一毛）。" },
  { id: "i274", grade: 5, term: "十萬火急", zhuyin: "ㄕˊ ㄨㄢˋ ㄏㄨㄛˇ ㄐㄧˊ", pinyin: "shí wàn huǒ jí", meaning: "事情緊急到了極點。", example: "傷患大出血，十萬火急送往醫院。", syn: ["刻不容緩", "迫在眉睫"] , wordExp: "十萬＝形容緊急程度；火急＝像火燒一樣急。緊急到極點。",deep:"典故由來：古代軍情文書插羽毛、標「火急」以示緊急，「十萬」極言其甚。\n字面意思：十萬分的火速緊急。\n引申意思：事情緊急到極點（如：十萬火急，馬上出發）。" },
  { id: "i275", grade: 5, term: "百發百中", zhuyin: "ㄅㄞˇ ㄈㄚ ㄅㄞˇ ㄓㄨㄥˋ", pinyin: "bǎi fā bǎi zhòng", meaning: "射箭百次全中，比喻料事或做事極有把握。", example: "老投手控球百發百中，連續三振打者。", misuse: "「中」在此讀ㄓㄨㄥˋ。" , wordExp: "百發＝射一百次；百中＝中一百次。每發必中，極有把握。",deep:"典故由來：出自《戰國策．西周策》：楚國養由基「去柳葉者百步而射之，百發百中」。\n字面意思：射一百次、中一百次。\n引申意思：料事或做事極有把握（如：他投籃百發百中）。褒義。" },
  { id: "i276", grade: 5, term: "千鈞一髮", zhuyin: "ㄑㄧㄢ ㄐㄩㄣ ㄧ ㄈㄚˇ", pinyin: "qiān jūn yī fǎ", meaning: "情況危急到了極點。", example: "千鈞一髮之際，消防員把他拉出火場。", syn: ["危在旦夕", "岌岌可危"] , wordExp: "千鈞＝三萬斤重；一髮＝一根頭髮。千鈞重物繫於一髮，危險至極。",deep:"典故由來：語本《漢書．枚乘傳》「夫以一縷之任，繫千鈞之重」；韓愈〈與孟尚書書〉「其危如一髮引千鈞」。鈞是三十斤。\n字面意思：千鈞重物繫在一根頭髮上。\n引申意思：情勢危急到極點（如：千鈞一髮之際，他拉住了孩子）。" },
  { id: "i277", grade: 5, term: "萬無一失", zhuyin: "ㄨㄢˋ ㄨˊ ㄧ ㄕ", pinyin: "wàn wú yī shī", meaning: "非常周全，絕不會出差錯。", example: "重要資料多做兩份備份，才能萬無一失。", syn: ["十拿九穩"] , wordExp: "萬＝一萬次；無一失＝沒有一次失誤。絕對穩妥。",deep:"典故由來：語本漢代文獻「萬不失一」（《史記》等）。\n字面意思：一萬次中不出一次差錯。\n引申意思：極有把握、絕不出錯（如：計畫周密，萬無一失）。" },
  { id: "i278", grade: 5, term: "應接不暇", zhuyin: "ㄧㄥˋ ㄐㄧㄝ ㄅㄨˋ ㄒㄧㄚˊ", pinyin: "yìng jiē bù xiá", meaning: "事物繁多，來不及應付或欣賞。", example: "訂單如雪片般湧入，讓客服應接不暇。", misuse: "「應」在此讀ㄧㄥˋ。" , wordExp: "應接＝應酬接待；不暇＝沒有空閒。事物太多，接應不過來。",deep:"典故由來：出自《世說新語．言語》：王子敬說「從山陰道上行，山川自相映發，使人應接不暇」。\n字面意思：來不及一一應對接待。\n引申意思：美景或事務繁多，來不及應付（如：訂單多到應接不暇）。" },
  { id: "i279", grade: 5, term: "目不暇給", zhuyin: "ㄇㄨˋ ㄅㄨˋ ㄒㄧㄚˊ ㄐㄧˇ", pinyin: "mù bù xiá jǐ", meaning: "美好事物太多，眼睛看不過來。", example: "花燈爭奇鬥豔，令人目不暇給。", misuse: "「給」在此讀ㄐㄧˇ。", syn: ["美不勝收"] , wordExp: "目＝眼睛；不暇＝來不及；給＝供應。美景多得眼睛看不過來。",deep:"典故由來：與「應接不暇」同源的後起語；「暇」是空閒，「給」是供給。\n字面意思：眼睛來不及看。\n引申意思：美好事物太多，看不過來（如：櫥窗琳瑯滿目，令人目不暇給）。" },
  { id: "i280", grade: 5, term: "美不勝收", zhuyin: "ㄇㄟˇ ㄅㄨˋ ㄕㄥ ㄕㄡ", pinyin: "měi bù shēng shōu", meaning: "美好的事物多得看不完。", example: "太魯閣峽谷景色美不勝收。", misuse: "「勝」在此讀ㄕㄥ（審訂音）。", syn: ["目不暇給"] , wordExp: "美＝美景；不勝＝承受不完；收＝收攬。美好事物多得欣賞不完。",deep:"典故由來：見清．錢泳《履園叢話》：「重游其地，見樓臺花木，美不勝收。」\n字面意思：美景多得無法全部收覽。\n引申意思：美好事物極多（如：湖畔風光美不勝收）。" },
  { id: "i281", grade: 5, term: "嘆為觀止", zhuyin: "ㄊㄢˋ ㄨㄟˊ ㄍㄨㄢ ㄓˇ", pinyin: "tàn wéi guān zhǐ", meaning: "讚嘆所見事物美好到了極點。", example: "故宮的翠玉白菜工藝精巧，令人嘆為觀止。", misuse: "是讚美之詞，不可用於形容慘狀。" , wordExp: "嘆＝讚嘆；為＝是；觀止＝看到這裡就夠了。好到讓人讚嘆「看到此為止」。",deep:"典故由來：出自《左傳．襄公二十九年》：吳公子季札在魯國觀賞樂舞，看到〈韶箾〉時說「觀止矣」——看到這裡就是極致，不必再看別的了。\n字面意思：讚嘆看到這裡已是極致。\n引申意思：讚美事物好到極點（如：巧奪天工的雕刻令人嘆為觀止）。褒義。" },
  { id: "i282", grade: 5, term: "迥然不同", zhuyin: "ㄐㄩㄥˇ ㄖㄢˊ ㄅㄨˋ ㄊㄨㄥˊ", pinyin: "jiǒng rán bù tóng", meaning: "相差很大，完全不一樣。", example: "兄弟倆個性迥然不同，一動一靜。", syn: ["截然不同", "大相逕庭"] , wordExp: "迥然＝相距很遠的樣子；不同＝不一樣。相差極大。",deep:"典故由來：由字面組合而成；「迥」是遠、差得遠。\n字面意思：相差遙遠、完全不同。\n引申意思：差別極大（如：兄弟倆個性迥然不同）。" },
  { id: "i283", grade: 5, term: "截然不同", zhuyin: "ㄐㄧㄝˊ ㄖㄢˊ ㄅㄨˋ ㄊㄨㄥˊ", pinyin: "jié rán bù tóng", meaning: "界線分明，完全不同。", example: "同一件事，兩家媒體的報導角度截然不同。", syn: ["迥然不同"] , wordExp: "截然＝像切斷一樣分明；不同＝不一樣。界線分明，完全不同。",deep:"典故由來：由字面組合而成；「截然」是像切斷般分明。\n字面意思：像刀切一樣分得清清楚楚。\n引申意思：界線分明、完全不同（如：兩人的看法截然不同）。" },
  { id: "i284", grade: 5, term: "大相逕庭", zhuyin: "ㄉㄚˋ ㄒㄧㄤ ㄐㄧㄥˋ ㄊㄧㄥˊ", pinyin: "dà xiāng jìng tíng", meaning: "彼此差距極大，明顯不同。", example: "理想與現實大相逕庭，令他一時難以適應。", syn: ["天壤之別"] , wordExp: "大相＝彼此非常；逕＝門外小路；庭＝門內庭院。門裡門外差得遠，相差極大。",deep:"典故由來：語本《莊子．逍遙遊》：「大有逕庭，不近人情焉。」逕是門外小路，庭是堂前院子，兩者相隔。\n字面意思：門外小路和堂前庭院相距甚遠。\n引申意思：彼此差距極大（如：理想與現實大相逕庭）。" },
  { id: "i285", grade: 5, term: "相輔相成", zhuyin: "ㄒㄧㄤ ㄈㄨˇ ㄒㄧㄤ ㄔㄥˊ", pinyin: "xiāng fǔ xiāng chéng", meaning: "互相配合、互相補足，缺一不可。", example: "理論與實作相輔相成，缺一不可。", syn: ["相得益彰"] , wordExp: "相輔＝互相輔助；相成＝互相成全。彼此配合，缺一不可。",deep:"典故由來：由字面組合而成，明代文獻已見。\n字面意思：互相輔助、互相成全。\n引申意思：兩者互相配合、缺一不可（如：理論與實務相輔相成）。褒義。" },
  { id: "i286", grade: 5, term: "相得益彰", zhuyin: "ㄒㄧㄤ ㄉㄜˊ ㄧˋ ㄓㄤ", pinyin: "xiāng dé yì zhāng", meaning: "互相配合，彼此的長處更加顯著。", example: "紅酒配起司，兩者相得益彰。", syn: ["相輔相成"] , wordExp: "相得＝互相配合得宜；益＝更加；彰＝顯著。互相襯托，優點更明顯。",deep:"典故由來：出自漢．王褒〈聖主得賢臣頌〉：「聚精會神，相得益章（彰）。」\n字面意思：互相配合，好處更加顯著。\n引申意思：兩者相配，彼此長處更突出（如：紅花綠葉相得益彰）。褒義。" },
  { id: "i287", grade: 6, term: "出類拔萃", zhuyin: "ㄔㄨ ㄌㄟˋ ㄅㄚˊ ㄘㄨㄟˋ", pinyin: "chū lèi bá cuì", meaning: "才能超出同類之上。", example: "她的表現出類拔萃，獲選為模範生。", syn: ["鶴立雞群", "卓爾不群"] , wordExp: "出＝超出；類＝同類；拔＝高出；萃＝聚集的草叢。從同類中高高突出。",deep:"典故由來：出自《孟子．公孫丑上》：讚孔子「出於其類，拔乎其萃」——超出同類、高出群聚。\n字面意思：超出同類、高出草叢（萃＝聚集）。\n引申意思：才能遠超同輩（如：她的表現出類拔萃）。褒義。" },
  { id: "i288", grade: 6, term: "名副其實", zhuyin: "ㄇㄧㄥˊ ㄈㄨˋ ㄑㄧˊ ㄕˊ", pinyin: "míng fù qí shí", meaning: "名聲與實際相符。", example: "這家老店是名副其實的百年餅舖。", misuse: "「副」不可寫成「符」（「名符其實」為俗寫）。" , wordExp: "名＝名聲；副＝相符合；其實＝它的實質。名聲和實際相符。",deep:"典故由來：語本漢代「名實相副」的說法（曹操〈與王修書〉等）。\n字面意思：名聲和實際互相符合（副＝相稱）。\n引申意思：名不虛傳（如：名副其實的冠軍）。注意「副」不寫作「符」。" },
  { id: "i289", grade: 6, term: "首屈一指", zhuyin: "ㄕㄡˇ ㄑㄩ ㄧ ㄓˇ", pinyin: "shǒu qū yī zhǐ", meaning: "位居第一，最為優秀。", example: "這座港口的吞吐量在亞洲首屈一指。", syn: ["數一數二", "名列前茅"] , wordExp: "首＝首先；屈＝彎下；一指＝第一根手指。數第一名時先彎的那根指頭，居於首位。",deep:"典故由來：清代文獻常見；屈指計數時先彎大拇指，故第一稱「首屈一指」。\n字面意思：彎手指計算時首先彎下的那一指。\n引申意思：位居第一（如：他的醫術在國內首屈一指）。褒義。" },
  { id: "i290", grade: 6, term: "出神入化", zhuyin: "ㄔㄨ ㄕㄣˊ ㄖㄨˋ ㄏㄨㄚˋ", pinyin: "chū shén rù huà", meaning: "技藝高妙到了極點。", example: "布袋戲偶在師傅手中出神入化，栩栩如生。", syn: ["爐火純青", "登峰造極"] , wordExp: "出神＝超出神妙；入化＝進入化境。技藝高超到神妙的境界。",deep:"典故由來：元明戲曲評點用語，形容技藝神妙。\n字面意思：進入神妙、化境的境界。\n引申意思：技藝高超到極點（如：琴藝出神入化）。褒義。" },
  { id: "i291", grade: 6, term: "爐火純青", zhuyin: "ㄌㄨˊ ㄏㄨㄛˇ ㄔㄨㄣˊ ㄑㄧㄥ", pinyin: "lú huǒ chún qīng", meaning: "功夫修養達到精純完美的境界。", example: "老師傅的刀工已臻爐火純青。", syn: ["出神入化", "登峰造極"] , wordExp: "爐火＝爐中的火；純青＝變成純青色。火候到家時火焰轉青，功夫精純。",deep:"典故由來：源自道家煉丹：爐火燒到冒純青色火焰，火候才到家。\n字面意思：爐火燒出純青的火焰。\n引申意思：功夫、技藝達到精純完美（如：演技已臻爐火純青）。褒義。" },
  { id: "i292", grade: 6, term: "登峰造極", zhuyin: "ㄉㄥ ㄈㄥ ㄗㄠˋ ㄐㄧˊ", pinyin: "dēng fēng zào jí", meaning: "達到最高的境界或成就。", example: "這部作品讓他的導演生涯登峰造極。", syn: ["爐火純青", "出神入化"] , wordExp: "登＝登上；峰＝山峰；造＝到達；極＝頂點。攀上最高峰，成就到頂。",deep:"典故由來：出自《世說新語．文學》：支道林論書「不知便可登峰造極不？」\n字面意思：登上山峰、到達最高點（造＝到達）。\n引申意思：成就達到最高境界（如：他的雕刻藝術登峰造極）。褒義。" },
  { id: "i293", grade: 6, term: "貫徹始終", zhuyin: "ㄍㄨㄢˋ ㄔㄜˋ ㄕˇ ㄓㄨㄥ", pinyin: "guàn chè shǐ zhōng", meaning: "從頭到尾徹底執行，毫不鬆懈。", example: "節能政策要貫徹始終，才能看見成效。", syn: ["有始有終"] , wordExp: "貫徹＝貫穿通到底；始終＝從開始到結束。從頭到尾徹底執行。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：從開始到結束貫穿到底。\n引申意思：徹底執行、毫不鬆懈（如：政策要貫徹始終）。褒義。" },
  { id: "i294", grade: 6, term: "全力以赴", zhuyin: "ㄑㄩㄢˊ ㄌㄧˋ ㄧˇ ㄈㄨˋ", pinyin: "quán lì yǐ fù", meaning: "用全部的力量去做。", example: "不論結果如何，我都會全力以赴。", syn: ["竭盡全力"] , wordExp: "全力＝全部力量；以赴＝去投入。使出全力去做。",deep:"典故由來：清代文獻已見；「赴」是奔赴。\n字面意思：用全部力量奔赴目標。\n引申意思：竭盡全力（如：全力以赴準備比賽）。褒義。" },
  { id: "i295", grade: 6, term: "精疲力竭", zhuyin: "ㄐㄧㄥ ㄆㄧˊ ㄌㄧˋ ㄐㄧㄝˊ", pinyin: "jīng pí lì jié", meaning: "精神與體力都消耗殆盡。", example: "跑完馬拉松，他精疲力竭地癱坐在地。", syn: ["筋疲力盡"] , wordExp: "精＝精神；疲＝疲倦；力＝體力；竭＝枯竭。精神體力都用盡了。",deep:"典故由來：宋代文獻已見「精疲力竭」。\n字面意思：精神疲乏、力氣用盡。\n引申意思：極度疲累（如：跑完全馬，精疲力竭）。" },
  { id: "i296", grade: 6, term: "事倍功半", zhuyin: "ㄕˋ ㄅㄟˋ ㄍㄨㄥ ㄅㄢˋ", pinyin: "shì bèi gōng bàn", meaning: "費力多而收效少。", example: "方法不對，讀再久也是事倍功半。", misuse: "與「事半功倍」意思相反，勿混用。" , wordExp: "事＝費的事；倍＝加倍；功＝成效；半＝一半。花雙倍力氣只得一半成果。",deep:"典故由來：語本《孟子．公孫丑上》「事半古之人，功必倍之」的反面。\n字面意思：費兩倍的事，只收一半的功。\n引申意思：方法不對，費力多收效少（如：死背不理解，事倍功半）。貶義。" },
  { id: "i297", grade: 6, term: "事半功倍", zhuyin: "ㄕˋ ㄅㄢˋ ㄍㄨㄥ ㄅㄟˋ", pinyin: "shì bàn gōng bèi", meaning: "費力少而收效大。", example: "先列大綱再動筆，寫作文事半功倍。", misuse: "與「事倍功半」意思相反，勿混用。" , wordExp: "事半＝費事一半；功倍＝成效加倍。方法對了，省力又見效。",deep:"典故由來：出自《孟子．公孫丑上》：「故事半古之人，功必倍之，惟此時為然。」\n字面意思：費一半的事，收加倍的功。\n引申意思：方法得當，省力而收效大（如：善用工具事半功倍）。褒義。" },
  { id: "i298", grade: 6, term: "觸類旁通", zhuyin: "ㄔㄨˋ ㄌㄟˋ ㄆㄤˊ ㄊㄨㄥ", pinyin: "chù lèi páng tōng", meaning: "掌握一類知識後，能類推理解其他相關事理。", example: "他數理基礎扎實，學程式便能觸類旁通。", syn: ["舉一反三", "融會貫通"] , wordExp: "觸＝接觸；類＝同類事物；旁通＝旁及貫通。懂一類就能通其他類。",deep:"典故由來：語本《易經．繫辭上》：「引而伸之，觸類而長之。」\n字面意思：接觸一類事物，就能旁及貫通其他。\n引申意思：掌握規律後能類推理解相關事理（如：學好基礎便能觸類旁通）。褒義。" },
  { id: "i299", grade: 6, term: "融會貫通", zhuyin: "ㄖㄨㄥˊ ㄏㄨㄟˋ ㄍㄨㄢˋ ㄊㄨㄥ", pinyin: "róng huì guàn tōng", meaning: "把各方面的知識道理融合領會，全盤通曉。", example: "把公式背熟不夠，要融會貫通才能活用。", syn: ["觸類旁通"] , wordExp: "融會＝融合領會；貫通＝貫穿通曉。把所學融成一體，全盤通曉。",deep:"典故由來：出自朱熹《朱子全書》：「窮理之熟，然後能融會貫通。」\n字面意思：融合領會、貫穿通曉。\n引申意思：把各方面知識融合，全盤通曉（如：把各科知識融會貫通）。褒義。" },
  { id: "i300", grade: 6, term: "溫故知新", zhuyin: "ㄨㄣ ㄍㄨˋ ㄓ ㄒㄧㄣ", pinyin: "wēn gù zhī xīn", meaning: "溫習舊知識而獲得新的領悟。", example: "考前把舊講義再讀一遍，溫故知新。", misuse: "出自《論語》「溫故而知新，可以為師矣」。" , wordExp: "溫＝溫習；故＝舊的知識；知新＝獲得新體會。複習舊知而領悟新義。",deep:"典故由來：出自《論語．為政》：「溫故而知新，可以為師矣。」\n字面意思：溫習舊的，知道新的。\n引申意思：複習舊知識而有新領悟（如：讀書要溫故知新）。褒義。" },
  // ---- i301-i350（國中 7-9，會考常考）----
  { id: "i301", grade: 7, term: "不速之客", zhuyin: "ㄅㄨˋ ㄙㄨˋ ㄓ ㄎㄜˋ", pinyin: "bù sù zhī kè", meaning: "沒有邀請而自己來的客人。", example: "颱風夜來了一位不速之客，原來是走失的鄰居小狗。", misuse: "「速」是邀請的意思，不是快速。" , wordExp: "不速＝沒有邀請（速＝邀請）；之客＝的客人。未經邀請自己來的客人。",deep:"典故由來：出自《易經．需卦》：「有不速之客三人來，敬之終吉。」速＝邀請。\n字面意思：沒有被邀請的客人。\n引申意思：不請自來的人（如：宴會來了位不速之客）。" },
  { id: "i302", grade: 7, term: "別出心裁", zhuyin: "ㄅㄧㄝˊ ㄔㄨ ㄒㄧㄣ ㄘㄞˊ", pinyin: "bié chū xīn cái", meaning: "獨創新意，與眾不同。", example: "她的畢業展別出心裁，用回收物拼成台灣地圖。", syn: ["匠心獨運", "獨樹一幟"] , wordExp: "別＝另外；出＝提出；心裁＝心中的設計。想出與眾不同的新點子。",deep:"典故由來：清代文評用語；「心裁」是心中的設計剪裁。\n字面意思：另外想出與眾不同的設計。\n引申意思：構想獨特新穎（如：舞台設計別出心裁）。褒義。" },
  { id: "i303", grade: 7, term: "匠心獨運", zhuyin: "ㄐㄧㄤˋ ㄒㄧㄣ ㄉㄨˊ ㄩㄣˋ", pinyin: "jiàng xīn dú yùn", meaning: "運用巧妙獨到的創作構思。", example: "這棟圖書館的設計匠心獨運，處處是巧思。", syn: ["別出心裁"] , wordExp: "匠心＝巧匠般的構思；獨運＝獨自運用。創作構思獨到精巧。",deep:"典故由來：語本唐．王士源〈孟浩然集序〉：「文不按古，匠心獨妙。」\n字面意思：像巧匠一樣獨自運用巧思。\n引申意思：創作構思巧妙獨到（如：這座建築匠心獨運）。褒義。" },
  { id: "i304", grade: 7, term: "一針見血", zhuyin: "ㄧ ㄓㄣ ㄐㄧㄢˋ ㄒㄧㄝˇ", pinyin: "yī zhēn jiàn xiě", meaning: "言論簡潔而能切中要害。", example: "教練一針見血地指出球隊防守的漏洞。", syn: ["一語中的", "切中要害"] , wordExp: "一針＝一針下去；見血＝就見到血。一句話就切中要害。",deep:"典故由來：近代用語，以針刺見血為喻。\n字面意思：一針下去就見到血。\n引申意思：言論直接切中要害（如：他的評論一針見血）。褒義。" },
  { id: "i305", grade: 7, term: "判若兩人", zhuyin: "ㄆㄢˋ ㄖㄨㄛˋ ㄌㄧㄤˇ ㄖㄣˊ", pinyin: "pàn ruò liǎng rén", meaning: "前後表現差異極大，像是兩個人。", example: "戒菸後他精神奕奕，和從前判若兩人。" , wordExp: "判＝分辨；若＝好像；兩人＝兩個人。前後判若兩人，改變極大。",deep:"典故由來：清代小說常見的組合語。\n字面意思：看起來像是兩個不同的人。\n引申意思：前後表現差異極大（如：他戒菸後判若兩人）。" },
  { id: "i306", grade: 7, term: "咄咄逼人", zhuyin: "ㄉㄨㄛˋ ㄉㄨㄛˋ ㄅㄧ ㄖㄣˊ", pinyin: "duò duò bī rén", meaning: "氣勢洶洶，言語尖銳，使人難堪。", example: "他咄咄逼人的質問，讓會議氣氛降到冰點。", syn: ["盛氣凌人"], misuse: "「咄」讀ㄉㄨㄛˋ。" , wordExp: "咄咄＝呵斥聲；逼人＝逼向人。氣勢言語盛氣凌人。",deep:"典故由來：出自《世說新語》：殷仲堪與桓玄等作危語，參軍插話妙絕，殷曰「咄咄逼人」；晉衛鑠評王羲之書法亦用此語。\n字面意思：氣勢逼人（咄咄＝驚嘆聲）。\n引申意思：言語氣勢盛氣凌人（如：態度咄咄逼人）。貶義。" },
  { id: "i307", grade: 7, term: "姍姍來遲", zhuyin: "ㄕㄢ ㄕㄢ ㄌㄞˊ ㄔˊ", pinyin: "shān shān lái chí", meaning: "慢吞吞地來晚了。", example: "電影都開演十分鐘了，他才姍姍來遲。", misuse: "「姍」不可寫成「珊」。" , wordExp: "姍姍＝走路緩慢從容的樣子；來遲＝來晚了。慢吞吞地遲到。",deep:"典故由來：出自《漢書．外戚傳》：漢武帝思念李夫人，方士夜致其魂，帝望影吟：「是邪？非邪？……偏何姍姍其來遲！」\n字面意思：緩步慢行，來得很晚（姍姍＝走路緩慢從容）。\n引申意思：遲到（如：主角姍姍來遲）。今多含輕微責備或戲謔。" },
  { id: "i308", grade: 7, term: "家喻戶曉", zhuyin: "ㄐㄧㄚ ㄩˋ ㄏㄨˋ ㄒㄧㄠˇ", pinyin: "jiā yù hù xiǎo", meaning: "每家每戶都知道，形容名聲極大。", example: "這首民謠家喻戶曉，連小朋友都會唱。", syn: ["眾所周知", "婦孺皆知"] , wordExp: "家＝家家；喻＝明白；戶＝戶戶；曉＝知道。家家戶戶都知道。",deep:"典故由來：宋代文獻已見「家喻戶曉」。\n字面意思：家家明白、戶戶知道。\n引申意思：人人皆知（如：家喻戶曉的故事）。" },
  { id: "i309", grade: 7, term: "屈指可數", zhuyin: "ㄑㄩ ㄓˇ ㄎㄜˇ ㄕㄨˇ", pinyin: "qū zhǐ kě shǔ", meaning: "扳著手指就能數完，形容數量極少。", example: "全校能游完一千公尺的人屈指可數。", syn: ["寥寥無幾", "鳳毛麟角"] , wordExp: "屈指＝彎著手指；可數＝數得完。扳指頭就數完，數量很少。",deep:"典故由來：唐代文獻已見；扳著手指計算。\n字面意思：彎著手指就數得完。\n引申意思：數量極少（如：合格者屈指可數）。" },
  { id: "i310", grade: 7, term: "巧奪天工", zhuyin: "ㄑㄧㄠˇ ㄉㄨㄛˊ ㄊㄧㄢ ㄍㄨㄥ", pinyin: "qiǎo duó tiān gōng", meaning: "人工技藝精巧，勝過自然。", example: "這座木雕廟宇巧奪天工，遊客讚不絕口。", misuse: "形容「人工」技藝，不能形容天然景觀。" , wordExp: "巧＝技巧精巧；奪＝勝過；天工＝自然的造化。人工精巧勝過天然。",deep:"典故由來：元代文獻已見「巧奪天工」。\n字面意思：人工的精巧勝過天然（奪＝勝過）。\n引申意思：技藝精巧絕妙（如：這尊玉雕巧奪天工）。注意：只能形容人工製品，不能形容自然景物。" },
  { id: "i311", grade: 7, term: "心曠神怡", zhuyin: "ㄒㄧㄣ ㄎㄨㄤˋ ㄕㄣˊ ㄧˊ", pinyin: "xīn kuàng shén yí", meaning: "心胸開闊，精神愉快。", example: "站上合歡山頂眺望雲海，令人心曠神怡。", syn: ["賞心悅目"] , wordExp: "心曠＝心境開闊；神怡＝精神愉快。心胸開朗，精神舒暢。",deep:"典故由來：出自宋．范仲淹〈岳陽樓記〉：「登斯樓也，則有心曠神怡，寵辱偕忘。」\n字面意思：心境開闊，精神愉悅。\n引申意思：心情舒暢（如：山頂遠眺，令人心曠神怡）。褒義。" },
  { id: "i312", grade: 7, term: "愛不釋手", zhuyin: "ㄞˋ ㄅㄨˋ ㄕˋ ㄕㄡˇ", pinyin: "ài bù shì shǒu", meaning: "喜愛得捨不得放手。", example: "這本小說太精采，他愛不釋手，一夜讀完。" , wordExp: "愛＝喜愛；不釋＝捨不得放下；手＝手中。喜歡得放不下手。",deep:"典故由來：語本南朝梁．蕭統〈陶淵明集序〉：「余愛嗜其文，不能釋手。」\n字面意思：喜愛得放不下手。\n引申意思：非常喜愛（如：對這本書愛不釋手）。" },
  { id: "i313", grade: 7, term: "明察秋毫", zhuyin: "ㄇㄧㄥˊ ㄔㄚˊ ㄑㄧㄡ ㄏㄠˊ", pinyin: "míng chá qiū háo", meaning: "目光敏銳，連極細微的事物都看得清楚。", example: "會計主任明察秋毫，一眼看出帳目的錯誤。", misuse: "「秋毫」指鳥獸秋天新生的細毛。" , wordExp: "明察＝明晰洞察；秋毫＝秋天鳥獸新生細毛。連極細微處都看得清。",deep:"典故由來：出自《孟子．梁惠王上》：「明足以察秋毫之末。」秋毫是秋天鳥獸新生的細毛。\n字面意思：能看清秋天鳥獸的細毛。\n引申意思：觀察入微，極小處都看得清（如：法官明察秋毫）。褒義。" },
  { id: "i314", grade: 7, term: "東山再起", zhuyin: "ㄉㄨㄥ ㄕㄢ ㄗㄞˋ ㄑㄧˇ", pinyin: "dōng shān zài qǐ", meaning: "失敗或退隱後重新出來活動。", example: "公司倒閉後他沉潛三年，如今東山再起。", syn: ["捲土重來"], misuse: "謝安隱居東山後復出的典故。" , wordExp: "東山＝謝安隱居的東山；再起＝再度出仕。失勢後重新崛起。",deep:"典故由來：出自《晉書．謝安傳》：謝安隱居會稽東山，朝廷屢徵不出，後復出任要職，成救國名相，時人稱「東山再起」。\n字面意思：從東山重新出來。\n引申意思：失勢或失敗後重新崛起（如：企業家破產後東山再起）。" },
  { id: "i315", grade: 7, term: "心不在焉", zhuyin: "ㄒㄧㄣ ㄅㄨˋ ㄗㄞˋ ㄧㄢ", pinyin: "xīn bù zài yān", meaning: "心思不集中在眼前的事情上。", example: "他上課心不在焉，一直望著窗外。", syn: ["魂不守舍"] , wordExp: "心＝心思；不在焉＝不在這裡。心思不在眼前的事上。",deep:"典故由來：出自《禮記．大學》：「心不在焉，視而不見，聽而不聞，食而不知其味。」\n字面意思：心思不在這裡。\n引申意思：注意力不集中（如：上課心不在焉）。貶義。" },
  { id: "i316", grade: 7, term: "名列前茅", zhuyin: "ㄇㄧㄥˊ ㄌㄧㄝˋ ㄑㄧㄢˊ ㄇㄠˊ", pinyin: "míng liè qián máo", meaning: "成績或名次排在前面。", example: "她每次段考都名列前茅。", syn: ["數一數二", "首屈一指"] , wordExp: "名＝名次；列＝排在；前茅＝前鋒（茅旌）。成績排在最前面。",deep:"典故由來：語本《左傳．宣公十二年》：楚軍行軍「前茅慮無」——前鋒部隊舉茅旌偵察警戒。\n字面意思：名字排在前鋒的行列。\n引申意思：成績名次在前（如：段考名列前茅）。褒義。" },
  { id: "i317", grade: 8, term: "樂此不疲", zhuyin: "ㄌㄜˋ ㄘˇ ㄅㄨˋ ㄆㄧˊ", pinyin: "lè cǐ bù pí", meaning: "喜歡做某事，不覺得疲倦。", example: "爺爺每天整理盆栽，樂此不疲。",deep:"典故由來：出自《後漢書．光武帝紀》：光武帝勤於政事，太子勸他休息，他說：「我自樂此，不為疲也。」\n字面意思：喜愛這件事而不覺疲倦。\n引申意思：沉浸於喜歡的事（如：他研究昆蟲樂此不疲）。褒義。" },
  { id: "i318", grade: 8, term: "毛骨悚然", zhuyin: "ㄇㄠˊ ㄍㄨˇ ㄙㄨㄥˇ ㄖㄢˊ", pinyin: "máo gǔ sǒng rán", meaning: "非常害怕，寒毛豎起。", example: "深夜聽到閣樓傳來腳步聲，令人毛骨悚然。", syn: ["不寒而慄"],deep:"典故由來：明清小說常見；悚然＝害怕的樣子。\n字面意思：寒毛和骨頭都發冷發抖。\n引申意思：極度恐懼（如：恐怖片看得人毛骨悚然）。" },
  { id: "i319", grade: 8, term: "氣宇軒昂", zhuyin: "ㄑㄧˋ ㄩˇ ㄒㄩㄢ ㄤˊ", pinyin: "qì yǔ xuān áng", meaning: "神采飛揚，氣度不凡。", example: "儀隊隊長氣宇軒昂，吸引全場目光。", syn: ["器宇不凡"],deep:"典故由來：明代小說常用語；軒昂＝高昂不凡。\n字面意思：氣度像高車一樣軒敞昂揚。\n引申意思：精神飽滿、氣度不凡（如：他氣宇軒昂地步入會場）。褒義。" },
  { id: "i320", grade: 8, term: "洛陽紙貴", zhuyin: "ㄌㄨㄛˋ ㄧㄤˊ ㄓˇ ㄍㄨㄟˋ", pinyin: "luò yáng zhǐ guì", meaning: "著作風行一時，流傳甚廣。", example: "這本散文集出版後洛陽紙貴，一再加印。", misuse: "左思〈三都賦〉使洛陽紙價上漲的典故。",deep:"典故由來：出自《晉書．左思傳》：左思〈三都賦〉寫成後，「豪貴之家競相傳寫，洛陽為之紙貴」。\n字面意思：洛陽的紙價因搶購而上漲。\n引申意思：著作大受歡迎、風行一時（如：新書暢銷，洛陽紙貴）。褒義。" },
  { id: "i321", grade: 8, term: "津津樂道", zhuyin: "ㄐㄧㄣ ㄐㄧㄣ ㄌㄜˋ ㄉㄠˋ", pinyin: "jīn jīn lè dào", meaning: "很有興味地談論。", example: "那場逆轉勝至今仍被球迷津津樂道。",deep:"典故由來：清代文獻常見；「津津」是興味濃厚的樣子。\n字面意思：有滋有味地談論。\n引申意思：喜歡談論、談得起勁（如：那場逆轉勝至今被球迷津津樂道）。" },
  { id: "i322", grade: 8, term: "無動於衷", zhuyin: "ㄨˊ ㄉㄨㄥˋ ㄩˊ ㄓㄨㄥ", pinyin: "wú dòng yú zhōng", meaning: "內心毫無觸動，漠不關心。", example: "任憑大家勸說，他仍無動於衷。", misuse: "「衷」指內心，不可寫成「中」。", syn: ["不為所動"],deep:"典故由來：清代文獻常見；「衷」是內心。\n字面意思：內心毫無觸動。\n引申意思：漠不關心、不為所動（如：對勸告無動於衷）。貶義。" },
  { id: "i323", grade: 8, term: "無懈可擊", zhuyin: "ㄨˊ ㄒㄧㄝˋ ㄎㄜˇ ㄐㄧˊ", pinyin: "wú xiè kě jí", meaning: "沒有任何破綻可以挑剔攻擊。", example: "她的答辯邏輯嚴密，無懈可擊。", syn: ["天衣無縫"],deep:"典故由來：語本兵家「擊其懈怠」之說；「懈」是鬆懈的破綻。\n字面意思：沒有可以攻擊的鬆懈之處。\n引申意思：嚴密完美，挑不出毛病（如：論證無懈可擊）。褒義。" },
  { id: "i324", grade: 8, term: "相形見絀", zhuyin: "ㄒㄧㄤ ㄒㄧㄥˊ ㄐㄧㄢˋ ㄔㄨˋ", pinyin: "xiāng xíng jiàn chù", meaning: "互相比較之下，顯出不足。", example: "跟職業選手同場，業餘好手也相形見絀。", misuse: "「絀」讀ㄔㄨˋ，不可寫成「拙」。",deep:"典故由來：見清．吳趼人《二十年目睹之怪現狀》；「絀」是不足。\n字面意思：互相比較之下顯出短絀。\n引申意思：比較後顯得遜色（如：與冠軍相比，眾人相形見絀）。注意「絀」不寫作「拙」。" },
  { id: "i325", grade: 8, term: "眼花撩亂", zhuyin: "ㄧㄢˇ ㄏㄨㄚ ㄌㄧㄠˊ ㄌㄨㄢˋ", pinyin: "yǎn huā liáo luàn", meaning: "眼前事物繁雜，看得迷亂。", example: "琳瑯滿目的商品讓人眼花撩亂。", syn: ["目不暇給"],deep:"典故由來：出自元．王實甫《西廂記》：張生初見鶯鶯「似神仙歸洞天……眼花撩亂口難言」。\n字面意思：眼睛被撩撥得迷亂。\n引申意思：事物繁多看不過來（如：商品多得令人眼花撩亂）。" },
  { id: "i326", grade: 8, term: "義不容辭", zhuyin: "ㄧˋ ㄅㄨˋ ㄖㄨㄥˊ ㄘˊ", pinyin: "yì bù róng cí", meaning: "道義上不容許推辭。", example: "社區有難，身為里長義不容辭。", syn: ["責無旁貸"],deep:"典故由來：見《三國演義》：「豈可推調？此是義不容辭。」\n字面意思：道義上不容許推辭。\n引申意思：責任所在必須承擔（如：幫助災民義不容辭）。褒義。" },
  { id: "i327", grade: 8, term: "耳濡目染", zhuyin: "ㄦˇ ㄖㄨˊ ㄇㄨˋ ㄖㄢˇ", pinyin: "ěr rú mù rǎn", meaning: "經常聽到看到，不知不覺受到影響。", example: "生長在音樂世家，她耳濡目染，也愛上大提琴。", syn: ["潛移默化"],deep:"典故由來：出自唐．韓愈〈清河郡公房公墓碣銘〉：「目擩耳染，不學以能。」（擩＝沾染）\n字面意思：耳朵沾濕、眼睛染色——常聽常看。\n引申意思：長期接觸而不知不覺受影響（如：父母愛閱讀，孩子耳濡目染）。" },
  { id: "i328", grade: 8, term: "膾炙人口", zhuyin: "ㄎㄨㄞˋ ㄓˋ ㄖㄣˊ ㄎㄡˇ", pinyin: "kuài zhì rén kǒu", meaning: "詩文或事物廣受喜愛與傳誦。", example: "〈望春風〉是膾炙人口的台灣歌謠。", misuse: "「膾」是細切的肉，「炙」是烤肉，比喻美好事物人人愛。",deep:"典故由來：出自五代．王定保《唐摭言》：評詩句「皆膾炙人口」。膾是細切肉，炙是烤肉，都是人人愛吃的美味。\n字面意思：像美味的膾和炙人人愛吃。\n引申意思：詩文作品人人傳誦喜愛（如：膾炙人口的名曲）。褒義。" },
  { id: "i329", grade: 8, term: "言簡意賅", zhuyin: "ㄧㄢˊ ㄐㄧㄢˇ ㄧˋ ㄍㄞ", pinyin: "yán jiǎn yì gāi", meaning: "言辭簡潔，意思完備。", example: "報告要言簡意賅，別拖泥帶水。", misuse: "「賅」讀ㄍㄞ，完備之意。", syn: ["要言不煩"],deep:"典故由來：清代文評用語；「賅」是完備。\n字面意思：言辭簡單而意思完備。\n引申意思：話少但把意思說完整（如：報告言簡意賅）。褒義。" },
  { id: "i330", grade: 8, term: "趨之若鶩", zhuyin: "ㄑㄩ ㄓ ㄖㄨㄛˋ ㄨˋ", pinyin: "qū zhī ruò wù", meaning: "像成群的鴨子般爭相前往，多含貶義。", example: "網紅店開幕，民眾趨之若鶩排隊三小時。", misuse: "「鶩」是鴨，不可寫成「騖」；多用於盲目跟風。",deep:"典故由來：明清文獻常見；鶩是鴨子，鴨群見食爭相奔往。\n字面意思：像鴨群一樣爭相跑去。\n引申意思：許多人爭相追逐某事物（如：名店開幕，眾人趨之若鶩）。多含貶義（盲目跟風）。" },
  { id: "i331", grade: 8, term: "迎刃而解", zhuyin: "ㄧㄥˊ ㄖㄣˋ ㄦˊ ㄐㄧㄝˇ", pinyin: "yíng rèn ér jiě", meaning: "主要問題解決後，其餘問題也順勢化解。", example: "找到經費來源後，其他困難都迎刃而解。",deep:"典故由來：出自《晉書．杜預傳》：杜預伐吳，主張乘勝前進：「譬如破竹，數節之後，皆迎刃而解。」\n字面意思：竹子碰到刀刃就順勢裂開。\n引申意思：主要關卡突破後，其餘問題順利解決（如：找到關鍵後，難題迎刃而解）。" },
  { id: "i332", grade: 8, term: "適得其反", zhuyin: "ㄕˋ ㄉㄜˊ ㄑㄧˊ ㄈㄢˇ", pinyin: "shì dé qí fǎn", meaning: "結果與願望正好相反。", example: "逼孩子熬夜苦讀反而適得其反，成績更差。", syn: ["弄巧成拙", "欲速則不達"],deep:"典故由來：清代文獻常見的組合語。\n字面意思：恰好得到相反的結果。\n引申意思：結果與期望相反（如：逼得太緊反而適得其反）。貶義。" },
  { id: "i333", grade: 8, term: "鍥而不捨", zhuyin: "ㄑㄧㄝˋ ㄦˊ ㄅㄨˋ ㄕㄜˇ", pinyin: "qiè ér bù shě", meaning: "不斷雕刻不放手，比喻堅持到底。", example: "記者鍥而不捨地追查，終於揭發弊案。", syn: ["持之以恆", "堅持不懈"], misuse: "「鍥」讀ㄑㄧㄝˋ，雕刻之意。出自《荀子・勸學》。",deep:"典故由來：出自《荀子．勸學》：「鍥而舍之，朽木不折；鍥而不舍，金石可鏤。」（鍥＝雕刻）\n字面意思：不停地刻下去，不放手。\n引申意思：堅持不懈（如：鍥而不捨地追查真相）。褒義。" },
  { id: "i334", grade: 8, term: "開門見山", zhuyin: "ㄎㄞ ㄇㄣˊ ㄐㄧㄢˋ ㄕㄢ", pinyin: "kāi mén jiàn shān", meaning: "說話寫文章直接切入主題。", example: "他開門見山地說明來意，不繞圈子。", syn: ["直截了當", "單刀直入"],deep:"典故由來：語本宋．嚴羽《滄浪詩話》評李白詩「發句謂之開門見山」。\n字面意思：一開門就看見山。\n引申意思：說話作文直接進入主題（如：開門見山地說明來意）。褒義。" },
  { id: "i335", grade: 9, term: "集思廣益", zhuyin: "ㄐㄧˊ ㄙ ㄍㄨㄤˇ ㄧˋ", pinyin: "jí sī guǎng yì", meaning: "集合眾人的智慧，廣泛吸收有益意見。", example: "班會集思廣益，想出了園遊會的創意主題。", syn: ["群策群力"],deep:"典故由來：語本諸葛亮〈教與軍師長史參軍掾屬〉：「夫參署者，集眾思，廣忠益也。」\n字面意思：集合眾人的思考，擴大有益的意見。\n引申意思：廣納眾議（如：開會集思廣益）。褒義。" },
  { id: "i336", grade: 9, term: "面面相覷", zhuyin: "ㄇㄧㄢˋ ㄇㄧㄢˋ ㄒㄧㄤ ㄑㄩˋ", pinyin: "miàn miàn xiāng qù", meaning: "互相對看，不知所措。", example: "老師突然宣布抽考，全班面面相覷。", misuse: "「覷」讀ㄑㄩˋ，看的意思。",deep:"典故由來：見宋．《續傳燈錄》：「僧問：如何是大疑府？師曰：畢缽巖下，面面相覷。」\n字面意思：你看我、我看你（覷＝看）。\n引申意思：驚訝或無措地互相對望（如：突然停電，大家面面相覷）。" },
  { id: "i337", grade: 9, term: "顧名思義", zhuyin: "ㄍㄨˋ ㄇㄧㄥˊ ㄙ ㄧˋ", pinyin: "gù míng sī yì", meaning: "看到名稱就能想到它的含義。", example: "「夜市」顧名思義，就是晚上營業的市集。",deep:"典故由來：出自《三國志．王昶傳》：王昶為子姪取名，要他們「顧名思義」，名字取謙實之義以自我警惕。\n字面意思：看著名稱就想到它的意義。\n引申意思：從名稱推知內涵（如：「防水袋」顧名思義就是不透水的袋子）。" },
  { id: "i338", grade: 9, term: "首當其衝", zhuyin: "ㄕㄡˇ ㄉㄤ ㄑㄧˊ ㄔㄨㄥ", pinyin: "shǒu dāng qí chōng", meaning: "最先受到攻擊或遭遇災難。", example: "颱風登陸，沿海漁村首當其衝。", misuse: "常被誤用為「首先去做某事」；正確義是「最先受害」。",deep:"典故由來：語本《漢書．五行志》：「鄭當其衝，不能修德。」鄭國位於要衝，首先遭受攻擊。\n字面意思：首先位於要衝之地。\n引申意思：最先受到衝擊或災難（如：颱風來襲，沿海村落首當其衝）。注意：不是「首先去做」的意思，常被誤用。" },
  { id: "i339", grade: 9, term: "駕輕就熟", zhuyin: "ㄐㄧㄚˋ ㄑㄧㄥ ㄐㄧㄡˋ ㄕㄨˊ", pinyin: "jià qīng jiù shú", meaning: "駕輕車走熟路，比喻做熟悉的事，輕鬆容易。", example: "他當過三屆總務，辦起活動駕輕就熟。", syn: ["得心應手", "輕車熟路"],deep:"典故由來：出自唐．韓愈〈送石處士序〉：「若駟馬駕輕車就熟路。」\n字面意思：駕著輕車走熟悉的路。\n引申意思：做熟悉的事，輕鬆勝任（如：老手處理這案子駕輕就熟）。褒義。" },
  { id: "i340", grade: 9, term: "高瞻遠矚", zhuyin: "ㄍㄠ ㄓㄢ ㄩㄢˇ ㄓㄨˇ", pinyin: "gāo zhān yuǎn zhǔ", meaning: "眼光遠大，看得高遠。", example: "創辦人高瞻遠矚，三十年前就投入綠能。", misuse: "「矚」是注視，不可寫成「囑」。", syn: ["深謀遠慮"],deep:"典故由來：清代文獻常見；瞻、矚都是看。\n字面意思：站得高看得遠。\n引申意思：眼光遠大（如：領導人要高瞻遠矚）。褒義。" },
  { id: "i341", grade: 9, term: "鴉雀無聲", zhuyin: "ㄧㄚ ㄑㄩㄝˋ ㄨˊ ㄕㄥ", pinyin: "yā què wú shēng", meaning: "非常安靜，一點聲音也沒有。", example: "指揮舉起手，音樂廳頓時鴉雀無聲。", syn: ["萬籟俱寂"],deep:"典故由來：宋代禪宗語錄已見「鴉去無聲」之語，後作「鴉雀無聲」。\n字面意思：連烏鴉麻雀的聲音都沒有。\n引申意思：非常寂靜（如：全場鴉雀無聲）。" },
  { id: "i342", grade: 9, term: "口若懸河", zhuyin: "ㄎㄡˇ ㄖㄨㄛˋ ㄒㄩㄢˊ ㄏㄜˊ", pinyin: "kǒu ruò xuán hé", meaning: "說話滔滔不絕，像瀑布傾瀉。", example: "導遊口若懸河，把地方掌故講得活靈活現。", syn: ["滔滔不絕"], misuse: "形容善辯健談；「侃侃而談」則強調從容不迫，兩者有別。",deep:"典故由來：出自《世說新語．賞譽》：王衍評郭象清談「如懸河瀉水，注而不竭」。\n字面意思：說話像高懸的河流傾瀉不停。\n引申意思：能言善辯、滔滔不絕（如：他口若懸河地介紹產品）。含褒義，過度則近油嘴。" },
  { id: "i343", grade: 9, term: "侃侃而談", zhuyin: "ㄎㄢˇ ㄎㄢˇ ㄦˊ ㄊㄢˊ", pinyin: "kǎn kǎn ér tán", meaning: "從容不迫、理直氣壯地談論。", example: "面對評審提問，她侃侃而談，毫不怯場。", misuse: "強調從容自信，不是話多；勿與「口若懸河」混用。",deep:"典故由來：出自《論語．鄉黨》：孔子在朝「與下大夫言，侃侃如也」。侃侃＝從容和樂的樣子。\n字面意思：從容不迫地談話。\n引申意思：理直氣壯、從容暢談（如：他對答如流，侃侃而談）。褒義。" },
  { id: "i344", grade: 9, term: "滔滔不絕", zhuyin: "ㄊㄠ ㄊㄠ ㄅㄨˋ ㄐㄩㄝˊ", pinyin: "tāo tāo bù jué", meaning: "說話連續不斷。", example: "談起最愛的棒球，他就滔滔不絕。", syn: ["口若懸河"],deep:"典故由來：「滔滔」語出《詩經》形容大水奔流；五代以後凝為「滔滔不絕」。\n字面意思：像大水奔流不停。\n引申意思：說話連續不斷（如：一聊起電影就滔滔不絕）。" },
  { id: "i345", grade: 9, term: "一暴十寒", zhuyin: "ㄧ ㄆㄨˋ ㄕˊ ㄏㄢˊ", pinyin: "yī pù shí hán", meaning: "曬一天凍十天，比喻做事沒有恆心。", example: "學語言最忌一暴十寒，三天打魚兩天曬網。", misuse: "「暴」通「曝」，讀ㄆㄨˋ。出自《孟子》。", syn: ["半途而廢"],deep:"典故由來：出自《孟子．告子上》：「雖有天下易生之物也，一日暴之，十日寒之，未有能生者也。」\n字面意思：曬一天、凍十天。\n引申意思：勤少懈多、沒有恆心（如：學習一暴十寒，難有成效）。貶義；「暴」通「曝」，讀ㄆㄨˋ。" },
  { id: "i346", grade: 9, term: "人云亦云", zhuyin: "ㄖㄣˊ ㄩㄣˊ ㄧˋ ㄩㄣˊ", pinyin: "rén yún yì yún", meaning: "沒有主見，別人說什麼就跟著說什麼。", example: "看新聞要查證，不要人云亦云。", syn: ["隨聲附和"],deep:"典故由來：金．蔡松年詩已見「人云亦云」。\n字面意思：別人說什麼，自己也跟著說什麼。\n引申意思：沒有主見、隨聲附和（如：讀報要思辨，別人云亦云）。貶義。" },
  { id: "i347", grade: 9, term: "以訛傳訛", zhuyin: "ㄧˇ ㄜˊ ㄔㄨㄢˊ ㄜˊ", pinyin: "yǐ é chuán é", meaning: "把不正確的訊息繼續錯誤地傳下去。", example: "網路謠言以訛傳訛，越傳越離譜。", misuse: "「訛」讀ㄜˊ，錯誤之意。",deep:"典故由來：宋代文獻已見；「訛」是錯誤。\n字面意思：把錯的又錯著傳下去。\n引申意思：錯誤訊息越傳越走樣（如：網路謠言以訛傳訛）。貶義。" },
  { id: "i348", grade: 9, term: "好高騖遠", zhuyin: "ㄏㄠˋ ㄍㄠ ㄨˋ ㄩㄢˇ", pinyin: "hào gāo wù yuǎn", meaning: "不切實際地追求過高過遠的目標。", example: "初學者別好高騖遠，先把基本功練穩。", misuse: "「好」讀ㄏㄠˋ；「騖」是追求，不可寫成「鶩」。",deep:"典故由來：出自《宋史．程顥傳》：程顥批評學者「厭卑近而騖高遠」。騖＝馬奔馳、追求。\n字面意思：追求過高過遠的目標。\n引申意思：不切實際、眼高手低（如：先打好基礎，別好高騖遠）。貶義；「騖」不寫作「鶩」（鴨）。" },
  { id: "i349", grade: 9, term: "始作俑者", zhuyin: "ㄕˇ ㄗㄨㄛˋ ㄩㄥˇ ㄓㄜˇ", pinyin: "shǐ zuò yǒng zhě", meaning: "第一個做壞事或開惡例的人，貶義。", example: "亂丟垃圾的始作俑者被監視器拍個正著。", misuse: "貶義詞，不可當「創始人」的褒義用。",deep:"典故由來：出自《孟子．梁惠王上》引孔子：「始作俑者，其無後乎！」俑是陪葬的人形木偶，孔子痛斥發明以人形陪葬的人。\n字面意思：最早製作人俑陪葬的人。\n引申意思：第一個做壞事、開惡例的人（如：他是這股歪風的始作俑者）。貶義；不可用於稱讚首創者。" },
  { id: "i350", grade: 9, term: "杞人憂天", zhuyin: "ㄑㄧˇ ㄖㄣˊ ㄧㄡ ㄊㄧㄢ", pinyin: "qǐ rén yōu tiān", meaning: "毫無必要的憂慮。", example: "隕石撞地球機率極低，別杞人憂天了。", syn: ["庸人自擾"],deep:"典故由來：出自《列子．天瑞》：杞國有人擔心天會塌下來，愁得吃不下睡不著。\n字面意思：杞國人擔憂天塌。\n引申意思：不必要的憂慮（如：那是杞人憂天，標準內根本安全）。貶義。" },
  // ---- i351-i400（高中 10-12，學測指考層級）----
  { id: "i351", grade: 10, term: "白駒過隙", zhuyin: "ㄅㄞˊ ㄐㄩ ㄍㄨㄛˋ ㄒㄧˋ", pinyin: "bái jū guò xì", meaning: "白馬奔馳掠過縫隙，比喻時光飛逝。", example: "驀然回首，高中三年如白駒過隙。", syn: ["光陰似箭", "歲月如梭"], misuse: "出自《莊子》。「隙」是縫隙。",deep:"典故由來：出自《莊子．知北遊》：「人生天地之間，若白駒之過郤（隙），忽然而已。」\n字面意思：白馬奔馳掠過牆縫。\n引申意思：時光飛逝（如：光陰如白駒過隙）。" },
  { id: "i352", grade: 10, term: "滄海桑田", zhuyin: "ㄘㄤ ㄏㄞˇ ㄙㄤ ㄊㄧㄢˊ", pinyin: "cāng hǎi sāng tián", meaning: "大海變桑田，桑田變大海，比喻世事變化極大。", example: "重回眷村舊址，高樓林立，滄海桑田。", syn: ["白雲蒼狗", "物換星移"],deep:"典故由來：出自晉．葛洪《神仙傳》：仙女麻姑自言「已見東海三為桑田」。\n字面意思：大海變成桑田、桑田變成大海。\n引申意思：世事變化巨大（如：五十年後重遊，滄海桑田）。" },
  { id: "i353", grade: 10, term: "曇花一現", zhuyin: "ㄊㄢˊ ㄏㄨㄚ ㄧ ㄒㄧㄢˋ", pinyin: "tán huā yī xiàn", meaning: "美好事物出現不久就消逝。", example: "那股熱潮只是曇花一現，半年就退燒了。", syn: ["稍縱即逝"],deep:"典故由來：語本《妙法蓮華經》：「如優曇缽花，時一現耳。」曇花夜開數小時即謝。\n字面意思：曇花開放一下就凋謝。\n引申意思：美好事物短暫出現就消失（如：他的走紅只是曇花一現）。" },
  { id: "i354", grade: 10, term: "明日黃花", zhuyin: "ㄇㄧㄥˊ ㄖˋ ㄏㄨㄤˊ ㄏㄨㄚ", pinyin: "míng rì huáng huā", meaning: "過時的事物。", example: "昔日的當紅產品，如今已成明日黃花。", misuse: "語出蘇軾詩「明日黃花蝶也愁」；不可誤作「昨日黃花」。",deep:"典故由來：出自宋．蘇軾〈九日次韻王鞏〉：「相逢不用忙歸去，明日黃花蝶也愁。」重陽過後菊花即過時。\n字面意思：重陽節隔天的菊花。\n引申意思：過時的事物（如：這款手機已成明日黃花）。注意：是「明日」不是「昨日」黃花。" },
  { id: "i355", grade: 10, term: "甘之如飴", zhuyin: "ㄍㄢ ㄓ ㄖㄨˊ ㄧˊ", pinyin: "gān zhī rú yí", meaning: "把苦難當作糖一樣甘甜，心甘情願承受。", example: "照顧病母雖然辛苦，他卻甘之如飴。", misuse: "「飴」讀ㄧˊ，麥芽糖。",deep:"典故由來：語本《詩經．大雅．綿》：「堇荼如飴。」苦菜也甘之如糖。\n字面意思：甘甜得像麥芽糖（飴＝麥芽糖）。\n引申意思：心甘情願承受辛苦（如：照顧家人再累也甘之如飴）。褒義。" },
  { id: "i356", grade: 10, term: "手不釋卷", zhuyin: "ㄕㄡˇ ㄅㄨˋ ㄕˋ ㄐㄩㄢˋ", pinyin: "shǒu bù shì juàn", meaning: "書本不離手，形容勤奮好學。", example: "通勤路上他仍手不釋卷，把握零碎時間。", syn: ["孜孜不倦"], misuse: "「卷」讀ㄐㄩㄢˋ，書冊之意。",deep:"典故由來：出自《三國志》裴注引《江表傳》：曹操稱光武帝「當兵馬之務，手不釋卷」，孫權以此勉呂蒙。\n字面意思：手裡的書卷放不下來。\n引申意思：勤奮好學（如：他終日手不釋卷）。褒義。" },
  { id: "i357", grade: 10, term: "披星戴月", zhuyin: "ㄆㄧ ㄒㄧㄥ ㄉㄞˋ ㄩㄝˋ", pinyin: "pī xīng dài yuè", meaning: "頂著星月奔波，形容早出晚歸的辛勞。", example: "農忙時節，父親披星戴月地下田。", syn: ["早出晚歸"],deep:"典故由來：元代戲曲常見「披星戴月」。\n字面意思：身披星光、頭頂月色。\n引申意思：早出晚歸、日夜奔波（如：農人披星戴月地工作）。" },
  { id: "i358", grade: 10, term: "豁然開朗", zhuyin: "ㄏㄨㄛˋ ㄖㄢˊ ㄎㄞ ㄌㄤˇ", pinyin: "huò rán kāi lǎng", meaning: "由狹隘幽暗忽然變得開闊明亮，也比喻突然領悟。", example: "聽完學長的分析，我對選組的疑惑豁然開朗。", misuse: "出自〈桃花源記〉。", syn: ["恍然大悟", "茅塞頓開"],deep:"典故由來：出自晉．陶淵明〈桃花源記〉：漁人穿過山口，「初極狹，纔通人；復行數十步，豁然開朗」。\n字面意思：突然變得開闊明亮。\n引申意思：眼前開闊，或心中疑團頓解（如：聽完說明，豁然開朗）。褒義。" },
  { id: "i359", grade: 10, term: "過猶不及", zhuyin: "ㄍㄨㄛˋ ㄧㄡˊ ㄅㄨˋ ㄐㄧˊ", pinyin: "guò yóu bù jí", meaning: "事情做過頭跟做不夠一樣，都不恰當。", example: "補習補到半夜，過猶不及，反而傷身。", misuse: "出自《論語》。強調中庸之道。",deep:"典故由來：出自《論語．先進》：子貢問師與商孰賢，孔子曰：「過猶不及。」\n字面意思：過頭跟不夠一樣（不好）。\n引申意思：凡事要恰到好處（如：管教過嚴或放任都不宜，過猶不及）。" },
  { id: "i360", grade: 10, term: "瑕不掩瑜", zhuyin: "ㄒㄧㄚˊ ㄅㄨˋ ㄧㄢˇ ㄩˊ", pinyin: "xiá bù yǎn yú", meaning: "小缺點掩蓋不了整體的美好。", example: "劇情稍有瑕疵，但瑕不掩瑜，仍是年度佳作。", misuse: "「瑕」是玉的斑點，「瑜」是玉的光彩。",deep:"典故由來：出自《禮記．聘義》：論玉「瑕不掩瑜，瑜不掩瑕」。瑕是玉斑，瑜是玉的光彩。\n字面意思：玉上的斑點遮不住光彩。\n引申意思：小缺點無損整體美好（如：小失誤瑕不掩瑜）。褒義。" },
  { id: "i361", grade: 10, term: "眾矢之的", zhuyin: "ㄓㄨㄥˋ ㄕˇ ㄓ ㄉㄧˋ", pinyin: "zhòng shǐ zhī dì", meaning: "眾人攻擊的目標。", example: "政策一公布，主管機關便成了眾矢之的。", misuse: "「的」讀ㄉㄧˋ，箭靶中心。",deep:"典故由來：清代文獻常見；「的」是箭靶中心。\n字面意思：眾人箭矢共射的靶心。\n引申意思：被大家攻擊指責的對象（如：政策失當使官員成眾矢之的）。" },
  { id: "i362", grade: 10, term: "噤若寒蟬", zhuyin: "ㄐㄧㄣˋ ㄖㄨㄛˋ ㄏㄢˊ ㄔㄢˊ", pinyin: "jìn ruò hán chán", meaning: "像深秋的蟬不再鳴叫，形容不敢作聲。", example: "主管一發怒，會議室裡人人噤若寒蟬。", misuse: "「噤」讀ㄐㄧㄣˋ，閉口不言。",deep:"典故由來：語本《後漢書．杜密傳》：批評劉勝「知善不薦，聞惡無言……自同寒蟬」。寒蟬深秋不再鳴叫。\n字面意思：像寒天的蟬一樣不出聲。\n引申意思：因害怕而不敢說話（如：高壓之下人人噤若寒蟬）。貶義。" },
  { id: "i363", grade: 10, term: "懸梁刺股", zhuyin: "ㄒㄩㄢˊ ㄌㄧㄤˊ ㄘˋ ㄍㄨˇ", pinyin: "xuán liáng cì gǔ", meaning: "把頭髮繫在梁上、用錐子刺大腿以防打瞌睡，形容發憤苦讀。", example: "他以懸梁刺股的精神拚國考，終於金榜題名。", syn: ["囊螢映雪", "鑿壁偷光"],deep:"典故由來：懸梁：漢孫敬讀書以繩繫髮懸屋梁防瞌睡；刺股：《戰國策》蘇秦讀書欲睡「引錐自刺其股」。\n字面意思：頭髮懸梁、錐子刺大腿。\n引申意思：發憤刻苦讀書（如：懸梁刺股的苦讀精神）。褒義。" },
  { id: "i364", grade: 10, term: "焚膏繼晷", zhuyin: "ㄈㄣˊ ㄍㄠ ㄐㄧˋ ㄍㄨㄟˇ", pinyin: "fén gāo jì guǐ", meaning: "點燈接替日光，夜以繼日地勤讀勤作。", example: "考前一個月，他焚膏繼晷地衝刺。", misuse: "「晷」讀ㄍㄨㄟˇ，日影。出自韓愈〈進學解〉。", syn: ["夜以繼日"],deep:"典故由來：出自唐．韓愈〈進學解〉：「焚膏油以繼晷，恆兀兀以窮年。」（晷＝日影）\n字面意思：燒燈油接續日光。\n引申意思：夜以繼日地勤讀勤作（如：焚膏繼晷準備學測）。褒義。" },
  { id: "i365", grade: 10, term: "目不識丁", zhuyin: "ㄇㄨˋ ㄅㄨˋ ㄕˋ ㄉㄧㄥ", pinyin: "mù bù shì dīng", meaning: "連「丁」字都不認識，形容不識字。", example: "阿嬤目不識丁，卻把三個孩子都栽培成大學生。", misuse: "與「胸無點墨」（沒學問）略有別，本詞指不識字。",deep:"典故由來：出自《舊唐書．張弘靖傳》：軍吏罵士卒「挽得兩石力弓，不如識一丁字」。\n字面意思：連「丁」字都不認識。\n引申意思：完全不識字（如：昔日農村不少人目不識丁）。貶義。" },
  { id: "i366", grade: 10, term: "鵬程萬里", zhuyin: "ㄆㄥˊ ㄔㄥˊ ㄨㄢˋ ㄌㄧˇ", pinyin: "péng chéng wàn lǐ", meaning: "比喻前程遠大。", example: "師長祝福畢業生鵬程萬里。", misuse: "出自《莊子・逍遙遊》大鵬之典。", syn: ["前程似錦"],deep:"典故由來：出自《莊子．逍遙遊》：大鵬「摶扶搖而上者九萬里」，飛往南海。\n字面意思：大鵬一飛萬里的前程。\n引申意思：前程遠大（如：祝畢業生鵬程萬里）。褒義，常用於祝福。" },
  { id: "i367", grade: 10, term: "頭角崢嶸", zhuyin: "ㄊㄡˊ ㄐㄧㄠˇ ㄓㄥ ㄖㄨㄥˊ", pinyin: "tóu jiǎo zhēng róng", meaning: "才華出眾，表現突出。", example: "她高一就在全國科展頭角崢嶸。", syn: ["嶄露頭角"],deep:"典故由來：語本唐．韓愈〈柳子厚墓誌銘〉：「雖少年，已自成人，能取進士第，嶄然見頭角。」\n字面意思：頭上的角高峻突出。\n引申意思：才華出眾、鋒芒顯露（如：他在科展中頭角崢嶸）。褒義。" },
  { id: "i368", grade: 11, term: "邯鄲學步", zhuyin: "ㄏㄢˊ ㄉㄢ ㄒㄩㄝˊ ㄅㄨˋ", pinyin: "hán dān xué bù", meaning: "模仿別人不成，反而失去自己原有的本領。", example: "一味抄襲外國制度，恐怕邯鄲學步，兩頭落空。", syn: ["東施效顰"], misuse: "出自《莊子》：燕國人到邯鄲學走路的典故。",deep:"典故由來：出自《莊子．秋水》：燕國少年到趙國邯鄲學走路姿勢，沒學會反而忘了原本的走法，只好爬回去。\n字面意思：到邯鄲學走路。\n引申意思：盲目模仿不成，反失本領（如：全盤照抄別國制度，恐成邯鄲學步）。貶義。" },
  { id: "i369", grade: 11, term: "越俎代庖", zhuyin: "ㄩㄝˋ ㄗㄨˇ ㄉㄞˋ ㄆㄠˊ", pinyin: "yuè zǔ dài páo", meaning: "超出自己職分，代別人做事。", example: "行政部門越俎代庖替委員會做決定，引發爭議。", misuse: "「俎」是祭器，「庖」是廚師。出自《莊子》。",deep:"典故由來：出自《莊子．逍遙遊》：「庖人雖不治庖，尸祝不越樽俎而代之矣。」廚師不做飯，主祭者也不能越過禮器去代他下廚。\n字面意思：越過祭器去代廚師做菜（俎＝禮器；庖＝廚師）。\n引申意思：超出職分代人做事（如：這是他的職權，我不便越俎代庖）。" },
  { id: "i370", grade: 11, term: "指鹿為馬", zhuyin: "ㄓˇ ㄌㄨˋ ㄨㄟˊ ㄇㄚˇ", pinyin: "zhǐ lù wéi mǎ", meaning: "顛倒是非，混淆黑白。", example: "明明是他失誤，卻指鹿為馬怪罪別人。", misuse: "趙高欺君的典故。", syn: ["顛倒是非", "混淆是非"],deep:"典故由來：出自《史記．秦始皇本紀》：趙高獻鹿給秦二世，硬說是馬，群臣畏其權勢多附和，趙高藉此剷除異己。\n字面意思：指著鹿說是馬。\n引申意思：顛倒是非、混淆黑白（如：睜眼說瞎話，指鹿為馬）。貶義。" },
  { id: "i371", grade: 11, term: "圖窮匕見", zhuyin: "ㄊㄨˊ ㄑㄩㄥˊ ㄅㄧˇ ㄒㄧㄢˋ", pinyin: "tú qióng bǐ xiàn", meaning: "事情發展到最後，真相或本意顯露出來。", example: "對方一再讓步後圖窮匕見，提出苛刻條件。", misuse: "「見」通「現」，讀ㄒㄧㄢˋ。荊軻刺秦王的典故。",deep:"典故由來：出自《戰國策．燕策》：荊軻獻督亢地圖於秦王，圖卷展到盡頭，藏著的匕首露出，荊軻持匕行刺。\n字面意思：地圖展盡，匕首出現（見＝現）。\n引申意思：事情發展到最後，真相或本意暴露（如：談判至此圖窮匕見）。" },
  { id: "i372", grade: 11, term: "金蟬脫殼", zhuyin: "ㄐㄧㄣ ㄔㄢˊ ㄊㄨㄛ ㄑㄧㄠˋ", pinyin: "jīn chán tuō qiào", meaning: "用計脫身，使人不察。", example: "嫌犯留下外套金蟬脫殼，從後門溜走。", misuse: "「殼」在此讀ㄑㄧㄠˋ。",deep:"典故由來：元代雜劇與兵法三十六計之一：蟬脫殼而去，留空殼惑敵。\n字面意思：金蟬脫去外殼飛走。\n引申意思：用計脫身而不被察覺（如：嫌犯金蟬脫殼逃離包圍）。" },
  { id: "i373", grade: 11, term: "閉門造車", zhuyin: "ㄅㄧˋ ㄇㄣˊ ㄗㄠˋ ㄔㄜ", pinyin: "bì mén zào chē", meaning: "不問實際情況，只憑主觀想像做事。", example: "產品設計要傾聽使用者，不能閉門造車。", syn: ["紙上談兵"],deep:"典故由來：出自宋．朱熹《中庸或問》：「古語所謂閉門造車，出門合轍，蓋言其法之同。」原指規格統一，後轉為貶義。\n字面意思：關起門來造車。\n引申意思：不顧實際、只憑想像行事（如：政策不能閉門造車）。貶義。" },
  { id: "i374", grade: 11, term: "陽奉陰違", zhuyin: "ㄧㄤˊ ㄈㄥˋ ㄧㄣ ㄨㄟˊ", pinyin: "yáng fèng yīn wéi", meaning: "表面遵從，暗地裡違背。", example: "他對規定陽奉陰違，遲早出事。", syn: ["口是心非"],deep:"典故由來：明清官場用語；「陽」表面、「陰」暗地。\n字面意思：表面奉行，暗中違背。\n引申意思：表裡不一、敷衍應付（如：對規定陽奉陰違）。貶義。" },
  { id: "i375", grade: 11, term: "隔靴搔癢", zhuyin: "ㄍㄜˊ ㄒㄩㄝ ㄙㄠ ㄧㄤˇ", pinyin: "gé xuē sāo yǎng", meaning: "沒有切中要點，不能解決問題。", example: "這些補救措施隔靴搔癢，未觸及制度根本。", misuse: "與「一針見血」相對。",deep:"典故由來：出自宋．《五燈會元》：「說得十分好，只是隔靴搔癢。」\n字面意思：隔著靴子抓癢。\n引申意思：不切要點、無法解決問題（如：這篇評論隔靴搔癢）。貶義。" },
  { id: "i376", grade: 11, term: "雕蟲小技", zhuyin: "ㄉㄧㄠ ㄔㄨㄥˊ ㄒㄧㄠˇ ㄐㄧˋ", pinyin: "diāo chóng xiǎo jì", meaning: "微不足道的技能，多用作自謙。", example: "區區排版功夫，雕蟲小技，不足掛齒。", misuse: "自謙或輕視之詞，不可用來讚美他人。",deep:"典故由來：語本漢．揚雄自謙作賦是「童子雕蟲篆刻」；《北史》有「雕蟲小技」。\n字面意思：雕刻蟲書的小技藝。\n引申意思：微不足道的技能（如：雕蟲小技，何足掛齒）。多作自謙。" },
  { id: "i377", grade: 11, term: "敝帚自珍", zhuyin: "ㄅㄧˋ ㄓㄡˇ ㄗˋ ㄓㄣ", pinyin: "bì zhǒu zì zhēn", meaning: "破掃帚也當寶貝，比喻珍惜自己的東西。", example: "這些手稿雖不成熟，我卻敝帚自珍。", misuse: "多作自謙用；「敝」是破舊，不可寫成「蔽」。",deep:"典故由來：語本曹丕《典論．論文》引諺語：「家有敝帚，享之千金。」\n字面意思：把自家的破掃帚當千金寶貝。\n引申意思：珍視自己的東西（雖不值錢）（如：這些舊筆記敝帚自珍）。多作自謙。" },
  { id: "i378", grade: 11, term: "數典忘祖", zhuyin: "ㄕㄨˇ ㄉㄧㄢˇ ㄨㄤˋ ㄗㄨˇ", pinyin: "shǔ diǎn wàng zǔ", meaning: "列舉典故卻忘了祖先的職守，比喻忘本。", example: "連家鄉的歷史都不屑了解，未免數典忘祖。", misuse: "「數」在此讀ㄕㄨˇ，列舉之意。",deep:"典故由來：出自《左傳．昭公十五年》：晉大夫籍談出使周朝，答不出晉國與王室的典故淵源，周景王譏他「數典而忘其祖」——他祖先正是掌典籍之官。\n字面意思：列舉典故卻忘了自己祖先的職守。\n引申意思：忘本（如：崇洋而貶抑自身文化，無異數典忘祖）。貶義。" },
  { id: "i379", grade: 11, term: "文過飾非", zhuyin: "ㄨㄣˋ ㄍㄨㄛˋ ㄕˋ ㄈㄟ", pinyin: "wèn guò shì fēi", meaning: "用漂亮的言辭掩飾自己的過錯。", example: "出了包就該承認，別再文過飾非。", misuse: "「文」在此讀ㄨㄣˋ，掩飾之意（審訂音）。", syn: ["諱疾忌醫"],deep:"典故由來：語本《論語．子張》：「小人之過也必文。」（文＝掩飾）\n字面意思：掩飾過錯、粉飾錯誤。\n引申意思：用言辭掩蓋過失（如：勇於認錯，不要文過飾非）。貶義。" },
  { id: "i380", grade: 11, term: "穿鑿附會", zhuyin: "ㄔㄨㄢ ㄗㄨㄛˋ ㄈㄨˋ ㄏㄨㄟˋ", pinyin: "chuān zuò fù huì", meaning: "把不相干的事理勉強牽合解釋。", example: "把地震說成觸怒神明，是穿鑿附會。", misuse: "「鑿」在此讀ㄗㄨㄛˋ（審訂音）。", syn: ["牽強附會"],deep:"典故由來：宋代學者批評解經牽強的用語（洪邁《容齋隨筆》等）。\n字面意思：硬鑿洞、勉強黏合。\n引申意思：把不相干的事勉強牽合解釋（如：這種解讀是穿鑿附會）。貶義。" },
  { id: "i381", grade: 11, term: "貽笑大方", zhuyin: "ㄧˊ ㄒㄧㄠˋ ㄉㄚˋ ㄈㄤ", pinyin: "yí xiào dà fāng", meaning: "被內行人譏笑。", example: "一知半解就高談闊論，難免貽笑大方。", misuse: "「大方」指有見識的內行人；「貽」是留下。",deep:"典故由來：出自《莊子．秋水》：河伯見北海才知自己渺小，說「吾長見笑於大方之家」。\n字面意思：被見識廣博的行家譏笑（貽＝留給）。\n引申意思：外行舉動讓內行人笑話（如：獻醜之作，恐貽笑大方）。多作自謙。" },
  { id: "i382", grade: 11, term: "剛愎自用", zhuyin: "ㄍㄤ ㄅㄧˋ ㄗˋ ㄩㄥˋ", pinyin: "gāng bì zì yòng", meaning: "固執己見，不聽勸告。", example: "他剛愎自用，聽不進任何建言。", misuse: "「愎」讀ㄅㄧˋ，固執之意。", syn: ["一意孤行", "師心自用"],deep:"典故由來：出自《左傳．宣公十二年》：評楚將伍參語「剛愎不仁，未肯用命」。愎＝固執。\n字面意思：剛硬固執，自以為是。\n引申意思：固執己見不聽勸（如：主管剛愎自用，聽不進建言）。貶義。" },
  { id: "i383", grade: 11, term: "動輒得咎", zhuyin: "ㄉㄨㄥˋ ㄓㄜˊ ㄉㄜˊ ㄐㄧㄡˋ", pinyin: "dòng zhé dé jiù", meaning: "一有舉動就遭受責難。", example: "在嚴苛的主管底下做事，動輒得咎。", misuse: "「輒」讀ㄓㄜˊ，就、總是；「咎」是過失責難。出自韓愈〈進學解〉。",deep:"典故由來：出自唐．韓愈〈進學解〉：「跋前躓後，動輒得咎。」\n字面意思：一有動作就獲罪（輒＝就；咎＝罪責）。\n引申意思：做什麼都被責難（如：新人動輒得咎，無所適從）。" },
  { id: "i384", grade: 11, term: "尸位素餐", zhuyin: "ㄕ ㄨㄟˋ ㄙㄨˋ ㄘㄢ", pinyin: "shī wèi sù cān", meaning: "占著職位不做事，白領俸祿。", example: "議員批評該機關首長尸位素餐，毫無作為。", misuse: "「尸」是空占其位；「素餐」是白吃飯。",deep:"典故由來：出自《漢書．朱雲傳》：朱雲斥朝廷大臣「皆尸位素餐」。尸位＝像祭禮中的神主一樣空占位子；素餐＝白吃飯。\n字面意思：空占職位、白領俸祿。\n引申意思：居其位不謀其事（如：尸位素餐的官員）。貶義。" },
  { id: "i385", grade: 12, term: "沆瀣一氣", zhuyin: "ㄏㄤˋ ㄒㄧㄝˋ ㄧ ㄑㄧˋ", pinyin: "hàng xiè yī qì", meaning: "氣味相投的人勾結在一起，貶義。", example: "承包商與監工沆瀣一氣，偷工減料。", misuse: "「沆瀣」讀ㄏㄤˋ ㄒㄧㄝˋ，夜間水氣。", syn: ["狼狽為奸", "同流合汙"],deep:"典故由來：出自宋．錢易《南部新書》：唐代主考官崔沆錄取考生崔瀣，時人嘲「座主門生，沆瀣一氣」。沆瀣本是夜間水氣。\n字面意思：（兩人名字合成的）水氣連成一氣。\n引申意思：臭味相投的人勾結一起（如：官商沆瀣一氣）。貶義。" },
  { id: "i386", grade: 12, term: "暴殄天物", zhuyin: "ㄅㄠˋ ㄊㄧㄢˇ ㄊㄧㄢ ㄨˋ", pinyin: "bào tiǎn tiān wù", meaning: "任意糟蹋東西，不知愛惜。", example: "整桌菜沒吃幾口就倒掉，真是暴殄天物。", misuse: "「殄」讀ㄊㄧㄢˇ，滅絕之意。",deep:"典故由來：出自《尚書．武成》：「今商王受無道，暴殄天物。」（殄＝滅絕）\n字面意思：殘害滅絕天生萬物。\n引申意思：任意糟蹋東西（如：剩菜整桌倒掉，暴殄天物）。貶義。" },
  { id: "i387", grade: 12, term: "鞭辟入裡", zhuyin: "ㄅㄧㄢ ㄆㄧˋ ㄖㄨˋ ㄌㄧˇ", pinyin: "biān pì rù lǐ", meaning: "分析透澈，切中要害。", example: "這篇社論鞭辟入裡，直指問題核心。", misuse: "「辟」在此讀ㄆㄧˋ。形容言論深刻，非指鞭打。", syn: ["一針見血"],deep:"典故由來：語本朱熹語錄「鞭辟近裡」——鞭策自己切近內裡。\n字面意思：鞭策剖析深入到最裡層。\n引申意思：分析透澈、切中要害（如：評論鞭辟入裡）。褒義。" },
  { id: "i388", grade: 12, term: "醍醐灌頂", zhuyin: "ㄊㄧˊ ㄏㄨˊ ㄍㄨㄢˋ ㄉㄧㄥˇ", pinyin: "tí hú guàn dǐng", meaning: "灌輸智慧，使人徹底醒悟。", example: "老師一席話如醍醐灌頂，令我茅塞頓開。", misuse: "「醍醐」是乳酪提煉的精華，佛家喻最高教義。", syn: ["茅塞頓開"],deep:"典故由來：佛家語；醍醐是乳製精華，灌頂是密宗儀式。唐．顧況詩：「豈知灌頂有醍醐。」\n字面意思：把醍醐從頭頂澆下。\n引申意思：聽了高明見解而徹底醒悟（如：一席話如醍醐灌頂）。褒義。" },
  { id: "i389", grade: 12, term: "曲突徙薪", zhuyin: "ㄑㄩ ㄊㄨˊ ㄒㄧˇ ㄒㄧㄣ", pinyin: "qū tú xǐ xīn", meaning: "把煙囪改彎、移開柴火，比喻事先防範禍患。", example: "與其災後補救，不如曲突徙薪，先做好防災。", misuse: "「突」是煙囪，「徙」是遷移。", syn: ["未雨綢繆", "防患未然"],deep:"典故由來：出自《漢書．霍光傳》：客人勸主人把直煙囪改彎、移開柴薪以防火，主人不聽，果然失火——救火者受宴謝，獻策者反被遺忘。\n字面意思：彎曲煙囪、搬走柴薪（突＝煙囪；徙＝遷移）。\n引申意思：防患於未然（如：曲突徙薪勝過事後補救）。褒義。" },
  { id: "i390", grade: 12, term: "每下愈況", zhuyin: "ㄇㄟˇ ㄒㄧㄚˋ ㄩˋ ㄎㄨㄤˋ", pinyin: "měi xià yù kuàng", meaning: "情況越來越壞。", example: "老街商圈人潮每下愈況，店家紛紛歇業。", misuse: "出自《莊子》；今多與「每況愈下」通用，指情勢日壞。",deep:"典故由來：出自《莊子．知北遊》：「每下愈況」原指從愈低微處愈能看清實情（驗豬肥瘦要踩豬腳脛）；後世多誤倒為「每況愈下」表越來越糟。\n字面意思：（今用法）情況越來越差。\n引申意思：情勢日漸敗壞（如：體力每下愈況）。使用時知其原義更佳。" },
  { id: "i391", grade: 12, term: "危如累卵", zhuyin: "ㄨㄟˊ ㄖㄨˊ ㄌㄟˇ ㄌㄨㄢˇ", pinyin: "wéi rú lěi luǎn", meaning: "像疊起來的蛋一樣，形容情勢極度危險。", example: "強震過後，山坡上的老屋危如累卵。", misuse: "「累」在此讀ㄌㄟˇ，堆疊之意。", syn: ["岌岌可危", "千鈞一髮"],deep:"典故由來：出自《史記．范雎列傳》：「秦王之國，危於累卵。」\n字面意思：危險得像疊起來的蛋。\n引申意思：情勢極危（如：城防危如累卵）。" },
  { id: "i392", grade: 12, term: "大放厥詞", zhuyin: "ㄉㄚˋ ㄈㄤˋ ㄐㄩㄝˊ ㄘˊ", pinyin: "dà fàng jué cí", meaning: "誇誇其談，大發議論，今多含貶義。", example: "他對不熟的領域也敢大放厥詞。", misuse: "「厥」是「其」的意思。今多用於貶義。",deep:"典故由來：出自唐．韓愈〈祭柳子厚文〉：「玉佩瓊琚，大放厥辭。」原讚文辭華美，今轉貶義。\n字面意思：大大地發表他的言詞（厥＝其）。\n引申意思：誇誇其談、胡言亂語（如：他在會上大放厥詞）。今多貶義。" },
  { id: "i393", grade: 12, term: "沐猴而冠", zhuyin: "ㄇㄨˋ ㄏㄡˊ ㄦˊ ㄍㄨㄢˋ", pinyin: "mù hóu ér guàn", meaning: "獼猴戴帽裝人樣，譏諷虛有其表。", example: "不學無術卻居高位，無異沐猴而冠。", misuse: "「冠」在此讀ㄍㄨㄢˋ，戴帽子。譏諷項羽的典故。",deep:"典故由來：出自《史記．項羽本紀》：有人譏項羽「人言楚人沐猴而冠耳，果然」。獼猴戴帽，終非人類。\n字面意思：獼猴洗過澡戴上帽子。\n引申意思：虛有其表、竊據名位（如：沐猴而冠，難成大器）。貶義。" },
  { id: "i394", grade: 12, term: "膠柱鼓瑟", zhuyin: "ㄐㄧㄠ ㄓㄨˋ ㄍㄨˇ ㄙㄜˋ", pinyin: "jiāo zhù gǔ sè", meaning: "把瑟的弦柱黏死再彈奏，比喻固執拘泥、不知變通。", example: "時代變了還死守舊規，未免膠柱鼓瑟。", syn: ["刻舟求劍", "食古不化"],deep:"典故由來：出自《史記．廉頗藺相如列傳》：藺相如評趙括「王以名使括，若膠柱而鼓瑟耳」——把調弦的柱黏死，就無法變調。\n字面意思：黏住弦柱彈瑟。\n引申意思：拘泥不知變通（如：制度要與時俱進，不可膠柱鼓瑟）。貶義。" },
  { id: "i395", grade: 12, term: "蚍蜉撼樹", zhuyin: "ㄆㄧˊ ㄈㄨˊ ㄏㄢˋ ㄕㄨˋ", pinyin: "pí fú hàn shù", meaning: "螞蟻想搖動大樹，比喻不自量力。", example: "小公司想告贏跨國集團？別人笑他蚍蜉撼樹。", misuse: "「蚍蜉」是大螞蟻。出自韓愈詩。", syn: ["螳臂當車", "以卵擊石"],deep:"典故由來：出自唐．韓愈〈調張籍〉：「蚍蜉撼大樹，可笑不自量。」\n字面意思：大螞蟻想搖動大樹。\n引申意思：不自量力（如：挑戰權威若無實力，無異蚍蜉撼樹）。貶義。" },
  { id: "i396", grade: 12, term: "觥籌交錯", zhuyin: "ㄍㄨㄥ ㄔㄡˊ ㄐㄧㄠ ㄘㄨㄛˋ", pinyin: "gōng chóu jiāo cuò", meaning: "酒杯與酒籌交相錯雜，形容宴飲盡歡。", example: "尾牙席間觥籌交錯，賓主盡歡。", misuse: "「觥」讀ㄍㄨㄥ，酒器。出自〈醉翁亭記〉。",deep:"典故由來：出自宋．歐陽修〈醉翁亭記〉：「觥籌交錯，起坐而諠譁者，眾賓懽也。」觥是酒杯，籌是行酒令的籤。\n字面意思：酒杯與酒籌交錯往來。\n引申意思：宴飲熱鬧盡歡（如：席間觥籌交錯）。" },
  { id: "i397", grade: 12, term: "諱莫如深", zhuyin: "ㄏㄨㄟˋ ㄇㄛˋ ㄖㄨˊ ㄕㄣ", pinyin: "huì mò rú shēn", meaning: "把事情隱瞞得非常嚴密，絕口不提。", example: "對於離職原因，他始終諱莫如深。", misuse: "「諱」是隱瞞忌言。",deep:"典故由來：出自《穀梁傳．莊公三十二年》：「諱莫如深，深則隱。」\n字面意思：隱瞞得再深不過了。\n引申意思：把事情瞞得極緊、絕口不提（如：對那段往事諱莫如深）。" },
  { id: "i398", grade: 12, term: "飲鴆止渴", zhuyin: "ㄧㄣˇ ㄓㄣˋ ㄓˇ ㄎㄜˇ", pinyin: "yǐn zhèn zhǐ kě", meaning: "喝毒酒解渴，比喻只圖眼前、不顧後患。", example: "借高利貸還債無異飲鴆止渴。", misuse: "「鴆」讀ㄓㄣˋ，毒鳥，其羽泡酒有劇毒。", syn: ["挖肉補瘡"],deep:"典故由來：出自《後漢書．霍諝傳》：「譬猶療飢於附子，止渴於鴆毒，未入腸胃，已絕咽喉。」鴆羽泡的酒有劇毒。\n字面意思：喝毒酒解渴。\n引申意思：只圖眼前、不顧後患（如：借高利貸還債是飲鴆止渴）。貶義。" },
  { id: "i399", grade: 12, term: "黔驢技窮", zhuyin: "ㄑㄧㄢˊ ㄌㄩˊ ㄐㄧˋ ㄑㄩㄥˊ", pinyin: "qián lǘ jì qióng", meaning: "有限的本領用完了，再也無計可施。", example: "對手識破他所有招數，他已黔驢技窮。", misuse: "柳宗元〈黔之驢〉的典故。", syn: ["江郎才盡"],deep:"典故由來：出自唐．柳宗元〈黔之驢〉：黔地的驢只會踢，被老虎識破「技止此耳」而吃掉。\n字面意思：黔地驢子的本領用完了。\n引申意思：有限的本領耗盡、無計可施（如：對手已黔驢技窮）。貶義。" },
  { id: "i400", grade: 12, term: "顛沛流離", zhuyin: "ㄉㄧㄢ ㄆㄟˋ ㄌㄧㄡˊ ㄌㄧˊ", pinyin: "diān pèi liú lí", meaning: "生活困頓，四處流浪。", example: "戰亂年代，祖父母顛沛流離，輾轉來台。", syn: ["流離失所"],deep:"典故由來：「顛沛」語出《論語．里仁》「顛沛必於是」；「流離」見《漢書》。\n字面意思：跌倒困頓、流轉離散。\n引申意思：生活困苦、四處流浪（如：戰亂中百姓顛沛流離）。" },
  // ---- 2026-08-02 二輪擴充：i401-i450（國小低年級）----
  { id: "i401", grade: 1, term: "手舞足蹈", zhuyin: "ㄕㄡˇ ㄨˇ ㄗㄨˊ ㄉㄠˋ", pinyin: "shǒu wǔ zú dào", meaning: "高興得手腳都舞動起來。", example: "聽到要去遊樂園，弟弟高興得手舞足蹈。", syn: ["歡天喜地"] , wordExp: "手舞＝手揮舞；足蹈＝腳跳動。高興得手腳都跳起舞來。",deep:"典故由來：語出《詩經．大序》：「情動於中而形於言……不知手之舞之，足之蹈之也。」\n字面意思：手舞動、腳跳動。\n引申意思：高興到手腳都跳起舞來（如：他樂得手舞足蹈）。形容喜悅到極點。" },
  { id: "i402", grade: 1, term: "東奔西跑", zhuyin: "ㄉㄨㄥ ㄅㄣ ㄒㄧ ㄆㄠˇ", pinyin: "dōng bēn xī pǎo", meaning: "到處奔走忙碌。", example: "為了找遺失的小狗，全家東奔西跑了一下午。" , wordExp: "東奔、西跑＝到處奔跑。四處奔波忙碌。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：往東奔、往西跑。\n引申意思：到處奔走忙碌（如：為了辦活動，他東奔西跑）。" },
  { id: "i403", grade: 1, term: "大搖大擺", zhuyin: "ㄉㄚˋ ㄧㄠˊ ㄉㄚˋ ㄅㄞˇ", pinyin: "dà yáo dà bǎi", meaning: "走路搖擺神氣，滿不在乎的樣子。", example: "小花貓大搖大擺地走過客廳。" , wordExp: "大搖、大擺＝大幅度搖擺。走路搖搖擺擺，滿不在乎。",deep:"典故由來：清代小說常見的口語成語（如《官場現形記》），由字面組合而成。\n字面意思：大幅度地搖擺身體走路。\n引申意思：走路神氣十足、滿不在乎的樣子（如：他大搖大擺地走進教室）。常帶貶義，形容旁若無人。" },
  { id: "i404", grade: 1, term: "交頭接耳", zhuyin: "ㄐㄧㄠ ㄊㄡˊ ㄐㄧㄝ ㄦˇ", pinyin: "jiāo tóu jiē ěr", meaning: "湊近耳邊低聲私語。", example: "台下觀眾交頭接耳，討論剛才的魔術。" , wordExp: "交頭＝頭靠著頭；接耳＝嘴湊近耳朵。靠在一起小聲說悄悄話。",deep:"典故由來：元明戲曲小說常見的口語成語，由字面組合而成。\n字面意思：頭靠著頭、耳朵貼著耳朵。\n引申意思：湊近低聲私語（如：兩人在台下交頭接耳）。多用於不便公開的談話。" },
  { id: "i405", grade: 1, term: "面紅耳赤", zhuyin: "ㄇㄧㄢˋ ㄏㄨㄥˊ ㄦˇ ㄔˋ", pinyin: "miàn hóng ěr chì", meaning: "因害羞、緊張或激動而滿臉通紅。", example: "被老師點名唱歌，他害羞得面紅耳赤。" , wordExp: "面紅＝臉發紅；耳赤＝耳朵發紅。臉和耳朵都漲紅了。",deep:"典故由來：由字面組合而成，宋明理學語錄中已見類似說法。\n字面意思：臉紅到耳朵都赤了。\n引申意思：因害羞、緊張、激動或爭執而滿臉通紅（如：兩人爭得面紅耳赤）。" },
  { id: "i406", grade: 1, term: "張口結舌", zhuyin: "ㄓㄤ ㄎㄡˇ ㄐㄧㄝˊ ㄕㄜˊ", pinyin: "zhāng kǒu jié shé", meaning: "張著嘴說不出話，形容理屈或驚呆。", example: "被問到關鍵問題，他張口結舌答不上來。", syn: ["啞口無言"] , wordExp: "張口＝張開嘴；結舌＝舌頭打結。嘴張著說不出話。",deep:"典故由來：由字面組合而成的常用語；「結舌」指舌頭像打了結。\n字面意思：張著嘴、舌頭打結，說不出話。\n引申意思：理虧語塞或驚呆說不出話（如：被問得張口結舌）。" },
  { id: "i407", grade: 1, term: "搖頭晃腦", zhuyin: "ㄧㄠˊ ㄊㄡˊ ㄏㄨㄤˋ ㄋㄠˇ", pinyin: "yáo tóu huàng nǎo", meaning: "頭搖來搖去，自得其樂的樣子。", example: "爺爺搖頭晃腦地吟起唐詩。" , wordExp: "搖頭、晃腦＝頭搖來搖去。得意或陶醉的樣子。",deep:"典故由來：由字面組合而成，清代小說常見。\n字面意思：頭搖來搖去。\n引申意思：自得其樂或讀書吟誦入神的樣子（如：他搖頭晃腦地背詩）；有時帶調侃意味。" },
  { id: "i408", grade: 1, term: "大名鼎鼎", zhuyin: "ㄉㄚˋ ㄇㄧㄥˊ ㄉㄧㄥˇ ㄉㄧㄥˇ", pinyin: "dà míng dǐng dǐng", meaning: "名氣非常大。", example: "這位大名鼎鼎的棒球選手是我們的校友。", syn: ["赫赫有名", "鼎鼎大名"] , wordExp: "大名＝響亮的名聲；鼎鼎＝盛大的樣子。名氣非常響亮。",deep:"典故由來：清代小說常見的口語成語；「鼎鼎」是盛大的樣子。\n字面意思：名氣盛大。\n引申意思：名氣非常大（如：大名鼎鼎的科學家）。褒義；「鼎」不可寫成「頂」。" },
  { id: "i409", grade: 1, term: "二話不說", zhuyin: "ㄦˋ ㄏㄨㄚˋ ㄅㄨˋ ㄕㄨㄛ", pinyin: "èr huà bù shuō", meaning: "不多說什麼，立刻行動。", example: "看到同學跌倒，他二話不說上前扶起。" , wordExp: "二話＝第二句話；不說＝不多說。一句廢話也沒有，馬上行動。",deep:"典故由來：由字面組合而成的口語成語。\n字面意思：第二句話都不說。\n引申意思：不囉嗦、立刻行動（如：他二話不說就答應幫忙）。形容乾脆爽快。" },
  { id: "i410", grade: 1, term: "人山人海", zhuyin: "ㄖㄣˊ ㄕㄢ ㄖㄣˊ ㄏㄞˇ", pinyin: "rén shān rén hǎi", meaning: "人多得像山和海一樣，形容非常擁擠。", example: "跨年晚會現場人山人海。", syn: ["萬頭攢動"] , wordExp: "人山、人海＝人多得像山像海。人非常多。",deep:"典故由來：明清白話小說常見的口語成語。\n字面意思：人多得像山、像海。\n引申意思：形容人非常多、非常擁擠（如：跨年晚會人山人海）。只用來形容「人」多，不能形容車或東西多。" },
  { id: "i411", grade: 1, term: "車水馬龍", zhuyin: "ㄔㄜ ㄕㄨㄟˇ ㄇㄚˇ ㄌㄨㄥˊ", pinyin: "chē shuǐ mǎ lóng", meaning: "車馬往來不絕，形容熱鬧繁華。", example: "站前大道車水馬龍，好不熱鬧。", syn: ["川流不息"] , wordExp: "車如流水；馬如游龍。車馬往來不絕，非常熱鬧。",deep:"典故由來：出自《後漢書．明德馬皇后紀》：「車如流水，馬如游龍。」馬皇后形容外戚家門前車馬熱鬧的景象。\n字面意思：車像流水、馬像游龍，往來不絕。\n引申意思：形容車馬（車輛）繁多、市街熱鬧繁華（如：市中心車水馬龍）。" },
  { id: "i412", grade: 1, term: "良師益友", zhuyin: "ㄌㄧㄤˊ ㄕ ㄧˋ ㄧㄡˇ", pinyin: "liáng shī yì yǒu", meaning: "使人受益的好老師與好朋友。", example: "這本百科全書是我的良師益友。" , wordExp: "良師＝好老師；益友＝有幫助的朋友。像好老師又像好朋友。",deep:"典故由來：「益友」語出《論語．季氏》：「益者三友：友直、友諒、友多聞。」\n字面意思：使人受益的好老師和好朋友。\n引申意思：能教導又能相伴成長的人（如：這本書是我的良師益友）。也可形容書籍、事物。" },
  { id: "i413", grade: 1, term: "一言為定", zhuyin: "ㄧ ㄧㄢˊ ㄨㄟˊ ㄉㄧㄥˋ", pinyin: "yī yán wéi dìng", meaning: "一句話說定，不再改變。", example: "週末去打球，一言為定！" , wordExp: "一言＝一句話；為定＝就說定了。一句話說定，不再改變。",deep:"典故由來：明清小說常用的口語成語，由字面組合而成。\n字面意思：一句話就說定。\n引申意思：約定之後不再更改（如：明天見，一言為定！）。強調守信。" },
  { id: "i414", grade: 1, term: "百依百順", zhuyin: "ㄅㄞˇ ㄧ ㄅㄞˇ ㄕㄨㄣˋ", pinyin: "bǎi yī bǎi shùn", meaning: "凡事都依從對方。", example: "爺爺對孫女百依百順，疼愛有加。", syn: ["言聽計從"] , wordExp: "百＝樣樣；依、順＝依從順從。樣樣都順著對方。",deep:"典故由來：明清小說常見的口語成語，由字面組合而成。\n字面意思：一百件事都依從、順從。\n引申意思：凡事都順著對方（如：爺爺對孫子百依百順）。常含「過度寵溺、沒有原則」的提醒意味。" },
  { id: "i415", grade: 2, term: "千軍萬馬", zhuyin: "ㄑㄧㄢ ㄐㄩㄣ ㄨㄢˋ ㄇㄚˇ", pinyin: "qiān jūn wàn mǎ", meaning: "兵馬眾多，聲勢浩大。", example: "瀑布傾瀉而下，有如千軍萬馬奔騰。" , wordExp: "千軍＝上千士兵；萬馬＝上萬戰馬。兵馬極多，聲勢浩大。",deep:"典故由來：由字面組合而成；千、萬極言兵馬之多。\n字面意思：上千的軍隊、上萬的戰馬。\n引申意思：兵馬眾多、聲勢浩大（如：千軍萬馬奔騰而來）；也形容競爭者眾（如：千軍萬馬過獨木橋）。" },
  { id: "i416", grade: 2, term: "萬眾一心", zhuyin: "ㄨㄢˋ ㄓㄨㄥˋ ㄧ ㄒㄧㄣ", pinyin: "wàn zhòng yī xīn", meaning: "眾人同心協力。", example: "全校萬眾一心，為運動會加油。", syn: ["眾志成城", "同心協力"] , wordExp: "萬眾＝千萬群眾；一心＝同一條心。所有人同心協力。",deep:"典故由來：語本《後漢書．朱雋傳》：「萬人一心，猶不可當。」\n字面意思：千萬人同一條心。\n引申意思：眾人團結一致（如：全國萬眾一心抗災）。褒義。" },
  { id: "i417", grade: 2, term: "眾志成城", zhuyin: "ㄓㄨㄥˋ ㄓˋ ㄔㄥˊ ㄔㄥˊ", pinyin: "zhòng zhì chéng chéng", meaning: "眾人齊心，力量堅固如城。", example: "災後重建靠的是全村眾志成城。", syn: ["萬眾一心"] , wordExp: "眾志＝眾人的意志；成城＝築成城牆。人心齊，堅固得像城牆。",deep:"典故由來：語本《國語．周語》：「眾心成城，眾口鑠金。」\n字面意思：眾人的意志聚成堅固的城牆。\n引申意思：團結一心力量無比堅固（如：眾志成城，渡過難關）。褒義。" },
  { id: "i418", grade: 2, term: "風平浪靜", zhuyin: "ㄈㄥ ㄆㄧㄥˊ ㄌㄤˋ ㄐㄧㄥˋ", pinyin: "fēng píng làng jìng", meaning: "沒有風浪，平靜無事。", example: "風波過後，班上又恢復風平浪靜。" , wordExp: "風平＝風停了；浪靜＝浪息了。海面平靜，比喻平安無事。",deep:"典故由來：宋代禪宗語錄已見，後成常用語。\n字面意思：沒有風、沒有浪，水面平靜。\n引申意思：平靜無事（如：風波過後，一切風平浪靜）。也可形容表面平靜。" },
  { id: "i419", grade: 2, term: "花好月圓", zhuyin: "ㄏㄨㄚ ㄏㄠˇ ㄩㄝˋ ㄩㄢˊ", pinyin: "huā hǎo yuè yuán", meaning: "花開得好、月亮圓滿，比喻美好圓滿。", example: "中秋夜花好月圓，全家團聚賞月。" , wordExp: "花好＝花開得美；月圓＝月亮滿圓。美好圓滿的景象。",deep:"典故由來：語本宋詞祝頌語「願花長好、月長圓」。\n字面意思：花開得正好，月亮正圓。\n引申意思：比喻美好圓滿（多用於祝賀婚禮：花好月圓）。" },
  { id: "i420", grade: 2, term: "秋高氣爽", zhuyin: "ㄑㄧㄡ ㄍㄠ ㄑㄧˋ ㄕㄨㄤˇ", pinyin: "qiū gāo qì shuǎng", meaning: "秋天天空晴朗，氣候涼爽宜人。", example: "秋高氣爽，正是登山的好時節。" , wordExp: "秋高＝秋空高爽；氣爽＝空氣清爽。秋天晴朗涼爽。",deep:"典故由來：語本唐．杜甫詩「高秋爽氣相鮮新」，後凝成「秋高氣爽」。\n字面意思：秋天天空高朗、空氣清爽。\n引申意思：形容秋天晴朗涼爽的天氣（如：秋高氣爽，適合郊遊）。" },
  { id: "i421", grade: 2, term: "冰天雪地", zhuyin: "ㄅㄧㄥ ㄊㄧㄢ ㄒㄩㄝˇ ㄉㄧˋ", pinyin: "bīng tiān xuě dì", meaning: "冰雪遍布，非常寒冷的景象。", example: "北國冰天雪地，湖面全結了冰。" , wordExp: "冰天＝結冰的天地；雪地＝積雪的大地。到處冰雪，非常寒冷。",deep:"典故由來：由字面組合而成，清代小說常見。\n字面意思：天結冰、地積雪。\n引申意思：形容極為寒冷的景象（如：北國冰天雪地）。" },
  { id: "i422", grade: 2, term: "寒風刺骨", zhuyin: "ㄏㄢˊ ㄈㄥ ㄘˋ ㄍㄨˇ", pinyin: "hán fēng cì gǔ", meaning: "寒冷的風像刺進骨頭一樣。", example: "寒流來襲，清晨寒風刺骨。" , wordExp: "寒風＝冷風；刺骨＝刺進骨頭。冷風凍得像刺進骨頭裡。",deep:"典故由來：由字面組合而成。\n字面意思：寒風像刺進骨頭。\n引申意思：形容風極冷（如：寒風刺骨的冬夜）。" },
  { id: "i423", grade: 2, term: "春風滿面", zhuyin: "ㄔㄨㄣ ㄈㄥ ㄇㄢˇ ㄇㄧㄢˋ", pinyin: "chūn fēng mǎn miàn", meaning: "滿臉笑容，心情愉快的樣子。", example: "得了獎的他春風滿面地走進教室。", syn: ["喜氣洋洋"] , wordExp: "春風＝和暖的風；滿面＝布滿臉上。臉上洋溢喜氣，像沐浴春風。",deep:"典故由來：由字面組合而成；「春風」喻和悅之氣。\n字面意思：滿臉如沐春風。\n引申意思：滿面笑容、心情愉快（如：他春風滿面地走進來，一定有好事）。" },
  { id: "i424", grade: 2, term: "笑容可掬", zhuyin: "ㄒㄧㄠˋ ㄖㄨㄥˊ ㄎㄜˇ ㄐㄩˊ", pinyin: "xiào róng kě jú", meaning: "笑容滿面，和藹可親。", example: "店長笑容可掬地招呼每位客人。", misuse: "「掬」是雙手捧取，形容笑意彷彿捧得出來。" , wordExp: "笑容＝笑意；可掬＝可以用手捧起。滿臉笑意彷彿捧得出來。",deep:"典故由來：見《三國演義》空城計：諸葛亮「坐於城樓之上，笑容可掬」。\n字面意思：笑容多得可以用手捧起來。\n引申意思：滿臉堆笑、和藹可親（如：店員笑容可掬地招呼客人）。" },
  { id: "i425", grade: 2, term: "綠樹成蔭", zhuyin: "ㄌㄩˋ ㄕㄨˋ ㄔㄥˊ ㄧㄣ", pinyin: "lǜ shù chéng yīn", meaning: "樹木茂密，樹蔭遮蔽成片。", example: "校園裡綠樹成蔭，夏天也很涼快。" , wordExp: "綠樹＝茂密的樹；成蔭＝連成樹蔭。枝葉茂密，遮出一片陰涼。",deep:"典故由來：語本唐．杜牧〈嘆花〉：「綠葉成陰子滿枝。」\n字面意思：綠樹茂密、樹蔭連成一片。\n引申意思：形容樹木繁茂的景象（如：校園綠樹成蔭）。" },
  { id: "i426", grade: 3, term: "狼吞虎嚥", zhuyin: "ㄌㄤˊ ㄊㄨㄣ ㄏㄨˇ ㄧㄢˋ", pinyin: "láng tūn hǔ yàn", meaning: "吃東西又猛又急。", example: "他餓壞了，狼吞虎嚥地扒完一碗飯。" , wordExp: "狼吞＝像狼一樣吞；虎嚥＝像虎一樣嚥。吃相又急又猛。",deep:"典故由來：由字面組合而成；狼、虎進食兇猛急促。\n字面意思：像狼虎一樣吞嚥食物。\n引申意思：吃東西又猛又急（如：餓了一天，狼吞虎嚥地扒飯）。相對詞：細嚼慢嚥。" },
  { id: "i427", grade: 3, term: "垂涎三尺", zhuyin: "ㄔㄨㄟˊ ㄒㄧㄢˊ ㄙㄢ ㄔˇ", pinyin: "chuí xián sān chǐ", meaning: "形容非常貪饞或渴望得到。", example: "烤雞的香味讓人垂涎三尺。", misuse: "「涎」讀ㄒㄧㄢˊ，口水。" , wordExp: "垂＝滴下；涎＝口水；三尺＝誇張的長度。饞得口水都要流下三尺。",deep:"典故由來：語本唐．柳宗元〈三戒〉「群犬垂涎」；「垂涎三尺」為後起的誇張說法。\n字面意思：口水流下三尺長。\n引申意思：非常貪饞，或極想得到（如：對名畫垂涎三尺）。多含貶義。" },
  { id: "i428", grade: 3, term: "飢腸轆轆", zhuyin: "ㄐㄧ ㄔㄤˊ ㄌㄨˋ ㄌㄨˋ", pinyin: "jī cháng lù lù", meaning: "肚子餓得咕嚕作響。", example: "跑完大隊接力，大家都飢腸轆轆。" , wordExp: "飢腸＝餓著的肚腸；轆轆＝車輪滾動聲。肚子餓得咕嚕作響。",deep:"典故由來：由字面組合而成；「轆轆」是車輪聲，形容腸鳴。\n字面意思：餓得肚子咕嚕咕嚕響。\n引申意思：非常飢餓（如：跑完步飢腸轆轆）。" },
  { id: "i429", grade: 3, term: "白紙黑字", zhuyin: "ㄅㄞˊ ㄓˇ ㄏㄟ ㄗˋ", pinyin: "bái zhǐ hēi zì", meaning: "寫成文字的憑據，清楚明確。", example: "合約白紙黑字寫得清清楚楚。" , wordExp: "白紙＝白色的紙；黑字＝黑色的字。寫得清清楚楚的憑據。",deep:"典故由來：元曲中已見的口語成語。\n字面意思：白紙上寫著黑字。\n引申意思：有文字為憑、清楚明確不容抵賴（如：合約白紙黑字寫得清楚）。" },
  { id: "i430", grade: 3, term: "一清二楚", zhuyin: "ㄧ ㄑㄧㄥ ㄦˋ ㄔㄨˇ", pinyin: "yī qīng èr chǔ", meaning: "非常清楚明白。", example: "監視器把經過拍得一清二楚。", syn: ["一目了然"] , wordExp: "一、二＝強調；清、楚＝清楚。清清楚楚，明明白白。",deep:"典故由來：由字面組合而成的口語成語。\n字面意思：一是清、二是楚，樣樣分明。\n引申意思：非常清楚明白（如：帳目記得一清二楚）。" },
  { id: "i431", grade: 3, term: "一乾二淨", zhuyin: "ㄧ ㄍㄢ ㄦˋ ㄐㄧㄥˋ", pinyin: "yī gān èr jìng", meaning: "非常乾淨；一點不剩。", example: "他把作業的事忘得一乾二淨。" , wordExp: "一、二＝強調；乾、淨＝乾淨。乾乾淨淨，一點不剩。",deep:"典故由來：由字面組合而成的口語成語。\n字面意思：一是乾、二是淨。\n引申意思：非常乾淨，或一點不剩（如：把飯吃得一乾二淨；把叮嚀忘得一乾二淨）。" },
  { id: "i432", grade: 3, term: "三三兩兩", zhuyin: "ㄙㄢ ㄙㄢ ㄌㄧㄤˇ ㄌㄧㄤˇ", pinyin: "sān sān liǎng liǎng", meaning: "三兩成群，零零散散。", example: "放學後，同學三三兩兩地走出校門。" , wordExp: "三三、兩兩＝三個一群、兩個一夥。零零散散的小群。",deep:"典故由來：古樂府詩已見「三三兩兩」的說法。\n字面意思：三個一群、兩個一夥。\n引申意思：人零零散散、成小群（如：同學三三兩兩走出校門）。" },
  { id: "i433", grade: 3, term: "五湖四海", zhuyin: "ㄨˇ ㄏㄨˊ ㄙˋ ㄏㄞˇ", pinyin: "wǔ hú sì hǎi", meaning: "泛指各地各方。", example: "營隊成員來自五湖四海。", syn: ["四面八方"] , wordExp: "五湖＝五大湖泊；四海＝四方大海。泛指全國、各地。",deep:"典故由來：唐代詩文已見；五湖指太湖等大湖，四海指四方之海。\n字面意思：五大湖、四方海。\n引申意思：泛指全國、各地（如：朋友來自五湖四海）。" },
  { id: "i434", grade: 3, term: "八面玲瓏", zhuyin: "ㄅㄚ ㄇㄧㄢˋ ㄌㄧㄥˊ ㄌㄨㄥˊ", pinyin: "bā miàn líng lóng", meaning: "處事圓滑，面面俱到。", example: "他八面玲瓏，各方人馬都處得來。", misuse: "多帶褒貶兩可的圓滑意味。" , wordExp: "八面＝各個方向；玲瓏＝精巧透亮。各方面都應付得圓滑周到。",deep:"典故由來：語本唐詩「八窗玲瓏」（四面八方窗子明亮通透），後演為「八面玲瓏」。\n字面意思：八個面都精巧通透。\n引申意思：處事圓滑、對誰都應付得宜（如：他八面玲瓏，人緣極好）。今多含貶義，暗指世故。" },
  { id: "i435", grade: 3, term: "九死一生", zhuyin: "ㄐㄧㄡˇ ㄙˇ ㄧ ㄕㄥ", pinyin: "jiǔ sǐ yī shēng", meaning: "歷經極大危險而倖存。", example: "登山隊在暴風雪中九死一生地脫困。", syn: ["死裡逃生"] , wordExp: "九死＝九次瀕死；一生＝一次活命。歷經萬般凶險僥倖存活。",deep:"典故由來：語本屈原《離騷》：「雖九死其猶未悔。」\n字面意思：九次死裡逃生只活一回。\n引申意思：歷經極大危險而倖存（如：戰場上九死一生）。" },
  { id: "i436", grade: 3, term: "十拿九穩", zhuyin: "ㄕˊ ㄋㄚˊ ㄐㄧㄡˇ ㄨㄣˇ", pinyin: "shí ná jiǔ wěn", meaning: "非常有把握。", example: "這題他練過上百次，十拿九穩。", syn: ["萬無一失", "勝券在握"] , wordExp: "十拿＝十次去拿；九穩＝九次穩當。極有把握。",deep:"典故由來：明代小說常見的口語成語。\n字面意思：十次裡有九次拿得穩。\n引申意思：非常有把握（如：這場比賽他十拿九穩）。" },
  { id: "i437", grade: 3, term: "百年樹人", zhuyin: "ㄅㄞˇ ㄋㄧㄢˊ ㄕㄨˋ ㄖㄣˊ", pinyin: "bǎi nián shù rén", meaning: "培育人才是長遠大計。", example: "十年樹木，百年樹人，教育急不得。" , wordExp: "百年＝長遠的時間；樹＝培植；人＝人才。培養人才是百年大計。",deep:"典故由來：出自《管子．權修》：「一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人。」後凝為「十年樹木，百年樹人」。\n字面意思：培育人才像種樹，需要百年。\n引申意思：培養人才是長遠大業（如：教育是百年樹人的事業）。" },
  { id: "i438", grade: 3, term: "千方百計", zhuyin: "ㄑㄧㄢ ㄈㄤ ㄅㄞˇ ㄐㄧˋ", pinyin: "qiān fāng bǎi jì", meaning: "想盡各種辦法。", example: "他千方百計想讓奶奶展露笑容。", syn: ["想方設法"] , wordExp: "千方＝上千種方法；百計＝上百種計策。想盡一切辦法。",deep:"典故由來：宋《朱子語類》已見「千方百計」。\n字面意思：一千種方法、一百種計謀。\n引申意思：想盡各種辦法（如：千方百計解決問題）。" },
  { id: "i439", grade: 3, term: "千言萬語", zhuyin: "ㄑㄧㄢ ㄧㄢˊ ㄨㄢˋ ㄩˇ", pinyin: "qiān yán wàn yǔ", meaning: "要說的話非常多。", example: "重逢時千言萬語，一時不知從何說起。" , wordExp: "千言＝千句話；萬語＝萬句話。要說的話極多。",deep:"典故由來：唐代詩文常見，由字面組合而成。\n字面意思：一千句話、一萬句話。\n引申意思：要說的話很多，說不完（如：千言萬語道不盡感謝）。" },
  { id: "i440", grade: 3, term: "萬水千山", zhuyin: "ㄨㄢˋ ㄕㄨㄟˇ ㄑㄧㄢ ㄕㄢ", pinyin: "wàn shuǐ qiān shān", meaning: "路途遙遠險阻。", example: "候鳥飛越萬水千山回到故鄉。" , wordExp: "萬水＝萬條河；千山＝千座山。路途遙遠艱險。",deep:"典故由來：唐代詩文常見，由字面組合而成。\n字面意思：一萬條水、一千座山。\n引申意思：路途遙遠艱險（如：跨越萬水千山來相會）。" },
  { id: "i441", grade: 3, term: "三令五申", zhuyin: "ㄙㄢ ㄌㄧㄥˋ ㄨˇ ㄕㄣ", pinyin: "sān lìng wǔ shēn", meaning: "一再命令告誡。", example: "校方三令五申禁止騎車載人。" , wordExp: "三、五＝多次；令＝命令；申＝說明告誡。一再命令告誡。",deep:"典故由來：出自《史記．孫子吳起列傳》：孫武替吳王訓練宮女，「三令五申」講明號令，宮女仍嬉笑，孫武斬隊長立威，之後令行禁止。\n字面意思：再三命令、一再申誡。\n引申意思：一次又一次告誡（如：學校三令五申禁止騎車載人）。" },
  { id: "i442", grade: 3, term: "四平八穩", zhuyin: "ㄙˋ ㄆㄧㄥˊ ㄅㄚ ㄨㄣˇ", pinyin: "sì píng bā wěn", meaning: "穩妥周全，也指做事保守不出錯。", example: "他的報告四平八穩，挑不出毛病。" , wordExp: "四平＝四邊平穩；八穩＝八方安穩。穩穩當當，不出差錯。",deep:"典故由來：見《水滸傳》：形容人「生得四平八穩」。\n字面意思：四面平正、八方安穩。\n引申意思：穩妥周全；也指做事只求不出錯、缺乏創新（如：文章寫得四平八穩）。後一義含貶意。" },
  { id: "i443", grade: 3, term: "五體投地", zhuyin: "ㄨˇ ㄊㄧˇ ㄊㄡˊ ㄉㄧˋ", pinyin: "wǔ tǐ tóu dì", meaning: "佩服到了極點。", example: "學長解題又快又漂亮，令我五體投地。", syn: ["心悅誠服"] , wordExp: "五體＝雙手雙膝與頭；投地＝觸地。行大禮跪拜，佩服到極點。",deep:"典故由來：源自佛教最恭敬的禮拜方式：雙肘、雙膝、頭部五處著地（見《楞嚴經》等佛典）。\n字面意思：身體五個部位都碰到地面。\n引申意思：佩服到極點（如：他的棋藝令我佩服得五體投地）。" },
  { id: "i444", grade: 3, term: "七拼八湊", zhuyin: "ㄑㄧ ㄆㄧㄣ ㄅㄚ ㄘㄡˋ", pinyin: "qī pīn bā còu", meaning: "把零碎的東西勉強湊在一起。", example: "報告七拼八湊，內容毫無條理。", syn: ["東拼西湊"] , wordExp: "七、八＝雜亂；拼、湊＝拼湊。東拼西湊，勉強成篇。",deep:"典故由來：由字面組合而成的口語成語。\n字面意思：七處拼、八處湊。\n引申意思：把零碎的東西勉強湊合（如：報告是七拼八湊趕出來的）。貶義。" },
  { id: "i445", grade: 3, term: "亂七八糟", zhuyin: "ㄌㄨㄢˋ ㄑㄧ ㄅㄚ ㄗㄠ", pinyin: "luàn qī bā zāo", meaning: "混亂沒有條理。", example: "房間亂七八糟，該整理了。", syn: ["雜亂無章"] , wordExp: "七、八＝雜亂；糟＝糟糕。亂糟糟沒有條理。",deep:"典故由來：由字面組合而成的口語成語，清代小說常見。\n字面意思：七也亂、八也糟。\n引申意思：混亂沒條理（如：房間亂七八糟）。貶義。" },
  { id: "i446", grade: 3, term: "千奇百怪", zhuyin: "ㄑㄧㄢ ㄑㄧˊ ㄅㄞˇ ㄍㄨㄞˋ", pinyin: "qiān qí bǎi guài", meaning: "各種各樣奇怪的事物。", example: "深海生物千奇百怪，超乎想像。", syn: ["光怪陸離"] , wordExp: "千、百＝眾多；奇、怪＝奇特怪異。各式各樣的奇特事物。",deep:"典故由來：宋代文獻已見「千奇百怪」。\n字面意思：一千種奇、一百種怪。\n引申意思：各式各樣稀奇古怪（如：海底生物千奇百怪）。" },
  { id: "i447", grade: 3, term: "口是心非", zhuyin: "ㄎㄡˇ ㄕˋ ㄒㄧㄣ ㄈㄟ", pinyin: "kǒu shì xīn fēi", meaning: "嘴上說的和心裡想的不一致。", example: "他口是心非，嘴上說沒關係，其實很在意。", syn: ["言不由衷"] , wordExp: "口＝嘴上；是＝說是；心＝心裡；非＝想的相反。嘴上一套，心裡一套。",deep:"典故由來：出自晉．葛洪《抱朴子》：「口是心非，背向異辭。」\n字面意思：嘴上說是，心裡想的卻不是。\n引申意思：心口不一（如：他口是心非，答應了卻不想做）。貶義。" },
  { id: "i448", grade: 3, term: "有始有終", zhuyin: "ㄧㄡˇ ㄕˇ ㄧㄡˇ ㄓㄨㄥ", pinyin: "yǒu shǐ yǒu zhōng", meaning: "做事能堅持到底。", example: "答應的事就要有始有終。", syn: ["貫徹始終"] , wordExp: "有始＝有開頭；有終＝有結尾。做事從頭堅持到尾。",deep:"典故由來：語本《論語．子張》：「有始有卒者，其惟聖人乎！」\n字面意思：有開頭也有結尾。\n引申意思：做事能堅持到底（如：學才藝要有始有終）。褒義；相對詞：虎頭蛇尾、半途而廢。" },
  { id: "i449", grade: 3, term: "自告奮勇", zhuyin: "ㄗˋ ㄍㄠˋ ㄈㄣˋ ㄩㄥˇ", pinyin: "zì gào fèn yǒng", meaning: "主動要求承擔任務。", example: "他自告奮勇擔任小組長。", syn: ["毛遂自薦"] , wordExp: "自告＝自己請求；奮勇＝鼓起勇氣。主動勇敢地承擔任務。",deep:"典故由來：清代小說常見的口語成語；「告」是請求。\n字面意思：自己請求奮勇承擔。\n引申意思：主動要求接下任務（如：他自告奮勇當班長）。褒義。" },
  { id: "i450", grade: 3, term: "小心翼翼", zhuyin: "ㄒㄧㄠˇ ㄒㄧㄣ ㄧˋ ㄧˋ", pinyin: "xiǎo xīn yì yì", meaning: "非常謹慎，不敢疏忽。", example: "他小心翼翼地捧著金魚缸走回家。", syn: ["謹小慎微"] , wordExp: "小心＝謹慎；翼翼＝恭敬謹慎的樣子。非常小心謹慎。",deep:"典故由來：出自《詩經．大雅．大明》：「維此文王，小心翼翼。」原形容周文王恭敬謹慎。\n字面意思：恭敬謹慎的樣子（翼翼＝恭敬）。\n引申意思：非常小心、不敢大意（如：小心翼翼地捧著魚缸）。" },
  // ---- i451-i500（國小中高年級）----
  { id: "i451", grade: 4, term: "喜出望外", zhuyin: "ㄒㄧˇ ㄔㄨ ㄨㄤˋ ㄨㄞˋ", pinyin: "xǐ chū wàng wài", meaning: "遇到意想不到的好事而特別高興。", example: "以為門票賣完了，竟拿到兩張，真是喜出望外。", syn: ["大喜過望"] , wordExp: "喜＝歡喜；出＝超出；望外＝期望之外。好事出乎意料，格外高興。",deep:"典故由來：出自宋．蘇軾〈與李之儀書〉：「契闊八年，豈謂復有見日，漸近中原，辱書尤數，喜出望外。」\n字面意思：喜悅超出原本的期望。\n引申意思：遇到意想不到的好事而格外高興（如：意外獲獎，喜出望外）。" },
  { id: "i452", grade: 4, term: "忐忑不安", zhuyin: "ㄊㄢˇ ㄊㄜˋ ㄅㄨˋ ㄢ", pinyin: "tǎn tè bù ān", meaning: "心神不定，惶恐不安。", example: "面試前他忐忑不安，手心冒汗。", syn: ["七上八下"] , wordExp: "忐忑＝心上上下下。心神不寧，七上八下。",deep:"典故由來：「忐忑」是後起的會意字：心上上下下，七上八下。\n字面意思：心裡上上下下不安定。\n引申意思：心神不寧（如：等待放榜，忐忑不安）。" },
  { id: "i453", grade: 4, term: "無精打采", zhuyin: "ㄨˊ ㄐㄧㄥ ㄉㄚˇ ㄘㄞˇ", pinyin: "wú jīng dǎ cǎi", meaning: "提不起精神，沒有活力。", example: "熬夜之後，他整天無精打采。", syn: ["垂頭喪氣"] , wordExp: "無精＝沒有精神；打采＝提起神采。沒精神、沒活力。",deep:"典故由來：見清．曹雪芹《紅樓夢》：「賈璉是醉了，嗔道無精打采。」\n字面意思：沒有精神、提不起神采。\n引申意思：精神萎靡（如：沒睡飽，整天無精打采）。相對詞：神采奕奕。" },
  { id: "i454", grade: 4, term: "興致勃勃", zhuyin: "ㄒㄧㄥˋ ㄓˋ ㄅㄛˊ ㄅㄛˊ", pinyin: "xìng zhì bó bó", meaning: "興趣濃厚，情緒高昂。", example: "大家興致勃勃地討論營火晚會的節目。", syn: ["興高采烈"] , wordExp: "興致＝興趣；勃勃＝旺盛的樣子。興趣濃厚高昂。",deep:"典故由來：見清．李汝珍《鏡花緣》：「到了郡考，眾人以為必是首卷，誰知仍是第二，心中不服，興致勃勃。」後多指興趣濃厚。\n字面意思：興致旺盛的樣子（勃勃＝旺盛）。\n引申意思：興趣濃、勁頭足（如：興致勃勃地參加營隊）。" },
  { id: "i455", grade: 4, term: "依依難捨", zhuyin: "ㄧ ㄧ ㄋㄢˊ ㄕㄜˇ", pinyin: "yī yī nán shě", meaning: "非常留戀，捨不得離開。", example: "營隊結束，隊員們依依難捨地互道再見。", syn: ["依依不捨"] , wordExp: "依依＝留戀；難捨＝難以割捨。捨不得分離。",deep:"典故由來：「依依」語出《詩經．小雅．采薇》「楊柳依依」，形容留戀不捨。\n字面意思：戀戀不捨，難以分離。\n引申意思：非常留戀、捨不得離開（如：轉學前與同學依依難捨）。" },
  { id: "i456", grade: 4, term: "情不自禁", zhuyin: "ㄑㄧㄥˊ ㄅㄨˋ ㄗˋ ㄐㄧㄣ", pinyin: "qíng bù zì jīn", meaning: "感情激動，控制不住自己。", example: "聽到熟悉的旋律，她情不自禁地跟著唱。", misuse: "「禁」在此讀ㄐㄧㄣ，承受、控制之意。" , wordExp: "情＝感情；不自禁＝自己控制不住。感情激動得無法自制。",deep:"典故由來：語本南朝梁．劉遵詩：「步月如有意，情來不自禁。」\n字面意思：感情湧上來，自己禁止不住。\n引申意思：情緒激動控制不住（如：聽到國歌，情不自禁站起來）。多用於正面或感動的情緒。" },
  { id: "i457", grade: 4, term: "不由自主", zhuyin: "ㄅㄨˋ ㄧㄡˊ ㄗˋ ㄓㄨˇ", pinyin: "bù yóu zì zhǔ", meaning: "由不得自己作主，控制不了。", example: "天氣一冷，牙齒就不由自主地打顫。", syn: ["情不自禁"] , wordExp: "不由＝由不得；自主＝自己作主。身不由己。",deep:"典故由來：見《紅樓夢》：「我也不由自主，就進來了。」\n字面意思：由不得自己作主。\n引申意思：行為不受自己控制（如：緊張得手不由自主地發抖）。多指身體反應。" },
  { id: "i458", grade: 4, term: "破涕為笑", zhuyin: "ㄆㄛˋ ㄊㄧˋ ㄨㄟˊ ㄒㄧㄠˋ", pinyin: "pò tì wéi xiào", meaning: "停止哭泣，轉為笑容。", example: "小丑的表演讓哭鬧的妹妹破涕為笑。" , wordExp: "破涕＝止住眼淚；為笑＝轉為笑容。轉哭為笑。",deep:"典故由來：出自晉．劉琨〈答盧諶書〉：「時復相與舉觴對膝，破涕為笑。」\n字面意思：停止眼淚，轉為笑容。\n引申意思：轉悲為喜（如：聽到好消息，她破涕為笑）。" },
  { id: "i459", grade: 4, term: "淚流滿面", zhuyin: "ㄌㄟˋ ㄌㄧㄡˊ ㄇㄢˇ ㄇㄧㄢˋ", pinyin: "lèi liú mǎn miàn", meaning: "眼淚流了滿臉，非常傷心或感動。", example: "看到失散多年的親人，他淚流滿面。", syn: ["泣不成聲"] , wordExp: "淚流＝眼淚流淌；滿面＝滿臉。哭得滿臉是淚。",deep:"典故由來：由字面組合而成。\n字面意思：眼淚流滿了臉。\n引申意思：極度傷心或感動（如：重逢時淚流滿面）。" },
  { id: "i460", grade: 4, term: "百感交集", zhuyin: "ㄅㄞˇ ㄍㄢˇ ㄐㄧㄠ ㄐㄧˊ", pinyin: "bǎi gǎn jiāo jí", meaning: "各種感觸交織在心頭。", example: "回到母校，他百感交集，往事歷歷在目。", syn: ["感慨萬千"] , wordExp: "百感＝各種感觸；交集＝交織聚集。多種情緒湧上心頭。",deep:"典故由來：語本《世說新語．言語》：衛玠渡江時感嘆「見此芒芒，不覺百端交集」。\n字面意思：上百種感觸交織聚集。\n引申意思：各種情緒同時湧上心頭（如：回到母校，百感交集）。" },
  { id: "i461", grade: 4, term: "歷歷在目", zhuyin: "ㄌㄧˋ ㄌㄧˋ ㄗㄞˋ ㄇㄨˋ", pinyin: "lì lì zài mù", meaning: "過去的情景清楚地浮現眼前。", example: "童年趣事至今歷歷在目。", syn: ["記憶猶新"] , wordExp: "歷歷＝清清楚楚；在目＝在眼前。往事清晰浮現眼前。",deep:"典故由來：語本唐．杜甫〈歷歷〉詩：「歷歷開元事，分明在眼前。」\n字面意思：一件件清楚地呈現在眼前（歷歷＝分明可數）。\n引申意思：往事清晰浮現（如：童年情景歷歷在目）。" },
  { id: "i462", grade: 4, term: "記憶猶新", zhuyin: "ㄐㄧˋ ㄧˋ ㄧㄡˊ ㄒㄧㄣ", pinyin: "jì yì yóu xīn", meaning: "對過去的事記得清清楚楚，像新發生一樣。", example: "第一次上台的緊張，我至今記憶猶新。", syn: ["歷歷在目"] , wordExp: "記憶＝記得的印象；猶＝還；新＝新鮮。記得像新發生的一樣。",deep:"典故由來：由字面組合而成，宋代文獻已見。\n字面意思：記憶還像新的一樣。\n引申意思：對往事記得非常清楚（如：那次旅行至今記憶猶新）。" },
  { id: "i463", grade: 4, term: "煥然一新", zhuyin: "ㄏㄨㄢˋ ㄖㄢˊ ㄧ ㄒㄧㄣ", pinyin: "huàn rán yī xīn", meaning: "面貌完全改變，呈現嶄新氣象。", example: "教室重新粉刷後煥然一新。", syn: ["面目一新"] , wordExp: "煥然＝光亮一新的樣子；一新＝全部更新。面貌全新。",deep:"典故由來：語本唐．張彥遠《歷代名畫記》：描述名畫修復後「煥然如新」。\n字面意思：光亮鮮明，像全新的一樣（煥＝光亮）。\n引申意思：面貌全變、氣象一新（如：教室粉刷後煥然一新）。注意「煥」不寫作「換」。" },
  { id: "i464", grade: 4, term: "五彩繽紛", zhuyin: "ㄨˇ ㄘㄞˇ ㄅㄧㄣ ㄈㄣ", pinyin: "wǔ cǎi bīn fēn", meaning: "色彩繁多而絢麗。", example: "熱氣球節會場五彩繽紛。", syn: ["五顏六色", "五光十色"] , wordExp: "五彩＝多種色彩；繽紛＝繁盛交錯。色彩繁多絢麗。",deep:"典故由來：由字面組合而成；「繽紛」是繁多交錯的樣子。\n字面意思：五種彩色繁盛交錯。\n引申意思：色彩繁多絢麗（如：煙火五彩繽紛）。" },
  { id: "i465", grade: 4, term: "爭奇鬥豔", zhuyin: "ㄓㄥ ㄑㄧˊ ㄉㄡˋ ㄧㄢˋ", pinyin: "zhēng qí dòu yàn", meaning: "競相展現奇特豔麗，互比美好。", example: "花展中各色玫瑰爭奇鬥豔。" , wordExp: "爭＝競相；奇＝奇特；鬥＝比拼；豔＝豔麗。競相比美。",deep:"典故由來：由字面組合而成，宋代詩文已見類似說法。\n字面意思：爭比奇特、鬥比豔麗。\n引申意思：競相展現美麗（如：花園裡百花爭奇鬥豔）。" },
  { id: "i466", grade: 4, term: "生機盎然", zhuyin: "ㄕㄥ ㄐㄧ ㄤˋ ㄖㄢˊ", pinyin: "shēng jī àng rán", meaning: "充滿生命力與活力。", example: "春雨過後，田野生機盎然。", syn: ["欣欣向榮"] , wordExp: "生機＝生命力；盎然＝洋溢的樣子。充滿蓬勃生氣。",deep:"典故由來：由字面組合而成；「盎然」是洋溢充滿的樣子。\n字面意思：生命力洋溢。\n引申意思：充滿生氣活力（如：春天萬物生機盎然）。" },
  { id: "i467", grade: 4, term: "枝繁葉茂", zhuyin: "ㄓ ㄈㄢˊ ㄧㄝˋ ㄇㄠˋ", pinyin: "zhī fán yè mào", meaning: "枝葉繁多茂盛。", example: "老榕樹枝繁葉茂，像一把大傘。", syn: ["根深葉茂"] , wordExp: "枝繁＝枝條繁多；葉茂＝葉子茂密。草木長得旺盛。",deep:"典故由來：由字面組合而成，明代文獻已見。\n字面意思：枝條繁多、葉子茂密。\n引申意思：草木茂盛；也比喻家族興旺（如：老榕樹枝繁葉茂）。" },
  { id: "i468", grade: 4, term: "碩果僅存", zhuyin: "ㄕㄨㄛˋ ㄍㄨㄛˇ ㄐㄧㄣˇ ㄘㄨㄣˊ", pinyin: "shuò guǒ jǐn cún", meaning: "留存下來的珍貴人或物。", example: "這家老戲院是鎮上碩果僅存的日治建築。" , wordExp: "碩果＝大果實；僅存＝只剩下。碩大的果實只剩一顆，僅存的珍貴之物。",deep:"典故由來：語本《易經．剝卦》：「碩果不食。」大果實留在樹上沒被摘食。\n字面意思：唯一留存的大果實。\n引申意思：碩果僅存指留存下來的珍貴人或物（如：他是那一代大師中碩果僅存的一位）。" },
  { id: "i469", grade: 4, term: "從容不迫", zhuyin: "ㄘㄨㄥ ㄖㄨㄥˊ ㄅㄨˋ ㄆㄛˋ", pinyin: "cōng róng bù pò", meaning: "鎮定沉著，不慌不忙。", example: "面對追問，她從容不迫地一一說明。", syn: ["不慌不忙", "泰然自若"] , wordExp: "從容＝安詳沉著；不迫＝不慌張。沉著不慌。",deep:"典故由來：語本《莊子．秋水》：莊子見「鯈魚出遊從容」，以魚的悠然自得論辯快樂。\n字面意思：舉止從容，不慌不忙。\n引申意思：沉著鎮定（如：他從容不迫地回答考官）。褒義；相對詞：驚慌失措。" },
  { id: "i470", grade: 4, term: "手足無措", zhuyin: "ㄕㄡˇ ㄗㄨˊ ㄨˊ ㄘㄨㄛˋ", pinyin: "shǒu zú wú cuò", meaning: "慌張得不知如何是好。", example: "突然被推上台，他一時手足無措。", syn: ["不知所措", "六神無主"] , wordExp: "手足＝手和腳；無措＝不知怎麼放。慌張得手腳不知往哪擺。",deep:"典故由來：語本《論語．子路》：「刑罰不中，則民無所措手足。」人民慌得手腳不知往哪擺。\n字面意思：手腳不知道放哪裡。\n引申意思：慌張得不知如何是好（如：突發狀況讓他手足無措）。相對詞：從容不迫。" },
  { id: "i471", grade: 4, term: "若無其事", zhuyin: "ㄖㄨㄛˋ ㄨˊ ㄑㄧˊ ㄕˋ", pinyin: "ruò wú qí shì", meaning: "好像沒發生事情一樣，不動聲色。", example: "闖了禍還若無其事地看電視。", syn: ["泰然自若"] , wordExp: "若＝好像；無其事＝沒那回事。裝作沒事一樣。",deep:"典故由來：清末小說常見的口語成語。\n字面意思：好像沒有那回事一樣。\n引申意思：形容鎮定或漠不關心（如：他闖了禍還若無其事）。視語境可褒（沉著）可貶（冷漠）。" },
  { id: "i472", grade: 4, term: "屏氣凝神", zhuyin: "ㄅㄧㄥˇ ㄑㄧˋ ㄋㄧㄥˊ ㄕㄣˊ", pinyin: "bǐng qì níng shén", meaning: "屏住呼吸，集中精神。", example: "觀眾屏氣凝神，看走鋼索的人跨出每一步。", misuse: "「屏」在此讀ㄅㄧㄥˇ，抑止之意。", syn: ["全神貫注"] , wordExp: "屏＝抑止；氣＝呼吸；凝＝凝聚；神＝精神。憋住呼吸、集中精神。",deep:"典故由來：語本《論語．鄉黨》：孔子入公門「屏氣似不息者」——憋住氣像沒呼吸一樣恭敬。\n字面意思：憋住呼吸、凝聚心神。\n引申意思：高度專注（如：全場屏氣凝神看著走鋼索表演）。注意「屏」讀ㄅㄧㄥˇ。" },
  { id: "i473", grade: 4, term: "聚沙成塔", zhuyin: "ㄐㄩˋ ㄕㄚ ㄔㄥˊ ㄊㄚˇ", pinyin: "jù shā chéng tǎ", meaning: "累積微小的力量而成大功。", example: "每天存五元，聚沙成塔也能買腳踏車。", syn: ["積少成多", "集腋成裘"] , wordExp: "聚＝聚集；沙＝細沙；成塔＝堆成寶塔。細沙也能堆成塔，積少成多。",deep:"典故由來：語本《妙法蓮華經》：「乃至童子戲，聚沙為佛塔。」\n字面意思：把沙子聚成佛塔。\n引申意思：積少成多，累積小力量成大事（如：每天存十元，聚沙成塔）。近義：積少成多、集腋成裘。" },
  { id: "i474", grade: 5, term: "滴水穿石", zhuyin: "ㄉㄧ ㄕㄨㄟˇ ㄔㄨㄢ ㄕˊ", pinyin: "dī shuǐ chuān shí", meaning: "微小的力量持之以恆，也能成就大事。", example: "每天背五個單字，滴水穿石，一年就是一千八。", syn: ["磨杵成針", "持之以恆"] , wordExp: "滴水＝一滴滴的水；穿石＝穿透石頭。水滴不斷，石頭也能穿，貴在堅持。",deep:"典故由來：出自宋．羅大經《鶴林玉露》：張乖崖懲治小吏時說「一日一錢，千日千錢，繩鋸木斷，水滴石穿」。\n字面意思：水滴不斷落下，能穿透石頭。\n引申意思：力量雖小，持之以恆必能成功（如：學語言要有滴水穿石的功夫）。褒義。" },
  { id: "i475", grade: 5, term: "念念不忘", zhuyin: "ㄋㄧㄢˋ ㄋㄧㄢˋ ㄅㄨˋ ㄨㄤˋ", pinyin: "niàn niàn bù wàng", meaning: "牢記在心，時時想著。", example: "他對外婆做的蘿蔔糕念念不忘。", syn: ["魂牽夢縈"] , wordExp: "念念＝一個念頭接一個念頭；不忘＝忘不了。時時記掛在心。",deep:"典故由來：宋代理學語錄常見「念念不忘」。\n字面意思：一個念頭接一個念頭，不曾忘記。\n引申意思：時時記掛在心（如：他對故鄉念念不忘）。" },
  { id: "i476", grade: 5, term: "戀戀不捨", zhuyin: "ㄌㄧㄢˋ ㄌㄧㄢˋ ㄅㄨˋ ㄕㄜˇ", pinyin: "liàn liàn bù shě", meaning: "非常留戀，捨不得離去。", example: "遊客戀戀不捨地離開這座美麗的小島。", syn: ["依依不捨"] , wordExp: "戀戀＝依戀的樣子；不捨＝捨不得。捨不得離開。",deep:"典故由來：語本《史記．范雎蔡澤列傳》：須賈贈綈袍，范雎感其「戀戀有故人之意」。\n字面意思：留戀不捨的樣子。\n引申意思：捨不得離開（如：畢業典禮後大家戀戀不捨）。" },
  { id: "i477", grade: 5, term: "朝思暮想", zhuyin: "ㄓㄠ ㄙ ㄇㄨˋ ㄒㄧㄤˇ", pinyin: "zhāo sī mù xiǎng", meaning: "從早到晚都在想念。", example: "他終於見到朝思暮想的偶像。", misuse: "「朝」讀ㄓㄠ，早晨。" , wordExp: "朝＝早晨；思＝思念；暮＝傍晚；想＝想念。從早想到晚。",deep:"典故由來：宋詞中常見的組合語。\n字面意思：早上想、晚上也想。\n引申意思：日夜思念（如：朝思暮想的故鄉）。" },
  { id: "i478", grade: 5, term: "望眼欲穿", zhuyin: "ㄨㄤˋ ㄧㄢˇ ㄩˋ ㄔㄨㄢ", pinyin: "wàng yǎn yù chuān", meaning: "盼望殷切，眼睛都要望穿了。", example: "球迷望眼欲穿，等著偶像返台開球。", syn: ["引頸期盼"] , wordExp: "望眼＝盼望的眼睛；欲穿＝快要望穿。盼望極為殷切。",deep:"典故由來：由「望穿秋水」等詩詞意象凝成的常用語。\n字面意思：眼睛都快望穿了。\n引申意思：盼望極為殷切（如：孩子望眼欲穿地等媽媽回家）。" },
  { id: "i479", grade: 5, term: "如願以償", zhuyin: "ㄖㄨˊ ㄩㄢˋ ㄧˇ ㄔㄤˊ", pinyin: "rú yuàn yǐ cháng", meaning: "願望得到實現。", example: "苦練三年，他如願以償進入校隊。", syn: ["夢寐以求"] , wordExp: "如＝依照；願＝心願；以償＝得到實現。心願達成。",deep:"典故由來：清代小說常見；「償」是實現、滿足。\n字面意思：像所許的願望一樣得到實現。\n引申意思：願望實現（如：他如願以償考上第一志願）。" },
  { id: "i480", grade: 5, term: "夢寐以求", zhuyin: "ㄇㄥˋ ㄇㄟˋ ㄧˇ ㄑㄧㄡˊ", pinyin: "mèng mèi yǐ qiú", meaning: "連睡夢中都在追求，形容渴望已久。", example: "這是他夢寐以求的錄取通知。", syn: ["朝思暮想"] , wordExp: "夢寐＝睡夢之中；以求＝也在追求。連做夢都想得到。",deep:"典故由來：語本《詩經．周南．關雎》：「窈窕淑女，寤寐求之。」醒著睡著都在追求。\n字面意思：連睡夢中都在追求。\n引申意思：渴望已久（如：夢寐以求的旅行終於成行）。" },
  { id: "i481", grade: 5, term: "大失所望", zhuyin: "ㄉㄚˋ ㄕ ㄙㄨㄛˇ ㄨㄤˋ", pinyin: "dà shī suǒ wàng", meaning: "非常失望。", example: "續集拍得草率，影迷大失所望。" , wordExp: "大失＝大大失去；所望＝所期望的。期望完全落空。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：原來的期望完全落空。\n引申意思：非常失望（如：比賽結果令人大失所望）。" },
  { id: "i482", grade: 5, term: "出乎意料", zhuyin: "ㄔㄨ ㄏㄨ ㄧˋ ㄌㄧㄠˋ", pinyin: "chū hū yì liào", meaning: "超出原先的預料。", example: "比賽結果出乎意料，黑馬奪冠。", syn: ["始料未及"] , wordExp: "出乎＝超出；意料＝預料。在預料之外。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：超出了預先的料想。\n引申意思：意想不到（如：結局出乎意料）。" },
  { id: "i483", grade: 5, term: "恰到好處", zhuyin: "ㄑㄧㄚˋ ㄉㄠˋ ㄏㄠˇ ㄔㄨˋ", pinyin: "qià dào hǎo chù", meaning: "正好達到最適當的程度。", example: "這道湯鹹淡恰到好處。", syn: ["恰如其分"] , wordExp: "恰＝正好；到＝達到；好處＝最適當的程度。分寸拿捏得剛剛好。",deep:"典故由來：見清．王士禛《帶經堂詩話》等文評用語。\n字面意思：恰好達到最合適的地方。\n引申意思：程度正好、不多不少（如：調味恰到好處）。褒義。" },
  { id: "i484", grade: 5, term: "一舉成名", zhuyin: "ㄧ ㄐㄩˇ ㄔㄥˊ ㄇㄧㄥˊ", pinyin: "yī jǔ chéng míng", meaning: "一次行動就成就了名聲。", example: "她以一首自創曲一舉成名。", syn: ["一鳴驚人"] , wordExp: "一舉＝一次行動；成名＝成就名聲。一次就出名。",deep:"典故由來：語本元．劉祁《歸潛志》：「古人謂十年窗下無人問，一舉成名天下知。」\n字面意思：一次行動就成名。\n引申意思：因一次表現而聲名大噪（如：這部電影讓她一舉成名）。" },
  { id: "i485", grade: 5, term: "脫穎而出", zhuyin: "ㄊㄨㄛ ㄧㄥˇ ㄦˊ ㄔㄨ", pinyin: "tuō yǐng ér chū", meaning: "才能顯露，超越眾人。", example: "他從百位參賽者中脫穎而出。", misuse: "「穎」是錐尖，出自毛遂自薦的典故。", syn: ["嶄露頭角"] , wordExp: "脫＝掙脫而出；穎＝錐子的尖端。錐尖藏在袋中終會露出，才能顯露出眾。",deep:"典故由來：出自《史記．平原君列傳》：毛遂說，賢士如錐子放在袋中，錐尖立現；若早被重用，就會「穎脫而出」——整個錐鋒都露出來。\n字面意思：錐尖穿透布袋顯露出來。\n引申意思：才能顯露、超越眾人（如：他在選拔中脫穎而出）。褒義。" },
  { id: "i486", grade: 5, term: "名不虛傳", zhuyin: "ㄇㄧㄥˊ ㄅㄨˋ ㄒㄩ ㄔㄨㄢˊ", pinyin: "míng bù xū chuán", meaning: "名聲與實際相符，不是空有虛名。", example: "這家牛肉麵名不虛傳，湯頭一絕。", syn: ["名副其實"] , wordExp: "名＝名聲；不虛＝不是虛假；傳＝流傳。名聲與實際相符。",deep:"典故由來：晉代文獻已見「名不虛傳」。\n字面意思：名聲不是白白流傳的。\n引申意思：名聲與實際相符（如：這家老店名不虛傳）。褒義。" },
  { id: "i487", grade: 5, term: "有口皆碑", zhuyin: "ㄧㄡˇ ㄎㄡˇ ㄐㄧㄝ ㄅㄟ", pinyin: "yǒu kǒu jiē bēi", meaning: "人人稱讚，如同口頭的紀念碑。", example: "老診所的醫德有口皆碑。", syn: ["交口稱譽"] , wordExp: "有口＝人人開口；皆＝都是；碑＝記功的石碑。人人稱讚，如同口頭立碑。",deep:"典故由來：出自宋．《五燈會元》：「勸君不用鐫頑石，路上行人口似碑。」\n字面意思：人人的嘴都是一座記功碑。\n引申意思：人人稱讚（如：他的服務有口皆碑）。褒義。" },
  { id: "i488", grade: 5, term: "讚不絕口", zhuyin: "ㄗㄢˋ ㄅㄨˋ ㄐㄩㄝˊ ㄎㄡˇ", pinyin: "zàn bù jué kǒu", meaning: "不停地稱讚。", example: "評審對她的琴藝讚不絕口。" , wordExp: "讚＝稱讚；不絕口＝不停口。稱讚個不停。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：稱讚的話不停口。\n引申意思：不停地稱讚（如：吃過的人都讚不絕口）。褒義。" },
  { id: "i489", grade: 5, term: "刮目相看", zhuyin: "ㄍㄨㄚ ㄇㄨˋ ㄒㄧㄤ ㄎㄢˋ", pinyin: "guā mù xiāng kàn", meaning: "以全新的眼光看待進步的人。", example: "半年不見，他的球技令人刮目相看。", misuse: "呂蒙「士別三日」的典故。" , wordExp: "刮目＝擦亮眼睛；相看＝來看待。用全新眼光看待對方的進步。",deep:"典故由來：出自《三國志．呂蒙傳》裴注：呂蒙聽勸苦讀，魯肅驚其進步，呂蒙說：「士別三日，即更刮目相待。」\n字面意思：擦亮眼睛重新看待。\n引申意思：用新眼光看待進步的人（如：他的表現令人刮目相看）。褒義。" },
  { id: "i490", grade: 5, term: "另眼相看", zhuyin: "ㄌㄧㄥˋ ㄧㄢˇ ㄒㄧㄤ ㄎㄢˋ", pinyin: "lìng yǎn xiāng kàn", meaning: "用不同於一般的眼光看待。", example: "他的創意讓老師對他另眼相看。" , wordExp: "另眼＝另外一種眼光；相看＝看待。特別看重。",deep:"典故由來：明清小說常見的口語成語。\n字面意思：用另一種眼光看待。\n引申意思：特別看待、格外重視（如：老師對他另眼相看）。" },
  { id: "i491", grade: 5, term: "受寵若驚", zhuyin: "ㄕㄡˋ ㄔㄨㄥˇ ㄖㄨㄛˋ ㄐㄧㄥ", pinyin: "shòu chǒng ruò jīng", meaning: "受到過分的禮遇而感到不安。", example: "突然被指定領獎，他受寵若驚。" , wordExp: "受寵＝受到寵愛；若驚＝像受驚一樣。受到厚待反而不安。",deep:"典故由來：語本《老子》：「寵辱若驚……得之若驚，失之若驚。」\n字面意思：受到寵愛反而驚慌。\n引申意思：受到過分禮遇而不安（如：長官親自接見，他受寵若驚）。" },
  { id: "i492", grade: 5, term: "感激不盡", zhuyin: "ㄍㄢˇ ㄐㄧ ㄅㄨˋ ㄐㄧㄣˋ", pinyin: "gǎn jī bù jìn", meaning: "感激之情無法言盡。", example: "承蒙救命之恩，感激不盡。", syn: ["感恩戴德"] , wordExp: "感激＝感謝；不盡＝說不完。感謝之情無法道盡。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：感激之情說不完。\n引申意思：非常感謝（如：承蒙相助，感激不盡）。" },
  { id: "i493", grade: 5, term: "沒齒難忘", zhuyin: "ㄇㄛˋ ㄔˇ ㄋㄢˊ ㄨㄤˋ", pinyin: "mò chǐ nán wàng", meaning: "一輩子難以忘記。", example: "老師的恩情，學生沒齒難忘。", misuse: "「沒」在此讀ㄇㄛˋ，終盡之意。" , wordExp: "沒＝終盡；齒＝年齒（一生）；難忘＝難以忘記。一輩子忘不了。",deep:"典故由來：語本《論語．憲問》：「沒齒無怨言。」沒齒＝終身（到牙齒掉光）。\n字面意思：一輩子難以忘記。\n引申意思：終身難忘的恩情（如：救命之恩，沒齒難忘）。" },
  { id: "i494", grade: 5, term: "投桃報李", zhuyin: "ㄊㄡˊ ㄊㄠˊ ㄅㄠˋ ㄌㄧˇ", pinyin: "tóu táo bào lǐ", meaning: "互相贈答，禮尚往來。", example: "鄰居送菜來，媽媽投桃報李回贈水果。", syn: ["禮尚往來"] , wordExp: "投＝贈送；桃＝桃子；報＝回報；李＝李子。你送桃我回李，禮尚往來。",deep:"典故由來：出自《詩經．大雅．抑》：「投我以桃，報之以李。」\n字面意思：你送我桃子，我回贈李子。\n引申意思：友好往來、互相贈答（如：鄰里投桃報李，感情融洽）。" },
  { id: "i495", grade: 5, term: "慷慨解囊", zhuyin: "ㄎㄤ ㄎㄞˇ ㄐㄧㄝˇ ㄋㄤˊ", pinyin: "kāng kǎi jiě náng", meaning: "大方地拿出錢財幫助別人。", example: "校友慷慨解囊，資助清寒學生獎學金。", syn: ["樂善好施"] , wordExp: "慷慨＝大方；解囊＝解開錢袋。大方掏錢相助。",deep:"典故由來：明清文獻常見；「解囊」是解開錢袋。\n字面意思：大方地解開錢袋。\n引申意思：慷慨拿出錢財助人（如：各界慷慨解囊賑災）。褒義。" },
  { id: "i496", grade: 5, term: "拋頭露面", zhuyin: "ㄆㄠ ㄊㄡˊ ㄌㄨˋ ㄇㄧㄢˋ", pinyin: "pāo tóu lù miàn", meaning: "公開出現在眾人面前。", example: "他不愛拋頭露面，得獎也婉拒採訪。" , wordExp: "拋頭＝露出頭；露面＝現出臉。公開出現在眾人面前。",deep:"典故由來：明代小說常見；舊時婦女不宜公開露面，故有此語。\n字面意思：把頭臉暴露在人前。\n引申意思：公開出現在眾人面前（如：他不愛拋頭露面）。今為中性用語。" },
  { id: "i497", grade: 5, term: "拾金不昧", zhuyin: "ㄕˊ ㄐㄧㄣ ㄅㄨˋ ㄇㄟˋ", pinyin: "shí jīn bù mèi", meaning: "撿到財物不藏起來占為己有。", example: "他拾金不昧，把皮夾送到警察局。", misuse: "「昧」是隱藏。" , wordExp: "拾＝撿到；金＝錢財；不昧＝不隱藏。撿到財物不私吞。",deep:"典故由來：見清代筆記小說；「昧」是隱藏。\n字面意思：撿到金錢財物不藏起來。\n引申意思：撿到東西歸還失主的美德（如：小學生拾金不昧受表揚）。褒義。" },
  { id: "i498", grade: 5, term: "路不拾遺", zhuyin: "ㄌㄨˋ ㄅㄨˋ ㄕˊ ㄧˊ", pinyin: "lù bù shí yí", meaning: "社會風氣良好，掉在路上的東西沒人撿走。", example: "小鎮民風淳樸，路不拾遺。", syn: ["夜不閉戶"] , wordExp: "路＝路上；不拾遺＝沒人撿走失物。民風淳厚，失物無人侵占。",deep:"典故由來：語本《韓非子．外儲說左上》：子產治鄭、商鞅治秦，皆使「道不拾遺」。\n字面意思：路上掉的東西沒人撿走。\n引申意思：社會風氣良好、治安清明（如：路不拾遺、夜不閉戶）。褒義。" },
  { id: "i499", grade: 5, term: "井水不犯河水", zhuyin: "ㄐㄧㄥˇ ㄕㄨㄟˇ ㄅㄨˋ ㄈㄢˋ ㄏㄜˊ ㄕㄨㄟˇ", pinyin: "jǐng shuǐ bù fàn hé shuǐ", meaning: "彼此互不相干、互不侵犯。", example: "兩部門職權分明，井水不犯河水。" , wordExp: "井水、河水＝兩種水源；不犯＝互不侵犯。各管各的，互不相干。",deep:"典故由來：見《紅樓夢》：「我和他井水不犯河水，怎麼就沖了他？」\n字面意思：井水和河水互不相犯。\n引申意思：彼此互不相干、互不侵擾（如：兩部門井水不犯河水）。" },
  { id: "i500", grade: 5, term: "集腋成裘", zhuyin: "ㄐㄧˊ ㄧㄝˋ ㄔㄥˊ ㄑㄧㄡˊ", pinyin: "jí yè chéng qiú", meaning: "聚集眾多狐腋下的皮毛才能成一件裘衣，比喻積少成多。", example: "班費靠大家集腋成裘，一點一滴存下來。", misuse: "「腋」讀ㄧㄝˋ。", syn: ["聚沙成塔", "積少成多"] , wordExp: "集＝收集；腋＝狐狸腋下的毛皮；成裘＝做成皮衣。小皮聚成裘衣，積少成多。",deep:"典故由來：語本《慎子．知忠》：「狐白之裘，蓋非一狐之皮也。」狐狸腋下白毛極少，須集眾多才能成裘。\n字面意思：聚集許多狐腋皮毛做成皮衣。\n引申意思：積少成多（如：零錢捐款集腋成裘）。褒義；近義：聚沙成塔。" },
  // ---- i501-i550(國小高年級-國中) ----
  { id: "i501", grade: 6, term: "一目了然", zhuyin: "ㄧ ㄇㄨˋ ㄌㄧㄠˇ ㄖㄢˊ", pinyin: "yī mù liǎo rán", meaning: "一眼就看得清清楚楚。", example: "圖表把數據整理得一目了然。", syn: ["一清二楚"] , wordExp: "一目＝一眼；了然＝清楚明白。一眼就看清楚。",deep:"典故由來：語本朱熹《朱子語類》「一目瞭然」。\n字面意思：一眼看去就完全明白。\n引申意思：一看就懂（如：圖表讓數據一目了然）。" },
  { id: "i502", grade: 6, term: "一視同仁", zhuyin: "ㄧ ㄕˋ ㄊㄨㄥˊ ㄖㄣˊ", pinyin: "yī shì tóng rén", meaning: "平等對待，不分親疏厚薄。", example: "老師對每位學生一視同仁。", syn: ["等量齊觀"] , wordExp: "一視＝同樣看待；同仁＝同樣仁愛。不分彼此，平等對待。",deep:"典故由來：出自唐．韓愈〈原人〉：「是故聖人一視而同仁。」\n字面意思：同樣看待、一樣仁愛。\n引申意思：平等對待不分厚薄（如：老師對學生一視同仁）。褒義。" },
  { id: "i503", grade: 6, term: "有條不紊", zhuyin: "ㄧㄡˇ ㄊㄧㄠˊ ㄅㄨˋ ㄨㄣˋ", pinyin: "yǒu tiáo bù wèn", meaning: "有條理、有次序，一點不亂。", example: "她把活動流程安排得有條不紊。", misuse: "「紊」讀ㄨㄣˋ，亂之意。", syn: ["井然有序"] , wordExp: "有條＝有條理；不紊＝不紊亂。井井有條，一點不亂。",deep:"典故由來：出自《尚書．盤庚》：「若網在綱，有條而不紊。」像網目繫在總繩上，條理分明。\n字面意思：有條理而不紊亂。\n引申意思：做事井然有序（如：他有條不紊地處理事務）。褒義。" },
  { id: "i504", grade: 6, term: "不遺餘力", zhuyin: "ㄅㄨˋ ㄧˊ ㄩˊ ㄌㄧˋ", pinyin: "bù yí yú lì", meaning: "毫無保留地使出全部力量。", example: "他推廣閱讀不遺餘力。", syn: ["全力以赴", "竭盡全力"] , wordExp: "不遺＝不留下；餘力＝剩餘的力量。一點力氣都不保留。",deep:"典故由來：出自《戰國策．趙策》：「秦之攻我也，不遺餘力矣。」\n字面意思：不留下剩餘的力量。\n引申意思：毫無保留地盡力（如：不遺餘力推廣閱讀）。褒義。" },
  { id: "i505", grade: 6, term: "不勝枚舉", zhuyin: "ㄅㄨˋ ㄕㄥ ㄇㄟˊ ㄐㄩˇ", pinyin: "bù shēng méi jǔ", meaning: "數量太多，無法一一列舉。", example: "台灣的美食不勝枚舉。", misuse: "「勝」在此讀ㄕㄥ(審訂音)。", syn: ["不計其數", "多如牛毛"] , wordExp: "不勝＝承受不完；枚＝一個個；舉＝列舉。多得一個個數不完。",deep:"典故由來：清代文獻常見；「枚」是一個一個。\n字面意思：多得無法一個個舉出。\n引申意思：數量極多（如：這類例子不勝枚舉）。" },
  { id: "i506", grade: 6, term: "捲土重來", zhuyin: "ㄐㄩㄢˇ ㄊㄨˇ ㄔㄨㄥˊ ㄌㄞˊ", pinyin: "juǎn tǔ chóng lái", meaning: "失敗後重整旗鼓，再次來過。", example: "落選後他沉潛四年，捲土重來。", misuse: "出自杜牧〈題烏江亭〉。", syn: ["東山再起"] , wordExp: "捲土＝捲起塵土；重來＝再度前來。人馬奔馳捲起塵土再殺回來，失敗後重整旗鼓。",deep:"典故由來：出自唐．杜牧〈題烏江亭〉：「江東子弟多才俊，捲土重來未可知。」感嘆項羽若渡江東山再起，勝負未定。\n字面意思：人馬奔跑捲起塵土再次殺回。\n引申意思：失敗後重整旗鼓再來（如：今年落選，明年捲土重來）。" },
  { id: "i507", grade: 6, term: "不翼而飛", zhuyin: "ㄅㄨˋ ㄧˋ ㄦˊ ㄈㄟ", pinyin: "bù yì ér fēi", meaning: "沒有翅膀卻飛走了，比喻東西突然不見。", example: "桌上的錢包竟然不翼而飛。", syn: ["無影無蹤"] , wordExp: "不翼＝沒有翅膀；而飛＝卻飛走了。東西無翼卻不見了。",deep:"典故由來：語本《管子．戒》：「無翼而飛者，聲也。」後轉指東西憑空消失。\n字面意思：沒有翅膀卻飛走了。\n引申意思：東西突然不見（如：桌上的錢包不翼而飛）。" },
  { id: "i508", grade: 6, term: "不脛而走", zhuyin: "ㄅㄨˋ ㄐㄧㄥˋ ㄦˊ ㄗㄡˇ", pinyin: "bù jìng ér zǒu", meaning: "消息沒有腿卻傳得飛快。", example: "喜訊不脛而走，全村都知道了。", misuse: "「脛」是小腿。用於消息流傳，物品消失用「不翼而飛」。" , wordExp: "不脛＝沒有小腿；而走＝卻跑得快。消息沒腿卻傳千里。",deep:"典故由來：語本漢．孔融〈論盛孝章書〉：「珠玉無脛而自至者，以人好之也。」脛是小腿。\n字面意思：沒有腿卻跑得飛快。\n引申意思：消息迅速流傳（如：得獎喜訊不脛而走）。注意：東西消失用「不翼而飛」，消息傳開用「不脛而走」。" },
  { id: "i509", grade: 6, term: "水洩不通", zhuyin: "ㄕㄨㄟˇ ㄒㄧㄝˋ ㄅㄨˋ ㄊㄨㄥ", pinyin: "shuǐ xiè bù tōng", meaning: "連水都流不出去，形容擁擠或包圍嚴密。", example: "簽名會現場擠得水洩不通。", syn: ["人山人海"] , wordExp: "水洩＝水的排洩；不通＝流不出去。連水都流不出去，擠得密不透風。",deep:"典故由來：見宋．《五燈會元》：「直得水洩不通。」\n字面意思：連水都洩漏不出去。\n引申意思：極為擁擠或包圍嚴密（如：演唱會擠得水洩不通）。" },
  { id: "i510", grade: 6, term: "門庭若市", zhuyin: "ㄇㄣˊ ㄊㄧㄥˊ ㄖㄨㄛˋ ㄕˋ", pinyin: "mén tíng ruò shì", meaning: "門前熱鬧得像市場，形容來客眾多。", example: "新開的診所門庭若市。", misuse: "與「門可羅雀」相對。" , wordExp: "門庭＝門口庭院；若＝好像；市＝市場。門前熱鬧得像市集。",deep:"典故由來：出自《戰國策．齊策》鄒忌諷齊王納諫：齊威王懸賞納諫，「令初下，群臣進諫，門庭若市」。\n字面意思：門口和庭院熱鬧得像市場。\n引申意思：上門的人非常多（如：名醫診所門庭若市）。相對詞：門可羅雀。" },
  { id: "i511", grade: 6, term: "門可羅雀", zhuyin: "ㄇㄣˊ ㄎㄜˇ ㄌㄨㄛˊ ㄑㄩㄝˋ", pinyin: "mén kě luó què", meaning: "門前冷清得可以張網捕雀。", example: "連續踩雷後，這家店門可羅雀。", misuse: "與「門庭若市」相對。" , wordExp: "門＝門前；可＝可以；羅＝張網捕；雀＝麻雀。門前冷清得能張網捉鳥。",deep:"典故由來：出自《史記．汲鄭列傳》：翟公任廷尉時賓客盈門，罷官後「門外可設雀羅」——門前冷清得能張網捕雀。\n字面意思：門前可以張網捕麻雀。\n引申意思：訪客稀少、非常冷清（如：生意慘淡，門可羅雀）。相對詞：門庭若市。" },
  { id: "i512", grade: 6, term: "絡繹不絕", zhuyin: "ㄌㄨㄛˋ ㄧˋ ㄅㄨˋ ㄐㄩㄝˊ", pinyin: "luò yì bù jué", meaning: "人車連續不斷。", example: "賞櫻人潮絡繹不絕。", syn: ["川流不息"] , wordExp: "絡繹＝前後相連；不絕＝不斷。人馬車船連續不斷。",deep:"典故由來：語本《後漢書》「絡繹不絕」，形容使者車馬相連。\n字面意思：像絲線連續不斷。\n引申意思：人馬車船來往不斷（如：參觀人潮絡繹不絕）。" },
  { id: "i513", grade: 6, term: "摩肩接踵", zhuyin: "ㄇㄛˊ ㄐㄧㄢ ㄐㄧㄝ ㄓㄨㄥˇ", pinyin: "mó jiān jiē zhǒng", meaning: "肩碰肩、腳跟腳，形容人多擁擠。", example: "年貨大街上人們摩肩接踵。", misuse: "「踵」是腳跟。" , wordExp: "摩＝磨擦；肩＝肩膀；接＝碰著；踵＝腳跟。肩擦肩、腳碰腳，擁擠不堪。",deep:"典故由來：語本《戰國策．齊策》形容臨淄「車轂擊，人肩摩」——車輪相撞、人肩相擦。\n字面意思：肩擦肩、腳跟碰腳跟（踵＝腳跟）。\n引申意思：人多擁擠（如：老街上遊客摩肩接踵）。" },
  { id: "i514", grade: 6, term: "座無虛席", zhuyin: "ㄗㄨㄛˋ ㄨˊ ㄒㄩ ㄒㄧˊ", pinyin: "zuò wú xū xí", meaning: "座位全滿，沒有空位。", example: "音樂會座無虛席，一票難求。" , wordExp: "座＝座位；無＝沒有；虛＝空的；席＝席位。座位全滿。",deep:"典故由來：語本《晉書》記講學盛況「聽者填滿，座無虛席」。\n字面意思：座位沒有空著的。\n引申意思：出席者眾多（如：演講座無虛席）。" },
  { id: "i515", grade: 6, term: "高朋滿座", zhuyin: "ㄍㄠ ㄆㄥˊ ㄇㄢˇ ㄗㄨㄛˋ", pinyin: "gāo péng mǎn zuò", meaning: "賓客眾多，滿堂都是。", example: "開幕酒會高朋滿座。", syn: ["座無虛席"] , wordExp: "高朋＝尊貴的朋友；滿座＝坐滿席位。賓客滿堂。",deep:"典故由來：出自唐．王勃〈滕王閣序〉：「千里逢迎，高朋滿座。」\n字面意思：尊貴的朋友坐滿了席位。\n引申意思：賓客眾多（如：壽宴上高朋滿座）。褒義。" },
  { id: "i516", grade: 6, term: "賓至如歸", zhuyin: "ㄅㄧㄣ ㄓˋ ㄖㄨˊ ㄍㄨㄟ", pinyin: "bīn zhì rú guī", meaning: "客人來到像回到家一樣舒適。", example: "民宿主人親切，讓旅客賓至如歸。" , wordExp: "賓＝客人；至＝來到；如＝好像；歸＝回家。客人來了像回到家一樣自在。",deep:"典故由來：出自《左傳．襄公三十一年》：子產論接待諸侯，要使「賓至如歸，無寧菑患」。\n字面意思：客人來到就像回到自己家。\n引申意思：招待周到，令客人賓至如歸（如：這家旅館服務讓人賓至如歸）。褒義。" },
  { id: "i517", grade: 6, term: "無微不至", zhuyin: "ㄨˊ ㄨㄟˊ ㄅㄨˋ ㄓˋ", pinyin: "wú wéi bù zhì", meaning: "照顧得非常周到細緻。", example: "住院期間，護理師照顧得無微不至。", syn: ["體貼入微"] , wordExp: "無微＝沒有一處細微；不至＝照顧不到。連最細微處都照顧到。",deep:"典故由來：宋代文獻已見；「微」是細小之處。\n字面意思：連細微之處都照顧到，沒有不到位的。\n引申意思：照顧極為周到（如：媽媽照顧家人無微不至）。褒義。" },
  { id: "i518", grade: 6, term: "體貼入微", zhuyin: "ㄊㄧˇ ㄊㄧㄝ ㄖㄨˋ ㄨㄟˊ", pinyin: "tǐ tiē rù wéi", meaning: "關懷照顧細緻周到。", example: "他對長輩體貼入微，人人稱讚。", syn: ["無微不至"] , wordExp: "體貼＝體察關懷；入微＝深入細微。關懷體察極其細緻。",deep:"典故由來：清代小說常見的組合語。\n字面意思：體恤關懷深入到細微處。\n引申意思：關懷細緻周到（如：他對長輩體貼入微）。褒義。" },
  { id: "i519", grade: 6, term: "感同身受", zhuyin: "ㄍㄢˇ ㄊㄨㄥˊ ㄕㄣ ㄕㄡˋ", pinyin: "gǎn tóng shēn shòu", meaning: "雖未親歷，感受如同親身經歷一般。", example: "聽他描述災區見聞，大家感同身受。", misuse: "原義是代人感謝，今多指同理感受。" , wordExp: "感＝感受；同＝如同；身受＝親身承受。別人的遭遇像發生在自己身上。",deep:"典故由來：清代書信慣用語：請人幫忙時說「感同身受」——感激之情如同親身受惠。今義轉為同理感受。\n字面意思：感受如同親身經歷。\n引申意思：對他人的遭遇能深切體會（如：聽了災民的故事，大家感同身受）。" },
  { id: "i520", grade: 6, term: "設身處地", zhuyin: "ㄕㄜˋ ㄕㄣ ㄔㄨˇ ㄉㄧˋ", pinyin: "shè shēn chǔ dì", meaning: "站在別人的立場著想。", example: "設身處地想一想，你就能諒解他了。", syn: ["將心比心"] , wordExp: "設＝假設；身＝自身；處地＝處在那個境地。把自己放到對方的處境想。",deep:"典故由來：語本朱熹《中庸章句》：「體謂設以身處其地而察其心也。」\n字面意思：假設自己處在別人的位置。\n引申意思：站在他人立場著想（如：多設身處地為人想）。褒義。" },
  { id: "i521", grade: 6, term: "將心比心", zhuyin: "ㄐㄧㄤ ㄒㄧㄣ ㄅㄧˇ ㄒㄧㄣ", pinyin: "jiāng xīn bǐ xīn", meaning: "拿自己的心去體會別人的心。", example: "將心比心，別讓外送員久等。", syn: ["設身處地"] , wordExp: "將＝拿；心＝自己的心；比心＝比照別人的心。用自己的心體會別人的心。",deep:"典故由來：宋代語錄已見「將心比心」。\n字面意思：拿自己的心去比別人的心。\n引申意思：推己及人、體諒別人（如：將心比心，別為難他）。褒義。" },
  { id: "i522", grade: 6, term: "同甘共苦", zhuyin: "ㄊㄨㄥˊ ㄍㄢ ㄍㄨㄥˋ ㄎㄨˇ", pinyin: "tóng gān gòng kǔ", meaning: "一起分享快樂、分擔痛苦。", example: "創業夥伴同甘共苦十年。", syn: ["患難與共", "同舟共濟"] , wordExp: "同甘＝同享甘甜；共苦＝共嘗苦難。甘苦與共。",deep:"典故由來：語本《戰國策．燕策》：燕昭王「與百姓同其甘苦」。\n字面意思：一同嘗甘甜、共同受苦。\n引申意思：同享歡樂、共度患難（如：夫妻同甘共苦數十年）。褒義。" },
  { id: "i523", grade: 6, term: "相依為命", zhuyin: "ㄒㄧㄤ ㄧ ㄨㄟˊ ㄇㄧㄥˋ", pinyin: "xiāng yī wéi mìng", meaning: "彼此依靠著生活。", example: "祖孫倆相依為命，感情深厚。" , wordExp: "相依＝互相依靠；為命＝維持生活。彼此依靠著過日子。",deep:"典故由來：語本晉．李密〈陳情表〉：「母孫二人，更相為命。」\n字面意思：互相依靠著活命。\n引申意思：彼此依靠生活（如：祖孫倆相依為命）。" },
  { id: "i524", grade: 6, term: "形影不離", zhuyin: "ㄒㄧㄥˊ ㄧㄥˇ ㄅㄨˋ ㄌㄧˊ", pinyin: "xíng yǐng bù lí", meaning: "像身體和影子一樣分不開。", example: "這對好朋友上下學都形影不離。", syn: ["如影隨形"] , wordExp: "形＝身形；影＝影子；不離＝不分開。像身體和影子一樣總在一起。",deep:"典故由來：清代文獻常見；身體與影子不能分離。\n字面意思：像形體和影子一樣不分開。\n引申意思：關係親密、總在一起（如：這對好友形影不離）。" },
  { id: "i525", grade: 6, term: "志趣相投", zhuyin: "ㄓˋ ㄑㄩˋ ㄒㄧㄤ ㄊㄡˊ", pinyin: "zhì qù xiāng tóu", meaning: "志向興趣彼此契合。", example: "兩人志趣相投，一起組了樂團。", syn: ["志同道合", "情投意合"] , wordExp: "志趣＝志向興趣；相投＝彼此契合。志向興趣合得來。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：志向興趣互相投合。\n引申意思：彼此志同道合（如：兩人志趣相投，一見如故）。褒義。" },
  { id: "i526", grade: 7, term: "青梅竹馬", zhuyin: "ㄑㄧㄥ ㄇㄟˊ ㄓㄨˊ ㄇㄚˇ", pinyin: "qīng méi zhú mǎ", meaning: "從小一起長大的玩伴。", example: "他們是青梅竹馬，感情自然深厚。", misuse: "出自李白〈長干行〉。" , wordExp: "青梅＝青色梅子；竹馬＝竹竿當馬騎。小時一起玩梅弄馬的玩伴。",deep:"典故由來：出自唐．李白〈長干行〉：「郎騎竹馬來，遶床弄青梅。同居長干里，兩小無嫌猜。」\n字面意思：玩青梅、騎竹馬的童年玩伴。\n引申意思：自幼一起長大的親密玩伴（如：他倆是青梅竹馬）。多指男女。" },
  { id: "i527", grade: 7, term: "萍水相逢", zhuyin: "ㄆㄧㄥˊ ㄕㄨㄟˇ ㄒㄧㄤ ㄈㄥˊ", pinyin: "píng shuǐ xiāng féng", meaning: "素不相識的人偶然相遇。", example: "旅途中萍水相逢的旅伴，竟成了摯友。", misuse: "出自王勃〈滕王閣序〉。" , wordExp: "萍＝浮萍；水＝水面；相逢＝相遇。像浮萍隨水偶然相聚，陌生人偶遇。",deep:"典故由來：出自唐．王勃〈滕王閣序〉：「萍水相逢，盡是他鄉之客。」浮萍隨水漂流，偶然相聚。\n字面意思：像浮萍在水上偶然相遇。\n引申意思：素不相識的人偶然相識（如：旅途中萍水相逢的朋友）。" },
  { id: "i528", grade: 7, term: "一見如故", zhuyin: "ㄧ ㄐㄧㄢˋ ㄖㄨˊ ㄍㄨˋ", pinyin: "yī jiàn rú gù", meaning: "初次見面就像老朋友一樣投緣。", example: "兩人一見如故，聊到深夜。", syn: ["相見恨晚"] , wordExp: "一見＝初次見面；如故＝像老朋友。初見就投緣如舊識。",deep:"典故由來：語本古語「傾蓋如故」（初見即如老友）；《晉書》有「一面如舊」。\n字面意思：第一次見面就像老朋友。\n引申意思：初識即投緣（如：兩人一見如故，聊到深夜）。褒義。" },
  { id: "i529", grade: 7, term: "相見恨晚", zhuyin: "ㄒㄧㄤ ㄐㄧㄢˋ ㄏㄣˋ ㄨㄢˇ", pinyin: "xiāng jiàn hèn wǎn", meaning: "遺憾認識得太晚。", example: "談起共同嗜好，兩人大有相見恨晚之感。", syn: ["一見如故"] , wordExp: "相見＝彼此見面；恨＝遺憾；晚＝太晚。遺憾認識得太遲。",deep:"典故由來：語本《史記．平津侯主父列傳》：漢武帝召見主父偃等三人，說：「公等皆安在？何相見之晚也！」\n字面意思：遺憾彼此見面太晚。\n引申意思：投緣到可惜沒早點認識（如：談起音樂，兩人大有相見恨晚之感）。" },
  { id: "i530", grade: 7, term: "不打不相識", zhuyin: "ㄅㄨˋ ㄉㄚˇ ㄅㄨˋ ㄒㄧㄤ ㄕˋ", pinyin: "bù dǎ bù xiāng shì", meaning: "經過衝突反而彼此了解、成為朋友。", example: "球場上吵過一架，倒是不打不相識。" , wordExp: "不打＝沒有衝突過；不相識＝不會相熟。打過交道（甚至吵過）反而成了朋友。",deep:"典故由來：出自《水滸傳》：「不打不成相識。」好漢們往往先交手後結義。\n字面意思：沒有交過手就不會相識。\n引申意思：經過衝突反而成為朋友（如：他們吵過一架，不打不相識）。" },
  { id: "i531", grade: 7, term: "化干戈為玉帛", zhuyin: "ㄏㄨㄚˋ ㄍㄢ ㄍㄜ ㄨㄟˊ ㄩˋ ㄅㄛˊ", pinyin: "huà gān gē wéi yù bó", meaning: "把戰爭衝突化為和平友好。", example: "兩家公司化干戈為玉帛，攜手合作。", misuse: "干戈指兵器，玉帛指禮物。" , wordExp: "干戈＝兵器（戰爭）；玉帛＝玉器絲綢（禮物）。把戰爭化為和平友好。",deep:"典故由來：語本《淮南子．原道訓》：大禹修德，「執玉帛者萬國」——干戈是兵器，玉帛是禮物。\n字面意思：把兵器換成禮品。\n引申意思：化戰爭衝突為和平（如：兩家握手言歡，化干戈為玉帛）。褒義。" },
  { id: "i532", grade: 7, term: "握手言和", zhuyin: "ㄨㄛˋ ㄕㄡˇ ㄧㄢˊ ㄏㄜˊ", pinyin: "wò shǒu yán hé", meaning: "和解，恢復友好。", example: "兩位選手賽後握手言和。", syn: ["化干戈為玉帛"] , wordExp: "握手＝握住對方的手；言和＝說和。和解修好。",deep:"典故由來：由現代禮儀「握手」組成的常用語。\n字面意思：握手表示和好。\n引申意思：停止爭執、恢復友好（如：兩隊賽後握手言和）。" },
  { id: "i533", grade: 7, term: "冰釋前嫌", zhuyin: "ㄅㄧㄥ ㄕˋ ㄑㄧㄢˊ ㄒㄧㄢˊ", pinyin: "bīng shì qián xián", meaning: "過去的嫌隙像冰一樣融解消失。", example: "一場懇談讓兩人冰釋前嫌。" , wordExp: "冰釋＝像冰融化；前嫌＝以前的嫌隙。舊怨如冰消融。",deep:"典故由來：語本《老子》「渙兮若冰之將釋」；嫌隙如冰霜遇暖消融。\n字面意思：以前的嫌隙像冰一樣融化。\n引申意思：消除舊怨（如：一席長談後兩人冰釋前嫌）。褒義。" },
  { id: "i534", grade: 7, term: "既往不咎", zhuyin: "ㄐㄧˋ ㄨㄤˇ ㄅㄨˋ ㄐㄧㄡˋ", pinyin: "jì wǎng bù jiù", meaning: "對過去的錯誤不再追究。", example: "只要誠心改過，一律既往不咎。", misuse: "「咎」是責怪。出自《論語》。" , wordExp: "既往＝已經過去的事；不咎＝不責怪。過去的錯不再追究。",deep:"典故由來：出自《論語．八佾》：「成事不說，遂事不諫，既往不咎。」\n字面意思：已經過去的事不再責怪（咎＝責備）。\n引申意思：不追究過去的過錯（如：只要改過，既往不咎）。" },
  { id: "i535", grade: 7, term: "寬宏大量", zhuyin: "ㄎㄨㄢ ㄏㄨㄥˊ ㄉㄚˋ ㄌㄧㄤˋ", pinyin: "kuān hóng dà liàng", meaning: "度量寬大，能容人。", example: "他寬宏大量，不跟人計較小事。", syn: ["宰相肚裡能撐船"] , wordExp: "寬宏＝寬闊宏大；大量＝大度量。度量寬大能容人。",deep:"典故由來：元明戲曲常見的組合語。\n字面意思：度量寬闊宏大。\n引申意思：胸襟開闊能容人（如：他寬宏大量，不記舊怨）。褒義。" },
  { id: "i536", grade: 7, term: "斤斤計較", zhuyin: "ㄐㄧㄣ ㄐㄧㄣ ㄐㄧˋ ㄐㄧㄠˋ", pinyin: "jīn jīn jì jiào", meaning: "對細小的事過分計較。", example: "別為了一塊錢斤斤計較。", syn: ["錙銖必較"] , wordExp: "斤斤＝看得清清楚楚；計較＝計算比較。連小事都要計較。",deep:"典故由來：語本《詩經．周頌．執競》「斤斤其明」，原指明察，後轉為過分計較。\n字面意思：一斤一斤地計算比較。\n引申意思：對瑣碎小事過分計較（如：別為小錢斤斤計較）。貶義。" },
  { id: "i537", grade: 7, term: "錙銖必較", zhuyin: "ㄗ ㄓㄨ ㄅㄧˋ ㄐㄧㄠˋ", pinyin: "zī zhū bì jiào", meaning: "極小的錢財利益都要計較。", example: "他對帳目錙銖必較，一毛不差。", misuse: "「錙銖」是古代極小的重量單位。" , wordExp: "錙、銖＝古代極小的重量單位；必較＝一定計較。一分一毫都要計較。",deep:"典故由來：語本《荀子．富國》「割國之錙銖以賂之」；錙、銖是古代極小的重量單位。\n字面意思：極小的分量也要計較。\n引申意思：一絲一毫都要爭（如：他錙銖必較，一毛不拔）。貶義。" },
  { id: "i538", grade: 7, term: "唯利是圖", zhuyin: "ㄨㄟˊ ㄌㄧˋ ㄕˋ ㄊㄨˊ", pinyin: "wéi lì shì tú", meaning: "只貪求利益，別的什麼都不顧。", example: "黑心廠商唯利是圖，罔顧食安。", syn: ["見利忘義"] , wordExp: "唯＝只有；利＝利益；是圖＝去謀求。眼中只有利益。",deep:"典故由來：語本《左傳．成公十三年》：「余雖與晉出入，余唯利是視。」\n字面意思：只把利益當目標。\n引申意思：一心圖利、不顧道義（如：奸商唯利是圖）。貶義。" },
  { id: "i539", grade: 7, term: "見利忘義", zhuyin: "ㄐㄧㄢˋ ㄌㄧˋ ㄨㄤˋ ㄧˋ", pinyin: "jiàn lì wàng yì", meaning: "見到利益就忘了道義。", example: "他見利忘義，出賣了合夥人。", misuse: "與「見義勇為」相對。" , wordExp: "見利＝見到利益；忘義＝忘了道義。利字當頭忘了道義。",deep:"典故由來：出自《漢書》：評酈寄賣友，「夫賣友者，謂見利而忘義也」。\n字面意思：看見利益就忘記道義。\n引申意思：為利益背棄道義（如：見利忘義之人不可深交）。貶義。" },
  { id: "i540", grade: 7, term: "貪得無厭", zhuyin: "ㄊㄢ ㄉㄜˊ ㄨˊ ㄧㄢˋ", pinyin: "tān dé wú yàn", meaning: "貪心永遠不滿足。", example: "他貪得無厭，撈了還想再撈。", misuse: "「厭」是滿足之意。", syn: ["得寸進尺"] , wordExp: "貪＝貪求；得＝獲得；無厭＝不滿足。貪心永不滿足。",deep:"典故由來：語本《左傳．昭公二十八年》：「貪惏無饜，忿類無期。」（饜＝滿足）\n字面意思：貪心永不滿足。\n引申意思：慾望無窮（如：貪得無厭，終致身敗名裂）。貶義。" },
  { id: "i541", grade: 7, term: "得寸進尺", zhuyin: "ㄉㄜˊ ㄘㄨㄣˋ ㄐㄧㄣˋ ㄔˇ", pinyin: "dé cùn jìn chǐ", meaning: "得到一點還想要更多。", example: "一再讓步只會讓對方得寸進尺。", syn: ["貪得無厭", "得隴望蜀"] , wordExp: "得寸＝得到一寸；進尺＝又要一尺。得了還想再要。",deep:"典故由來：語本《戰國策．秦策》：范雎說秦王遠交近攻，「得寸則王之寸也，得尺亦王之尺也」，後轉義為貪求不止。\n字面意思：得到一寸又想進一尺。\n引申意思：慾望越來越大（如：對他讓步，他反而得寸進尺）。貶義。" },
  { id: "i542", grade: 7, term: "得隴望蜀", zhuyin: "ㄉㄜˊ ㄌㄨㄥˇ ㄨㄤˋ ㄕㄨˇ", pinyin: "dé lǒng wàng shǔ", meaning: "得到隴地又想取蜀地，貪心不足。", example: "簽了新約又要求加碼，未免得隴望蜀。", syn: ["得寸進尺"] , wordExp: "得隴＝取得隴地；望蜀＝又望著蜀地。得了一處還想更多。",deep:"典故由來：出自《後漢書．岑彭傳》：光武帝下令「人苦不知足，既平隴，復望蜀」——平定隴地又想攻取蜀地。\n字面意思：得到隴地又盼望蜀地。\n引申意思：貪心不足（如：加薪了還嫌少，真是得隴望蜀）。貶義。" },
  { id: "i543", grade: 7, term: "安貧樂道", zhuyin: "ㄢ ㄆㄧㄣˊ ㄌㄜˋ ㄉㄠˋ", pinyin: "ān pín lè dào", meaning: "安於清貧，樂於堅守信念道義。", example: "老教授安貧樂道，一生治學不輟。" , wordExp: "安＝安於；貧＝清貧；樂＝樂於；道＝道義。安於貧困，樂守正道。",deep:"典故由來：出自《後漢書．韋彪傳》：「安貧樂道，恬於進趣。」\n字面意思：安於貧困，樂於守道。\n引申意思：不因清貧改變信念（如：老教授安貧樂道，潛心學問）。褒義。" },
  { id: "i544", grade: 7, term: "安分守己", zhuyin: "ㄢ ㄈㄣˋ ㄕㄡˇ ㄐㄧˇ", pinyin: "ān fèn shǒu jǐ", meaning: "守本分，不做逾越的事。", example: "他一生安分守己，勤懇工作。", misuse: "「分」在此讀ㄈㄣˋ，本分。" , wordExp: "安＝安守；分＝本分；守己＝守住自己。守本分不越軌。",deep:"典故由來：宋代文獻已見的組合語。\n字面意思：安於本分，守住自己。\n引申意思：規矩老實，不做越軌之事（如：他安分守己地過日子）。褒義。" },
  { id: "i545", grade: 7, term: "循規蹈矩", zhuyin: "ㄒㄩㄣˊ ㄍㄨㄟ ㄉㄠˋ ㄐㄩˇ", pinyin: "xún guī dào jǔ", meaning: "遵守規矩，不越軌。", example: "他做事循規蹈矩，從不投機。", syn: ["安分守己"] , wordExp: "循＝遵循；規、矩＝圓規曲尺（規則）；蹈＝踩踏。一舉一動都照規矩。",deep:"典故由來：宋代語錄常見；規、矩是畫圓與方的工具。\n字面意思：依循圓規、踩著方矩。\n引申意思：守規矩不越軌（如：循規蹈矩的好學生）。今也可微帶「保守拘謹」意味。" },
  { id: "i546", grade: 7, term: "我行我素", zhuyin: "ㄨㄛˇ ㄒㄧㄥˊ ㄨㄛˇ ㄙㄨˋ", pinyin: "wǒ xíng wǒ sù", meaning: "不管別人怎麼說，仍照自己的一套行事。", example: "任憑勸告，他依然我行我素。", syn: ["一意孤行"] , wordExp: "我行＝我照自己的做；我素＝我平素的樣子。不理會別人，照舊行事。",deep:"典故由來：語本《禮記．中庸》「君子素其位而行」，清《官場現形記》轉為今義。\n字面意思：我照我平素的樣子行事。\n引申意思：不理會別人的意見，依然故我（如：屢勸不聽，我行我素）。貶義。" },
  { id: "i547", grade: 7, term: "一意孤行", zhuyin: "ㄧ ㄧˋ ㄍㄨ ㄒㄧㄥˊ", pinyin: "yī yì gū xíng", meaning: "不聽勸告，固執地照自己的意思行事。", example: "他一意孤行，結果賠上全部積蓄。", syn: ["剛愎自用", "我行我素"] , wordExp: "一意＝一個念頭；孤行＝獨自行事。不聽勸告，固執己見。",deep:"典故由來：出自《史記．酷吏列傳》：趙禹「孤立行一意而已」——謝絕賓客，獨行己意。\n字面意思：固執地按自己一個念頭行事。\n引申意思：不聽勸告獨斷行事（如：他一意孤行，終致失敗）。貶義。" },
  { id: "i548", grade: 7, term: "獨斷獨行", zhuyin: "ㄉㄨˊ ㄉㄨㄢˋ ㄉㄨˊ ㄒㄧㄥˊ", pinyin: "dú duàn dú xíng", meaning: "獨自決斷行事，不採納他人意見。", example: "主管獨斷獨行，團隊士氣低落。", syn: ["一意孤行"] , wordExp: "獨斷＝獨自決斷；獨行＝獨自施行。不採納他人意見。",deep:"典故由來：清代文獻常見的組合語。\n字面意思：獨自決斷、獨自行動。\n引申意思：不採納他人意見（如：主管獨斷獨行，團隊離心）。貶義。" },
  { id: "i549", grade: 7, term: "當機立斷", zhuyin: "ㄉㄤ ㄐㄧ ㄌㄧˋ ㄉㄨㄢˋ", pinyin: "dāng jī lì duàn", meaning: "抓住時機，立刻決斷。", example: "隊長當機立斷喊出暫停，穩住局面。", syn: ["雷厲風行"] , wordExp: "當機＝面對時機；立斷＝立刻決斷。抓住時機馬上決定。",deep:"典故由來：語本「應機立斷」（漢陳琳文），後作「當機立斷」。\n字面意思：面對時機立刻決斷。\n引申意思：關鍵時刻果斷決定（如：指揮官當機立斷下令撤離）。褒義。" },
  { id: "i550", grade: 7, term: "猶豫不決", zhuyin: "ㄧㄡˊ ㄩˋ ㄅㄨˋ ㄐㄩㄝˊ", pinyin: "yóu yù bù jué", meaning: "拿不定主意，遲遲無法決定。", example: "他猶豫不決，錯過了報名期限。", syn: ["舉棋不定", "優柔寡斷"] , wordExp: "猶豫＝遲疑；不決＝不能決定。拿不定主意。",deep:"典故由來：語本《戰國策．趙策》：「平原君猶豫未有所決。」\n字面意思：遲疑而不能決定。\n引申意思：拿不定主意（如：面對選擇猶豫不決）。貶義。" },
  // ---- i551-i600(國中) ----
  { id: "i551", grade: 7, term: "舉棋不定", zhuyin: "ㄐㄩˇ ㄑㄧˊ ㄅㄨˋ ㄉㄧㄥˋ", pinyin: "jǔ qí bù dìng", meaning: "拿著棋子不知下哪一步，比喻遲疑難決。", example: "選組的事他舉棋不定，問了好多人。", syn: ["猶豫不決"] , wordExp: "舉棋＝拿起棋子；不定＝下不了。棋子懸著不知落哪，遲疑難決。",deep:"典故由來：出自《左傳．襄公二十五年》：「弈者舉棋不定，不勝其耦。」下棋的人拿著棋子定不了往哪下，就贏不了對手。\n字面意思：拿著棋子決定不了下在哪裡。\n引申意思：臨事遲疑不決（如：換不換工作，他舉棋不定）。貶義。" },
  { id: "i552", grade: 7, term: "優柔寡斷", zhuyin: "ㄧㄡ ㄖㄡˊ ㄍㄨㄚˇ ㄉㄨㄢˋ", pinyin: "yōu róu guǎ duàn", meaning: "做事遲疑，缺乏決斷力。", example: "他優柔寡斷，機會一再流失。", syn: ["猶豫不決"] , wordExp: "優柔＝猶豫柔弱；寡＝缺少；斷＝決斷。遇事拖延，缺乏果斷。",deep:"典故由來：語本《韓非子．亡徵》：「緩心而無成，柔茹而寡斷……亡國之風也。」\n字面意思：過分柔和，缺少決斷。\n引申意思：遇事遲疑不果斷（如：優柔寡斷，錯失良機）。貶義。" },
  { id: "i553", grade: 7, term: "深思熟慮", zhuyin: "ㄕㄣ ㄙ ㄕㄡˊ ㄌㄩˋ", pinyin: "shēn sī shóu lǜ", meaning: "深入而周密地思考。", example: "這是深思熟慮後的決定，不是衝動。", syn: ["三思而行"] , wordExp: "深思＝深入思考；熟慮＝周密考慮。想得深、想得透。",deep:"典故由來：宋代文獻已見的組合語。\n字面意思：深入思考、成熟考慮。\n引申意思：周密思考後才行動（如：經過深思熟慮才決定）。褒義。" },
  { id: "i554", grade: 7, term: "深謀遠慮", zhuyin: "ㄕㄣ ㄇㄡˊ ㄩㄢˇ ㄌㄩˋ", pinyin: "shēn móu yuǎn lǜ", meaning: "計畫周密，考慮長遠。", example: "創辦人深謀遠慮，早已布局海外。", syn: ["高瞻遠矚"] , wordExp: "深謀＝深遠的謀劃；遠慮＝長遠的考量。計畫周密長遠。",deep:"典故由來：出自漢．賈誼〈過秦論〉：「深謀遠慮，行軍用兵之道，非及曩時之士也。」\n字面意思：謀劃深遠、考慮長久。\n引申意思：計畫周密、眼光長遠（如：領導者要深謀遠慮）。褒義。" },
  { id: "i555", grade: 7, term: "急中生智", zhuyin: "ㄐㄧˊ ㄓㄨㄥ ㄕㄥ ㄓˋ", pinyin: "jí zhōng shēng zhì", meaning: "危急時突然想出應付的辦法。", example: "他急中生智，用外套撲滅了小火。", syn: ["隨機應變"] , wordExp: "急中＝危急之中；生智＝生出智謀。情急之下想出好辦法。",deep:"典故由來：清代小說常見的組合語。\n字面意思：危急之中生出智謀。\n引申意思：緊急關頭想出好辦法（如：他急中生智，用外套滅了火）。褒義。" },
  { id: "i556", grade: 7, term: "隨機應變", zhuyin: "ㄙㄨㄟˊ ㄐㄧ ㄧㄥˋ ㄅㄧㄢˋ", pinyin: "suí jī yìng biàn", meaning: "依情況變化靈活應對。", example: "導遊隨機應變，把取消的行程換成驚喜。", syn: ["見機行事"] , wordExp: "隨機＝順著時機；應變＝應付變化。視情況靈活應對。",deep:"典故由來：語本《舊唐書》「隨機應變」。\n字面意思：跟隨時機變化而應對。\n引申意思：靈活應付情勢變化（如：臨場要能隨機應變）。褒義。" },
  { id: "i557", grade: 7, term: "臨渴掘井", zhuyin: "ㄌㄧㄣˊ ㄎㄜˇ ㄐㄩㄝˊ ㄐㄧㄥˇ", pinyin: "lín kě jué jǐng", meaning: "事到臨頭才想辦法，為時已晚。", example: "考前一晚才翻書，無異臨渴掘井。", syn: ["臨時抱佛腳"] , wordExp: "臨渴＝到了口渴；掘井＝才挖井。事到臨頭才想辦法。",deep:"典故由來：語本《晏子春秋》：「譬之猶臨難而遽鑄兵，臨噎而遽掘井。」\n字面意思：口渴了才去挖井。\n引申意思：事到臨頭才想辦法，來不及了（如：考前一晚才讀書，無異臨渴掘井）。貶義；相對詞：未雨綢繆。" },
  { id: "i558", grade: 7, term: "防患未然", zhuyin: "ㄈㄤˊ ㄏㄨㄢˋ ㄨㄟˋ ㄖㄢˊ", pinyin: "fáng huàn wèi rán", meaning: "在禍患發生前先加以防備。", example: "定期檢查電線，防患未然。", syn: ["未雨綢繆", "曲突徙薪"] , wordExp: "防＝防備；患＝禍患；未然＝尚未發生。禍患未發先防範。",deep:"典故由來：語本《易經．既濟》：「君子以思患而豫防之。」\n字面意思：在禍患還沒發生時就防備。\n引申意思：事先防範（如：定期檢修，防患未然）。褒義。" },
  { id: "i559", grade: 7, term: "亡命之徒", zhuyin: "ㄨㄤˊ ㄇㄧㄥˋ ㄓ ㄊㄨˊ", pinyin: "wáng mìng zhī tú", meaning: "不顧性命作惡的人。", example: "警方圍捕這夥亡命之徒。" , wordExp: "亡命＝不要命；之徒＝的人。不顧性命作惡的人。",deep:"典故由來：「亡命」出自《史記》：逃亡而除去名籍，稱亡命。\n字面意思：不要性命（逃亡）的人。\n引申意思：不顧性命作惡的人（如：一夥亡命之徒）。貶義。" },
  { id: "i560", grade: 7, term: "無惡不作", zhuyin: "ㄨˊ ㄜˋ ㄅㄨˋ ㄗㄨㄛˋ", pinyin: "wú è bù zuò", meaning: "什麼壞事都做得出來。", example: "這個集團無惡不作，終於被繩之以法。", syn: ["作惡多端"] , wordExp: "無惡＝沒有壞事；不作＝不去做。什麼壞事都做。",deep:"典故由來：清代小說常見的組合語。\n字面意思：沒有一件壞事不做。\n引申意思：壞事做盡（如：惡霸無惡不作）。貶義。" },
  { id: "i561", grade: 7, term: "為非作歹", zhuyin: "ㄨㄟˊ ㄈㄟ ㄗㄨㄛˋ ㄉㄞˇ", pinyin: "wéi fēi zuò dǎi", meaning: "做各種壞事。", example: "仗著人多就為非作歹，遲早受法律制裁。", syn: ["無惡不作"] , wordExp: "為＝做；非＝不對的事；作＝幹；歹＝壞事。做盡壞事。",deep:"典故由來：元代戲曲常見的口語成語。\n字面意思：做不對的事、幹壞事。\n引申意思：為非作歹指做各種壞事（如：豈容歹徒為非作歹）。貶義。" },
  { id: "i562", grade: 7, term: "繩之以法", zhuyin: "ㄕㄥˊ ㄓ ㄧˇ ㄈㄚˇ", pinyin: "shéng zhī yǐ fǎ", meaning: "依法律制裁。", example: "詐騙集團全數被繩之以法。" , wordExp: "繩＝約束制裁；之＝他；以法＝用法律。依法律制裁。",deep:"典故由來：「繩」本指木匠彈線的墨繩，引申為糾正、制裁；漢代文獻已見「繩之以法」。\n字面意思：用法律的準繩來糾正制裁。\n引申意思：依法懲處（如：犯罪者必繩之以法）。" },
  { id: "i563", grade: 7, term: "天網恢恢", zhuyin: "ㄊㄧㄢ ㄨㄤˇ ㄏㄨㄟ ㄏㄨㄟ", pinyin: "tiān wǎng huī huī", meaning: "天道如大網，作惡者終難逃脫。", example: "天網恢恢，疏而不漏，逃亡十年仍被逮。", misuse: "出自《老子》。" , wordExp: "天網＝上天的法網；恢恢＝廣大的樣子。天道之網廣大，疏而不漏。",deep:"典故由來：出自《老子》：「天網恢恢，疏而不失。」\n字面意思：天道像廣大的網，網目雖疏卻不會漏失。\n引申意思：作惡者終究逃不過制裁（常說「天網恢恢，疏而不漏」）。" },
  { id: "i564", grade: 7, term: "水到渠成", zhuyin: "ㄕㄨㄟˇ ㄉㄠˋ ㄑㄩˊ ㄔㄥˊ", pinyin: "shuǐ dào qú chéng", meaning: "條件成熟，事情自然成功。", example: "基本功練足了，升段自然水到渠成。", syn: ["瓜熟蒂落"] , wordExp: "水到＝水流到；渠成＝溝渠自然形成。條件成熟，事情自然成功。",deep:"典故由來：出自宋．蘇軾〈答秦太虛書〉：「至時別作經畫，水到渠成，不須預慮。」\n字面意思：水流到之處自然形成溝渠。\n引申意思：條件成熟，事情自然成功（如：實力夠了，錄取便水到渠成）。" },
  { id: "i565", grade: 7, term: "順水推舟", zhuyin: "ㄕㄨㄣˋ ㄕㄨㄟˇ ㄊㄨㄟ ㄓㄡ", pinyin: "shùn shuǐ tuī zhōu", meaning: "順著情勢說話行事。", example: "大家都贊成，他便順水推舟答應了。", syn: ["因勢利導"] , wordExp: "順水＝順著水流；推舟＝推船。順著情勢辦事，毫不費力。",deep:"典故由來：元代戲曲常見的口語成語。\n字面意思：順著水流推船。\n引申意思：順著情勢或別人的話行事（如：他順水推舟答應了）。" },
  { id: "i566", grade: 7, term: "如虎添翼", zhuyin: "ㄖㄨˊ ㄏㄨˇ ㄊㄧㄢ ㄧˋ", pinyin: "rú hǔ tiān yì", meaning: "強者又增添了助力。", example: "王牌投手歸隊，球隊如虎添翼。", syn: ["錦上添花"] , wordExp: "如＝好像；虎＝老虎；添翼＝加上翅膀。強者再添助力。",deep:"典故由來：語本《韓非子．難勢》：「毋為虎傅翼，將飛入邑，擇人而食之。」（傅＝添加）\n字面意思：像老虎添了翅膀。\n引申意思：強者又得助力，更加厲害（如：新外援加盟，球隊如虎添翼）。" },
  { id: "i567", grade: 7, term: "如日中天", zhuyin: "ㄖㄨˊ ㄖˋ ㄓㄨㄥ ㄊㄧㄢ", pinyin: "rú rì zhōng tiān", meaning: "像正午的太陽，事業聲望正盛。", example: "樂團聲勢如日中天，巡演場場完售。" , wordExp: "如日＝像太陽；中天＝正在天頂。聲勢正旺，如日正當中。",deep:"典故由來：語本《詩經．邶風．簡兮》「日之方中」。\n字面意思：像太陽正在天空正中。\n引申意思：事業聲望正達頂峰（如：他的演藝事業如日中天）。褒義。" },
  { id: "i568", grade: 7, term: "如釋重負", zhuyin: "ㄖㄨˊ ㄕˋ ㄓㄨㄥˋ ㄈㄨˋ", pinyin: "rú shì zhòng fù", meaning: "像放下重擔一樣輕鬆。", example: "交出報告的那一刻，他如釋重負。" , wordExp: "如釋＝像放下；重負＝沉重的擔子。放下重擔般輕鬆。",deep:"典故由來：出自《穀梁傳．昭公二十九年》：「昭公出奔，民如釋重負。」\n字面意思：像放下沉重的擔子。\n引申意思：緊張或負擔解除後的輕鬆（如：考完試如釋重負）。" },
  { id: "i569", grade: 7, term: "如坐針氈", zhuyin: "ㄖㄨˊ ㄗㄨㄛˋ ㄓㄣ ㄓㄢ", pinyin: "rú zuò zhēn zhān", meaning: "像坐在插針的毯子上，心神不寧。", example: "等待放榜的他如坐針氈。", misuse: "「氈」讀ㄓㄢ。", syn: ["坐立不安"] , wordExp: "如坐＝像坐在；針氈＝插著針的毛毯。坐立難安。",deep:"典故由來：出自《晉書．杜錫傳》：杜錫常勸諫愍懷太子，太子懷恨，命人在他坐的氈墊中插針，刺得他坐立難安。\n字面意思：像坐在插滿針的氈墊上。\n引申意思：心神不寧、坐立難安（如：等待結果時如坐針氈）。" },
  { id: "i570", grade: 7, term: "如履薄冰", zhuyin: "ㄖㄨˊ ㄌㄩˇ ㄅㄛˊ ㄅㄧㄥ", pinyin: "rú lǚ bó bīng", meaning: "像走在薄冰上，戒慎恐懼。", example: "接手大案子，他如履薄冰，步步謹慎。", misuse: "「履」是踩踏。出自《詩經》。", syn: ["戰戰兢兢"] , wordExp: "如履＝像踩在；薄冰＝薄薄的冰層。戒慎恐懼，步步小心。",deep:"典故由來：出自《詩經．小雅．小旻》：「戰戰兢兢，如臨深淵，如履薄冰。」\n字面意思：像踩在薄冰上（履＝踩）。\n引申意思：戒慎恐懼、小心翼翼（如：處理危機如履薄冰）。" },
  { id: "i571", grade: 7, term: "戰戰兢兢", zhuyin: "ㄓㄢˋ ㄓㄢˋ ㄐㄧㄥ ㄐㄧㄥ", pinyin: "zhàn zhàn jīng jīng", meaning: "戒慎恐懼、小心謹慎的樣子。", example: "新人戰戰兢兢，不敢出半點差錯。", syn: ["如履薄冰"] , wordExp: "戰戰＝發抖的樣子；兢兢＝小心謹慎。既害怕又謹慎。",deep:"典故由來：出自《詩經．小雅．小旻》：「戰戰兢兢，如臨深淵，如履薄冰。」\n字面意思：害怕發抖、小心謹慎的樣子。\n引申意思：戒慎恐懼（如：新手戰戰兢兢地上路）。" },
  { id: "i572", grade: 8, term: "千頭萬緒", zhuyin: "ㄑㄧㄢ ㄊㄡˊ ㄨㄢˋ ㄒㄩˋ", pinyin: "qiān tóu wàn xù", meaning: "事情繁多，頭緒紛亂。", example: "搬家事務千頭萬緒，得列清單處理。", syn: ["百廢待舉"],deep:"典故由來：語本三國魏文獻「千端萬緒」，後作「千頭萬緒」。\n字面意思：一千個頭、一萬條線緒。\n引申意思：事情繁雜、頭緒紛亂（如：開學事務千頭萬緒）。" },
  { id: "i573", grade: 8, term: "百廢待舉", zhuyin: "ㄅㄞˇ ㄈㄟˋ ㄉㄞˋ ㄐㄩˇ", pinyin: "bǎi fèi dài jǔ", meaning: "許多荒廢的事務等著興辦。", example: "災後百廢待舉，重建工作千頭萬緒。",deep:"典故由來：語本宋．范仲淹〈岳陽樓記〉「百廢具興」。\n字面意思：許多荒廢的事等待興辦。\n引申意思：大量事務亟待重建處理（如：戰後百廢待舉）。" },
  { id: "i574", grade: 8, term: "井井有條", zhuyin: "ㄐㄧㄥˇ ㄐㄧㄥˇ ㄧㄡˇ ㄊㄧㄠˊ", pinyin: "jǐng jǐng yǒu tiáo", meaning: "條理分明，整齊不亂。", example: "倉庫被他管理得井井有條。", syn: ["井然有序", "有條不紊"],deep:"典故由來：出自《荀子．儒效》：「井井兮其有理也。」井田阡陌方正有序。\n字面意思：像井字一樣方正有條理。\n引申意思：整齊有序（如：他把倉庫管理得井井有條）。褒義。" },
  { id: "i575", grade: 8, term: "有聲有色", zhuyin: "ㄧㄡˇ ㄕㄥ ㄧㄡˇ ㄙㄜˋ", pinyin: "yǒu shēng yǒu sè", meaning: "表現精彩生動。", example: "社團被他經營得有聲有色。", syn: ["繪聲繪影"],deep:"典故由來：清代文評用語。\n字面意思：有聲音、有色彩。\n引申意思：表現得精彩生動（如：活動辦得有聲有色）。褒義。" },
  { id: "i576", grade: 8, term: "繪聲繪影", zhuyin: "ㄏㄨㄟˋ ㄕㄥ ㄏㄨㄟˋ ㄧㄥˇ", pinyin: "huì shēng huì yǐng", meaning: "描述得生動逼真，也指傳言活靈活現。", example: "目擊者繪聲繪影地描述當時情景。", misuse: "用於傳聞時常含不盡可信的意味。",deep:"典故由來：清代文獻常見。\n字面意思：把聲音和影像都描繪出來。\n引申意思：描述生動逼真；也指謠言講得像真的（如：他繪聲繪影地轉述現場）。" },
  { id: "i577", grade: 8, term: "活靈活現", zhuyin: "ㄏㄨㄛˊ ㄌㄧㄥˊ ㄏㄨㄛˊ ㄒㄧㄢˋ", pinyin: "huó líng huó xiàn", meaning: "生動逼真，彷彿就在眼前。", example: "說書人把武松打虎講得活靈活現。", syn: ["栩栩如生"],deep:"典故由來：明代小說評點用語。\n字面意思：活生生地靈動顯現。\n引申意思：描寫或模仿逼真傳神（如：把人物演得活靈活現）。褒義。" },
  { id: "i578", grade: 8, term: "維妙維肖", zhuyin: "ㄨㄟˊ ㄇㄧㄠˋ ㄨㄟˊ ㄒㄧㄠˋ", pinyin: "wéi miào wéi xiào", meaning: "模仿或描繪得精妙逼真。", example: "他模仿老師的語氣維妙維肖。", misuse: "「肖」讀ㄒㄧㄠˋ，相似。",deep:"典故由來：清代文評用語；「維」是語助詞，「肖」是相似。\n字面意思：精妙又相似。\n引申意思：模仿逼真（如：口技維妙維肖）。褒義；「肖」不寫作「俏」。" },
  { id: "i579", grade: 8, term: "躍然紙上", zhuyin: "ㄩㄝˋ ㄖㄢˊ ㄓˇ ㄕㄤˋ", pinyin: "yuè rán zhǐ shàng", meaning: "描寫生動，彷彿從紙上活了起來。", example: "人物性格在他筆下躍然紙上。",deep:"典故由來：出自清．薛雪《一瓢詩話》：「如生龍活虎，躍然紙上。」\n字面意思：好像跳動在紙面上。\n引申意思：描寫生動傳神（如：人物形象躍然紙上）。褒義。" },
  { id: "i580", grade: 8, term: "入木三分", zhuyin: "ㄖㄨˋ ㄇㄨˋ ㄙㄢ ㄈㄣ", pinyin: "rù mù sān fēn", meaning: "筆力遒勁；後喻見解描寫深刻。", example: "這篇評論對人性刻畫入木三分。", misuse: "王羲之筆力透入木板的典故。",deep:"典故由來：出自唐．張懷瓘《書斷》：王羲之寫祝版，工人削字，「筆入木三分」。\n字面意思：筆力滲入木板三分深。\n引申意思：本形容書法筆力遒勁，今多指見解、刻畫深刻（如：他把角色演得入木三分）。褒義。" },
  { id: "i581", grade: 8, term: "力透紙背", zhuyin: "ㄌㄧˋ ㄊㄡˋ ㄓˇ ㄅㄟˋ", pinyin: "lì tòu zhǐ bèi", meaning: "筆力強勁；文辭深刻有力。", example: "他的書法蒼勁，力透紙背。", syn: ["入木三分"],deep:"典故由來：語本唐．顏真卿〈述張長史筆法十二意〉：用筆「常欲使其透過紙背」。\n字面意思：筆力穿透到紙的背面。\n引申意思：書法遒勁；文辭深刻有力（如：這篇批判力透紙背）。褒義。" },
  { id: "i582", grade: 8, term: "行雲流水", zhuyin: "ㄒㄧㄥˊ ㄩㄣˊ ㄌㄧㄡˊ ㄕㄨㄟˇ", pinyin: "xíng yún liú shuǐ", meaning: "自然流暢，毫不做作。", example: "這篇散文如行雲流水，一氣呵成。", syn: ["一氣呵成"],deep:"典故由來：出自宋．蘇軾〈答謝民師書〉：好文章「大略如行雲流水，初無定質，但常行於所當行，常止於不可不止」。\n字面意思：像飄動的雲、流動的水。\n引申意思：文章、動作自然流暢（如：文筆如行雲流水）。褒義。" },
  { id: "i583", grade: 8, term: "一氣呵成", zhuyin: "ㄧ ㄑㄧˋ ㄏㄜ ㄔㄥˊ", pinyin: "yī qì hē chéng", meaning: "一口氣完成，流暢不間斷。", example: "靈感一來，他一氣呵成寫完整首曲子。", syn: ["行雲流水"],deep:"典故由來：出自明．胡應麟《詩藪》：評杜詩「若百川東注，一氣呵成」。\n字面意思：一口氣完成。\n引申意思：過程流暢不間斷（如：這幅字一氣呵成）。褒義。" },
  { id: "i584", grade: 8, term: "字字珠璣", zhuyin: "ㄗˋ ㄗˋ ㄓㄨ ㄐㄧ", pinyin: "zì zì zhū jī", meaning: "每個字都像珍珠美玉，文辭精妙。", example: "這封家書字字珠璣，感人至深。", misuse: "「璣」是不圓的珠子。",deep:"典故由來：清代文評用語；珠璣是珍珠美玉。\n字面意思：每個字都像珍珠寶玉。\n引申意思：文辭精妙（如：這篇短文字字珠璣）。褒義。" },
  { id: "i585", grade: 8, term: "妙筆生花", zhuyin: "ㄇㄧㄠˋ ㄅㄧˇ ㄕㄥ ㄏㄨㄚ", pinyin: "miào bǐ shēng huā", meaning: "文筆高妙，文章寫得極好。", example: "她妙筆生花，平凡題材也寫得動人。", misuse: "李白夢筆頭生花的典故。",deep:"典故由來：出自《開元天寶遺事》：李白少年夢見筆頭生花，從此才思橫溢、名聞天下。\n字面意思：奇妙的筆開出花來。\n引申意思：文筆極佳（如：她妙筆生花，把小城寫活了）。褒義。" },
  { id: "i586", grade: 8, term: "神來之筆", zhuyin: "ㄕㄣˊ ㄌㄞˊ ㄓ ㄅㄧˇ", pinyin: "shén lái zhī bǐ", meaning: "創作中靈感突現的精彩之處。", example: "結尾的轉折是全劇的神來之筆。",deep:"典故由來：清代文評用語；如有神助的一筆。\n字面意思：像神靈降臨揮出的一筆。\n引申意思：創作中靈感突現的精彩之處（如：結尾堪稱神來之筆）。褒義。" },
  { id: "i587", grade: 8, term: "錦心繡口", zhuyin: "ㄐㄧㄣˇ ㄒㄧㄣ ㄒㄧㄡˋ ㄎㄡˇ", pinyin: "jǐn xīn xiù kǒu", meaning: "文思優美，談吐出眾。", example: "主持人錦心繡口，串場妙語如珠。", syn: ["妙語如珠"],deep:"典故由來：出自唐．柳宗元〈乞巧文〉：「駢四儷六，錦心繡口。」\n字面意思：錦緞般的心思、刺繡般的口才。\n引申意思：文思優美、談吐華美（如：才女錦心繡口）。褒義。" },
  { id: "i588", grade: 8, term: "妙語如珠", zhuyin: "ㄇㄧㄠˋ ㄩˇ ㄖㄨˊ ㄓㄨ", pinyin: "miào yǔ rú zhū", meaning: "精妙的話語一句接一句。", example: "他致詞妙語如珠，全場笑聲不斷。",deep:"典故由來：由字面組合而成的常用語。\n字面意思：精妙話語像成串珍珠。\n引申意思：言談風趣精彩、妙語連連（如：主持人妙語如珠）。褒義。" },
  { id: "i589", grade: 8, term: "出口成章", zhuyin: "ㄔㄨ ㄎㄡˇ ㄔㄥˊ ㄓㄤ", pinyin: "chū kǒu chéng zhāng", meaning: "一開口就是好文章，才思敏捷。", example: "他飽讀詩書，出口成章。", syn: ["下筆成章"],deep:"典故由來：語本《詩經．小雅．都人士》：「彼都人士，出言有章。」\n字面意思：一開口就成文章。\n引申意思：才思敏捷、口才極好（如：他出口成章，即席演講毫不費力）。褒義。" },
  { id: "i590", grade: 8, term: "引經據典", zhuyin: "ㄧㄣˇ ㄐㄧㄥ ㄐㄩˋ ㄉㄧㄢˇ", pinyin: "yǐn jīng jù diǎn", meaning: "引用經書典籍作為根據。", example: "他辯論時引經據典，很有說服力。", syn: ["旁徵博引"],deep:"典故由來：語本《後漢書》臣子上書「引據大義」的傳統。\n字面意思：引用經書、依據典籍。\n引申意思：說話為文引用經典佐證（如：他講課引經據典）。褒義；濫用則顯掉書袋。" },
  { id: "i591", grade: 8, term: "旁徵博引", zhuyin: "ㄆㄤˊ ㄓㄥ ㄅㄛˊ ㄧㄣˇ", pinyin: "páng zhēng bó yǐn", meaning: "廣泛地引用各種資料佐證。", example: "這篇論文旁徵博引，論證扎實。", syn: ["引經據典"],deep:"典故由來：清代文評用語。\n字面意思：從旁徵集、廣博引用。\n引申意思：廣泛引用各種資料佐證（如：論文旁徵博引）。褒義。" },
  { id: "i592", grade: 8, term: "斷章取義", zhuyin: "ㄉㄨㄢˋ ㄓㄤ ㄑㄩˇ ㄧˋ", pinyin: "duàn zhāng qǔ yì", meaning: "截取片段文字，曲解原意。", example: "報導斷章取義，扭曲了他的發言。", misuse: "與「望文生義」不同：前者截取，後者憑字面猜。",deep:"典故由來：出自《左傳．襄公二十八年》：「賦詩斷章，余取所求焉。」春秋時外交賦詩，常只取詩中片段表意。\n字面意思：截斷文章、只取一段。\n引申意思：截取片段、曲解原意（如：媒體斷章取義扭曲了他的發言）。貶義。" },
  { id: "i593", grade: 8, term: "望文生義", zhuyin: "ㄨㄤˋ ㄨㄣˊ ㄕㄥ ㄧˋ", pinyin: "wàng wén shēng yì", meaning: "只就字面猜測意思，不求正解。", example: "「差強人意」常被望文生義誤解成不滿意。",deep:"典故由來：清代學者批評不求甚解的讀書法。\n字面意思：只看字面就產生解釋。\n引申意思：不求正解、望著字面猜意思（如：「差強人意」常被望文生義誤解）。貶義。" },
  { id: "i594", grade: 8, term: "咬文嚼字", zhuyin: "ㄧㄠˇ ㄨㄣˊ ㄐㄧㄠˊ ㄗˋ", pinyin: "yǎo wén jiáo zì", meaning: "過分斟酌字句；也指賣弄學問。", example: "寫作要自然，別一味咬文嚼字。",deep:"典故由來：出自元．喬吉散曲：以「咬文嚼字」形容雕琢文字。\n字面意思：把文字咬住細嚼。\n引申意思：過分斟酌字句、賣弄學問（如：別咬文嚼字，說重點）。多含貶義；也可指認真推敲（中性）。" },
  { id: "i595", grade: 8, term: "現身說法", zhuyin: "ㄒㄧㄢˋ ㄕㄣ ㄕㄨㄛ ㄈㄚˇ", pinyin: "xiàn shēn shuō fǎ", meaning: "以親身經歷為例來說明或勸導。", example: "更生人現身說法，勸學子遠離毒品。",deep:"典故由來：佛家語：觀音菩薩應眾生因緣「現身說法」（《楞嚴經》）。\n字面意思：現出身形來說佛法。\n引申意思：以親身經歷為例勸導說明（如：戒毒過來人現身說法）。" },
  { id: "i596", grade: 8, term: "班門弄斧", zhuyin: "ㄅㄢ ㄇㄣˊ ㄋㄨㄥˋ ㄈㄨˇ", pinyin: "bān mén nòng fǔ", meaning: "在行家面前賣弄本領，不自量力。", example: "在國手面前談球技，豈非班門弄斧。", misuse: "魯班是巧匠，故曰班門。多作自謙。",deep:"典故由來：出自明．梅之渙〈題李白墓〉：「魯班門前弄大斧。」魯班是巧匠祖師。\n字面意思：在魯班門前耍弄斧頭。\n引申意思：在行家面前賣弄本領（如：在教授面前談這理論，實在班門弄斧）。貶義，也常用作自謙。" },
  { id: "i597", grade: 8, term: "獻曝之忱", zhuyin: "ㄒㄧㄢˋ ㄆㄨˋ ㄓ ㄔㄣˊ", pinyin: "xiàn pù zhī chén", meaning: "自謙所獻微薄但出於誠心。", example: "小小建議，聊表獻曝之忱。", misuse: "「曝」讀ㄆㄨˋ，農夫獻曬太陽之暖的典故。",deep:"典故由來：出自《列子．楊朱》：宋國農夫冬天曬太陽取暖，以為天下無此享受，想把「曬太陽」獻給國君。\n字面意思：獻上曬太陽的誠意。\n引申意思：自謙所獻微薄但出於真心（如：小小建議，聊表獻曝之忱）。謙詞。" },
  { id: "i598", grade: 8, term: "野人獻曝 ", zhuyin: "ㄧㄝˇ ㄖㄣˊ ㄒㄧㄢˋ ㄆㄨˋ", pinyin: "yě rén xiàn pù", meaning: "自謙見識淺陋而誠心貢獻。", example: "這點心得是野人獻曝，供大家參考。", syn: ["獻曝之忱"],deep:"典故由來：出自《列子．楊朱》：同「獻曝」故事——鄉野之人要把負日之暄獻給君王。\n字面意思：鄉野之人獻上曬太陽的方法。\n引申意思：自謙見識淺陋而誠心建言（如：野人獻曝，僅供參考）。謙詞。" },
  { id: "i599", grade: 8, term: "受益匪淺", zhuyin: "ㄕㄡˋ ㄧˋ ㄈㄟˇ ㄑㄧㄢˇ", pinyin: "shòu yì fěi qiǎn", meaning: "得到很大的益處。", example: "聽完講座，大家受益匪淺。", misuse: "「匪」通「非」，不是之意。",deep:"典故由來：由字面組合而成；「匪」通「非」。\n字面意思：得到的好處不淺。\n引申意思：收穫很大（如：聽君一席話，受益匪淺）。注意「匪」不寫作「非」。" },
  { id: "i600", grade: 8, term: "茅塞頓開", zhuyin: "ㄇㄠˊ ㄙㄜˋ ㄉㄨㄣˋ ㄎㄞ", pinyin: "máo sè dùn kāi", meaning: "心中疑惑像被茅草堵塞忽然打通。", example: "一句提點讓他茅塞頓開。", misuse: "「塞」在此讀ㄙㄜˋ。", syn: ["恍然大悟", "醍醐灌頂"],deep:"典故由來：出自《孟子．盡心下》：「山徑之蹊間，介然用之而成路；為間不用，則茅塞之矣。」心被茅草堵住，一旦打通便豁然開朗。\n字面意思：堵塞的茅草忽然打開。\n引申意思：疑惑頓時解開（如：經老師一點，茅塞頓開）。褒義。" },
  // ---- i601-i650(國中-高中) ----
  { id: "i601", grade: 9, term: "不恥下問", zhuyin: "ㄅㄨˋ ㄔˇ ㄒㄧㄚˋ ㄨㄣˋ", pinyin: "bù chǐ xià wèn", meaning: "不以向地位學問不如自己的人請教為恥。", example: "教授不恥下問，常向年輕工程師討教新工具。", misuse: "出自《論語》。不可寫成「不齒」。",deep:"典故由來：出自《論語．公冶長》：孔子讚孔文子「敏而好學，不恥下問」。\n字面意思：不以向不如自己的人請教為恥。\n引申意思：虛心求教（如：主管不恥下問，向新人請教軟體操作）。褒義；對象是地位學問較低者，向長輩請教不用此語。" },
  { id: "i602", grade: 9, term: "不學無術", zhuyin: "ㄅㄨˋ ㄒㄩㄝˊ ㄨˊ ㄕㄨˋ", pinyin: "bù xué wú shù", meaning: "沒有學問，也沒有本領。", example: "他不學無術，只靠關係謀職。", syn: ["胸無點墨"],deep:"典故由來：出自《漢書．霍光傳贊》：「然光不學亡（無）術，闇於大理。」\n字面意思：沒有學問、沒有方法本領。\n引申意思：沒有真才實學（如：不學無術之徒）。貶義。" },
  { id: "i603", grade: 9, term: "胸無點墨", zhuyin: "ㄒㄩㄥ ㄨˊ ㄉㄧㄢˇ ㄇㄛˋ", pinyin: "xiōng wú diǎn mò", meaning: "毫無學識。", example: "自誇博學卻胸無點墨，一問三不知。", syn: ["不學無術"],deep:"典故由來：清代小說常見；點墨＝一點墨水。\n字面意思：胸中沒有一點墨水。\n引申意思：毫無學識（如：他自嘲胸無點墨）。貶義，也可自謙。" },
  { id: "i604", grade: 9, term: "一知半解", zhuyin: "ㄧ ㄓ ㄅㄢˋ ㄐㄧㄝˇ", pinyin: "yī zhī bàn jiě", meaning: "了解得不透澈。", example: "對規則一知半解就上場，難怪頻頻犯規。", syn: ["似懂非懂"],deep:"典故由來：出自宋．嚴羽《滄浪詩話》：論悟有深淺，「有但得一知半解之悟」。\n字面意思：只知道一點、理解一半。\n引申意思：了解不透澈（如：對規則一知半解就上場）。貶義。" },
  { id: "i605", grade: 9, term: "生吞活剝", zhuyin: "ㄕㄥ ㄊㄨㄣ ㄏㄨㄛˊ ㄅㄛ", pinyin: "shēng tūn huó bō", meaning: "生硬地抄襲模仿或死記硬背。", example: "生吞活剝地背公式，一變化就不會了。", syn: ["囫圇吞棗"],deep:"典故由來：出自唐．劉肅《大唐新語》：張懷慶好抄名士文章，時人譏為「活剝王昌齡，生吞郭正一」。\n字面意思：把東西生著吞、活著剝。\n引申意思：生硬地抄襲模仿、囫圇吸收（如：生吞活剝地背公式）。貶義。" },
  { id: "i606", grade: 9, term: "舉一隅不以三隅反", zhuyin: "ㄐㄩˇ ㄧ ㄩˊ ㄅㄨˋ ㄧˇ ㄙㄢ ㄩˊ ㄈㄢˇ", pinyin: "jǔ yī yú bù yǐ sān yú fǎn", meaning: "告知一角卻不能推知其他三角，指不會舉一反三。", example: "若舉一隅不以三隅反，學再多也難活用。", misuse: "出自《論語》，孔子論教學。",deep:"典故由來：出自《論語．述而》：「舉一隅不以三隅反，則不復也。」\n字面意思：舉出一個角落，卻推不出其他三個角落。\n引申意思：不能舉一反三、不知類推（如：只會做例題，舉一隅不以三隅反）。貶義。" },
  { id: "i607", grade: 9, term: "淺嘗輒止", zhuyin: "ㄑㄧㄢˇ ㄔㄤˊ ㄓㄜˊ ㄓˇ", pinyin: "qiǎn cháng zhé zhǐ", meaning: "略微嘗試就停止，不深入鑽研。", example: "學才藝最忌淺嘗輒止，樣樣通樣樣鬆。", misuse: "「輒」讀ㄓㄜˊ，就之意。",deep:"典故由來：清代文獻常見；「輒」是就、便。\n字面意思：淺淺嘗一口就停止。\n引申意思：不深入鑽研（如：學什麼都淺嘗輒止）。貶義。" },
  { id: "i608", grade: 9, term: "學以致用", zhuyin: "ㄒㄩㄝˊ ㄧˇ ㄓˋ ㄩㄥˋ", pinyin: "xué yǐ zhì yòng", meaning: "把學到的知識運用在實際上。", example: "選修程式課後架了班網，真正學以致用。",deep:"典故由來：近代教育用語。\n字面意思：學了拿來使用。\n引申意思：把知識用於實務（如：實習讓學生學以致用）。褒義。" },
  { id: "i609", grade: 9, term: "青出於藍", zhuyin: "ㄑㄧㄥ ㄔㄨ ㄩˊ ㄌㄢˊ", pinyin: "qīng chū yú lán", meaning: "學生勝過老師，後人超越前人。", example: "弟子屢破紀錄，青出於藍。", misuse: "出自《荀子・勸學》。",deep:"典故由來：出自《荀子．勸學》：「青，取之於藍，而青於藍。」靛青從蓼藍提煉，卻比蓼藍更青。\n字面意思：青色從藍草中提出，卻比藍草更青。\n引申意思：學生勝過老師、後人超越前人（常說「青出於藍而勝於藍」）。褒義。" },
  { id: "i610", grade: 9, term: "後生可畏", zhuyin: "ㄏㄡˋ ㄕㄥ ㄎㄜˇ ㄨㄟˋ", pinyin: "hòu shēng kě wèi", meaning: "年輕人潛力可觀，令人敬畏。", example: "十六歲就奪金牌，後生可畏。", misuse: "出自《論語》。",deep:"典故由來：出自《論語．子罕》：「後生可畏，焉知來者之不如今也？」\n字面意思：年輕人值得敬畏。\n引申意思：年輕人潛力大、前途可觀（如：小將奪金，後生可畏）。褒義。" },
  { id: "i611", grade: 9, term: "長江後浪推前浪", zhuyin: "ㄔㄤˊ ㄐㄧㄤ ㄏㄡˋ ㄌㄤˋ ㄊㄨㄟ ㄑㄧㄢˊ ㄌㄤˋ", pinyin: "cháng jiāng hòu làng tuī qián làng", meaning: "新人輩出，不斷取代前人。", example: "電競圈長江後浪推前浪，新秀輩出。", syn: ["後生可畏"],deep:"典故由來：出自宋．劉斧《青瑣高議》：「長江後浪推前浪，浮事新人換舊人。」\n字面意思：長江後面的浪推著前面的浪。\n引申意思：新人輩出，不斷超越取代前人（如：科技界長江後浪推前浪）。" },
  { id: "i612", grade: 9, term: "薪火相傳", zhuyin: "ㄒㄧㄣ ㄏㄨㄛˇ ㄒㄧㄤ ㄔㄨㄢˊ", pinyin: "xīn huǒ xiāng chuán", meaning: "學問技藝一代一代傳承下去。", example: "布袋戲技藝靠師徒薪火相傳。", syn: ["一脈相承"],deep:"典故由來：語本《莊子．養生主》：「指窮於為薪，火傳也，不知其盡也。」柴會燒完，火種卻傳續不絕。\n字面意思：柴薪燒盡，火種相傳。\n引申意思：學問、技藝、精神代代相傳（如：傳統工藝薪火相傳）。褒義。" },
  { id: "i613", grade: 9, term: "一脈相承", zhuyin: "ㄧ ㄇㄞˋ ㄒㄧㄤ ㄔㄥˊ", pinyin: "yī mài xiāng chéng", meaning: "同一系統代代相傳。", example: "這套刀工與老師傅的手法一脈相承。", syn: ["薪火相傳"],deep:"典故由來：清代文獻常見；「脈」是血脈系統。\n字面意思：同一條血脈承接下來。\n引申意思：思想、技法同出一源、代代相承（如：師徒畫風一脈相承）。" },
  { id: "i614", grade: 9, term: "青黃不接", zhuyin: "ㄑㄧㄥ ㄏㄨㄤˊ ㄅㄨˋ ㄐㄧㄝ", pinyin: "qīng huáng bù jiē", meaning: "新舊接替不上，出現斷層。", example: "老將退役、新秀未成，球隊青黃不接。",deep:"典故由來：源自農事：舊穀（黃）吃完、新穀（青）未熟的缺糧時期，宋元文獻已見。\n字面意思：青苗未熟、黃穀已盡。\n引申意思：新舊接替不上、出現斷層（如：人才青黃不接）。" },
  { id: "i615", grade: 9, term: "後繼無人", zhuyin: "ㄏㄡˋ ㄐㄧˋ ㄨˊ ㄖㄣˊ", pinyin: "hòu jì wú rén", meaning: "沒有接續的人才。", example: "老手藝後繼無人，恐將失傳。", syn: ["青黃不接"],deep:"典故由來：近代組合語。\n字面意思：後面沒有接續的人。\n引申意思：技藝事業無人接班（如：老手藝後繼無人）。貶義（惋惜）。" },
  { id: "i616", grade: 9, term: "任勞任怨", zhuyin: "ㄖㄣˋ ㄌㄠˊ ㄖㄣˋ ㄩㄢˋ", pinyin: "rèn láo rèn yuàn", meaning: "做事不辭辛勞，不怕抱怨。", example: "總務任勞任怨，默默扛下瑣事。", syn: ["刻苦耐勞"],deep:"典故由來：語本漢．桓寬《鹽鐵論》「任勞而不任怨」，後合為「任勞任怨」。\n字面意思：承受勞苦，也承受抱怨。\n引申意思：做事勤懇、不計較委屈（如：媽媽任勞任怨照顧全家）。褒義。" },
  { id: "i617", grade: 9, term: "鞠躬盡瘁", zhuyin: "ㄐㄩˊ ㄍㄨㄥ ㄐㄧㄣˋ ㄘㄨㄟˋ", pinyin: "jú gōng jìn cuì", meaning: "不辭勞苦，竭盡心力。", example: "老院長為醫院鞠躬盡瘁三十年。", misuse: "出自諸葛亮〈出師表〉，後接「死而後已」。",deep:"典故由來：出自諸葛亮〈後出師表〉：「臣鞠躬盡瘁，死而後已。」（瘁＝勞累）\n字面意思：彎著身子恭敬做事，竭盡勞苦。\n引申意思：不辭辛勞、竭盡心力（如：他為教育鞠躬盡瘁）。褒義。" },
  { id: "i618", grade: 9, term: "死而後已", zhuyin: "ㄙˇ ㄦˊ ㄏㄡˋ ㄧˇ", pinyin: "sǐ ér hòu yǐ", meaning: "到死才停止，奉獻終身。", example: "他為偏鄉醫療奔走，鞠躬盡瘁，死而後已。", misuse: "「已」是停止。",deep:"典故由來：出自《論語．泰伯》曾子「死而後已，不亦遠乎」；諸葛亮〈後出師表〉亦用之。\n字面意思：到死才停止。\n引申意思：奉獻到生命最後（如：為理想奮鬥，死而後已）。褒義。" },
  { id: "i619", grade: 9, term: "夙夜匪懈", zhuyin: "ㄙㄨˋ ㄧㄝˋ ㄈㄟˇ ㄒㄧㄝˋ", pinyin: "sù yè fěi xiè", meaning: "日夜勤奮，不敢懈怠。", example: "研發團隊夙夜匪懈，如期交出成果。", misuse: "「匪」通「非」。",deep:"典故由來：出自《詩經．大雅．烝民》：「夙夜匪解（懈），以事一人。」\n字面意思：從早到晚不敢鬆懈（夙＝早，匪＝不）。\n引申意思：日夜勤奮（如：夙夜匪懈地籌備）。褒義。" },
  { id: "i620", grade: 9, term: "宵衣旰食", zhuyin: "ㄒㄧㄠ ㄧ ㄍㄢˋ ㄕˊ", pinyin: "xiāo yī gàn shí", meaning: "天未亮就穿衣，天黑才吃飯，形容勤於政事。", example: "首長宵衣旰食，處理災後重建。", misuse: "「旰」讀ㄍㄢˋ，天晚。",deep:"典故由來：出自《舊唐書》等：稱君王「宵衣旰食」——天未亮就穿衣上朝，天黑了才進食。\n字面意思：天沒亮就穿衣，天黑了才吃飯（旰＝天晚）。\n引申意思：勤於政事、操勞國事（如：領導人宵衣旰食）。褒義。" },
  { id: "i621", grade: 9, term: "夜以繼日", zhuyin: "ㄧㄝˋ ㄧˇ ㄐㄧˋ ㄖˋ", pinyin: "yè yǐ jì rì", meaning: "夜晚接著白天，不停地做。", example: "工程團隊夜以繼日搶修道路。", syn: ["焚膏繼晷", "日以繼夜"],deep:"典故由來：出自《孟子．離婁下》：周公「仰而思之，夜以繼日」。\n字面意思：用夜晚接續白天。\n引申意思：日夜不停地做（如：工程夜以繼日趕工）。" },
  { id: "i622", grade: 9, term: "全力衝刺", zhuyin: "ㄑㄩㄢˊ ㄌㄧˋ ㄔㄨㄥ ㄘˋ", pinyin: "quán lì chōng cì", meaning: "使出全部力量向目標邁進。", example: "會考前一個月，大家全力衝刺。",deep:"典故由來：現代體育用語轉為常用語。\n字面意思：用全部力量做最後奔跑。\n引申意思：全力朝目標邁進（如：考前全力衝刺）。褒義。" },
  { id: "i623", grade: 9, term: "摩拳擦掌", zhuyin: "ㄇㄛˊ ㄑㄩㄢˊ ㄘㄚ ㄓㄤˇ", pinyin: "mó quán cā zhǎng", meaning: "準備行動，躍躍欲試。", example: "選手們摩拳擦掌，等待鳴槍起跑。", syn: ["躍躍欲試"],deep:"典故由來：元代戲曲已見「摩拳擦掌」。\n字面意思：搓著拳頭、擦著手掌。\n引申意思：躍躍欲試、準備大幹一場（如：選手們摩拳擦掌）。" },
  { id: "i624", grade: 9, term: "蓄勢待發", zhuyin: "ㄒㄩˋ ㄕˋ ㄉㄞˋ ㄈㄚ", pinyin: "xù shì dài fā", meaning: "積蓄力量，等待時機行動。", example: "新產品蓄勢待發，只等發表會。", syn: ["整裝待發"],deep:"典故由來：現代組合語；「蓄勢」是積蓄力量。\n字面意思：積蓄力量，等待出發。\n引申意思：做好準備等待時機（如：新產品蓄勢待發）。褒義。" },
  { id: "i625", grade: 9, term: "整裝待發", zhuyin: "ㄓㄥˇ ㄓㄨㄤ ㄉㄞˋ ㄈㄚ", pinyin: "zhěng zhuāng dài fā", meaning: "整理好行裝，準備出發。", example: "登山隊清晨整裝待發。",deep:"典故由來：現代組合語。\n字面意思：整理好行裝，等待出發。\n引申意思：準備完成、隨時可行動（如：登山隊整裝待發）。" },
  { id: "i626", grade: 9, term: "旗開得勝", zhuyin: "ㄑㄧˊ ㄎㄞ ㄉㄜˊ ㄕㄥˋ", pinyin: "qí kāi dé shèng", meaning: "一開戰就獲勝，行事一開始就成功。", example: "預賽旗開得勝，士氣大振。", syn: ["馬到成功", "首戰告捷"],deep:"典故由來：元代戲曲已見「旗開得勝，馬到成功」。\n字面意思：軍旗一展開就打勝仗。\n引申意思：一開始就獲得成功（如：首戰旗開得勝）。褒義。" },
  { id: "i627", grade: 9, term: "銳不可當", zhuyin: "ㄖㄨㄟˋ ㄅㄨˋ ㄎㄜˇ ㄉㄤ", pinyin: "ruì bù kě dāng", meaning: "氣勢威猛，無法抵擋。", example: "地主隊氣勢銳不可當，連下三城。", misuse: "「當」在此讀ㄉㄤ，抵擋。",deep:"典故由來：語本《後漢書》「其鋒不可當」。\n字面意思：鋒銳得無法抵擋（當＝抵擋）。\n引申意思：氣勢威猛不可阻擋（如：主隊攻勢銳不可當）。褒義；「當」不寫作「擋」。" },
  { id: "i628", grade: 9, term: "乘勝追擊", zhuyin: "ㄔㄥˊ ㄕㄥˋ ㄓㄨㄟ ㄐㄧˊ", pinyin: "chéng shèng zhuī jí", meaning: "趁著勝利繼續進攻。", example: "上半場領先，下半場乘勝追擊。",deep:"典故由來：語本《戰國策》「乘勝逐北」的兵家用語。\n字面意思：趁著勝利追趕攻擊。\n引申意思：趁勝勢繼續進取（如：拿下第一城後乘勝追擊）。" },
  { id: "i629", grade: 9, term: "反敗為勝", zhuyin: "ㄈㄢˇ ㄅㄞˋ ㄨㄟˊ ㄕㄥˋ", pinyin: "fǎn bài wéi shèng", meaning: "從落敗的局面轉為勝利。", example: "九局下連得四分，反敗為勝。", syn: ["轉危為安"],deep:"典故由來：見《三國演義》等明清小說。\n字面意思：把敗局反轉為勝利。\n引申意思：扭轉頹勢獲勝（如：末局反敗為勝）。褒義。" },
  { id: "i630", grade: 9, term: "轉危為安", zhuyin: "ㄓㄨㄢˇ ㄨㄟˊ ㄨㄟˊ ㄢ", pinyin: "zhuǎn wéi wéi ān", meaning: "從危險轉為平安。", example: "手術順利，病人轉危為安。", misuse: "「危」讀ㄨㄟˊ(審訂音)。",deep:"典故由來：出自漢．劉向《戰國策書錄》：「皆高才秀士，度時君之所能行，出奇策異智，轉危為安，運亡為存。」\n字面意思：把危險轉為平安。\n引申意思：化解危機（如：談判成功，局勢轉危為安）。褒義。" },
  { id: "i631", grade: 9, term: "化險為夷", zhuyin: "ㄏㄨㄚˋ ㄒㄧㄢˇ ㄨㄟˊ ㄧˊ", pinyin: "huà xiǎn wéi yí", meaning: "使危險化為平安。", example: "機長冷靜處置，化險為夷。", misuse: "「夷」是平坦、平安。", syn: ["轉危為安"],deep:"典故由來：清代文獻常見；「夷」是平坦。\n字面意思：把險阻化為平地。\n引申意思：使危險化為平安（如：機長冷靜處置，化險為夷）。褒義。" },
  { id: "i632", grade: 9, term: "絕處逢生", zhuyin: "ㄐㄩㄝˊ ㄔㄨˋ ㄈㄥˊ ㄕㄥ", pinyin: "jué chù féng shēng", meaning: "在絕境中找到生路。", example: "公司靠轉型絕處逢生。", syn: ["柳暗花明", "起死回生"],deep:"典故由來：元代戲曲已見「絕處逢生」。\n字面意思：在絕路上遇到生路。\n引申意思：絕境中出現轉機（如：資金即將斷炊時絕處逢生）。" },
  { id: "i633", grade: 9, term: "起死回生", zhuyin: "ㄑㄧˇ ㄙˇ ㄏㄨㄟˊ ㄕㄥ", pinyin: "qǐ sǐ huí shēng", meaning: "把垂死的救活，比喻挽回絕望的局面。", example: "新教練讓墊底的球隊起死回生。", syn: ["妙手回春"],deep:"典故由來：語本《史記．扁鵲倉公列傳》：扁鵲救活虢太子，卻說「越人非能生死人也，此自當生者，越人能使之起耳」。\n字面意思：使死者復活。\n引申意思：挽回看似無望的局面；也讚醫術高明（如：一帖藥起死回生）。" },
  { id: "i634", grade: 9, term: "妙手回春", zhuyin: "ㄇㄧㄠˋ ㄕㄡˇ ㄏㄨㄟˊ ㄔㄨㄣ", pinyin: "miào shǒu huí chūn", meaning: "醫術高明，使重病痊癒。", example: "老中醫妙手回春，治好了他的痼疾。", misuse: "多用於稱讚醫生。",deep:"典故由來：清代小說常用；回春＝使春天回來。\n字面意思：靈妙的手讓春天重回（病體康復）。\n引申意思：醫術高明治好重病（如：老中醫妙手回春）。褒義。" },
  { id: "i635", grade: 9, term: "藥到病除", zhuyin: "ㄧㄠˋ ㄉㄠˋ ㄅㄧㄥˋ ㄔㄨˊ", pinyin: "yào dào bìng chú", meaning: "用藥立刻見效。", example: "對症下藥才能藥到病除。", syn: ["對症下藥"],deep:"典故由來：元代戲曲已見「藥到病除」。\n字面意思：藥一用上，病就去除。\n引申意思：辦法一出立即見效（如：這個對策藥到病除）。褒義。" },
  { id: "i636", grade: 9, term: "對症下藥", zhuyin: "ㄉㄨㄟˋ ㄓㄥˋ ㄒㄧㄚˋ ㄧㄠˋ", pinyin: "duì zhèng xià yào", meaning: "針對問題的根源採取對策。", example: "先找出成績下滑的原因，才能對症下藥。", syn: ["因材施教"],deep:"典故由來：語本《三國志．華佗傳》：華佗對同症狀的兩人開不同的藥，因病因不同——後世稱「對症下藥」。\n字面意思：針對病症開藥。\n引申意思：針對問題根源採取對策（如：找出癥結，對症下藥）。褒義。" },
  { id: "i637", grade: 9, term: "因材施教", zhuyin: "ㄧㄣ ㄘㄞˊ ㄕ ㄐㄧㄠˋ", pinyin: "yīn cái shī jiào", meaning: "依據學生的資質給予不同的教導。", example: "老師因材施教，讓每個孩子都有舞台。", misuse: "孔子的教育理念。",deep:"典故由來：語本朱熹《論語集注》：「孔子教人，各因其材。」\n字面意思：依據資質施行教育。\n引申意思：按學生特質給予不同教導（如：小班制利於因材施教）。褒義。" },
  { id: "i638", grade: 9, term: "有教無類", zhuyin: "ㄧㄡˇ ㄐㄧㄠˋ ㄨˊ ㄌㄟˋ", pinyin: "yǒu jiào wú lèi", meaning: "教育不分貴賤賢愚，人人都可受教。", example: "夜校秉持有教無類，招收各行各業學員。", misuse: "出自《論語》。",deep:"典故由來：出自《論語．衛靈公》：「子曰：有教無類。」\n字面意思：施教不分類別。\n引申意思：教育不分貧富貴賤、人人可受教（如：義務教育體現有教無類）。褒義。" },
  { id: "i639", grade: 9, term: "循循善誘", zhuyin: "ㄒㄩㄣˊ ㄒㄩㄣˊ ㄕㄢˋ ㄧㄡˋ", pinyin: "xún xún shàn yòu", meaning: "有步驟地耐心引導。", example: "教練循循善誘，帶新手入門。", syn: ["諄諄教誨"],deep:"典故由來：出自《論語．子罕》：顏淵讚孔子「夫子循循然善誘人」。\n字面意思：有次序地善於引導。\n引申意思：耐心而有步驟地教導（如：老師循循善誘）。褒義。" },
  { id: "i640", grade: 9, term: "諄諄教誨", zhuyin: "ㄓㄨㄣ ㄓㄨㄣ ㄐㄧㄠˋ ㄏㄨㄟˋ", pinyin: "zhūn zhūn jiào huì", meaning: "懇切耐心地教導。", example: "父親的諄諄教誨言猶在耳。", misuse: "「誨」讀ㄏㄨㄟˋ，教導之意。",deep:"典故由來：語本《詩經．大雅．抑》：「誨爾諄諄，聽我藐藐。」\n字面意思：懇切不倦地教導（諄諄＝懇切耐心）。\n引申意思：懇切反覆地教誨（如：父親的諄諄教誨）。褒義。" },
  { id: "i641", grade: 9, term: "言猶在耳", zhuyin: "ㄧㄢˊ ㄧㄡˊ ㄗㄞˋ ㄦˇ", pinyin: "yán yóu zài ěr", meaning: "話語彷彿還在耳邊，記憶猶新。", example: "師長叮嚀言猶在耳，不敢或忘。",deep:"典故由來：出自《左傳．文公七年》：「今君雖終，言猶在耳。」\n字面意思：話好像還在耳邊。\n引申意思：對別人的話記憶猶新（如：老師叮嚀言猶在耳）。" },
  { id: "i642", grade: 9, term: "銘記在心", zhuyin: "ㄇㄧㄥˊ ㄐㄧˋ ㄗㄞˋ ㄒㄧㄣ", pinyin: "míng jì zài xīn", meaning: "深深記在心裡。", example: "這份恩情我銘記在心。", syn: ["刻骨銘心"],deep:"典故由來：由字面組合而成的常用語。\n字面意思：像刻銘文一樣記在心裡。\n引申意思：深深記住（如：教訓銘記在心）。" },
  { id: "i643", grade: 9, term: "刻骨銘心", zhuyin: "ㄎㄜˋ ㄍㄨˇ ㄇㄧㄥˊ ㄒㄧㄣ", pinyin: "kè gǔ míng xīn", meaning: "感受深刻，永難忘懷。", example: "那次教訓刻骨銘心。", syn: ["沒齒難忘"],deep:"典故由來：語本唐．李白〈上安州李長史書〉：「深荷王公之德，銘刻心骨。」\n字面意思：刻在骨頭上、銘記在心裡。\n引申意思：感受極深、永難忘懷（如：刻骨銘心的初戀）。" },
  { id: "i644", grade: 9, term: "感恩戴德", zhuyin: "ㄍㄢˇ ㄣ ㄉㄞˋ ㄉㄜˊ", pinyin: "gǎn ēn dài dé", meaning: "感激別人的恩德。", example: "受助的家庭對善心人士感恩戴德。", syn: ["感激不盡"],deep:"典故由來：語本《三國志》「感恩戴義」，後作「感恩戴德」；戴＝尊奉。\n字面意思：感激恩惠、尊奉德澤。\n引申意思：深深感激他人恩德（如：對救命之恩感恩戴德）。褒義。" },
  { id: "i645", grade: 9, term: "結草銜環", zhuyin: "ㄐㄧㄝˊ ㄘㄠˇ ㄒㄧㄢˊ ㄏㄨㄢˊ", pinyin: "jié cǎo xián huán", meaning: "至死不忘報答恩情。", example: "承蒙提攜，他日必結草銜環以報。", misuse: "結草、銜環是兩個報恩典故。",deep:"典故由來：結草：《左傳．宣公十五年》魏顆不殉葬父妾，老人結草絆倒敵將報恩；銜環：《後漢書》注引楊寶救黃雀，雀銜玉環相報。\n字面意思：結草繩絆敵、銜玉環相報。\n引申意思：至死不忘報恩（如：大恩沒齒難忘，當結草銜環以報）。褒義。" },
  { id: "i646", grade: 9, term: "知恩圖報", zhuyin: "ㄓ ㄣ ㄊㄨˊ ㄅㄠˋ", pinyin: "zhī ēn tú bào", meaning: "受人恩惠，設法報答。", example: "他知恩圖報，事業有成後回饋母校。", syn: ["感恩戴德"],deep:"典故由來：明代小說常見的組合語。\n字面意思：知道恩惠就謀求報答。\n引申意思：受恩必報（如：他知恩圖報，回鄉興學）。褒義。" },
  { id: "i647", grade: 9, term: "忘恩負義", zhuyin: "ㄨㄤˋ ㄣ ㄈㄨˋ ㄧˋ", pinyin: "wàng ēn fù yì", meaning: "忘記別人的恩惠，背棄道義。", example: "他忘恩負義，反咬栽培他的恩師。", syn: ["過河拆橋"],deep:"典故由來：語本《漢書．張敞傳》「背恩忘義」。\n字面意思：忘記恩惠、背棄道義。\n引申意思：辜負有恩於己的人（如：忘恩負義之徒）。貶義。" },
  { id: "i648", grade: 9, term: "落葉歸根", zhuyin: "ㄌㄨㄛˋ ㄧㄝˋ ㄍㄨㄟ ㄍㄣ", pinyin: "luò yè guī gēn", meaning: "最終回到本源或故鄉。", example: "旅居海外五十年，他決定落葉歸根。",deep:"典故由來：出自宋．《景德傳燈錄》：「葉落歸根，來時無口。」\n字面意思：落葉回到樹根。\n引申意思：人最終回歸故鄉本源（如：遊子年老，盼落葉歸根）。" },
  { id: "i649", grade: 9, term: "衣錦還鄉", zhuyin: "ㄧ ㄐㄧㄣˇ ㄏㄨㄢˊ ㄒㄧㄤ", pinyin: "yī jǐn huán xiāng", meaning: "功成名就後榮耀地回到故鄉。", example: "他得了世界冠軍，衣錦還鄉。", syn: ["榮歸故里"],deep:"典故由來：語本《史記．項羽本紀》「富貴不歸故鄉，如衣繡夜行」；《南史》有「衣錦還鄉」。\n字面意思：穿著錦繡衣裳回故鄉。\n引申意思：功成名就後榮歸故里（如：學成衣錦還鄉）。「衣」作動詞讀ㄧˋ。" },
  { id: "i650", grade: 9, term: "光宗耀祖", zhuyin: "ㄍㄨㄤ ㄗㄨㄥ ㄧㄠˋ ㄗㄨˇ", pinyin: "guāng zōng yào zǔ", meaning: "使祖先和家族增添光彩。", example: "考取狀元在古代是光宗耀祖的大事。",deep:"典故由來：見《紅樓夢》等清代小說。\n字面意思：為宗族祖先增添光彩。\n引申意思：成就使家族榮耀（如：考取功名光宗耀祖）。" },
  // ---- i651-i700(高中) ----
  { id: "i651", grade: 10, term: "水乳交融", zhuyin: "ㄕㄨㄟˇ ㄖㄨˇ ㄐㄧㄠ ㄖㄨㄥˊ", pinyin: "shuǐ rǔ jiāo róng", meaning: "像水和乳汁融合，關係密切無間。", example: "樂手與觀眾情緒水乳交融。", syn: ["如膠似漆"],deep:"典故由來：清代小說常見；水與乳相合無間。\n字面意思：水和乳汁交融在一起。\n引申意思：關係融洽無間（如：軍民水乳交融）。褒義。" },
  { id: "i652", grade: 10, term: "唇齒相依", zhuyin: "ㄔㄨㄣˊ ㄔˇ ㄒㄧㄤ ㄧ", pinyin: "chún chǐ xiāng yī", meaning: "關係密切，互相依存。", example: "上下游產業唇齒相依，一榮俱榮。", syn: ["脣亡齒寒", "休戚與共"],deep:"典故由來：語本《三國志》論吳蜀「唇齒相依」的形勢。\n字面意思：像嘴唇和牙齒互相依靠。\n引申意思：關係密切、互相依存（如：兩國唇齒相依）。" },
  { id: "i653", grade: 10, term: "休戚與共", zhuyin: "ㄒㄧㄡ ㄑㄧ ㄩˇ ㄍㄨㄥˋ", pinyin: "xiū qī yǔ gòng", meaning: "禍福相關，命運一體。", example: "島嶼與海洋休戚與共，護海就是護家。", misuse: "「休」是喜、「戚」是憂。", syn: ["息息相關"],deep:"典故由來：語本《國語．周語》：單襄公稱晉孫周「為晉休戚，不背本也」。休＝喜，戚＝憂。\n字面意思：喜樂與憂患共同承受。\n引申意思：禍福相關、命運一體（如：企業與員工休戚與共）。褒義。" },
  { id: "i654", grade: 10, term: "息息相關", zhuyin: "ㄒㄧˊ ㄒㄧˊ ㄒㄧㄤ ㄍㄨㄢ", pinyin: "xí xí xiāng guān", meaning: "關係非常密切。", example: "睡眠品質與學習成效息息相關。", syn: ["休戚與共"],deep:"典故由來：清代文獻常見；「息息」指呼吸相連。\n字面意思：一呼一吸都相關連。\n引申意思：關係極密切（如：氣候與生活息息相關）。" },
  { id: "i655", grade: 10, term: "榮辱與共", zhuyin: "ㄖㄨㄥˊ ㄖㄨˋ ㄩˇ ㄍㄨㄥˋ", pinyin: "róng rù yǔ gòng", meaning: "光榮與恥辱一同承擔，關係緊密。", example: "隊員榮辱與共，勝敗都一起扛。", syn: ["休戚與共"],deep:"典故由來：由字面組合而成。\n字面意思：光榮與恥辱一起承擔。\n引申意思：命運緊密相連（如：球員與球隊榮辱與共）。褒義。" },
  { id: "i656", grade: 10, term: "相濡以沫", zhuyin: "ㄒㄧㄤ ㄖㄨˊ ㄧˇ ㄇㄛˋ", pinyin: "xiāng rú yǐ mò", meaning: "困境中以微薄之力互相扶持。", example: "戰亂中夫妻相濡以沫，攜手渡過難關。", misuse: "出自《莊子》，原句後接「不如相忘於江湖」。",deep:"典故由來：出自《莊子．大宗師》：泉水乾涸，魚兒困在陸地，「相呴以濕，相濡以沫，不如相忘於江湖」。\n字面意思：用唾沫互相濕潤（濡＝沾濕）。\n引申意思：困境中以微力相互扶持（如：患難夫妻相濡以沫）。褒義。" },
  { id: "i657", grade: 10, term: "和衷共濟", zhuyin: "ㄏㄜˊ ㄓㄨㄥ ㄍㄨㄥˋ ㄐㄧˋ", pinyin: "hé zhōng gòng jì", meaning: "同心協力，共渡難關。", example: "疫情期間各行各業和衷共濟。", syn: ["同舟共濟", "共體時艱"],deep:"典故由來：語本《尚書》「同寅協恭和衷哉」與《國語》「共濟」；和衷＝同心。\n字面意思：同心合力，共渡河川。\n引申意思：團結一致共克難關（如：災後全民和衷共濟）。褒義。" },
  { id: "i658", grade: 10, term: "眾擎易舉", zhuyin: "ㄓㄨㄥˋ ㄑㄧㄥˊ ㄧˋ ㄐㄩˇ", pinyin: "zhòng qíng yì jǔ", meaning: "眾人合力，事情容易成功。", example: "社區公園靠居民眾擎易舉建成。", misuse: "「擎」是往上托。", syn: ["群策群力"],deep:"典故由來：見明．張岱〈募修岳鄂王祠姆疏〉：「眾擎易舉，獨力難支。」\n字面意思：眾人一起舉，東西容易抬起（擎＝舉）。\n引申意思：眾人合力事情易成（如：眾擎易舉，募款迅速達標）。褒義。" },
  { id: "i659", grade: 10, term: "群策群力", zhuyin: "ㄑㄩㄣˊ ㄘㄜˋ ㄑㄩㄣˊ ㄌㄧˋ", pinyin: "qún cè qún lì", meaning: "大家一起出主意、出力量。", example: "園遊會靠全班群策群力才圓滿落幕。", syn: ["集思廣益"],deep:"典故由來：出自漢．揚雄《法言》：「漢屈群策，群策屈群力。」\n字面意思：集合眾人的計策與力量。\n引申意思：大家一起出謀出力（如：群策群力辦好校慶）。褒義。" },
  { id: "i660", grade: 10, term: "分崩離析", zhuyin: "ㄈㄣ ㄅㄥ ㄌㄧˊ ㄒㄧ", pinyin: "fēn bēng lí xī", meaning: "崩壞瓦解，四分五裂。", example: "內鬨讓聯盟分崩離析。", misuse: "出自《論語》。", syn: ["土崩瓦解"],deep:"典故由來：出自《論語．季氏》：「邦分崩離析而不能守也。」\n字面意思：分裂崩塌、離散解體。\n引申意思：國家集團四分五裂（如：聯盟分崩離析）。貶義。" },
  { id: "i661", grade: 10, term: "土崩瓦解", zhuyin: "ㄊㄨˇ ㄅㄥ ㄨㄚˇ ㄐㄧㄝˇ", pinyin: "tǔ bēng wǎ jiě", meaning: "徹底崩潰瓦解。", example: "謠言一出，信任土崩瓦解。", syn: ["分崩離析"],deep:"典故由來：語本《史記．秦始皇本紀論》：「秦之積衰，天下土崩瓦解。」\n字面意思：像土堆崩塌、瓦片碎裂。\n引申意思：徹底崩潰（如：防線土崩瓦解）。貶義。" },
  { id: "i662", grade: 10, term: "支離破碎", zhuyin: "ㄓ ㄌㄧˊ ㄆㄛˋ ㄙㄨㄟˋ", pinyin: "zhī lí pò suì", meaning: "殘破零散，不成整體。", example: "地震後家園支離破碎。", syn: ["四分五裂"],deep:"典故由來：元代以後常見的組合語。\n字面意思：肢體分離、破裂成碎片。\n引申意思：事物殘破零散（如：計畫被改得支離破碎）。貶義。" },
  { id: "i663", grade: 10, term: "四分五裂", zhuyin: "ㄙˋ ㄈㄣ ㄨˇ ㄌㄧㄝˋ", pinyin: "sì fēn wǔ liè", meaning: "分裂成許多部分，不統一。", example: "意見不合讓團隊四分五裂。", syn: ["分崩離析"],deep:"典故由來：出自《戰國策．魏策》：張儀說魏：「魏南與楚而不與齊，則齊攻其東……此所謂四分五裂之道也。」\n字面意思：分成四塊、裂成五片。\n引申意思：分裂不完整、不統一（如：意見四分五裂）。貶義。" },
  { id: "i664", grade: 10, term: "貌合神離", zhuyin: "ㄇㄠˋ ㄏㄜˊ ㄕㄣˊ ㄌㄧˊ", pinyin: "mào hé shén lí", meaning: "表面和好，內心不一致。", example: "兩派貌合神離，合作名存實亡。", syn: ["同床異夢"],deep:"典故由來：語本舊題黃石公《素書》：「貌合心離者孤。」\n字面意思：外表契合，精神分離。\n引申意思：表面和好、內心不合（如：兩人貌合神離）。貶義。" },
  { id: "i665", grade: 10, term: "同床異夢", zhuyin: "ㄊㄨㄥˊ ㄔㄨㄤˊ ㄧˋ ㄇㄥˋ", pinyin: "tóng chuáng yì mèng", meaning: "共同生活或共事，卻各有各的打算。", example: "合資雙方同床異夢，計畫終告吹。", syn: ["貌合神離"],deep:"典故由來：語本宋．陳亮〈與朱元晦書〉：「同床各做夢。」\n字面意思：睡同一張床，做各自的夢。\n引申意思：一起共事卻各懷打算（如：合作雙方同床異夢）。貶義。" },
  { id: "i666", grade: 10, term: "爾虞我詐", zhuyin: "ㄦˇ ㄩˊ ㄨㄛˇ ㄓㄚˋ", pinyin: "ěr yú wǒ zhà", meaning: "彼此猜疑欺騙。", example: "商場爾虞我詐，他始終堅持誠信。", misuse: "「虞」是欺騙、防範。", syn: ["勾心鬥角"],deep:"典故由來：出自《左傳．宣公十五年》：宋楚議和盟辭「我無爾詐，爾無我虞」——彼此不欺不防，後反用作互相欺詐。\n字面意思：你騙我、我防你（虞＝防備；詐＝欺騙）。\n引申意思：互相猜疑欺騙（如：商場上爾虞我詐）。貶義。" },
  { id: "i667", grade: 10, term: "勾心鬥角", zhuyin: "ㄍㄡ ㄒㄧㄣ ㄉㄡˋ ㄐㄧㄠˇ", pinyin: "gōu xīn dòu jiǎo", meaning: "各用心機，明爭暗鬥。", example: "宮廷劇裡人人勾心鬥角。", misuse: "原指宮室建築結構精巧，後轉為貶義。",deep:"典故由來：出自唐．杜牧〈阿房宮賦〉：「各抱地勢，鉤心鬥角。」原形容宮殿結構精巧，樑角交錯。\n字面意思：屋角向中心相鉤、簷角相對如鬥。\n引申意思：各用心機、明爭暗鬥（如：辦公室勾心鬥角）。貶義。" },
  { id: "i668", grade: 10, term: "暗潮洶湧", zhuyin: "ㄢˋ ㄔㄠˊ ㄒㄩㄥ ㄩㄥˇ", pinyin: "àn cháo xiōng yǒng", meaning: "表面平靜，暗中情勢激烈。", example: "改選前夕，派系暗潮洶湧。",deep:"典故由來：現代組合語；暗潮＝海面下的潛流。\n字面意思：表面平靜，水下潛流洶湧。\n引申意思：檯面下情勢激烈（如：黨內暗潮洶湧）。" },
  { id: "i669", grade: 10, term: "劍拔弩張", zhuyin: "ㄐㄧㄢˋ ㄅㄚˊ ㄋㄨˇ ㄓㄤ", pinyin: "jiàn bá nǔ zhāng", meaning: "形勢緊張，一觸即發。", example: "談判破裂，雙方劍拔弩張。", misuse: "「弩」是機械弓。", syn: ["一觸即發"],deep:"典故由來：出自南朝梁．袁昂《古今書評》：評韋誕書法「如龍威虎振，劍拔弩張」。\n字面意思：劍已出鞘、弩已張開。\n引申意思：形勢緊張、一觸即發（如：兩軍對峙，劍拔弩張）。" },
  { id: "i670", grade: 10, term: "一觸即發", zhuyin: "ㄧ ㄔㄨˋ ㄐㄧˊ ㄈㄚ", pinyin: "yī chù jí fā", meaning: "情勢緊張，稍一觸動就會爆發。", example: "邊境衝突一觸即發。", syn: ["劍拔弩張"],deep:"典故由來：清代文獻常見；「觸」是碰。\n字面意思：一碰就會爆發。\n引申意思：情勢極度緊張（如：衝突一觸即發）。" },
  { id: "i671", grade: 10, term: "如火如荼", zhuyin: "ㄖㄨˊ ㄏㄨㄛˇ ㄖㄨˊ ㄊㄨˊ", pinyin: "rú huǒ rú tú", meaning: "像火般紅、像荼花般白，形容氣勢旺盛熱烈。", example: "選前造勢如火如荼。", misuse: "「荼」讀ㄊㄨˊ，白色茅花，不可寫成「茶」。",deep:"典故由來：出自《國語．吳語》：吳王夫差夜陳三軍，白軍「望之如荼」、紅軍「望之如火」。荼是白色茅花。\n字面意思：像火一樣紅、像荼花一樣白。\n引申意思：氣勢旺盛、進行熱烈（如：活動如火如荼展開）。" },
  { id: "i672", grade: 10, term: "方興未艾", zhuyin: "ㄈㄤ ㄒㄧㄥ ㄨㄟˋ ㄞˋ", pinyin: "fāng xīng wèi ài", meaning: "正在興盛發展，尚未停止。", example: "綠能產業方興未艾。", misuse: "「艾」讀ㄞˋ，停止之意。", syn: ["如日中天"],deep:"典故由來：宋代文獻已見；「艾」是停止。\n字面意思：正在興起，尚未停止。\n引申意思：正蓬勃發展（如：綠能產業方興未艾）。褒義。" },
  { id: "i673", grade: 10, term: "蒸蒸日上", zhuyin: "ㄓㄥ ㄓㄥ ㄖˋ ㄕㄤˋ", pinyin: "zhēng zhēng rì shàng", meaning: "一天天興旺發展。", example: "老店轉型後生意蒸蒸日上。", syn: ["欣欣向榮"],deep:"典故由來：清代文獻常見；「蒸蒸」是上升的樣子。\n字面意思：像熱氣一天天上升。\n引申意思：事業日益興旺（如：業績蒸蒸日上）。褒義。" },
  { id: "i674", grade: 10, term: "江河日下", zhuyin: "ㄐㄧㄤ ㄏㄜˊ ㄖˋ ㄒㄧㄚˋ", pinyin: "jiāng hé rì xià", meaning: "像江水日日東流而下，情況一天天壞下去。", example: "實體唱片市場江河日下。", syn: ["每下愈況"],deep:"典故由來：清代文獻常見。\n字面意思：江河的水一天天向下流。\n引申意思：情況日益衰落（如：家道江河日下）。貶義。" },
  { id: "i675", grade: 10, term: "日薄西山", zhuyin: "ㄖˋ ㄅㄛˊ ㄒㄧ ㄕㄢ", pinyin: "rì bó xī shān", meaning: "太陽迫近西山，比喻衰亡在即。", example: "傳呼機產業早已日薄西山。", misuse: "「薄」是迫近。出自〈陳情表〉。", syn: ["氣息奄奄"],deep:"典故由來：出自晉．李密〈陳情表〉：「但以劉日薄西山，氣息奄奄。」（薄＝迫近）\n字面意思：太陽迫近西山。\n引申意思：衰老垂危或事物將沒落（如：傳統產業日薄西山）。" },
  { id: "i676", grade: 10, term: "苟延殘喘", zhuyin: "ㄍㄡˇ ㄧㄢˊ ㄘㄢˊ ㄔㄨㄢˇ", pinyin: "gǒu yán cán chuǎn", meaning: "勉強拖延一口殘餘的氣息。", example: "老工廠靠零星訂單苟延殘喘。",deep:"典故由來：出自明．馬中錫《中山狼傳》：狼求東郭先生「何不使我得早處囊中，以苟延殘喘乎」。\n字面意思：勉強拖延最後一口喘息。\n引申意思：勉強維持存續（如：靠貸款苟延殘喘）。貶義。" },
  { id: "i677", grade: 10, term: "迴光返照", zhuyin: "ㄏㄨㄟˊ ㄍㄨㄤ ㄈㄢˇ ㄓㄠˋ", pinyin: "huí guāng fǎn zhào", meaning: "衰亡前短暫的好轉。", example: "股價暴漲只是迴光返照，隨後崩跌。",deep:"典故由來：佛家與元曲用語：太陽落山前天空短暫回亮。\n字面意思：日落前光線的短暫返照。\n引申意思：衰亡前短暫的好轉（如：病危時的迴光返照）。" },
  { id: "i678", grade: 10, term: "物換星移", zhuyin: "ㄨˋ ㄏㄨㄢˋ ㄒㄧㄥ ㄧˊ", pinyin: "wù huàn xīng yí", meaning: "景物改變，星辰移位，指時序變遷。", example: "物換星移，老街早已不復當年。", misuse: "出自王勃〈滕王閣詩〉。", syn: ["滄海桑田", "時過境遷"],deep:"典故由來：出自唐．王勃〈滕王閣詩〉：「閣中帝子今何在？檻外長江空自流……物換星移幾度秋。」\n字面意思：景物更換、星辰移位。\n引申意思：時序變遷、世事更迭（如：物換星移，小鎮已成都會）。" },
  { id: "i679", grade: 10, term: "時過境遷", zhuyin: "ㄕˊ ㄍㄨㄛˋ ㄐㄧㄥˋ ㄑㄧㄢ", pinyin: "shí guò jìng qiān", meaning: "時間過去，環境改變。", example: "時過境遷，當年的恩怨早已放下。", syn: ["物換星移"],deep:"典故由來：清代文獻常見。\n字面意思：時間過去，環境改變。\n引申意思：情況隨時間改變（如：時過境遷，恩怨早已放下）。" },
  { id: "i680", grade: 10, term: "人事已非", zhuyin: "ㄖㄣˊ ㄕˋ ㄧˇ ㄈㄟ", pinyin: "rén shì yǐ fēi", meaning: "人與事都已改變，不同往昔。", example: "重回舊居，人事已非，不勝唏噓。", syn: ["物是人非"],deep:"典故由來：由「物是人非」衍生的常用語。\n字面意思：人與事都不是從前的了。\n引申意思：世事全變（如：重回母校，人事已非）。" },
  { id: "i681", grade: 10, term: "物是人非", zhuyin: "ㄨˋ ㄕˋ ㄖㄣˊ ㄈㄟ", pinyin: "wù shì rén fēi", meaning: "景物依舊，人事全非。", example: "老屋還在，物是人非。", misuse: "出自李清照詞。", syn: ["人事已非"],deep:"典故由來：出自宋．李清照〈武陵春〉：「物是人非事事休，欲語淚先流。」\n字面意思：景物依舊，人卻不同了。\n引申意思：懷念故人、感傷變遷（如：故居仍在，物是人非）。" },
  { id: "i682", grade: 10, term: "觸景傷情", zhuyin: "ㄔㄨˋ ㄐㄧㄥˇ ㄕㄤ ㄑㄧㄥˊ", pinyin: "chù jǐng shāng qíng", meaning: "看到眼前景物而引發傷感。", example: "路過母校，觸景傷情。", syn: ["睹物思人"],deep:"典故由來：元代戲曲已見「觸景傷情」。\n字面意思：接觸眼前景物而傷感。\n引申意思：見景生悲（如：舊地重遊，觸景傷情）。" },
  { id: "i683", grade: 10, term: "睹物思人", zhuyin: "ㄉㄨˇ ㄨˋ ㄙ ㄖㄣˊ", pinyin: "dǔ wù sī rén", meaning: "看到遺物而想念故人。", example: "整理遺物時睹物思人，淚流不止。", syn: ["觸景傷情"],deep:"典故由來：唐代以來詩文常見。\n字面意思：看見物品就想起那個人。\n引申意思：見遺物而懷念故人（如：睹物思人，淚流不止）。" },
  { id: "i684", grade: 10, term: "不勝唏噓", zhuyin: "ㄅㄨˋ ㄕㄥ ㄒㄧ ㄒㄩ", pinyin: "bù shēng xī xū", meaning: "感慨嘆息不已。", example: "老友凋零，令人不勝唏噓。", misuse: "「勝」讀ㄕㄥ(審訂音)。",deep:"典故由來：由字面組合而成；「唏噓」是嘆息聲。\n字面意思：忍不住連連嘆息。\n引申意思：感慨嘆息不已（如：英雄暮年，令人不勝唏噓）。" },
  { id: "i685", grade: 10, term: "感慨萬千", zhuyin: "ㄍㄢˇ ㄎㄞˇ ㄨㄢˋ ㄑㄧㄢ", pinyin: "gǎn kǎi wàn qiān", meaning: "感觸極多，心緒複雜。", example: "畢業十年重聚，人人感慨萬千。", syn: ["百感交集"],deep:"典故由來：由字面組合而成。\n字面意思：上萬種感觸湧上心頭。\n引申意思：感觸極多（如：站上頒獎台，感慨萬千）。" },
  { id: "i686", grade: 11, term: "撫今追昔", zhuyin: "ㄈㄨˇ ㄐㄧㄣ ㄓㄨㄟ ㄒㄧˊ", pinyin: "fǔ jīn zhuī xí", meaning: "面對眼前而追想過往。", example: "館慶特展讓老員工撫今追昔。", misuse: "「昔」審訂音ㄒㄧˊ。",deep:"典故由來：清代文獻常見的組合語。\n字面意思：撫視現在，追想從前。\n引申意思：對照今昔而生感慨（如：校慶時撫今追昔）。" },
  { id: "i687", grade: 11, term: "繼往開來", zhuyin: "ㄐㄧˋ ㄨㄤˇ ㄎㄞ ㄌㄞˊ", pinyin: "jì wǎng kāi lái", meaning: "承續過去，開創未來。", example: "百年校慶以繼往開來為主題。", syn: ["承先啟後"],deep:"典故由來：語本宋．朱熹〈中庸章句序〉：「繼往聖，開來學。」\n字面意思：繼承過去，開創未來。\n引申意思：承續前人事業並開拓新局（如：繼往開來的一代）。褒義。" },
  { id: "i688", grade: 11, term: "承先啟後", zhuyin: "ㄔㄥˊ ㄒㄧㄢ ㄑㄧˇ ㄏㄡˋ", pinyin: "chéng xiān qǐ hòu", meaning: "承接前人，開啟後人。", example: "這部辭典承先啟後，影響深遠。", syn: ["繼往開來"],deep:"典故由來：清代文獻常見，與「繼往開來」同義。\n字面意思：承接先人，啟導後人。\n引申意思：承接傳統、開啟未來（如：承先啟後的關鍵世代）。褒義。" },
  { id: "i689", grade: 11, term: "高屋建瓴", zhuyin: "ㄍㄠ ㄨ ㄐㄧㄢˋ ㄌㄧㄥˊ", pinyin: "gāo wū jiàn líng", meaning: "居高臨下，形勢有利，見識高遠。", example: "這篇社論高屋建瓴，統攝全局。", misuse: "「瓴」是水瓶，自屋頂傾水，勢不可擋。",deep:"典故由來：出自《史記．高祖本紀》：形容據關中之勢「譬猶居高屋之上建瓴水也」——從屋頂倒瓶水，勢不可擋（瓴＝水瓶）。\n字面意思：在高屋頂上倒瓶中水。\n引申意思：居高臨下、氣勢或見識高遠（如：這篇社論高屋建瓴）。褒義。" },
  { id: "i690", grade: 11, term: "提綱挈領", zhuyin: "ㄊㄧˊ ㄍㄤ ㄑㄧㄝˋ ㄌㄧㄥˇ", pinyin: "tí gāng qiè lǐng", meaning: "抓住要領、綱要。", example: "他提綱挈領地講完整章重點。", misuse: "「挈」讀ㄑㄧㄝˋ，提起。", syn: ["綱舉目張"],deep:"典故由來：語本《荀子．勸學》：「若挈裘領，詘五指而頓之。」提起皮衣領子一抖，毛就順了。\n字面意思：提起網的總繩、抓住衣領（挈＝提）。\n引申意思：抓住要點（如：報告提綱挈領，一聽就懂）。褒義。" },
  { id: "i691", grade: 11, term: "綱舉目張", zhuyin: "ㄍㄤ ㄐㄩˇ ㄇㄨˋ ㄓㄤ", pinyin: "gāng jǔ mù zhāng", meaning: "抓住大綱，細節自然分明。", example: "先定章程，綱舉目張，庶務就好辦了。", syn: ["提綱挈領"],deep:"典故由來：語本《呂氏春秋．用民》：「壹引其綱，萬目皆張。」拉起漁網總繩，網眼自然張開。\n字面意思：提起網綱，網目自張。\n引申意思：抓住關鍵，其餘自然理順（如：抓住主要矛盾，綱舉目張）。褒義。" },
  { id: "i692", grade: 11, term: "居高臨下", zhuyin: "ㄐㄩ ㄍㄠ ㄌㄧㄣˊ ㄒㄧㄚˋ", pinyin: "jū gāo lín xià", meaning: "處在高處俯視下方，占據有利地位。", example: "守軍居高臨下，易守難攻。", syn: ["高屋建瓴"],deep:"典故由來：兵家常語，居高處俯攻低處。\n字面意思：處在高處、面對下方。\n引申意思：占據有利位置（如：守軍居高臨下）；也指以上位者姿態對人（含貶義）。" },
  { id: "i693", grade: 11, term: "見微知著", zhuyin: "ㄐㄧㄢˋ ㄨㄟˊ ㄓ ㄓㄨˋ", pinyin: "jiàn wéi zhī zhù", meaning: "從細微跡象看出趨勢與真相。", example: "老刑警見微知著，從腳印識破謊言。", syn: ["一葉知秋"],deep:"典故由來：語本《韓非子．說林上》：「聖人見微以知萌，見端以知末。」\n字面意思：看見細微處就知道顯著的趨勢（著＝明顯）。\n引申意思：從小徵兆看出大局（如：分析師見微知著）。褒義。" },
  { id: "i694", grade: 11, term: "洞若觀火", zhuyin: "ㄉㄨㄥˋ ㄖㄨㄛˋ ㄍㄨㄢ ㄏㄨㄛˇ", pinyin: "dòng ruò guān huǒ", meaning: "觀察透澈，像看火一樣清楚。", example: "分析師對市場動向洞若觀火。", syn: ["明察秋毫", "洞燭機先"],deep:"典故由來：語本《尚書．盤庚》：「予若觀火。」\n字面意思：清楚得像看火一樣（洞＝透澈）。\n引申意思：觀察透澈明白（如：對局勢洞若觀火）。褒義。" },
  { id: "i695", grade: 11, term: "洞燭機先", zhuyin: "ㄉㄨㄥˋ ㄓㄨˊ ㄐㄧ ㄒㄧㄢ", pinyin: "dòng zhú jī xiān", meaning: "預先看出事情的徵兆。", example: "他洞燭機先，提早轉型避開危機。", syn: ["未卜先知"],deep:"典故由來：明清文獻常見；「機」是徵兆。\n字面意思：像燭火照亮般預見徵兆。\n引申意思：預先看出事情的發展（如：他洞燭機先，提早布局）。褒義。" },
  { id: "i696", grade: 11, term: "未卜先知", zhuyin: "ㄨㄟˋ ㄅㄨˇ ㄒㄧㄢ ㄓ", pinyin: "wèi bǔ xiān zhī", meaning: "不用占卜就預先知道。", example: "他彷彿未卜先知，早備好了雨備方案。", syn: ["料事如神"],deep:"典故由來：元代戲曲已見「未卜先知」。\n字面意思：不用占卜就預先知道。\n引申意思：有預見能力（如：他彷彿未卜先知）。" },
  { id: "i697", grade: 11, term: "料事如神", zhuyin: "ㄌㄧㄠˋ ㄕˋ ㄖㄨˊ ㄕㄣˊ", pinyin: "liào shì rú shén", meaning: "預料事情非常準確。", example: "軍師料事如神，敵軍果然中計。", syn: ["未卜先知"],deep:"典故由來：宋明小說常用語。\n字面意思：預料事情像神一樣準。\n引申意思：預測極準確（如：軍師料事如神）。褒義。" },
  { id: "i698", grade: 11, term: "運籌帷幄", zhuyin: "ㄩㄣˋ ㄔㄡˊ ㄨㄟˊ ㄨㄛˋ", pinyin: "yùn chóu wéi wò", meaning: "在帳幕中謀劃決策。", example: "總教練運籌帷幄，調度有方。", misuse: "「帷幄」是軍帳。出自《史記》論張良。",deep:"典故由來：出自《史記．高祖本紀》：劉邦稱張良「夫運籌策帷帳之中，決勝於千里之外，吾不如子房」。\n字面意思：在軍帳中運算籌劃（帷幄＝軍帳）。\n引申意思：在後方策劃指揮（如：主帥運籌帷幄）。褒義。" },
  { id: "i699", grade: 11, term: "決勝千里", zhuyin: "ㄐㄩㄝˊ ㄕㄥˋ ㄑㄧㄢ ㄌㄧˇ", pinyin: "jué shèng qiān lǐ", meaning: "在千里之外決定勝負，指謀略高明。", example: "運籌帷幄之中，決勝千里之外。", syn: ["運籌帷幄"],deep:"典故由來：同出《史記．高祖本紀》讚張良語。\n字面意思：在千里之外決定勝負。\n引申意思：謀略高明、遠程掌控全局（如：運籌帷幄，決勝千里）。褒義。" },
  { id: "i700", grade: 11, term: "神機妙算", zhuyin: "ㄕㄣˊ ㄐㄧ ㄇㄧㄠˋ ㄙㄨㄢˋ", pinyin: "shén jī miào suàn", meaning: "神奇的機智，巧妙的謀劃。", example: "諸葛亮神機妙算，草船借箭。", syn: ["料事如神"],deep:"典故由來：《三國演義》常以「神機妙算」讚諸葛亮。\n字面意思：神奇的機謀、巧妙的計算。\n引申意思：計謀高超（如：神機妙算的軍師）。褒義。" },
  // ---- i701-i750(高中) ----
  { id: "i701", grade: 11, term: "壯士斷腕", zhuyin: "ㄓㄨㄤˋ ㄕˋ ㄉㄨㄢˋ ㄨㄢˋ", pinyin: "zhuàng shì duàn wàn", meaning: "當機立斷，忍痛捨棄以保全大局。", example: "公司壯士斷腕，砍掉虧損部門。",deep:"典故由來：語本《三國志．陳泰傳》引古語：「蝮蛇螫手，壯士解腕。」毒蛇咬手，勇士立斷手腕保命。\n字面意思：勇士砍斷自己的手腕。\n引申意思：當機立斷、忍痛捨局部保全大局（如：企業壯士斷腕，裁撤虧損部門）。" },
  { id: "i702", grade: 11, term: "縱橫捭闔", zhuyin: "ㄗㄨㄥ ㄏㄥˊ ㄅㄞˇ ㄏㄜˊ", pinyin: "zōng héng bǎi hé", meaning: "以聯合或分化的手段進行政治外交運作。", example: "外交官縱橫捭闔，為國爭取盟友。", misuse: "「捭」讀ㄅㄞˇ，開；「闔」是閉。縱橫在此讀ㄗㄨㄥ ㄏㄥˊ。",deep:"典故由來：源自戰國縱橫家：合縱連橫之術；《鬼谷子》有〈捭闔〉篇（捭＝開，闔＝合）。\n字面意思：或縱或橫，或開或合。\n引申意思：靈活運用聯合與分化的外交政治手腕（如：外交場上縱橫捭闔）。" },
  { id: "i703", grade: 11, term: "孤注一擲", zhuyin: "ㄍㄨ ㄓㄨˋ ㄧ ㄓˊ", pinyin: "gū zhù yī zhí", meaning: "把所有資本押上，冒險一試。", example: "他孤注一擲，抵押房子創業。", misuse: "含冒險意味，多用於形勢危急。",deep:"典故由來：出自《宋史．寇準傳》：王欽若對真宗說，賭徒錢快輸光時把所有錢押作一注，稱「孤注」，譏寇準以皇帝為孤注。\n字面意思：把全部賭本押成一注擲出。\n引申意思：拿出所有本錢冒險一搏（如：孤注一擲投入全部積蓄）。含冒險意味。" },
  { id: "i704", grade: 11, term: "背城借一", zhuyin: "ㄅㄟˋ ㄔㄥˊ ㄐㄧㄝˋ ㄧ", pinyin: "bèi chéng jiè yī", meaning: "背靠城牆決一死戰，作最後奮鬥。", example: "季末保級戰，全隊背城借一。", syn: ["背水一戰"],deep:"典故由來：出自《左傳．成公二年》：齊國戰敗求和說「請收合餘燼，背城借一」——背靠城牆再借一戰。\n字面意思：背靠城牆，借最後一戰。\n引申意思：作最後的奮鬥（如：球隊背城借一，全力搶分）。" },
  { id: "i705", grade: 11, term: "義無反顧", zhuyin: "ㄧˋ ㄨˊ ㄈㄢˇ ㄍㄨˋ", pinyin: "yì wú fǎn gù", meaning: "為道義勇往直前，絕不退縮回頭。", example: "她義無反顧投入偏鄉教育。", syn: ["勇往直前"],deep:"典故由來：出自漢．司馬相如〈喻巴蜀檄〉：「義不反顧，計不旋踵。」\n字面意思：為道義向前，不回頭看。\n引申意思：毅然前行絕不退縮（如：義無反顧地投身救災）。褒義。" },
  { id: "i706", grade: 11, term: "勇往直前", zhuyin: "ㄩㄥˇ ㄨㄤˇ ㄓˊ ㄑㄧㄢˊ", pinyin: "yǒng wǎng zhí qián", meaning: "勇敢地一直向前。", example: "遇到挫折仍要勇往直前。", syn: ["一往無前"],deep:"典故由來：宋代語錄常見（朱熹「勇往直前」）。\n字面意思：勇敢地一直向前。\n引申意思：無所畏懼向前（如：追夢路上勇往直前）。褒義。" },
  { id: "i707", grade: 11, term: "披堅執銳", zhuyin: "ㄆㄧ ㄐㄧㄢ ㄓˊ ㄖㄨㄟˋ", pinyin: "pī jiān zhí ruì", meaning: "穿堅甲、持利器，親上戰場。", example: "老將披堅執銳，帶頭衝鋒。",deep:"典故由來：出自《史記．項羽本紀》：「披堅執銳，義不如公。」\n字面意思：身披堅甲、手執利器。\n引申意思：親上前線作戰（如：主將披堅執銳）。褒義。" },
  { id: "i708", grade: 11, term: "身先士卒", zhuyin: "ㄕㄣ ㄒㄧㄢ ㄕˋ ㄗㄨˊ", pinyin: "shēn xiān shì zú", meaning: "作戰時走在士兵前面，率先垂範。", example: "廠長身先士卒，假日也到產線幫忙。", syn: ["以身作則"],deep:"典故由來：《史記》《漢書》常見「身先士卒」。\n字面意思：自身走在士兵前面。\n引申意思：領導者親自帶頭（如：隊長身先士卒）。褒義。" },
  { id: "i709", grade: 11, term: "以身作則", zhuyin: "ㄧˇ ㄕㄣ ㄗㄨㄛˋ ㄗㄜˊ", pinyin: "yǐ shēn zuò zé", meaning: "用自己的行動作榜樣。", example: "要求學生守時，老師先以身作則。", syn: ["身教重於言教"],deep:"典故由來：語本《論語．子路》：「其身正，不令而行。」\n字面意思：拿自身作準則。\n引申意思：以自己的行為做榜樣（如：父母以身作則）。褒義。" },
  { id: "i710", grade: 11, term: "上行下效", zhuyin: "ㄕㄤˋ ㄒㄧㄥˊ ㄒㄧㄚˋ ㄒㄧㄠˋ", pinyin: "shàng xíng xià xiào", meaning: "在上位者怎麼做，下面的人就跟著學。", example: "主管帶頭節能，上行下效蔚為風氣。", misuse: "多用於警惕上位者的影響力。",deep:"典故由來：漢代文獻已見「上行之，下效之」。\n字面意思：上面怎麼做，下面就怎麼學。\n引申意思：上位者的言行影響群眾（如：主管守時，上行下效）。多用於提醒上位者。" },
  { id: "i711", grade: 11, term: "風行草偃", zhuyin: "ㄈㄥ ㄒㄧㄥˊ ㄘㄠˇ ㄧㄢˇ", pinyin: "fēng xíng cǎo yǎn", meaning: "風吹過草便倒伏，比喻德政教化感人之深。", example: "君子之德風，風行草偃。", misuse: "出自《論語》。「偃」是倒伏。",deep:"典故由來：出自《論語．顏淵》：「君子之德風，小人之德草，草上之風必偃。」（偃＝倒伏）\n字面意思：風吹過，草隨之倒伏。\n引申意思：德政教化使人自然順服（如：良好校風，風行草偃）。褒義。" },
  { id: "i712", grade: 11, term: "蔚然成風", zhuyin: "ㄨㄟˋ ㄖㄢˊ ㄔㄥˊ ㄈㄥ", pinyin: "wèi rán chéng fēng", meaning: "逐漸形成普遍的風氣。", example: "自帶環保杯已蔚然成風。",deep:"典故由來：語本「蔚成風氣」；蔚＝草木茂盛。\n字面意思：茂盛地形成風氣。\n引申意思：逐漸成為普遍風氣（如：環保觀念蔚然成風）。" },
  { id: "i713", grade: 11, term: "移風易俗", zhuyin: "ㄧˊ ㄈㄥ ㄧˋ ㄙㄨˊ", pinyin: "yí fēng yì sú", meaning: "改變舊有的風俗習慣。", example: "推行環保葬是移風易俗的大工程。",deep:"典故由來：出自《荀子．樂論》：音樂「其感人深，其移風易俗」。\n字面意思：轉移風氣、改變習俗。\n引申意思：改革社會舊習（如：新政移風易俗）。褒義。" },
  { id: "i714", grade: 11, term: "潛移默化", zhuyin: "ㄑㄧㄢˊ ㄧˊ ㄇㄛˋ ㄏㄨㄚˋ", pinyin: "qián yí mò huà", meaning: "在不知不覺中受到影響而改變。", example: "閱讀習慣在潛移默化中養成。", syn: ["耳濡目染"],deep:"典故由來：明清文獻常見；潛＝暗中，默＝無聲。\n字面意思：暗暗地轉移、無聲地變化。\n引申意思：不知不覺中受影響改變（如：家庭氣氛潛移默化影響孩子）。" },
  { id: "i715", grade: 11, term: "近朱者赤", zhuyin: "ㄐㄧㄣˋ ㄓㄨ ㄓㄜˇ ㄔˋ", pinyin: "jìn zhū zhě chì", meaning: "接近好人使人變好，環境影響人。", example: "近朱者赤，跟自律的人一起讀書進步快。", misuse: "後句為「近墨者黑」。",deep:"典故由來：出自晉．傅玄〈太子少傅箴〉：「近朱者赤，近墨者黑。」\n字面意思：接近硃砂的變紅。\n引申意思：環境與朋友影響人的品行（如：近朱者赤，要慎選朋友）。" },
  { id: "i716", grade: 11, term: "蓬生麻中", zhuyin: "ㄆㄥˊ ㄕㄥ ㄇㄚˊ ㄓㄨㄥ", pinyin: "péng shēng má zhōng", meaning: "蓬草長在麻中不扶自直，環境使人向善。", example: "蓬生麻中，不扶而直，選對環境很重要。", misuse: "出自《荀子・勸學》。",deep:"典故由來：出自《荀子．勸學》：「蓬生麻中，不扶而直。」\n字面意思：蓬草長在麻田裡，不用扶也長得直。\n引申意思：好環境使人自然向善（如：蓬生麻中，好班風帶動學習）。褒義。" },
  { id: "i717", grade: 11, term: "孟母三遷", zhuyin: "ㄇㄥˋ ㄇㄨˇ ㄙㄢ ㄑㄧㄢ", pinyin: "mèng mǔ sān qiān", meaning: "孟母為教育孟子三次搬家，指重視環境教育。", example: "為了學區，他們家上演現代孟母三遷。",deep:"典故由來：出自漢．劉向《列女傳》：孟母為讓孟子有好環境，從墓地旁、市場旁搬到學宮旁，孟子遂學禮儀。\n字面意思：孟子的母親三次搬家。\n引申意思：重視教育環境（如：現代父母孟母三遷，遷戶就學）。" },
  { id: "i718", grade: 11, term: "斷機教子", zhuyin: "ㄉㄨㄢˋ ㄐㄧ ㄐㄧㄠˋ ㄗˇ", pinyin: "duàn jī jiào zǐ", meaning: "孟母剪斷織布告誡孟子學習不可中輟。", example: "斷機教子的故事說明半途而廢前功盡棄。",deep:"典故由來：出自《列女傳》：孟子輟學回家，孟母剪斷織布機上的布，警惕他學業中斷如斷布，前功盡棄。\n字面意思：剪斷織機上的布來教育兒子。\n引申意思：告誡學習不可半途而廢（如：斷機教子的苦心）。" },
  { id: "i719", grade: 11, term: "曲高和寡", zhuyin: "ㄑㄩˇ ㄍㄠ ㄏㄜˋ ㄍㄨㄚˇ", pinyin: "qǔ gāo hè guǎ", meaning: "曲調高深，能唱和的人少；知音難得。", example: "這部實驗電影曲高和寡，票房慘澹。", misuse: "「和」在此讀ㄏㄜˋ，應和。",deep:"典故由來：出自宋玉〈對楚王問〉：客唱〈下里巴人〉，和者數千；唱〈陽春白雪〉，和者數十——「是其曲彌高，其和彌寡」。\n字面意思：曲調越高深，能跟著唱的人越少。\n引申意思：作品高深難有知音（如：這部實驗電影曲高和寡）。" },
  { id: "i720", grade: 11, term: "陽春白雪", zhuyin: "ㄧㄤˊ ㄔㄨㄣ ㄅㄞˊ ㄒㄩㄝˇ", pinyin: "yáng chūn bái xuě", meaning: "高雅而不通俗的文藝作品。", example: "古典樂未必是陽春白雪，也能親近大眾。", misuse: "與「下里巴人」相對。",deep:"典故由來：同出宋玉〈對楚王問〉：〈陽春〉〈白雪〉是高雅樂曲。\n字面意思：戰國高雅歌曲名。\n引申意思：高雅不通俗的文藝（如：古典樂被視為陽春白雪）。與「下里巴人」相對。" },
  { id: "i721", grade: 11, term: "下里巴人", zhuyin: "ㄒㄧㄚˋ ㄌㄧˇ ㄅㄚ ㄖㄣˊ", pinyin: "xià lǐ bā rén", meaning: "通俗的民間文藝。", example: "夜市歌謠雖是下里巴人，卻最貼近生活。", misuse: "與「陽春白雪」相對，非罵人之語。",deep:"典故由來：同出宋玉〈對楚王問〉：〈下里〉〈巴人〉是通俗歌曲。\n字面意思：戰國通俗歌曲名。\n引申意思：通俗的大眾文藝（如：流行歌是現代的下里巴人）。與「陽春白雪」相對。" },
  { id: "i722", grade: 11, term: "雅俗共賞", zhuyin: "ㄧㄚˇ ㄙㄨˊ ㄍㄨㄥˋ ㄕㄤˇ", pinyin: "yǎ sú gòng shǎng", meaning: "高雅與通俗的人都能欣賞。", example: "這齣歌仔戲雅俗共賞，場場爆滿。",deep:"典故由來：明代文獻已見「雅俗共賞」。\n字面意思：高雅者與通俗者都能欣賞。\n引申意思：作品老少咸宜、各層次都喜愛（如：這齣戲雅俗共賞）。褒義。" },
  { id: "i723", grade: 11, term: "交口稱譽", zhuyin: "ㄐㄧㄠ ㄎㄡˇ ㄔㄥ ㄩˋ", pinyin: "jiāo kǒu chēng yù", meaning: "眾人同聲稱讚。", example: "新館長上任半年，各界交口稱譽。", syn: ["有口皆碑"],deep:"典故由來：語本唐．韓愈〈柳子厚墓誌銘〉：「諸公要人……交口薦譽之。」\n字面意思：眾口同聲稱讚。\n引申意思：人人讚譽（如：新作交口稱譽）。褒義。" },
  { id: "i724", grade: 11, term: "餘音繞梁", zhuyin: "ㄩˊ ㄧㄣ ㄖㄠˋ ㄌㄧㄤˊ", pinyin: "yú yīn rào liáng", meaning: "歌聲美妙，餘音彷彿繞著屋梁不散。", example: "她的歌聲餘音繞梁，令人回味。", misuse: "「三日不絕」為其後句。",deep:"典故由來：出自《列子．湯問》：歌者韓娥過雍門鬻歌，去後「餘音繞梁欐，三日不絕」。\n字面意思：歌聲的餘音繞著屋梁不散。\n引申意思：歌聲優美，令人回味難忘（如：天籟之音，餘音繞梁）。褒義。" },
  { id: "i725", grade: 11, term: "萬人空巷", zhuyin: "ㄨㄢˋ ㄖㄣˊ ㄎㄨㄥ ㄒㄧㄤˋ", pinyin: "wàn rén kōng xiàng", meaning: "家家戶戶的人都出來了，形容轟動一時。", example: "燈會壓軸主燈點亮，萬人空巷。", misuse: "指人潮傾巢而出，不是街上沒人。",deep:"典故由來：出自宋．蘇軾詩：「賴有明朝看潮在，萬人空巷鬥新妝。」\n字面意思：人們全出來了，巷子都空了。\n引申意思：轟動一時、傾城出動（如：球隊凱旋，萬人空巷）。注意：是「巷空人出」，不是街上沒人。" },
  { id: "i726", grade: 11, term: "擲地有聲", zhuyin: "ㄓˊ ㄉㄧˋ ㄧㄡˇ ㄕㄥ", pinyin: "zhí dì yǒu shēng", meaning: "文辭優美鏗鏘，也指言論有力。", example: "這篇宣言擲地有聲。", misuse: "原指文章如金石般擲地作響。",deep:"典故由來：出自《晉書．孫綽傳》：孫綽自誇文章「卿試擲地，當作金石聲」。\n字面意思：扔到地上能發出金石之聲。\n引申意思：文辭優美鏗鏘或言論有力（如：宣言擲地有聲）。褒義。" },
  { id: "i727", grade: 11, term: "鏗鏘有力", zhuyin: "ㄎㄥ ㄑㄧㄤ ㄧㄡˇ ㄌㄧˋ", pinyin: "kēng qiāng yǒu lì", meaning: "聲音響亮有節奏，言辭有力。", example: "他鏗鏘有力地說出隊呼。", syn: ["擲地有聲"],deep:"典故由來：「鏗鏘」是金石撞擊聲，組合成語。\n字面意思：聲音如金石相擊，響亮有節奏。\n引申意思：聲音或言辭有力（如：演說鏗鏘有力）。褒義。" },
  { id: "i728", grade: 11, term: "振聾發聵", zhuyin: "ㄓㄣˋ ㄌㄨㄥˊ ㄈㄚ ㄎㄨㄟˋ", pinyin: "zhèn lóng fā kuì", meaning: "聲音大得連聾者都聽得見，比喻言論喚醒麻木的人。", example: "這場演說振聾發聵，發人深省。", misuse: "「聵」讀ㄎㄨㄟˋ，天生耳聾。",deep:"典故由來：出自清．袁枚《隨園詩話補遺》：「此數言，振聾發聵。」（聵＝天生耳聾）\n字面意思：聲音大得能喚醒聾人。\n引申意思：言論驚醒麻木糊塗的人（如：這篇報導振聾發聵）。褒義。" },
  { id: "i729", grade: 11, term: "發人深省", zhuyin: "ㄈㄚ ㄖㄣˊ ㄕㄣ ㄒㄧㄥˇ", pinyin: "fā rén shēn xǐng", meaning: "啟發人深刻思考反省。", example: "紀錄片結尾發人深省。", misuse: "「省」在此讀ㄒㄧㄥˇ，反省。",deep:"典故由來：語本唐．杜甫〈遊龍門奉先寺〉：「欲覺聞晨鐘，令人發深省。」\n字面意思：引發人深刻的醒悟。\n引申意思：使人深思反省（如：這部紀錄片發人深省）。褒義。" },
  { id: "i730", grade: 11, term: "暮鼓晨鐘", zhuyin: "ㄇㄨˋ ㄍㄨˇ ㄔㄣˊ ㄓㄨㄥ", pinyin: "mù gǔ chén zhōng", meaning: "寺院朝暮的鐘鼓聲，比喻使人警醒的言論。", example: "長者一席話如暮鼓晨鐘。", syn: ["當頭棒喝"],deep:"典故由來：佛寺制度：晨敲鐘、暮擊鼓報時醒眾。\n字面意思：傍晚的鼓聲、清晨的鐘聲。\n引申意思：使人警醒的言論教誨（如：長者之言如暮鼓晨鐘）。褒義。" },
  { id: "i731", grade: 11, term: "當頭棒喝", zhuyin: "ㄉㄤ ㄊㄡˊ ㄅㄤˋ ㄏㄜˋ", pinyin: "dāng tóu bàng hè", meaning: "使人立即醒悟的警示。", example: "醫生的警告如當頭棒喝，他立刻戒菸。", misuse: "「喝」在此讀ㄏㄜˋ，大聲斥喝。禪宗典故。",deep:"典故由來：禪宗公案：德山宣鑒以棒打、臨濟義玄以大喝接引學人，逼其當下開悟。\n字面意思：當頭一棒、大喝一聲。\n引申意思：使人立刻醒悟的嚴厲提醒（如：老師的話如當頭棒喝）。" },
  { id: "i732", grade: 12, term: "空谷足音", zhuyin: "ㄎㄨㄥ ㄍㄨˇ ㄗㄨˊ ㄧㄣ", pinyin: "kōng gǔ zú yīn", meaning: "空寂山谷中的腳步聲，比喻難得的音信、言論或人物。", example: "在喧囂的網路上，這篇理性長文有如空谷足音。",deep:"典故由來：語本《莊子．徐无鬼》：逃入空谷的人「聞人足音跫然而喜」。\n字面意思：空寂山谷裡傳來的腳步聲。\n引申意思：難得的音信、言論或人物（如：這番諍言如空谷足音）。褒義。" },
  { id: "i733", grade: 12, term: "如雷貫耳", zhuyin: "ㄖㄨˊ ㄌㄟˊ ㄍㄨㄢˋ ㄦˇ", pinyin: "rú léi guàn ěr", meaning: "名聲極大，像雷聲傳入耳中。", example: "久仰大名，如雷貫耳。", misuse: "用於恭維他人名氣。",deep:"典故由來：元代戲曲常見：「久聞先生大名，如雷貫耳。」\n字面意思：像雷聲穿入耳中。\n引申意思：名聲極大（如：大師之名如雷貫耳）。褒義。" },
  { id: "i734", grade: 12, term: "名聞遐邇", zhuyin: "ㄇㄧㄥˊ ㄨㄣˊ ㄒㄧㄚˊ ㄦˇ", pinyin: "míng wén xiá ěr", meaning: "名聲遠近皆知。", example: "鼎泰豐名聞遐邇，觀光客必訪。", misuse: "「遐」遠、「邇」近。", syn: ["馳名中外"],deep:"典故由來：《魏書》已見「名聞遐邇」；遐＝遠，邇＝近。\n字面意思：遠近都聽聞其名。\n引申意思：名聲遠播（如：小吃名聞遐邇）。褒義。" },
  { id: "i735", grade: 12, term: "遺臭萬年", zhuyin: "ㄧˊ ㄔㄡˋ ㄨㄢˋ ㄋㄧㄢˊ", pinyin: "yí chòu wàn nián", meaning: "惡名永遠流傳，被人唾罵。", example: "賣國求榮者遺臭萬年。", misuse: "與「流芳百世」相對。",deep:"典故由來：出自《晉書．桓溫傳》：桓溫嘆「既不能流芳後世，不足復遺臭萬載邪」。\n字面意思：惡臭流傳一萬年。\n引申意思：惡名永被唾罵（如：賣國者遺臭萬年）。貶義；相對詞：流芳百世。" },
  { id: "i736", grade: 12, term: "後患無窮", zhuyin: "ㄏㄡˋ ㄏㄨㄢˋ ㄨˊ ㄑㄩㄥˊ", pinyin: "hòu huàn wú qióng", meaning: "留下無窮的禍患。", example: "縱容作弊，後患無窮。", syn: ["養虎遺患"],deep:"典故由來：明清小說常用語。\n字面意思：留下的禍患沒有窮盡。\n引申意思：埋下無盡禍根（如：縱容作弊，後患無窮）。" },
  { id: "i737", grade: 12, term: "養虎遺患", zhuyin: "ㄧㄤˇ ㄏㄨˇ ㄧˊ ㄏㄨㄢˋ", pinyin: "yǎng hǔ yí huàn", meaning: "縱容敵人或壞人，給自己留下後患。", example: "姑息霸凌者無異養虎遺患。", misuse: "「遺」是留下。", syn: ["後患無窮"],deep:"典故由來：出自《史記．項羽本紀》：劉邦欲西歸，張良陳平諫「今釋弗擊，此所謂養虎自遺患也」。\n字面意思：養著老虎，給自己留下禍患。\n引申意思：寬縱敵人終受其害（如：姑息養虎遺患）。貶義。" },
  { id: "i738", grade: 12, term: "放虎歸山", zhuyin: "ㄈㄤˋ ㄏㄨˇ ㄍㄨㄟ ㄕㄢ", pinyin: "fàng hǔ guī shān", meaning: "放走敵人，留下禍根。", example: "沒收贓款卻放人，形同放虎歸山。", syn: ["養虎遺患"],deep:"典故由來：語本晉．司馬彪《零陵先賢傳》：劉巴諫「若使備討張魯，是放虎於山林也」。\n字面意思：把老虎放回山裡。\n引申意思：放走敵人留下後患（如：釋放主嫌形同放虎歸山）。" },
  { id: "i739", grade: 12, term: "斬草除根", zhuyin: "ㄓㄢˇ ㄘㄠˇ ㄔㄨˊ ㄍㄣ", pinyin: "zhǎn cǎo chú gēn", meaning: "徹底剷除，不留後患。", example: "防治登革熱要斬草除根，清除孳生源。", syn: ["除惡務盡"],deep:"典故由來：語本《左傳．隱公六年》：「見惡，如農夫之務去草焉……絕其本根，勿使能殖。」\n字面意思：割草連根拔除。\n引申意思：徹底剷除禍根（如：掃毒須斬草除根）。" },
  { id: "i740", grade: 12, term: "釜底抽薪", zhuyin: "ㄈㄨˇ ㄉㄧˇ ㄔㄡ ㄒㄧㄣ", pinyin: "fǔ dǐ chōu xīn", meaning: "從鍋底抽掉柴火，從根本解決問題。", example: "與其一直加班救火，不如釜底抽薪改流程。", misuse: "與「揚湯止沸」相對。",deep:"典故由來：出自北齊．魏收〈為侯景叛移梁朝文〉：「抽薪止沸，剪草除根。」\n字面意思：從鍋底抽掉燃燒的柴火。\n引申意思：從根本上解決問題（如：治本之道是釜底抽薪）。褒義；相對詞：揚湯止沸。" },
  { id: "i741", grade: 12, term: "揚湯止沸", zhuyin: "ㄧㄤˊ ㄊㄤ ㄓˇ ㄈㄟˋ", pinyin: "yáng tāng zhǐ fèi", meaning: "把滾水舀起再倒回去以止沸，治標不治本。", example: "只發補助不改制度，無異揚湯止沸。", misuse: "與「釜底抽薪」相對。",deep:"典故由來：語本《呂氏春秋》：「以湯止沸，沸愈不止；去火則止矣。」\n字面意思：舀起滾水再倒回去想止住沸騰。\n引申意思：治標不治本（如：補貼只是揚湯止沸）。貶義。" },
  { id: "i742", grade: 12, term: "頭痛醫頭", zhuyin: "ㄊㄡˊ ㄊㄨㄥˋ ㄧ ㄊㄡˊ", pinyin: "tóu tòng yī tóu", meaning: "只治表面症狀，不求根本解決。", example: "頭痛醫頭，腳痛醫腳，問題永遠解決不了。", syn: ["揚湯止沸"],deep:"典故由來：語本朱熹語錄：「頭痛灸頭，腳痛灸腳。」\n字面意思：頭痛只醫頭。\n引申意思：只解決表面症狀（常說「頭痛醫頭，腳痛醫腳」）。貶義。" },
  { id: "i743", grade: 12, term: "輕重倒置", zhuyin: "ㄑㄧㄥ ㄓㄨㄥˋ ㄉㄠˋ ㄓˋ", pinyin: "qīng zhòng dào zhì", meaning: "把重要與次要的順序弄反了。", example: "花大錢裝潢卻不顧食材品質，輕重倒置。", syn: ["本末倒置"],deep:"典故由來：宋代文獻已見。\n字面意思：輕的和重的放顛倒了。\n引申意思：主次不分（如：先玩再讀書是輕重倒置）。貶義。" },
  { id: "i744", grade: 12, term: "本末倒置", zhuyin: "ㄅㄣˇ ㄇㄛˋ ㄉㄠˋ ㄓˋ", pinyin: "běn mò dào zhì", meaning: "把主要和次要的位置弄顛倒。", example: "為了社團荒廢課業，未免本末倒置。", misuse: "「倒」在此讀ㄉㄠˋ。", syn: ["輕重倒置"],deep:"典故由來：宋．朱熹書信已見「本末倒置」。\n字面意思：樹根和枝梢倒過來放。\n引申意思：把根本與枝節弄顛倒（如：重包裝輕品質，本末倒置）。貶義。" },
  { id: "i745", grade: 12, term: "喧賓奪主", zhuyin: "ㄒㄩㄢ ㄅㄧㄣ ㄉㄨㄛˊ ㄓㄨˇ", pinyin: "xuān bīn duó zhǔ", meaning: "客人聲勢蓋過主人，次要壓過主要。", example: "配樂太搶戲，喧賓奪主。", syn: ["本末倒置"],deep:"典故由來：清代文獻常見。\n字面意思：客人的喧鬧壓過了主人。\n引申意思：次要事物壓過主要事物（如：配樂太搶戲，喧賓奪主）。貶義。" },
  { id: "i746", grade: 12, term: "畫地自限", zhuyin: "ㄏㄨㄚˋ ㄉㄧˋ ㄗˋ ㄒㄧㄢˋ", pinyin: "huà dì zì xiàn", meaning: "自我設限，不求突破。", example: "別畫地自限，文組也能學程式。", syn: ["故步自封"],deep:"典故由來：語本漢代「畫地為牢」：在地上畫圈為監獄。\n字面意思：在地上畫界限把自己圍住。\n引申意思：自我設限不求突破（如：不要畫地自限）。貶義。" },
  { id: "i747", grade: 12, term: "故步自封", zhuyin: "ㄍㄨˋ ㄅㄨˋ ㄗˋ ㄈㄥ", pinyin: "gù bù zì fēng", meaning: "安於現狀，不求進步。", example: "老品牌故步自封，終被市場淘汰。", misuse: "「故步」是舊有的步伐。", syn: ["墨守成規"],deep:"典故由來：語本《漢書．敘傳》：學步邯鄲者「又復失其故步」；「故步自封」即守著舊步伐把自己封住。\n字面意思：守著老步子，把自己封閉起來。\n引申意思：安於現狀、不求進步（如：技術故步自封終被淘汰）。貶義。" },
  { id: "i748", grade: 12, term: "墨守成規", zhuyin: "ㄇㄛˋ ㄕㄡˇ ㄔㄥˊ ㄍㄨㄟ", pinyin: "mò shǒu chéng guī", meaning: "固守舊規，不知變通。", example: "流程二十年沒改，全因主管墨守成規。", misuse: "「墨」指墨翟善守城，非筆墨。", syn: ["故步自封", "抱殘守缺"],deep:"典故由來：「墨守」源自墨子：《戰國策》載墨翟善守城，九拒公輸盤攻城之機變，後稱善守為「墨守」；今與「成規」連用轉為貶義。\n字面意思：像墨子守城一樣守著現成的規矩。\n引申意思：固守舊法不知變通（如：經營墨守成規，終被市場淘汰）。貶義。" },
  { id: "i749", grade: 12, term: "抱殘守缺", zhuyin: "ㄅㄠˋ ㄘㄢˊ ㄕㄡˇ ㄑㄩㄝ", pinyin: "bào cán shǒu quē", meaning: "守著殘缺的舊東西不放，不肯革新。", example: "抱殘守缺只會被時代拋下。", syn: ["墨守成規"],deep:"典故由來：語本《漢書．劉歆傳》：批評儒生「猶欲保殘守缺」。\n字面意思：抱著殘破的東西、守著缺漏不放。\n引申意思：戀舊拒新、不肯革新（如：抱殘守缺難以進步）。貶義。" },
  { id: "i750", grade: 12, term: "推陳出新", zhuyin: "ㄊㄨㄟ ㄔㄣˊ ㄔㄨ ㄒㄧㄣ", pinyin: "tuī chén chū xīn", meaning: "去除舊的，創造新的。", example: "老舖推陳出新，開發抹茶鳳梨酥。", syn: ["革故鼎新", "標新立異"],deep:"典故由來：清代文獻常見；本指倉米去陳納新。\n字面意思：推去陳舊的，產出新的。\n引申意思：去舊創新（如：老店推陳出新，屢創話題）。褒義。" },
  // ---- i751-i800(高中，學測層級收尾) ----
  { id: "i751", grade: 12, term: "標新立異", zhuyin: "ㄅㄧㄠ ㄒㄧㄣ ㄌㄧˋ ㄧˋ", pinyin: "biāo xīn lì yì", meaning: "提出新奇主張，表示與眾不同。", example: "設計要有理念，不是為標新立異而怪。", syn: ["獨樹一幟"],deep:"典故由來：出自《世說新語．文學》：支道林解《莊子．逍遙遊》「標新理於二家之表，立異義於眾賢之外」。\n字面意思：標舉新的道理、立下不同的見解。\n引申意思：創立新說或故意顯得與眾不同（如：造型標新立異）。原褒義，今常帶「刻意求異」的貶義。" },
  { id: "i752", grade: 12, term: "獨樹一幟", zhuyin: "ㄉㄨˊ ㄕㄨˋ ㄧ ㄓˋ", pinyin: "dú shù yī zhì", meaning: "自成一家，風格獨特。", example: "她的水墨動畫在影壇獨樹一幟。", misuse: "「幟」是旗幟。", syn: ["別樹一格", "自成一家"],deep:"典故由來：出自清．袁枚《隨園詩話》：「元、白在唐朝所以能獨樹一幟者，正為其不襲盛唐窠臼也。」\n字面意思：獨自樹起一面旗幟。\n引申意思：自成一家、風格獨特（如：畫風獨樹一幟）。褒義。" },
  { id: "i753", grade: 12, term: "別開生面", zhuyin: "ㄅㄧㄝˊ ㄎㄞ ㄕㄥ ㄇㄧㄢˋ", pinyin: "bié kāi shēng miàn", meaning: "另創新的風格局面。", example: "校慶辦成電競嘉年華，別開生面。", syn: ["別出心裁"],deep:"典故由來：語本唐．杜甫〈丹青引〉：「凌煙功臣少顏色，將軍下筆開生面。」曹霸重繪功臣像，面貌一新。\n字面意思：另外開創新的面貌。\n引申意思：創新格局、別具一格（如：晚會別開生面）。褒義。" },
  { id: "i754", grade: 12, term: "耳目一新", zhuyin: "ㄦˇ ㄇㄨˋ ㄧ ㄒㄧㄣ", pinyin: "ěr mù yī xīn", meaning: "所見所聞都有新鮮感。", example: "新編歌仔戲讓觀眾耳目一新。", syn: ["煥然一新"],deep:"典故由來：《魏書》已見「耳目更新」之語，後作「耳目一新」。\n字面意思：耳朵眼睛所接觸的全是新的。\n引申意思：見聞煥然一新（如：新裝潢令人耳目一新）。褒義。" },
  { id: "i755", grade: 12, term: "獨當一面", zhuyin: "ㄉㄨˊ ㄉㄤ ㄧ ㄇㄧㄢˋ", pinyin: "dú dāng yī miàn", meaning: "能單獨承擔一方面的重任。", example: "歷練三年，她已能獨當一面。", misuse: "「當」在此讀ㄉㄤ，承擔。",deep:"典故由來：出自《史記．留侯世家》：張良說漢王之將「獨韓信可屬大事，當一面」。\n字面意思：獨自承當一個方面。\n引申意思：能單獨負責一方重任（如：歷練多年，已能獨當一面）。褒義。" },
  { id: "i756", grade: 12, term: "獨占鰲頭", zhuyin: "ㄉㄨˊ ㄓㄢˋ ㄠˊ ㄊㄡˊ", pinyin: "dú zhàn áo tóu", meaning: "考試或競賽得第一名。", example: "她在全國科展獨占鰲頭。", misuse: "狀元立於殿前鰲頭石雕的典故。",deep:"典故由來：源自科舉：殿試放榜，狀元立於殿前石階上刻的巨鰲頭部迎榜，稱「獨占鰲頭」。\n字面意思：獨自站在鰲頭之上。\n引申意思：考試競賽得第一（如：他在全國賽獨占鰲頭）。褒義。" },
  { id: "i757", grade: 12, term: "金榜題名", zhuyin: "ㄐㄧㄣ ㄅㄤˇ ㄊㄧˊ ㄇㄧㄥˊ", pinyin: "jīn bǎng tí míng", meaning: "考試錄取，榜上有名。", example: "祝各位考生金榜題名。", misuse: "與「名落孫山」相對。",deep:"典故由來：見五代．王定保《唐摭言》：進士及第「金榜題名」。金榜是科舉殿試錄取名單。\n字面意思：名字寫上金色榜單。\n引申意思：考試錄取（如：祝你金榜題名）。褒義。" },
  { id: "i758", grade: 12, term: "蟾宮折桂", zhuyin: "ㄔㄢˊ ㄍㄨㄥ ㄓㄜˊ ㄍㄨㄟˋ", pinyin: "chán gōng zhé guì", meaning: "科舉登第，考試得中。", example: "苦讀十載，終得蟾宮折桂。", syn: ["金榜題名"],deep:"典故由來：語本《晉書．郤詵傳》：郤詵自評對策第一如「桂林之一枝」；後與月宮（蟾宮）傳說結合，稱登科為「蟾宮折桂」。\n字面意思：到月宮折取桂枝。\n引申意思：科舉登第、考試得中（如：蟾宮折桂，光耀門楣）。褒義。" },
  { id: "i759", grade: 12, term: "平步青雲", zhuyin: "ㄆㄧㄥˊ ㄅㄨˋ ㄑㄧㄥ ㄩㄣˊ", pinyin: "píng bù qīng yún", meaning: "順利地登上高位。", example: "他年紀輕輕平步青雲，升任協理。", syn: ["扶搖直上", "青雲直上"],deep:"典故由來：出自《史記．范雎列傳》：須賈對范雎說「賈不意君能自致於青雲之上」。\n字面意思：平穩地步上青雲高空。\n引申意思：順利晉升高位（如：他仕途平步青雲）。" },
  { id: "i760", grade: 12, term: "扶搖直上", zhuyin: "ㄈㄨˊ ㄧㄠˊ ㄓˊ ㄕㄤˋ", pinyin: "fú yáo zhí shàng", meaning: "乘旋風直上高空，地位快速上升。", example: "業績扶搖直上，連續三季創新高。", misuse: "「扶搖」是旋風。出自《莊子》。",deep:"典故由來：出自《莊子．逍遙遊》：大鵬「摶扶搖而上者九萬里」。扶搖是旋風。\n字面意思：乘著旋風直升高空。\n引申意思：地位、成績快速上升（如：聲勢扶搖直上）。" },
  { id: "i761", grade: 12, term: "一落千丈", zhuyin: "ㄧ ㄌㄨㄛˋ ㄑㄧㄢ ㄓㄤˋ", pinyin: "yī luò qiān zhàng", meaning: "急速下降。", example: "醜聞爆發後，形象一落千丈。", syn: ["一蹶不振"],deep:"典故由來：出自唐．韓愈〈聽穎師彈琴〉：「躋攀分寸不可上，失勢一落千丈強。」\n字面意思：一下子跌落千丈。\n引申意思：急遽下降（如：信譽一落千丈）。貶義。" },
  { id: "i762", grade: 12, term: "一蹶不振", zhuyin: "ㄧ ㄐㄩㄝˊ ㄅㄨˋ ㄓㄣˋ", pinyin: "yī jué bù zhèn", meaning: "跌倒後再也爬不起來，失敗後無法振作。", example: "別因一次落榜就一蹶不振。", misuse: "「蹶」讀ㄐㄩㄝˊ，跌倒。",deep:"典故由來：語本漢．劉向《說苑．談叢》：「一蹶之故，卻足不行。」跌一跤就不敢再走。\n字面意思：跌一跤就爬不起來（蹶＝跌倒）。\n引申意思：失敗後無法重新振作（如：投資失利後一蹶不振）。貶義。" },
  { id: "i763", grade: 12, term: "東窗事發", zhuyin: "ㄉㄨㄥ ㄔㄨㄤ ㄕˋ ㄈㄚ", pinyin: "dōng chuāng shì fā", meaning: "陰謀敗露。", example: "掏空案東窗事發，董座落跑。", misuse: "秦檜東窗下密謀害岳飛的典故。",deep:"典故由來：出自明．田汝成《西湖遊覽志餘》：秦檜在東窗下與妻密謀害岳飛；秦檜死後方士遊冥見他受罪，檜託言「東窗事發矣」。\n字面意思：東窗下密謀的事被揭發。\n引申意思：陰謀敗露（如：掏空案東窗事發）。貶義。" },
  { id: "i764", grade: 12, term: "紙包不住火", zhuyin: "ㄓˇ ㄅㄠ ㄅㄨˋ ㄓㄨˋ ㄏㄨㄛˇ", pinyin: "zhǐ bāo bù zhù huǒ", meaning: "真相終究無法掩蓋。", example: "紙包不住火，謊言遲早被拆穿。", syn: ["東窗事發"],deep:"典故由來：民間俗諺。\n字面意思：紙包不住火焰。\n引申意思：真相終究掩蓋不了（如：紙包不住火，弊案終會曝光）。" },
  { id: "i765", grade: 12, term: "欲蓋彌彰", zhuyin: "ㄩˋ ㄍㄞˋ ㄇㄧˊ ㄓㄤ", pinyin: "yù gài mí zhāng", meaning: "想掩蓋反而更加明顯。", example: "刪文滅證反而欲蓋彌彰。", misuse: "「彌」是更加、「彰」是明顯。",deep:"典故由來：出自《左傳．昭公三十一年》：「或求名而不得，或欲蓋而名章（彰）。」\n字面意思：想掩蓋，反而更加彰顯。\n引申意思：越隱瞞越暴露（如：刪文滅證反而欲蓋彌彰）。貶義。" },
  { id: "i766", grade: 12, term: "此地無銀三百兩", zhuyin: "ㄘˇ ㄉㄧˋ ㄨˊ ㄧㄣˊ ㄙㄢ ㄅㄞˇ ㄌㄧㄤˇ", pinyin: "cǐ dì wú yín sān bǎi liǎng", meaning: "想隱瞞反而不打自招。", example: "急著澄清沒人問的事，此地無銀三百兩。", syn: ["欲蓋彌彰"],deep:"典故由來：民間故事：張三埋銀三百兩，立牌「此地無銀三百兩」；鄰人王二偷走，又立牌「隔壁王二不曾偷」。\n字面意思：這裡沒有三百兩銀子。\n引申意思：想隱瞞反而自我暴露（如：急著澄清沒人問的事，此地無銀三百兩）。" },
  { id: "i767", grade: 12, term: "不打自招", zhuyin: "ㄅㄨˋ ㄉㄚˇ ㄗˋ ㄓㄠ", pinyin: "bù dǎ zì zhāo", meaning: "沒有拷問就自己招認，無意間暴露真相。", example: "他一慌就不打自招，說溜了嘴。",deep:"典故由來：明清小說常用語。\n字面意思：沒人拷打就自己招認。\n引申意思：無意間洩露自己的過錯或祕密（如：他一慌張就不打自招）。" },
  { id: "i768", grade: 12, term: "做賊心虛", zhuyin: "ㄗㄨㄛˋ ㄗㄟˊ ㄒㄧㄣ ㄒㄩ", pinyin: "zuò zéi xīn xū", meaning: "做了壞事心裡不安，怕被發覺。", example: "一被點名就臉色大變，做賊心虛。",deep:"典故由來：語本宋．《五燈會元》：「為賊人心虛。」\n字面意思：做了賊，心裡發虛。\n引申意思：做壞事怕被發覺而不安（如：他神色慌張，做賊心虛）。貶義。" },
  { id: "i769", grade: 12, term: "問心無愧", zhuyin: "ㄨㄣˋ ㄒㄧㄣ ㄨˊ ㄎㄨㄟˋ", pinyin: "wèn xīn wú kuì", meaning: "自問沒有對不起良心的地方。", example: "盡力而為，問心無愧就好。", syn: ["俯仰無愧"],deep:"典故由來：清代文獻常見；語意本於《孟子》「不愧不怍」。\n字面意思：問自己的良心，沒有慚愧。\n引申意思：自認無愧於心（如：盡力而為，問心無愧）。褒義。" },
  { id: "i770", grade: 12, term: "俯仰無愧", zhuyin: "ㄈㄨˇ ㄧㄤˇ ㄨˊ ㄎㄨㄟˋ", pinyin: "fǔ yǎng wú kuì", meaning: "對天對人都無所慚愧。", example: "一生清白，俯仰無愧。", misuse: "出自《孟子》「仰不愧於天，俯不怍於人」。",deep:"典故由來：語本《孟子．盡心上》：「仰不愧於天，俯不怍於人。」\n字面意思：抬頭低頭都無愧疚。\n引申意思：對天對人都問心無愧（如：一生行事俯仰無愧）。褒義。" },
  { id: "i771", grade: 12, term: "光明磊落", zhuyin: "ㄍㄨㄤ ㄇㄧㄥˊ ㄌㄟˇ ㄌㄨㄛˋ", pinyin: "guāng míng lěi luò", meaning: "心地坦白，行事正大。", example: "他做事光明磊落，禁得起檢驗。", syn: ["坦蕩無私"],deep:"典故由來：見朱熹語錄：「譬如人光明磊落底便是好人。」磊落＝石頭分明。\n字面意思：光明如日、磊落如石。\n引申意思：心地坦蕩、行事正大（如：為人光明磊落）。褒義。" },
  { id: "i772", grade: 12, term: "高風亮節", zhuyin: "ㄍㄠ ㄈㄥ ㄌㄧㄤˋ ㄐㄧㄝˊ", pinyin: "gāo fēng liàng jié", meaning: "高尚的品格與堅貞的節操。", example: "老先生高風亮節，深受敬重。", syn: ["德高望重"],deep:"典故由來：「高風」見《後漢書》讚高潔風範；後與「亮節」連用。\n字面意思：高尚的風範、堅貞的節操。\n引申意思：品格高尚（如：先生高風亮節，令人景仰）。褒義。" },
  { id: "i773", grade: 12, term: "潔身自愛", zhuyin: "ㄐㄧㄝˊ ㄕㄣ ㄗˋ ㄞˋ", pinyin: "jié shēn zì ài", meaning: "保持自身清白，不同流合汙。", example: "環境再亂，也要潔身自愛。", syn: ["出淤泥而不染"],deep:"典故由來：語本《孟子．萬章上》：「歸潔其身而已矣。」\n字面意思：保持自身潔淨並愛惜自己。\n引申意思：不同流合汙（如：亂世中潔身自愛）。褒義。" },
  { id: "i774", grade: 12, term: "出淤泥而不染", zhuyin: "ㄔㄨ ㄩ ㄋㄧˊ ㄦˊ ㄅㄨˋ ㄖㄢˇ", pinyin: "chū yū ní ér bù rǎn", meaning: "身處汙濁環境仍保持高潔。", example: "他在爾虞我詐的圈子裡出淤泥而不染。", misuse: "出自周敦頤〈愛蓮說〉。",deep:"典故由來：出自宋．周敦頤〈愛蓮說〉：「予獨愛蓮之出淤泥而不染，濯清漣而不妖。」\n字面意思：從汙泥中長出卻不被沾染。\n引申意思：身處惡劣環境仍保持高潔（如：他在染缸般的圈子裡出淤泥而不染）。褒義。" },
  { id: "i775", grade: 12, term: "同流合汙", zhuyin: "ㄊㄨㄥˊ ㄌㄧㄡˊ ㄏㄜˊ ㄨ", pinyin: "tóng liú hé wū", meaning: "跟壞人一起做壞事。", example: "他拒絕同流合汙，檢舉了圍標案。", syn: ["沆瀣一氣", "狼狽為奸"],deep:"典故由來：語本《孟子．盡心下》：「同乎流俗，合乎汙世。」\n字面意思：跟著汙流同行、與汙濁相合。\n引申意思：跟壞人一起做壞事（如：拒絕同流合汙）。貶義。" },
  { id: "i776", grade: 12, term: "狼狽為奸", zhuyin: "ㄌㄤˊ ㄅㄟˋ ㄨㄟˊ ㄐㄧㄢ", pinyin: "láng bèi wéi jiān", meaning: "互相勾結做壞事。", example: "業者與檢驗員狼狽為奸，偽造報告。", syn: ["沆瀣一氣"],deep:"典故由來：出自唐．段成式《酉陽雜俎》：傳說狽前腿短，須趴在狼身上同行，二獸相依為惡。\n字面意思：狼和狽勾結做壞事。\n引申意思：互相勾結作惡（如：兩人狼狽為奸，聯手詐騙）。貶義。" },
  { id: "i777", grade: 12, term: "助紂為虐", zhuyin: "ㄓㄨˋ ㄓㄡˋ ㄨㄟˊ ㄋㄩㄝˋ", pinyin: "zhù zhòu wéi nüè", meaning: "幫助壞人做壞事。", example: "明知是詐團還幫忙洗錢，形同助紂為虐。", misuse: "紂是商朝暴君。", syn: ["為虎作倀"],deep:"典故由來：語本《史記．留侯世家》：樊噲諫劉邦勿安享秦宮，「此所謂助桀為虐」；後亦作「助紂為虐」（桀、紂皆暴君）。\n字面意思：幫助暴君紂王施行暴虐。\n引申意思：幫壞人做壞事（如：提供資金給詐團形同助紂為虐）。貶義。" },
  { id: "i778", grade: 12, term: "為虎作倀", zhuyin: "ㄨㄟˊ ㄏㄨˇ ㄗㄨㄛˋ ㄔㄤ", pinyin: "wéi hǔ zuò chāng", meaning: "幫惡人為虎作亂害人。", example: "替黑心企業掩蓋事證，無異為虎作倀。", misuse: "「倀」讀ㄔㄤ，被虎咬死化為引路之鬼。",deep:"典故由來：出自宋代筆記（《太平廣記》）：傳說被虎咬死的人化為「倀鬼」，反而引導老虎吃人。\n字面意思：做老虎的倀鬼（替虎引路）。\n引申意思：甘心替惡人作幫兇（如：為虎作倀，欺壓同鄉）。貶義。" },
  { id: "i779", grade: 12, term: "仗義執言", zhuyin: "ㄓㄤˋ ㄧˋ ㄓˊ ㄧㄢˊ", pinyin: "zhàng yì zhí yán", meaning: "根據正義，說公道話。", example: "他仗義執言，替受屈的同事發聲。",deep:"典故由來：元明小說常用語；仗＝依恃。\n字面意思：依仗正義說出直話。\n引申意思：主持公道、敢說真話（如：他仗義執言，為弱者發聲）。褒義。" },
  { id: "i780", grade: 12, term: "捨己為人", zhuyin: "ㄕㄜˇ ㄐㄧˇ ㄨㄟˋ ㄖㄣˊ", pinyin: "shě jǐ wèi rén", meaning: "犧牲自己，成全別人。", example: "消防員捨己為人，令人動容。", syn: ["犧牲小我"],deep:"典故由來：由字面組合而成的常用語。\n字面意思：捨棄自己，成全別人。\n引申意思：犧牲自我利益幫助人（如：捨己為人的消防員）。褒義。" },
  { id: "i781", grade: 12, term: "急公好義", zhuyin: "ㄐㄧˊ ㄍㄨㄥ ㄏㄠˋ ㄧˋ", pinyin: "jí gōng hào yì", meaning: "熱心公益，喜歡助人。", example: "里長急公好義，鄰里大小事都幫。", misuse: "「好」讀ㄏㄠˋ。", syn: ["樂善好施"],deep:"典故由來：清代文獻常見；急＝熱心於。\n字面意思：熱心公益、愛好正義。\n引申意思：熱心助人、見義勇為（如：里長急公好義）。褒義。" },
  { id: "i782", grade: 12, term: "拔刀相助", zhuyin: "ㄅㄚˊ ㄉㄠ ㄒㄧㄤ ㄓㄨˋ", pinyin: "bá dāo xiāng zhù", meaning: "見義勇為，出手幫助。", example: "路見不平，拔刀相助。", syn: ["見義勇為"],deep:"典故由來：元代戲曲俗語：「路見不平，拔刀相助。」\n字面意思：拔出刀來幫助（受欺的人）。\n引申意思：見義勇為（如：路見不平拔刀相助）。褒義。" },
  { id: "i783", grade: 12, term: "有志竟成", zhuyin: "ㄧㄡˇ ㄓˋ ㄐㄧㄥˋ ㄔㄥˊ", pinyin: "yǒu zhì jìng chéng", meaning: "有決心的人終能成功。", example: "有志竟成，他終於考取飛行員。", misuse: "出自《後漢書》「有志者事竟成」。",deep:"典故由來：出自《後漢書．耿弇傳》：光武帝讚耿弇「將軍前在南陽建此大策，常以為落落難合，有志者事竟成也」。\n字面意思：有志向的人終能成功。\n引申意思：立定志向堅持必成（如：有志竟成，他終於圓夢）。褒義。" },
  { id: "i784", grade: 12, term: "精衛填海", zhuyin: "ㄐㄧㄥ ㄨㄟˋ ㄊㄧㄢˊ ㄏㄞˇ", pinyin: "jīng wèi tián hǎi", meaning: "意志堅定，不畏艱難地奮鬥到底。", example: "以精衛填海的毅力，他填補了資料庫的每個漏洞。", misuse: "炎帝之女化鳥銜石填海的神話。", syn: ["愚公移山"],deep:"典故由來：出自《山海經．北山經》：炎帝之女溺死東海，化為精衛鳥，常銜西山木石填海。\n字面意思：精衛鳥銜石填海。\n引申意思：意志堅定、不畏艱難奮鬥到底（如：以精衛填海的毅力治沙）。褒義。" },
  { id: "i785", grade: 12, term: "夸父追日", zhuyin: "ㄎㄨㄚ ㄈㄨˇ ㄓㄨㄟ ㄖˋ", pinyin: "kuā fǔ zhuī rì", meaning: "決心宏大，也喻不自量力。", example: "有人笑他夸父追日，他仍堅持研發新能源。", misuse: "神話人物，「父」讀ㄈㄨˇ。",deep:"典故由來：出自《山海經．海外北經》：夸父與日逐走，渴死道中，杖化鄧林。\n字面意思：夸父追趕太陽。\n引申意思：志向宏大勇於追求；也喻不自量力（如：明知艱難仍夸父追日般堅持）。" },
  { id: "i786", grade: 12, term: "磨杵成針", zhuyin: "ㄇㄛˊ ㄔㄨˇ ㄔㄥˊ ㄓㄣ", pinyin: "mó chǔ chéng zhēn", meaning: "鐵杵磨成繡花針，功到自然成。", example: "只要有恆心，磨杵成針。", misuse: "李白遇老媼磨杵的典故。", syn: ["滴水穿石"],deep:"典故由來：出自宋．祝穆《方輿勝覽》：李白少年棄學，見老婦磨鐵杵，答「欲作針」，白感悟發憤終成大家。\n字面意思：鐵杵磨成繡花針。\n引申意思：有恆心必能成功（如：只要功夫深，磨杵成針）。褒義。" },
  { id: "i787", grade: 12, term: "跛鱉千里", zhuyin: "ㄅㄛˇ ㄅㄧㄝ ㄑㄧㄢ ㄌㄧˇ", pinyin: "bǒ biē qiān lǐ", meaning: "跛腳的鱉努力不懈也能走千里。", example: "資質平平不要緊，跛鱉千里，貴在不停。", misuse: "出自《荀子・修身》。",deep:"典故由來：出自《荀子．修身》：「故蹞步而不休，跛鱉千里。」\n字面意思：跛腳的鱉不停地走，也能走千里。\n引申意思：資質差但不懈怠終能成功（如：跛鱉千里，貴在堅持）。褒義。" },
  { id: "i788", grade: 12, term: "駑馬十駕", zhuyin: "ㄋㄨˊ ㄇㄚˇ ㄕˊ ㄐㄧㄚˋ", pinyin: "nú mǎ shí jià", meaning: "劣馬走十天也能到達駿馬一日的路程，勤能補拙。", example: "駑馬十駕，功在不舍，他終於追上進度。", misuse: "出自《荀子・勸學》。「駑」是劣馬。",deep:"典故由來：出自《荀子．勸學》：「駑馬十駕，功在不舍。」劣馬拉車走十天，也能到達駿馬一日的路程。\n字面意思：劣馬拉車十天（也能到遠方）。\n引申意思：勤能補拙（如：我資質平平，願學駑馬十駕）。褒義。" },
  { id: "i789", grade: 12, term: "笨鳥先飛", zhuyin: "ㄅㄣˋ ㄋㄧㄠˇ ㄒㄧㄢ ㄈㄟ", pinyin: "bèn niǎo xiān fēi", meaning: "能力差的人先行動，以免落後。", example: "我理解慢，就笨鳥先飛提前預習。", syn: ["駑馬十駕"],deep:"典故由來：出自元．關漢卿《陳母教子》：「我似那靈禽在後，你這等坌（笨）鳥先飛。」\n字面意思：笨的鳥先起飛。\n引申意思：能力差的人先行動以免落後（如：笨鳥先飛，我提早準備）。多作自謙。" },
  { id: "i790", grade: 12, term: "懸崖勒馬", zhuyin: "ㄒㄩㄢˊ ㄧㄞˊ ㄌㄜˋ ㄇㄚˇ", pinyin: "xuán yái lè mǎ", meaning: "在危險邊緣及時醒悟回頭。", example: "染上賭癮的他懸崖勒馬，戒賭重生。", misuse: "「崖」審訂音ㄧㄞˊ。", syn: ["迷途知返"],deep:"典故由來：清代文獻常見。\n字面意思：在懸崖邊勒住馬。\n引申意思：臨危及時醒悟回頭（如：賭徒懸崖勒馬，戒賭重生）。褒義。" },
  { id: "i791", grade: 12, term: "見賢思齊", zhuyin: "ㄐㄧㄢˋ ㄒㄧㄢˊ ㄙ ㄑㄧˊ", pinyin: "jiàn xián sī qí", meaning: "看見賢者就想向他看齊。", example: "見賢思齊，他以學姊為榜樣。", misuse: "出自《論語》，後句「見不賢而內自省」。",deep:"典故由來：出自《論語．里仁》：「見賢思齊焉，見不賢而內自省也。」\n字面意思：見到賢者就想向他看齊。\n引申意思：以賢者為榜樣自我提升（如：見賢思齊，向學長學習）。褒義。" },
  { id: "i792", grade: 12, term: "三省吾身", zhuyin: "ㄙㄢ ㄒㄧㄥˇ ㄨˊ ㄕㄣ", pinyin: "sān xǐng wú shēn", meaning: "每天多次反省自己。", example: "他睡前寫日記三省吾身。", misuse: "「省」讀ㄒㄧㄥˇ。出自《論語》曾子語。",deep:"典故由來：出自《論語．學而》：曾子曰：「吾日三省吾身——為人謀而不忠乎？與朋友交而不信乎？傳不習乎？」\n字面意思：每天多次反省自己。\n引申意思：時時自我檢討（如：三省吾身，日日精進）。褒義。" },
  { id: "i793", grade: 12, term: "迷途知返", zhuyin: "ㄇㄧˊ ㄊㄨˊ ㄓ ㄈㄢˇ", pinyin: "mí tú zhī fǎn", meaning: "迷失道路後知道回頭。", example: "他迷途知返，重回校園完成學業。", syn: ["懸崖勒馬", "浪子回頭"],deep:"典故由來：語本《三國志．袁術傳》：陳珪書「若迷而知反，尚可以免」。\n字面意思：迷了路知道回頭。\n引申意思：犯錯後能醒悟改正（如：迷途知返，善莫大焉）。褒義。" },
  { id: "i794", grade: 12, term: "從善如流", zhuyin: "ㄘㄨㄥˊ ㄕㄢˋ ㄖㄨˊ ㄌㄧㄡˊ", pinyin: "cóng shàn rú liú", meaning: "樂於接受好的意見，像水順流般自然。", example: "主管從善如流，立刻採納建議。", syn: ["虛懷若谷"],deep:"典故由來：出自《左傳．成公八年》：讚欒書「從善如流，宜哉」。\n字面意思：聽從好意見像水順流而下。\n引申意思：樂於接受勸告（如：主管從善如流，立即改進）。褒義。" },
  { id: "i795", grade: 12, term: "虛懷若谷", zhuyin: "ㄒㄩ ㄏㄨㄞˊ ㄖㄨㄛˋ ㄍㄨˇ", pinyin: "xū huái ruò gǔ", meaning: "胸懷像山谷一樣深廣，非常謙虛。", example: "大師虛懷若谷，仍向後輩請教。", misuse: "出自《老子》。", syn: ["從善如流"],deep:"典故由來：語本《老子》：「敦兮其若樸，曠兮其若谷。」\n字面意思：胸懷像山谷一樣空闊。\n引申意思：非常謙虛能容（如：大師虛懷若谷）。褒義。" },
  { id: "i796", grade: 12, term: "浪子回頭", zhuyin: "ㄌㄤˋ ㄗˇ ㄏㄨㄟˊ ㄊㄡˊ", pinyin: "làng zǐ huí tóu", meaning: "不務正業的人悔改向善。", example: "浪子回頭金不換，他如今是志工隊長。", syn: ["迷途知返"],deep:"典故由來：明清俗諺：「浪子回頭金不換。」\n字面意思：遊蕩敗家的人回頭了。\n引申意思：不務正業者悔改向善（如：他浪子回頭，重拾學業）。褒義。" },
  { id: "i797", grade: 12, term: "功成不居", zhuyin: "ㄍㄨㄥ ㄔㄥˊ ㄅㄨˋ ㄐㄩ", pinyin: "gōng chéng bù jū", meaning: "建立功勞而不自居其功。", example: "他功成不居，把榮耀歸給團隊。", misuse: "出自《老子》。「居」是占有。",deep:"典故由來：出自《老子》：「生而不有，為而不恃，功成而弗居。」\n字面意思：功業完成而不占著功勞。\n引申意思：有功而不自誇（如：他功成不居，把榮耀歸給團隊）。褒義。" },
  { id: "i798", grade: 12, term: "居功厥偉", zhuyin: "ㄐㄩ ㄍㄨㄥ ㄐㄩㄝˊ ㄨㄟˇ", pinyin: "jū gōng jué wěi", meaning: "所建立的功勞非常大。", example: "台灣半導體的成就，他居功厥偉。", misuse: "「厥」是其。褒義，與自誇的「居功自傲」不同。",deep:"典故由來：近代組合語；「厥」是「其」的文言用法。\n字面意思：所建立的功勞非常偉大。\n引申意思：功勞極大（如：對建校居功厥偉）。褒義；注意不作「居功自傲」解。" },
  { id: "i799", grade: 12, term: "汗馬功勞", zhuyin: "ㄏㄢˋ ㄇㄚˇ ㄍㄨㄥ ㄌㄠˊ", pinyin: "hàn mǎ gōng láo", meaning: "作戰或工作中立下的大功勞。", example: "開疆闢土，他立下汗馬功勞。",deep:"典故由來：出自《韓非子．五蠹》：「棄私家之事，而必汗馬之勞。」戰馬奔馳出汗，指征戰辛勞。\n字面意思：戰馬出汗（換來）的功勞。\n引申意思：征戰或工作中立下的大功（如：他為公司立下汗馬功勞）。褒義。" },
  { id: "i800", grade: 12, term: "功敗垂成", zhuyin: "ㄍㄨㄥ ㄅㄞˋ ㄔㄨㄟˊ ㄔㄥˊ", pinyin: "gōng bài chuí chéng", meaning: "事情在即將成功時失敗了。", example: "最後一關失誤，功敗垂成，令人扼腕。", misuse: "「垂」是將近。", syn: ["前功盡棄"],deep:"典故由來：出自《晉書．謝玄傳論》：「降齡何促，功敗垂成。」惋惜謝玄北伐將成而病逝。\n字面意思：功業在即將完成時失敗（垂＝將近）。\n引申意思：事情在快成功時失敗（如：最後一關失誤，功敗垂成）。含惋惜意味。" },
  { id: "i801", grade: 1, term: "一石二鳥", zhuyin: "ㄧ ㄕˊ ㄦˋ ㄋㄧㄠˇ", pinyin: "yī shí èr niǎo", meaning: "做一件事同時得到兩種好處。", example: "騎車上學既省錢又能運動，真是一石二鳥。", wordExp: "一石＝一顆石頭；二鳥＝兩隻鳥。丟一顆石頭打中兩隻鳥。", deep: "典故由來：源自西方諺語 kill two birds with one stone 的翻譯，與「一舉兩得」「一箭雙鵰」意思相同。\n字面意思：投一顆石子，同時打中兩隻鳥。\n引申意思：做一件事同時收到兩種效果（如：邊聽廣播邊學英文，一石二鳥）。" },
  { id: "i802", grade: 1, term: "大驚小怪", zhuyin: "ㄉㄚˋ ㄐㄧㄥ ㄒㄧㄠˇ ㄍㄨㄞˋ", pinyin: "dà jīng xiǎo guài", meaning: "為了不重要的小事過分驚訝。", example: "只是一隻小壁虎而已，你不要大驚小怪。", wordExp: "大驚＝非常吃驚；小怪＝對小事覺得奇怪。對小事情反應過度。", deep: "典故由來：宋代朱熹書信中已有「無大驚小怪」的用法，是流傳已久的口語成語。\n字面意思：小小的事情卻大大地吃驚。\n引申意思：形容為不足為奇的小事過度緊張、反應誇張（如：打雷而已，別大驚小怪）。含勸人冷靜的意味。" },
  { id: "i803", grade: 1, term: "早出晚歸", zhuyin: "ㄗㄠˇ ㄔㄨ ㄨㄢˇ ㄍㄨㄟ", pinyin: "zǎo chū wǎn guī", meaning: "早上出門，很晚才回家，形容辛勤忙碌。", example: "爸爸為了養家，每天早出晚歸地工作。", wordExp: "早出＝一早出門；晚歸＝很晚回家。天亮出門天黑回家。", deep: "典故由來：由日常生活語彙組成，《戰國策》已有「早出晚歸」描述人民勞作的說法。\n字面意思：清早出門，夜晚才回來。\n引申意思：形容工作辛勞、整天在外奔波（如：農忙時節，農人早出晚歸）。" },
  { id: "i804", grade: 1, term: "大街小巷", zhuyin: "ㄉㄚˋ ㄐㄧㄝ ㄒㄧㄠˇ ㄒㄧㄤˋ", pinyin: "dà jiē xiǎo xiàng", meaning: "城裡所有的街道巷弄，指每個角落。", example: "過年前，大街小巷都掛起了紅燈籠。", wordExp: "大街＝寬大的馬路；小巷＝窄小的巷子。大路和小巷全包括。", deep: "典故由來：出自明清小說的常用語，《水滸傳》即有「大街小巷」的寫法。\n字面意思：寬闊的街道與狹窄的巷弄。\n引申意思：指城鎮的每一個角落、到處（如：消息傳遍了大街小巷）。" },
  { id: "i805", grade: 1, term: "心花怒放", zhuyin: "ㄒㄧㄣ ㄏㄨㄚ ㄋㄨˋ ㄈㄤˋ", pinyin: "xīn huā nù fàng", meaning: "心裡高興得像花朵盛開一樣。", example: "聽到要去遊樂園，弟弟高興得心花怒放。", wordExp: "心花＝心裡的花；怒放＝盛大地開放。心中的花全開了。", deep: "典故由來：清代小說《文明小史》等已見使用；「怒」在此不是生氣，是氣勢旺盛的意思。\n字面意思：心裡的花朵猛烈盛開。\n引申意思：形容高興到了極點（如：收到錄取通知，他心花怒放）。「怒放」的「怒」是旺盛、不是憤怒，這是本成語的重點。" },
  { id: "i806", grade: 1, term: "七手八腳", zhuyin: "ㄑㄧ ㄕㄡˇ ㄅㄚ ㄐㄧㄠˇ", pinyin: "qī shǒu bā jiǎo", meaning: "很多人一起動手，忙亂沒有條理的樣子。", example: "大家七手八腳地把教室布置好了。", wordExp: "七、八＝形容多而雜；手、腳＝動作。很多雙手腳一起動。", deep: "典故由來：出自宋代《續傳燈錄》：「上堂七手八腳，三頭兩面。」原是禪宗形容忙亂的話。\n字面意思：好像有七隻手、八隻腳一起動作。\n引申意思：人多手雜、大家一擁而上做事的樣子（如：眾人七手八腳把行李搬上車）。可形容熱心幫忙，也可形容忙中無序。" },
  { id: "i807", grade: 1, term: "三長兩短", zhuyin: "ㄙㄢ ㄔㄤˊ ㄌㄧㄤˇ ㄉㄨㄢˇ", pinyin: "sān cháng liǎng duǎn", meaning: "指意外的災禍或事故，多指生命危險。", example: "爺爺身體不好，萬一有個三長兩短怎麼辦？", wordExp: "三、兩＝幾個；長、短＝長短不齊的變故。指預料不到的意外。", deep: "典故由來：一說與棺木由三塊長板、兩塊短板構成有關，所以借指人的死亡與意外。\n字面意思：三個長的、兩個短的（不齊全的變故）。\n引申意思：委婉指意外、不幸，特別是生命危險（如：注意安全，別有什麼三長兩短）。多用在擔憂的語氣裡。" },
  { id: "i808", grade: 1, term: "眼明手快", zhuyin: "ㄧㄢˇ ㄇㄧㄥˊ ㄕㄡˇ ㄎㄨㄞˋ", pinyin: "yǎn míng shǒu kuài", meaning: "眼睛看得準，動作又敏捷。", example: "他眼明手快，一把接住掉下來的杯子。", wordExp: "眼明＝眼力好；手快＝動作快。看得準、出手快。", deep: "典故由來：出自元代雜劇的口語，《水滸傳》中也常見「眼明手快」形容好漢身手。\n字面意思：眼睛明亮，手腳快速。\n引申意思：形容反應靈敏、動作俐落（如：守門員眼明手快地撲住了球）。" },
  { id: "i809", grade: 2, term: "說三道四", zhuyin: "ㄕㄨㄛ ㄙㄢ ㄉㄠˋ ㄙˋ", pinyin: "shuō sān dào sì", meaning: "隨意批評、議論別人的事。", example: "不要在背後說三道四，有話當面講清楚。", wordExp: "說、道＝講；三、四＝這個那個。東講一句西講一句。", deep: "典故由來：由口語演變而成的俗語式成語，「三」「四」泛指雜七雜八的話。\n字面意思：說完三又講四，講個不停。\n引申意思：胡亂批評、背後議論他人（如：他最討厭別人對他的家事說三道四）。貶義。" },
  { id: "i810", grade: 2, term: "九霄雲外", zhuyin: "ㄐㄧㄡˇ ㄒㄧㄠ ㄩㄣˊ ㄨㄞˋ", pinyin: "jiǔ xiāo yún wài", meaning: "形容非常遙遠的地方，或忘得一乾二淨。", example: "一放暑假，他就把功課拋到九霄雲外了。", wordExp: "九霄＝天空的最高處；雲外＝雲層之外。天上最高最遠的地方。", deep: "典故由來：古人把天分為九重（九霄），最高一層叫「神霄」；元曲已見「九霄雲外」的用法。\n字面意思：高天之上、雲層之外。\n引申意思：極遙遠的地方；把事情忘得無影無蹤（如：緊張的心情早飛到九霄雲外）。" },
  { id: "i811", grade: 2, term: "度日如年", zhuyin: "ㄉㄨˋ ㄖˋ ㄖㄨˊ ㄋㄧㄢˊ", pinyin: "dù rì rú nián", meaning: "日子難熬，過一天像過一年那麼長。", example: "住院的那幾天，他覺得度日如年。", wordExp: "度＝過；日＝一天；如年＝像一年。過一天像過一年。", deep: "典故由來：出自宋代柳永〈戚氏〉詞：「孤館度日如年。」寫旅居孤獨、時間難熬。\n字面意思：過一天如同過一年。\n引申意思：形容日子痛苦難捱、時間漫長（如：等待放榜的日子度日如年）。" },
  { id: "i812", grade: 2, term: "日新月異", zhuyin: "ㄖˋ ㄒㄧㄣ ㄩㄝˋ ㄧˋ", pinyin: "rì xīn yuè yì", meaning: "每天每月都有新變化，進步非常快。", example: "科技日新月異，手機功能越來越強大。", wordExp: "日新＝天天更新；月異＝月月不同。天天有新面貌。", deep: "典故由來：語本《禮記．大學》：「苟日新，日日新，又日新。」商湯把這句話刻在洗澡盆上，提醒自己天天進步。\n字面意思：每天更新，每月不同。\n引申意思：形容發展變化極快、不斷進步（如：市容日新月異）。褒義。" },
  { id: "i813", grade: 2, term: "龍飛鳳舞", zhuyin: "ㄌㄨㄥˊ ㄈㄟ ㄈㄥˋ ㄨˇ", pinyin: "lóng fēi fèng wǔ", meaning: "形容書法筆勢活潑奔放，也戲稱字跡潦草。", example: "黑板上那行龍飛鳳舞的大字，是老師的墨寶。", wordExp: "龍飛＝像龍騰飛；鳳舞＝像鳳飛舞。筆勢像龍鳳飛騰。", deep: "典故由來：宋代蘇軾〈表忠觀碑〉有「天目之山，苕水出焉，龍飛鳳舞，萃於臨安」之語，本形容山勢奔放。\n字面意思：如龍騰飛、如鳳起舞。\n引申意思：形容書法灑脫有氣勢；口語中也戲稱字跡潦草難認（如：他的簽名龍飛鳳舞）。" },
  { id: "i814", grade: 2, term: "快馬加鞭", zhuyin: "ㄎㄨㄞˋ ㄇㄚˇ ㄐㄧㄚ ㄅㄧㄢ", pinyin: "kuài mǎ jiā biān", meaning: "對跑得快的馬再加鞭子，比喻加速進行。", example: "工程進度落後，工人們快馬加鞭趕工。", wordExp: "快馬＝跑得快的馬；加鞭＝再抽鞭子。讓快馬跑得更快。", deep: "典故由來：語見宋代王安石詩與《孟子》註疏引俗語，形容催趕行程。\n字面意思：騎著快馬還不斷揮鞭。\n引申意思：加緊速度、全力趕辦（如：距離交件只剩三天，大家快馬加鞭）。" },
  { id: "i815", grade: 2, term: "馬不停蹄", zhuyin: "ㄇㄚˇ ㄅㄨˋ ㄊㄧㄥˊ ㄊㄧˊ", pinyin: "mǎ bù tíng tí", meaning: "馬蹄不停，比喻一刻也不休息地連續進行。", example: "他下了飛機就馬不停蹄地趕到會場。", wordExp: "馬＝坐騎；不停蹄＝蹄子不停下。馬一路跑不休息。", deep: "典故由來：出自元代王實甫《麗春堂》：「贏的他急難措手，打的他馬不停蹄。」\n字面意思：馬跑個不停，蹄子沒有停歇。\n引申意思：連續不斷地奔走、做事不休息（如：選手馬不停蹄地南北參賽）。" },
  { id: "i816", grade: 2, term: "走馬看花", zhuyin: "ㄗㄡˇ ㄇㄚˇ ㄎㄢˋ ㄏㄨㄚ", pinyin: "zǒu mǎ kàn huā", meaning: "騎在奔跑的馬上看花，比喻粗略地觀察。", example: "三天玩五個城市，只能走馬看花。", wordExp: "走馬＝騎馬奔馳；看花＝賞花。騎在馬上匆匆賞花。", deep: "典故由來：出自唐代孟郊〈登科後〉：「春風得意馬蹄疾，一日看盡長安花。」原寫考中進士的暢快，後轉指匆匆瀏覽。\n字面意思：騎著奔跑的馬賞花。\n引申意思：匆促、粗略地觀察事物，不深入（如：走馬看花的參觀，學不到精髓）。" },
  { id: "i817", grade: 2, term: "汗流浹背", zhuyin: "ㄏㄢˋ ㄌㄧㄡˊ ㄐㄧㄚˊ ㄅㄟˋ", pinyin: "hàn liú jiá bèi", meaning: "汗水濕透背部，形容非常辛勞或極度緊張。", example: "球員們練到汗流浹背，仍不肯休息。", wordExp: "汗流＝流汗；浹＝濕透；背＝背部。汗水濕透了整個背。", deep: "典故由來：出自《史記．陳丞相世家》：漢文帝問政，周勃答不出來，「汗出沾背」，慚愧不安。\n字面意思：汗水流得濕透背脊。\n引申意思：形容勞動辛苦或緊張慚愧（如：搬了一下午家具，人人汗流浹背）。「浹」是濕透，不要寫成「夾」。" },
  { id: "i818", grade: 2, term: "舉手之勞", zhuyin: "ㄐㄩˇ ㄕㄡˇ ㄓ ㄌㄠˊ", pinyin: "jǔ shǒu zhī láo", meaning: "舉一下手的力氣，形容毫不費力的小事。", example: "隨手關燈只是舉手之勞，卻能節能減碳。", wordExp: "舉手＝抬一下手；之勞＝的辛勞。抬手就能完成的事。", deep: "典故由來：語本唐代韓愈〈應科目時與人書〉：「如有力者，哀其窮而運轉之，蓋一舉手一投足之勞也。」\n字面意思：只花抬一下手的力氣。\n引申意思：極容易、不費事的幫忙（如：幫忙撿個東西是舉手之勞）。常用於自謙或請託。" },
  { id: "i819", grade: 2, term: "輕而易舉", zhuyin: "ㄑㄧㄥ ㄦˊ ㄧˋ ㄐㄩˇ", pinyin: "qīng ér yì jǔ", meaning: "很輕鬆、毫不費力就能做到。", example: "這箱子不重，他輕而易舉就搬起來了。", wordExp: "輕＝分量輕；易舉＝容易舉起。輕得一下就舉起來。", deep: "典故由來：語本《詩經．大雅．烝民》「德輶如毛，民鮮克舉之」的朱熹註：「言人皆言德甚輕而易舉，然人莫能舉也。」\n字面意思：東西很輕，容易舉起。\n引申意思：事情容易辦到、毫不費力（如：對冠軍隊來說，贏這場球輕而易舉）。" },
  { id: "i820", grade: 2, term: "東拼西湊", zhuyin: "ㄉㄨㄥ ㄆㄧㄣ ㄒㄧ ㄘㄡˋ", pinyin: "dōng pīn xī còu", meaning: "到處拼湊、七拼八湊地聚集起來。", example: "他東拼西湊，總算籌到了報名費。", wordExp: "東、西＝到處；拼、湊＝拼合聚集。這裡湊一點那裡湊一點。", deep: "典故由來：明清白話小說常用語，《紅樓夢》中即有「東拼西湊」的說法。\n字面意思：東邊拼一塊，西邊湊一塊。\n引申意思：零零碎碎地拼合，多指勉強湊足錢財或材料（如：報告內容東拼西湊，缺乏條理）。" },
  { id: "i821", grade: 2, term: "風雨無阻", zhuyin: "ㄈㄥ ㄩˇ ㄨˊ ㄗㄨˇ", pinyin: "fēng yǔ wú zǔ", meaning: "颳風下雨都不能阻擋，照常進行。", example: "爺爺每天清晨到公園運動，風雨無阻。", wordExp: "風雨＝颳風下雨；無阻＝不能阻擋。壞天氣也擋不住。", deep: "典故由來：由「風雨不改」演變的常用語，明清小說書信中常見。\n字面意思：風雨都無法阻擋。\n引申意思：無論遇到什麼困難都堅持照常進行（如：送報伕風雨無阻地工作）。褒義，強調恆心。" },
  { id: "i822", grade: 3, term: "白手起家", zhuyin: "ㄅㄞˊ ㄕㄡˇ ㄑㄧˇ ㄐㄧㄚ", pinyin: "bái shǒu qǐ jiā", meaning: "不靠背景資本，憑自己的努力創立事業。", example: "王伯伯白手起家，從路邊攤做到連鎖餐廳。", wordExp: "白手＝空手、一無所有；起家＝建立家業。空著手建立起家業。", deep: "典故由來：「起家」語出《史記》，指從平民起用；「白手」指空無所有，合成後形容從零開始創業。\n字面意思：空著兩手建立家業。\n引申意思：沒有依靠、全憑自己奮鬥而成功（如：這位企業家白手起家的故事激勵人心）。褒義。" },
  { id: "i823", grade: 3, term: "半斤八兩", zhuyin: "ㄅㄢˋ ㄐㄧㄣ ㄅㄚ ㄌㄧㄤˇ", pinyin: "bàn jīn bā liǎng", meaning: "彼此程度相當，不相上下（多含貶義）。", example: "你們兩個都遲到，半斤八兩，誰也別笑誰。", wordExp: "半斤＝八兩（古制一斤十六兩）。半斤正好等於八兩。", deep: "典故由來：古代一斤為十六兩，半斤恰好是八兩，兩者完全相等；宋代已見此語。\n字面意思：半斤和八兩一樣重。\n引申意思：雙方一樣，難分高下，常用於彼此都不怎麼樣的情況（如：這兩隊實力半斤八兩）。" },
  { id: "i824", grade: 3, term: "舉世聞名", zhuyin: "ㄐㄩˇ ㄕˋ ㄨㄣˊ ㄇㄧㄥˊ", pinyin: "jǔ shì wén míng", meaning: "全世界都知道，名聲極大。", example: "故宮的文物收藏舉世聞名。", wordExp: "舉世＝全世界；聞名＝聽過名聲。全世界都聽過它的名字。", deep: "典故由來：「舉世」語出《莊子．逍遙遊》「舉世譽之而不加勸」；後與「聞名」結合成語。\n字面意思：全世界都聽聞其名。\n引申意思：名聲響亮、世界知名（如：玉山的美景舉世聞名）。近義：舉世皆知、名聞遐邇。" },
  { id: "i825", grade: 3, term: "別有洞天", zhuyin: "ㄅㄧㄝˊ ㄧㄡˇ ㄉㄨㄥˋ ㄊㄧㄢ", pinyin: "bié yǒu dòng tiān", meaning: "另有一番美妙的境界。", example: "穿過窄窄的巷口，裡面竟別有洞天，是座美麗的花園。", wordExp: "別有＝另外有；洞天＝神仙住的洞府。另有一處仙境。", deep: "典故由來：道教稱神仙居住的名山勝境為「洞天福地」；唐代李白〈山中問答〉「別有天地非人間」意境相近。\n字面意思：另外有一個神仙洞府。\n引申意思：另有一番奇妙天地或境界（如：這家小店地下室別有洞天）。" },
  { id: "i826", grade: 3, term: "面黃肌瘦", zhuyin: "ㄇㄧㄢˋ ㄏㄨㄤˊ ㄐㄧ ㄕㄡˋ", pinyin: "miàn huáng jī shòu", meaning: "臉色發黃、身體消瘦，形容營養不良或有病。", example: "那隻流浪狗面黃肌瘦，看了令人心疼。", wordExp: "面黃＝臉色蠟黃；肌瘦＝肌肉消瘦。臉黃身體瘦。", deep: "典故由來：元明雜劇小說常用語，形容饑民與病人的樣貌。\n字面意思：臉色枯黃，肌肉消瘦。\n引申意思：形容營養不良、健康狀況差（如：災民個個面黃肌瘦）。相對詞：紅光滿面。" },
  { id: "i827", grade: 3, term: "骨瘦如柴", zhuyin: "ㄍㄨˇ ㄕㄡˋ ㄖㄨˊ ㄔㄞˊ", pinyin: "gǔ shòu rú chái", meaning: "瘦得只剩骨頭，像木柴一樣。", example: "大病一場後，他變得骨瘦如柴。", wordExp: "骨瘦＝瘦到見骨；如柴＝像柴棒。瘦得像乾柴棒。", deep: "典故由來：宋代《五燈會元》已見「瘦如柴」的形容，後定型為四字成語。\n字面意思：瘦得骨頭像乾柴。\n引申意思：極度消瘦（如：非洲飢荒的孩童骨瘦如柴）。相對詞：大腹便便、腦滿腸肥。" },
  { id: "i828", grade: 3, term: "虎背熊腰", zhuyin: "ㄏㄨˇ ㄅㄟˋ ㄒㄩㄥˊ ㄧㄠ", pinyin: "hǔ bèi xióng yāo", meaning: "背寬腰粗，形容身材魁梧強壯。", example: "舉重選手個個虎背熊腰，力大無窮。", wordExp: "虎背＝像老虎的背；熊腰＝像熊的腰。背像虎、腰像熊。", deep: "典故由來：出自元代雜劇《飛刀對箭》：「這廝虎背熊腰，一貌非俗。」\n字面意思：老虎般的背、熊一般的腰。\n引申意思：形容體格健壯魁梧（如：他長得虎背熊腰，是天生的運動員）。多形容男性。" },
  { id: "i829", grade: 3, term: "揮汗如雨", zhuyin: "ㄏㄨㄟ ㄏㄢˋ ㄖㄨˊ ㄩˇ", pinyin: "huī hàn rú yǔ", meaning: "揮灑的汗水像下雨，形容天熱或勞動辛苦。", example: "盛夏的工地上，工人們揮汗如雨。", wordExp: "揮汗＝甩去汗水；如雨＝像下雨。汗水甩出去像下雨。", deep: "典故由來：出自《戰國策．齊策》：蘇秦形容臨淄人多，「揮汗成雨」——大家一起甩汗就像下雨。\n字面意思：揮灑汗水如同下雨。\n引申意思：形容流汗極多、辛勤勞動（如：選手在烈日下揮汗如雨地練習）。" },
  { id: "i830", grade: 4, term: "眉飛色舞", zhuyin: "ㄇㄟˊ ㄈㄟ ㄙㄜˋ ㄨˇ", pinyin: "méi fēi sè wǔ", meaning: "眉毛飛揚、神采飛舞，形容非常得意高興。", example: "說起自己的得意作品，他立刻眉飛色舞。", wordExp: "眉飛＝眉毛揚起；色舞＝神色飛舞。眉毛神色都在跳舞。", deep: "典故由來：清代小說《官場現形記》：「王主事一聽此言，不禁眉飛色舞。」\n字面意思：眉毛飛揚，臉色生動如舞。\n引申意思：喜悅得意、神采煥發的樣子（如：他眉飛色舞地描述奪冠經過）。" },
  { id: "i831", grade: 4, term: "呆若木雞", zhuyin: "ㄉㄞ ㄖㄨㄛˋ ㄇㄨˋ ㄐㄧ", pinyin: "dāi ruò mù jī", meaning: "像木頭雞一樣發呆，形容嚇傻或愣住的樣子。", example: "聽到這個驚人的消息，大家都呆若木雞。", wordExp: "呆＝發愣；若＝好像；木雞＝木頭做的雞。愣得像木雕的雞。", deep: "典故由來：出自《莊子．達生》：紀渻子為齊王養鬥雞，養到「望之似木雞」，別的雞一看就逃——原本是讚美精神內斂的最高境界，後世轉為發愣之義。\n字面意思：呆得像木頭刻的雞。\n引申意思：因驚嚇或意外而發愣（如：被突如其來的巨響嚇得呆若木雞）。原典為褒義、今義為驚呆，是語義轉變的著名例子。" },
  { id: "i832", grade: 4, term: "千叮萬囑", zhuyin: "ㄑㄧㄢ ㄉㄧㄥ ㄨㄢˋ ㄓㄨˇ", pinyin: "qiān dīng wàn zhǔ", meaning: "一再叮嚀交代，非常不放心。", example: "出門前，媽媽千叮萬囑要我過馬路小心。", wordExp: "千、萬＝許多次；叮、囑＝叮嚀交代。叮嚀了一千遍一萬遍。", deep: "典故由來：出自元代雜劇《瀟湘雨》：「我將這角文書千叮萬囑。」\n字面意思：叮嚀千次、囑咐萬次。\n引申意思：反覆再三地交代，形容關切掛心（如：教練千叮萬囑比賽的注意事項）。" },
  { id: "i833", grade: 4, term: "精打細算", zhuyin: "ㄐㄧㄥ ㄉㄚˇ ㄒㄧˋ ㄙㄨㄢˋ", pinyin: "jīng dǎ xì suàn", meaning: "精細地計劃盤算，不浪費一分一毫。", example: "媽媽精打細算，把家裡開銷管理得井井有條。", wordExp: "精、細＝精細；打、算＝盤算計畫。仔仔細細地計算。", deep: "典故由來：近代口語成語，「打算盤」的引申——算盤打得精、算得細。\n字面意思：精細地打算盤、計算。\n引申意思：仔細規劃用度、不浪費（如：出國旅行要精打細算才夠用）。褒義。" },
  { id: "i834", grade: 4, term: "開源節流", zhuyin: "ㄎㄞ ㄩㄢˊ ㄐㄧㄝˊ ㄌㄧㄡˊ", pinyin: "kāi yuán jié liú", meaning: "開拓收入來源，節省支出，使財務健全。", example: "公司經營困難，必須開源節流才能撐過去。", wordExp: "開源＝開發水源（收入）；節流＝節制水流（支出）。", deep: "典故由來：語本《荀子．富國》：「故明主必謹養其和，節其流，開其源。」把財政比喻成水源與水流。\n字面意思：開闢水源，節約水流。\n引申意思：增加收入、減少開支（如：家庭理財要懂得開源節流）。" },
  { id: "i835", grade: 4, term: "忍氣吞聲", zhuyin: "ㄖㄣˇ ㄑㄧˋ ㄊㄨㄣ ㄕㄥ", pinyin: "rěn qì tūn shēng", meaning: "把怒氣忍住、話吞回去，不敢發作。", example: "他被冤枉了卻忍氣吞聲，不敢辯解。", wordExp: "忍氣＝壓住怒氣；吞聲＝把聲音吞下。氣往肚裡吞、話不敢出口。", deep: "典故由來：出自元代雜劇《鴛鴦被》：「從今後忍氣吞聲，再不敢嚎咷痛哭。」\n字面意思：忍住氣、吞下聲。\n引申意思：受了委屈強自忍耐、不敢作聲（如：面對客人的無理要求，店員只能忍氣吞聲）。" },
  { id: "i836", grade: 4, term: "心平氣和", zhuyin: "ㄒㄧㄣ ㄆㄧㄥˊ ㄑㄧˋ ㄏㄜˊ", pinyin: "xīn píng qì hé", meaning: "心情平靜、態度溫和，不急不怒。", example: "有話好好說，大家心平氣和地討論。", wordExp: "心平＝心情平靜；氣和＝語氣平和。心和氣都平和。", deep: "典故由來：語本《左傳．昭公二十年》晏子論「和」：「君子聽之，以平其心，心平德和。」\n字面意思：心情平穩，氣息和緩。\n引申意思：態度冷靜溫和、不衝動（如：心平氣和才能把問題談清楚）。相對詞：怒氣沖沖。" },
  { id: "i837", grade: 4, term: "神清氣爽", zhuyin: "ㄕㄣˊ ㄑㄧㄥ ㄑㄧˋ ㄕㄨㄤˇ", pinyin: "shén qīng qì shuǎng", meaning: "精神清朗、心情舒暢。", example: "睡了一夜好覺，起床後神清氣爽。", wordExp: "神清＝精神清明；氣爽＝氣息舒暢。精神氣色都清爽。", deep: "典故由來：出自宋代李昉《太平廣記》引《逸史》：「神清氣爽，飄飄然有凌雲之志。」\n字面意思：精神清明，氣息爽朗。\n引申意思：身心舒暢、頭腦清醒（如：晨跑後神清氣爽，讀書特別有效率）。" },
  { id: "i838", grade: 4, term: "千載難逢", zhuyin: "ㄑㄧㄢ ㄗㄞˇ ㄋㄢˊ ㄈㄥˊ", pinyin: "qiān zǎi nán féng", meaning: "一千年也難遇到一次，形容機會極為難得。", example: "能到現場看世界盃決賽，真是千載難逢的機會。", wordExp: "千載＝千年（載＝年）；難逢＝難以遇到。千年也碰不到一次。", deep: "典故由來：語本《南齊書．瘐杲之傳》：「臣以凡庸，謬徼昌運，獎擢之厚，千載難逢。」\n字面意思：一千年也難以遇上。\n引申意思：機會極其難得（如：這是千載難逢的合作機會，千萬把握）。注意「載」讀ㄗㄞˇ，是「年」的意思。" },
  { id: "i839", grade: 4, term: "易如反掌", zhuyin: "ㄧˋ ㄖㄨˊ ㄈㄢˇ ㄓㄤˇ", pinyin: "yì rú fǎn zhǎng", meaning: "像翻一下手掌那麼容易。", example: "這道題對數學小老師來說易如反掌。", wordExp: "易＝容易；如＝好像；反掌＝翻轉手掌。容易得像翻手掌。", deep: "典故由來：語本《孟子．公孫丑上》：「以齊王，由反手也。」用齊國的條件稱王天下，就像翻轉手掌一樣容易。\n字面意思：容易得像翻一下手掌。\n引申意思：事情非常容易辦到（如：憑他的實力，通過檢定易如反掌）。近義：輕而易舉、探囊取物。" },
  { id: "i840", grade: 4, term: "狡兔三窟", zhuyin: "ㄐㄧㄠˇ ㄊㄨˋ ㄙㄢ ㄎㄨ", pinyin: "jiǎo tù sān kū", meaning: "狡猾的兔子有三個洞穴，比喻預留多條退路。", example: "他在各地都有安排，狡兔三窟，非常謹慎。", wordExp: "狡兔＝機警的兔子；三窟＝三個洞穴。兔子準備了三個藏身洞。", deep: "典故由來：出自《戰國策．齊策》：馮諼對孟嘗君說「狡兔有三窟，僅得免其死耳」，並替他經營三處退路，孟嘗君因此安穩數十年。\n字面意思：機警的兔子有三個洞窟。\n引申意思：預先安排多個藏身處或退路（如：投資要分散風險，狡兔三窟）。今多為中性或略帶貶義。" },
  { id: "i841", grade: 5, term: "世外桃源", zhuyin: "ㄕˋ ㄨㄞˋ ㄊㄠˊ ㄩㄢˊ", pinyin: "shì wài táo yuán", meaning: "與世隔絕、安樂美好的理想世界。", example: "這個小山村風景如畫，簡直是世外桃源。", wordExp: "世外＝塵世之外；桃源＝桃花源。塵世之外的桃花源。", deep: "典故由來：出自陶淵明〈桃花源記〉：漁人誤入與世隔絕的村落，居民安居樂業、不知外界朝代更迭。\n字面意思：人世之外的桃花源。\n引申意思：環境清幽、生活安樂的理想之地（如：他嚮往鄉居的世外桃源生活）；也指逃避現實的幻想境地。" },
  { id: "i842", grade: 5, term: "沉魚落雁", zhuyin: "ㄔㄣˊ ㄩˊ ㄌㄨㄛˋ ㄧㄢˋ", pinyin: "chén yú luò yàn", meaning: "形容女子容貌極美。", example: "畫中仕女有沉魚落雁之貌。", wordExp: "沉魚＝魚見了沉入水底；落雁＝雁見了降落沙洲。魚雁都為美貌折服。", deep: "典故由來：語本《莊子．齊物論》：毛嬙、麗姬是人間美女，但「魚見之深入，鳥見之高飛」——莊子原意是美醜無絕對標準；後世反用，說魚雁因驚豔而沉落。後與西施沉魚、昭君落雁的傳說結合。\n字面意思：使魚沉入水底、使雁降落地面。\n引申意思：形容女子絕美（如：沉魚落雁之容，閉月羞花之貌）。" },
  { id: "i843", grade: 5, term: "目中無人", zhuyin: "ㄇㄨˋ ㄓㄨㄥ ㄨˊ ㄖㄣˊ", pinyin: "mù zhōng wú rén", meaning: "眼裡沒有別人，形容驕傲自大、看不起人。", example: "他一得獎就目中無人，同學都不喜歡他。", wordExp: "目中＝眼睛裡；無人＝沒有別人。眼裡看不見其他人。", deep: "典故由來：明清小說常用語，《說唐》等書屢見，形容狂傲之人。\n字面意思：眼中沒有別人的存在。\n引申意思：自高自大、輕視他人（如：實力越強越要謙虛，不可目中無人）。貶義；近義：目空一切、旁若無人。" },
  { id: "i844", grade: 5, term: "大言不慚", zhuyin: "ㄉㄚˋ ㄧㄢˊ ㄅㄨˋ ㄘㄢˊ", pinyin: "dà yán bù cán", meaning: "說大話而毫不害臊。", example: "他大言不慚地說自己一定考第一名。", wordExp: "大言＝誇大的話；不慚＝不覺得慚愧。吹牛卻不臉紅。", deep: "典故由來：語本《論語．憲問》：「其言之不怍，則為之也難。」朱熹注：「大言不慚，則無必為之志。」——說大話不臉紅的人，多半做不到。\n字面意思：說大話而不感到慚愧。\n引申意思：譏諷人自誇卻無自知之明（如：沒練習還大言不慚要奪冠）。貶義。" },
  { id: "i845", grade: 5, term: "自吹自擂", zhuyin: "ㄗˋ ㄔㄨㄟ ㄗˋ ㄌㄟˊ", pinyin: "zì chuī zì léi", meaning: "自己吹喇叭、自己打鼓，比喻自我吹噓。", example: "他老是自吹自擂，說自己樣樣第一。", wordExp: "自吹＝自己吹號；自擂＝自己擂鼓。自己給自己吹打宣傳。", deep: "典故由來：由民間鼓吹樂隊的景象引申而來——別人辦事有人吹打助陣，自吹自擂則是自己捧自己。\n字面意思：自己吹喇叭、自己打鼓。\n引申意思：自我誇耀（如：真有本事不必自吹自擂）。貶義；近義：自賣自誇、大言不慚。" },
  { id: "i846", grade: 5, term: "心猿意馬", zhuyin: "ㄒㄧㄣ ㄩㄢˊ ㄧˋ ㄇㄚˇ", pinyin: "xīn yuán yì mǎ", meaning: "心像猿猴跳、意像馬奔跑，形容心思不定。", example: "複習時心猿意馬，一頁書看了半小時。", wordExp: "心猿＝心如猿猴亂跳；意馬＝意念如馬亂跑。心思像猿馬一樣管不住。", deep: "典故由來：佛教用語，佛經以猿猴躁動、奔馬難拴比喻人心妄念難以安定，唐代已見「心猿意馬」連用。\n字面意思：心是亂跳的猿、意是狂奔的馬。\n引申意思：心神不專、浮躁不定（如：靜坐就是要收束心猿意馬）。" },
  { id: "i847", grade: 5, term: "心灰意冷", zhuyin: "ㄒㄧㄣ ㄏㄨㄟ ㄧˋ ㄌㄥˇ", pinyin: "xīn huī yì lěng", meaning: "心像熄滅的灰、意念冰冷，形容極度失望。", example: "連續落選讓他心灰意冷，一度想放棄。", wordExp: "心灰＝心如死灰；意冷＝意志冷卻。心意都冷卻了。", deep: "典故由來：「心灰」語本《莊子》「形固可使如槁木，而心固可使如死灰乎」；後演變為「心灰意冷／心灰意懶」。\n字面意思：心成了冷灰，意念也冰冷。\n引申意思：灰心喪志、失去熱情（如：別因一次失敗就心灰意冷）。近義：灰心喪氣；相對：興致勃勃。" },
  { id: "i848", grade: 5, term: "喜形於色", zhuyin: "ㄒㄧˇ ㄒㄧㄥˊ ㄩˊ ㄙㄜˋ", pinyin: "xǐ xíng yú sè", meaning: "喜悅表現在臉色上，藏不住高興。", example: "一聽到錄取的消息，他不禁喜形於色。", wordExp: "喜＝喜悅；形＝表現；於色＝在臉色上。高興寫在臉上。", deep: "典故由來：出自《北史．高允傳》：「允喜形於色。」\n字面意思：喜悅顯現在臉色上。\n引申意思：內心的高興不自覺流露出來（如：他雖想保持鎮定，仍喜形於色）。相對詞：不動聲色、面不改色。" },
  { id: "i849", grade: 5, term: "怒髮衝冠", zhuyin: "ㄋㄨˋ ㄈㄚˇ ㄔㄨㄥ ㄍㄨㄢ", pinyin: "nù fǎ chōng guān", meaning: "憤怒得頭髮豎起、頂起帽子，形容盛怒。", example: "看到有人虐待動物，他氣得怒髮衝冠。", wordExp: "怒髮＝憤怒豎起的頭髮；衝冠＝頂起帽子。頭髮豎起把帽子都頂起來。", deep: "典故由來：出自《史記．廉頗藺相如列傳》：藺相如捧和氏璧入秦，見秦王無意償城，「怒髮上衝冠」，持璧欲擊柱。岳飛〈滿江紅〉「怒髮衝冠」更使其家喻戶曉。\n字面意思：憤怒使頭髮直豎，頂起了帽子。\n引申意思：形容憤怒到極點（如：聽聞噩耗真相，他怒髮衝冠）。注意「冠」指帽子，讀ㄍㄨㄢ。" },
  { id: "i850", grade: 5, term: "火上加油", zhuyin: "ㄏㄨㄛˇ ㄕㄤˋ ㄐㄧㄚ ㄧㄡˊ", pinyin: "huǒ shàng jiā yóu", meaning: "在火上澆油，比喻使衝突或情緒更加激烈。", example: "他正在氣頭上，你再頂嘴就是火上加油。", wordExp: "火上＝在火焰上；加油＝澆上油。火已經在燒還澆油助燃。", deep: "典故由來：由生活經驗形成的俗語式成語，元雜劇已見「火上澆油」。\n字面意思：往燃燒的火上倒油。\n引申意思：使原本緊張的局面更惡化、讓生氣的人更生氣（如：勸架要緩和氣氛，別火上加油）。" },
  { id: "i851", grade: 5, term: "翻山越嶺", zhuyin: "ㄈㄢ ㄕㄢ ㄩㄝˋ ㄌㄧㄥˇ", pinyin: "fān shān yuè lǐng", meaning: "翻過一座座山嶺，形容路途辛苦遙遠。", example: "郵差翻山越嶺，把信送到偏遠的部落。", wordExp: "翻、越＝越過；山、嶺＝山峰山脈。翻過大山越過峻嶺。", deep: "典故由來：由行旅語彙組成的常用成語，形容長途跋涉。\n字面意思：翻過高山，越過峻嶺。\n引申意思：長途跋涉的辛勞（如：志工翻山越嶺送物資進災區）。近義：跋山涉水、長途跋涉。" },
  { id: "i852", grade: 5, term: "翻箱倒櫃", zhuyin: "ㄈㄢ ㄒㄧㄤ ㄉㄠˇ ㄍㄨㄟˋ", pinyin: "fān xiāng dǎo guì", meaning: "把箱子櫃子全翻遍，形容徹底翻找。", example: "為了找那張照片，我翻箱倒櫃找了一下午。", wordExp: "翻箱＝翻開箱子；倒櫃＝倒出櫃子。箱櫃全部翻出來找。", deep: "典故由來：明清小說常用語，《紅樓夢》有「翻箱倒櫃」的描寫。\n字面意思：翻開箱子、倒空櫃子。\n引申意思：徹底搜尋（如：小偷把屋裡翻箱倒櫃弄得一團亂）。" },
  { id: "i853", grade: 5, term: "驚天動地", zhuyin: "ㄐㄧㄥ ㄊㄧㄢ ㄉㄨㄥˋ ㄉㄧˋ", pinyin: "jīng tiān dòng dì", meaning: "驚動天地，形容聲勢浩大或事件重大。", example: "隔壁工地傳來驚天動地的爆破聲。", wordExp: "驚天＝使天震驚；動地＝使地搖動。連天地都被驚動。", deep: "典故由來：出自唐代白居易〈李白墓〉詩：「可憐荒壟窮泉骨，曾有驚天動地文。」讚李白詩文氣魄。\n字面意思：驚動上天、搖動大地。\n引申意思：聲響巨大，或事業、事件影響非凡（如：一聲驚天動地的巨響）。" },
  { id: "i854", grade: 5, term: "驚弓之鳥", zhuyin: "ㄐㄧㄥ ㄍㄨㄥ ㄓ ㄋㄧㄠˇ", pinyin: "jīng gōng zhī niǎo", meaning: "被弓箭嚇怕的鳥，比喻受過驚嚇、遇事就害怕的人。", example: "上次地震後他成了驚弓之鳥，一點搖晃就往外跑。", wordExp: "驚弓＝被弓聲驚嚇；之鳥＝的鳥。聽到弓弦聲就墜落的鳥。", deep: "典故由來：出自《戰國策．楚策》：神射手更羸只拉空弦，一隻受過箭傷的雁應聲而落——牠聽到弦聲，舊傷驚裂而墜。\n字面意思：被弓箭嚇怕了的鳥。\n引申意思：受過驚嚇、心有餘悸而過度警覺的人（如：詐騙受害者成了驚弓之鳥，接到陌生電話就緊張）。" },
  { id: "i855", grade: 5, term: "忍辱負重", zhuyin: "ㄖㄣˇ ㄖㄨˋ ㄈㄨˋ ㄓㄨㄥˋ", pinyin: "rěn rù fù zhòng", meaning: "忍受屈辱，承擔重任。", example: "他忍辱負重多年，終於完成了改革大業。", wordExp: "忍辱＝忍受恥辱；負重＝背負重任。忍著委屈扛起重擔。", deep: "典故由來：出自《三國志．吳書．陸遜傳》：陸遜統軍抗劉備，老將不服，他說「國家所以屈諸君使相承望者，以僕有尺寸可稱，能忍辱負重故也」。\n字面意思：忍受侮辱，背負重任。\n引申意思：為了大局忍受委屈、承擔艱鉅任務（如：他忍辱負重，默默撐起整個團隊）。褒義。" },
  { id: "i856", grade: 6, term: "虎視眈眈", zhuyin: "ㄏㄨˇ ㄕˋ ㄉㄢ ㄉㄢ", pinyin: "hǔ shì dān dān", meaning: "像老虎般兇狠地盯著，伺機奪取。", example: "幾家大公司對這塊市場虎視眈眈。", wordExp: "虎視＝像虎一樣注視；眈眈＝瞪視的樣子。如虎盯獵物。", deep: "典故由來：出自《易經．頤卦》：「虎視眈眈，其欲逐逐。」\n字面意思：老虎緊盯獵物、目光兇狠。\n引申意思：貪婪地注視，隨時準備下手（如：對手對冠軍寶座虎視眈眈）。「眈」是目字旁，別寫成「耽」。" },
  { id: "i857", grade: 6, term: "兔死狐悲", zhuyin: "ㄊㄨˋ ㄙˇ ㄏㄨˊ ㄅㄟ", pinyin: "tù sǐ hú bēi", meaning: "兔子死了狐狸悲傷，比喻因同類遭遇不幸而傷感。", example: "同行倒閉，他兔死狐悲，擔心自己的前景。", wordExp: "兔死＝兔子死了；狐悲＝狐狸悲傷。同是山中動物，物傷其類。", deep: "典故由來：出自《宋史．李全傳》：「狐死兔泣，李氏滅，夏氏寧獨存？」原作「狐死兔泣」，後多作「兔死狐悲」，下句常接「物傷其類」。\n字面意思：兔子死了，狐狸感到悲傷。\n引申意思：因同類的不幸而聯想到自身，感到悲戚（如：看到同業被淘汰，不免兔死狐悲）。" },
  { id: "i858", grade: 6, term: "雞犬不寧", zhuyin: "ㄐㄧ ㄑㄩㄢˇ ㄅㄨˋ ㄋㄧㄥˊ", pinyin: "jī quǎn bù níng", meaning: "連雞狗都不得安寧，形容被騷擾得非常厲害。", example: "樓上日夜施工，吵得全棟住戶雞犬不寧。", wordExp: "雞犬＝雞和狗；不寧＝不得安寧。連家禽家畜都無法安生。", deep: "典故由來：出自唐代柳宗元〈捕蛇者說〉：悍吏下鄉催稅，「譁然而駭者，雖雞狗不得寧焉」。\n字面意思：雞和狗都不得安寧。\n引申意思：騷擾得所有人不得安生（如：惡鄰半夜喧鬧，攪得雞犬不寧）。" },
  { id: "i859", grade: 6, term: "雞鳴狗盜", zhuyin: "ㄐㄧ ㄇㄧㄥˊ ㄍㄡˇ ㄉㄠˋ", pinyin: "jī míng gǒu dào", meaning: "學雞叫、裝狗偷的小技倆，指微不足道的技能或卑下的行徑。", example: "他結交的多是雞鳴狗盜之徒，遲早出事。", wordExp: "雞鳴＝學雞叫；狗盜＝像狗一樣鑽洞偷竊。小偷小騙的伎倆。", deep: "典故由來：出自《史記．孟嘗君列傳》：孟嘗君被困秦國，門客一人裝狗夜盜狐白裘賄賂寵姬，一人學雞叫騙開函谷關城門，方能脫身。\n字面意思：學雞啼叫、學狗行竊。\n引申意思：不入流的小技，或行為不正的人（如：雞鳴狗盜之技，難登大雅之堂）。王安石〈讀孟嘗君傳〉即以此批評孟嘗君的門客。" },
  { id: "i860", grade: 6, term: "魚目混珠", zhuyin: "ㄩˊ ㄇㄨˋ ㄏㄨㄣˋ ㄓㄨ", pinyin: "yú mù hùn zhū", meaning: "拿魚眼睛冒充珍珠，比喻以假亂真。", example: "市面上有些劣質品魚目混珠，購買時要小心。", wordExp: "魚目＝魚的眼珠；混＝冒充；珠＝珍珠。魚眼裝成珍珠。", deep: "典故由來：語本《參同契》：「魚目豈為珠？蓬蒿不成檟。」魚眼圓白似珠而非珠。\n字面意思：用魚眼睛混充珍珠。\n引申意思：以假貨次品冒充真品好貨（如：假貨魚目混珠流入市場）。近義：濫竽充數（自謙或諷人）、以假亂真。" },
  { id: "i861", grade: 6, term: "口蜜腹劍", zhuyin: "ㄎㄡˇ ㄇㄧˋ ㄈㄨˋ ㄐㄧㄢˋ", pinyin: "kǒu mì fù jiàn", meaning: "嘴上甜如蜜，肚裡藏著劍，形容人陰險。", example: "他表面熱心，實則口蜜腹劍，要多提防。", wordExp: "口蜜＝嘴像蜂蜜甜；腹劍＝肚裡藏劍。嘴甜心狠。", deep: "典故由來：出自《資治通鑑》：唐玄宗宰相李林甫「口有蜜，腹有劍」，表面奉承、暗中陷害，世人以此語形容他。\n字面意思：口中如蜜甜，腹中藏利劍。\n引申意思：言語動聽而居心險惡（如：口蜜腹劍的人最難防範）。近義：笑裡藏刀、兩面三刀。" },
  { id: "i862", grade: 6, term: "笑裡藏刀", zhuyin: "ㄒㄧㄠˋ ㄌㄧˇ ㄘㄤˊ ㄉㄠ", pinyin: "xiào lǐ cáng dāo", meaning: "笑容裡藏著刀，形容外表和善、內心狠毒。", example: "對這種笑裡藏刀的人，要保持距離。", wordExp: "笑裡＝笑容之中；藏刀＝藏著利刃。笑著把刀藏在背後。", deep: "典故由來：出自《舊唐書．李義府傳》：李義府貌恭而心狠，時人說他「笑中有刀」，又號「李貓」。三十六計亦收「笑裡藏刀」。\n字面意思：笑容裡暗藏尖刀。\n引申意思：表面友善、暗中害人（如：商場上要小心笑裡藏刀的對手）。近義：口蜜腹劍。" },
  { id: "i863", grade: 6, term: "兩面三刀", zhuyin: "ㄌㄧㄤˇ ㄇㄧㄢˋ ㄙㄢ ㄉㄠ", pinyin: "liǎng miàn sān dāo", meaning: "當面一套、背後一套，耍兩面手法挑撥是非。", example: "他慣會兩面三刀，在同事間搬弄是非。", wordExp: "兩面＝兩副面孔；三刀＝多般手段。見人說人話、見鬼說鬼話還暗捅刀。", deep: "典故由來：出自元代李行道《灰闌記》：「豈知他有兩面三刀，向夫主廝搬調。」\n字面意思：擺出兩副面孔，暗藏多把刀。\n引申意思：陰險狡猾、當面背後不一致（如：兩面三刀的人遲早被拆穿）。貶義。" },
  { id: "i864", grade: 6, term: "不自量力", zhuyin: "ㄅㄨˋ ㄗˋ ㄌㄧㄤˋ ㄌㄧˋ", pinyin: "bù zì liàng lì", meaning: "不衡量自己的能力，去做辦不到的事。", example: "才學三個月就要挑戰職業選手，未免不自量力。", wordExp: "不＝沒有；自量＝衡量自己；力＝力量。不掂掂自己的斤兩。", deep: "典故由來：語本《左傳．隱公十一年》：「不度德，不量力。」息國不自量力攻打鄭國，大敗而回。\n字面意思：不衡量自身的力量。\n引申意思：高估自己、做能力不及的事（如：螳臂當車，不自量力）。近義：螳臂當車、蚍蜉撼樹。" },
  { id: "i865", grade: 6, term: "深藏不露", zhuyin: "ㄕㄣ ㄘㄤˊ ㄅㄨˋ ㄌㄨˋ", pinyin: "shēn cáng bù lù", meaning: "把本領深深藏起來不顯露。", example: "他平時安靜，唱起歌來驚豔全場，真是深藏不露。", wordExp: "深藏＝深深藏起；不露＝不顯露。有真本事卻不張揚。", deep: "典故由來：語本《史記．老子韓非列傳》：「良賈深藏若虛，君子盛德容貌若愚。」會做生意的人把好貨收起來，彷彿店裡空無一物。\n字面意思：深深收藏，不顯露出來。\n引申意思：有才能而不炫耀（如：高手深藏不露）。褒義；相對：鋒芒畢露、自吹自擂。" },
  { id: "i866", grade: 6, term: "老當益壯", zhuyin: "ㄌㄠˇ ㄉㄤ ㄧˋ ㄓㄨㄤˋ", pinyin: "lǎo dāng yì zhuàng", meaning: "年紀雖大，志氣體力反而更旺盛。", example: "七十歲的爺爺還能爬百岳，真是老當益壯。", wordExp: "老＝年老；當＝應當；益＝更加；壯＝豪壯。越老越有幹勁。", deep: "典故由來：出自《後漢書．馬援傳》：名將馬援說「丈夫為志，窮當益堅，老當益壯」，六十二歲仍請纓出征。\n字面意思：年老了應當更加豪壯。\n引申意思：年長而精神體力不減（如：老當益壯的他天天晨泳）。褒義；近義：寶刀未老。" },
  { id: "i867", grade: 6, term: "寶刀未老", zhuyin: "ㄅㄠˇ ㄉㄠ ㄨㄟˋ ㄌㄠˇ", pinyin: "bǎo dāo wèi lǎo", meaning: "寶刀還沒鈍，比喻年紀雖大、本領依舊高強。", example: "退休教練一出手示範，果然寶刀未老。", wordExp: "寶刀＝珍貴的刀（喻本領）；未老＝沒有變鈍。武器和功夫都沒退步。", deep: "典故由來：語本《三國演義》：黃忠年近七旬仍勇冠三軍，關羽稱「老將軍寶刀未老」。\n字面意思：寶刀仍然鋒利如昔。\n引申意思：年長者技藝不減當年（如：老歌手一開口，寶刀未老）。與「老當益壯」常互用，前者重技藝、後者重精神體力。" },
  { id: "i868", grade: 6, term: "心悅誠服", zhuyin: "ㄒㄧㄣ ㄩㄝˋ ㄔㄥˊ ㄈㄨˊ", pinyin: "xīn yuè chéng fú", meaning: "打從心裡高興而真誠地佩服、服從。", example: "老師以身作則，讓學生心悅誠服。", wordExp: "心悅＝內心喜悅；誠服＝真誠信服。發自內心的佩服。", deep: "典故由來：出自《孟子．公孫丑上》：「以德服人者，中心悅而誠服也。」靠武力使人屈服不是真服，以德服人才能讓人由衷信服。\n字面意思：心裡喜悅，真誠信服。\n引申意思：徹底服氣、毫無勉強（如：這個判決讓雙方都心悅誠服）。相對：口服心不服。" },
  { id: "i869", grade: 6, term: "心安理得", zhuyin: "ㄒㄧㄣ ㄢ ㄌㄧˇ ㄉㄜˊ", pinyin: "xīn ān lǐ dé", meaning: "自認做得合情合理，心裡坦然安穩。", example: "憑勞力賺錢，花得心安理得。", wordExp: "心安＝心裡安穩；理得＝在道理上站得住。心安是因為合理。", deep: "典故由來：語本《論語．陽貨》孔子與宰我論三年之喪：「食夫稻，衣夫錦，於女安乎？」——做事只求心安；後演成「心安理得」。\n字面意思：心中安然，於理無虧。\n引申意思：行事光明正大，所以問心無愧（如：拿該拿的報酬，心安理得）。相對：忐忑不安、做賊心虛。" },
  { id: "i870", grade: 6, term: "精神抖擻", zhuyin: "ㄐㄧㄥ ㄕㄣˊ ㄉㄡˇ ㄙㄡˇ", pinyin: "jīng shén dǒu sǒu", meaning: "精神振奮、充滿活力的樣子。", example: "選手們精神抖擻地步入會場。", wordExp: "精神＝精氣神；抖擻＝振作、奮發。把精神振作起來。", deep: "典故由來：「抖擻」原為佛家語（頭陀的音義兼譯，指去除塵垢煩惱）；龔自珍詩「我勸天公重抖擻，不拘一格降人才」使其廣為流傳。\n字面意思：精神振作飽滿。\n引申意思：神采奕奕、活力十足（如：睡飽後精神抖擻地上學）。相對：無精打采、垂頭喪氣。" },
  { id: "i871", grade: 6, term: "神采奕奕", zhuyin: "ㄕㄣˊ ㄘㄞˇ ㄧˋ ㄧˋ", pinyin: "shén cǎi yì yì", meaning: "精神煥發、容光四射的樣子。", example: "八十歲的奶奶依然神采奕奕，聲音宏亮。", wordExp: "神采＝神情風采；奕奕＝光明煥發的樣子。神情光彩照人。", deep: "典故由來：「奕奕」語出《詩經．小雅》「奕奕寢廟」，本指高大光明，後借形容精神煥發。\n字面意思：神情風采光亮煥發。\n引申意思：精神飽滿、氣色極好（如：他病癒復出，神采奕奕）。近義：容光煥發、精神抖擻。" },
  { id: "i872", grade: 6, term: "意氣風發", zhuyin: "ㄧˋ ㄑㄧˋ ㄈㄥ ㄈㄚ", pinyin: "yì qì fēng fā", meaning: "意志昂揚、精神煥發，像風一樣奮起。", example: "青年創業家意氣風發地介紹著理想藍圖。", wordExp: "意氣＝志氣情懷；風發＝像風一樣興起。志氣如風般昂揚。", deep: "典故由來：「風發」語本《詩經》與漢賦中「如風之發」的比喻；毛澤東詞「書生意氣，揮斥方遒」意境相承，今為常用褒義成語。\n字面意思：志氣像風一樣奮發。\n引申意思：精神振奮、豪情滿懷（如：畢業生意氣風發地邁向未來）。相對：垂頭喪氣、意志消沉。" },
  { id: "i873", grade: 6, term: "排山倒海", zhuyin: "ㄆㄞˊ ㄕㄢ ㄉㄠˇ ㄏㄞˇ", pinyin: "pái shān dǎo hǎi", meaning: "推開高山、翻倒大海，形容聲勢巨大不可阻擋。", example: "支持的聲浪排山倒海而來。", wordExp: "排＝推開；倒＝翻倒。把山推開、把海掀翻。", deep: "典故由來：語本《資治通鑑》等史書「排山壓卵」與宋代文人「回山倒海」的用法，後定型為「排山倒海」。\n字面意思：推開大山，翻倒大海。\n引申意思：力量或聲勢極為浩大（如：輿論排山倒海，逼得官方回應）。近義：雷霆萬鈞、萬馬奔騰。" },
  { id: "i874", grade: 6, term: "驚濤駭浪", zhuyin: "ㄐㄧㄥ ㄊㄠˊ ㄏㄞˋ ㄌㄤˋ", pinyin: "jīng táo hài làng", meaning: "令人驚恐的大風浪，比喻險惡的環境或遭遇。", example: "這家老店走過金融風暴的驚濤駭浪，屹立至今。", wordExp: "驚、駭＝使人驚嚇；濤、浪＝巨浪。嚇人的狂濤巨浪。", deep: "典故由來：唐代田穎〈玉山常文集序〉已見「驚濤駭浪」形容行船之險。\n字面意思：使人驚駭的巨濤大浪。\n引申意思：驚險的處境、重大的考驗（如：人生的驚濤駭浪，他都一一挺過）。相對：風平浪靜。" },
  { id: "i875", grade: 6, term: "支支吾吾", zhuyin: "ㄓ ㄓ ㄨˊ ㄨˊ", pinyin: "zhī zhī wú wú", meaning: "說話含混閃躲、不肯痛快說清楚。", example: "問他錢花去哪了，他支支吾吾答不上來。", wordExp: "支吾＝用話搪塞應付。說話吞吞吐吐、東拉西扯。", deep: "典故由來：「支吾」本作「枝梧」，原指用枝柱抵撐，引申為用言語抵擋搪塞；疊用加強語氣。\n字面意思：（說話）一再搪塞閃避。\n引申意思：心虛或有隱情，說話含糊躲閃（如：他支支吾吾，顯然另有隱情）。近義：吞吞吐吐、閃爍其詞。" },
  { id: "i876", grade: 6, term: "吞吞吐吐", zhuyin: "ㄊㄨㄣ ㄊㄨㄣ ㄊㄨˇ ㄊㄨˇ", pinyin: "tūn tūn tǔ tǔ", meaning: "想說又不敢說、話到嘴邊又縮回去的樣子。", example: "有話就直說，別吞吞吐吐的。", wordExp: "吞＝嚥下去；吐＝說出來。話一下吞回一下吐出。", deep: "典故由來：清代小說《兒女英雄傳》已見「吞吞吐吐」形容說話遮掩。\n字面意思：吞下去又吐出來，反反覆覆。\n引申意思：說話有顧忌、不乾脆（如：他吞吞吐吐半天，就是不說重點）。近義：支支吾吾、欲言又止。" },
  { id: "i877", grade: 6, term: "直言不諱", zhuyin: "ㄓˊ ㄧㄢˊ ㄅㄨˋ ㄏㄨㄟˋ", pinyin: "zhí yán bù huì", meaning: "直接說出意見，毫不忌諱隱瞞。", example: "他直言不諱地指出企劃案的三大缺點。", wordExp: "直言＝直接說；不諱＝不避忌。有話直說、毫不隱瞞。", deep: "典故由來：語本《晉書．劉波傳》：「臣鑒先徵，竊惟今事，是以敢肆狂瞽，直言無諱。」\n字面意思：直接說話，沒有忌諱。\n引申意思：坦率表達真實想法（如：感謝你直言不諱的建議）。褒義；近義：開誠布公、單刀直入。" },
  { id: "i878", grade: 6, term: "暢所欲言", zhuyin: "ㄔㄤˋ ㄙㄨㄛˇ ㄩˋ ㄧㄢˊ", pinyin: "chàng suǒ yù yán", meaning: "痛痛快快地把想說的話全說出來。", example: "班會上老師鼓勵大家暢所欲言。", wordExp: "暢＝盡情；所欲言＝想說的話。想說什麼就痛快說。", deep: "典故由來：語本明代李贄與清人書信中「暢所欲言」的用法，形容言談無所拘束。\n字面意思：痛快地說出想說的話。\n引申意思：在無壓力的環境中充分表達意見（如：座談會讓居民暢所欲言）。相對：欲言又止、噤若寒蟬。" },
  { id: "i879", grade: 6, term: "信口開河", zhuyin: "ㄒㄧㄣˋ ㄎㄡˇ ㄎㄞ ㄏㄜˊ", pinyin: "xìn kǒu kāi hé", meaning: "隨口亂說、漫無邊際，說話不負責任。", example: "沒有根據的事不要信口開河。", wordExp: "信口＝隨口；開河＝像河水滔滔。嘴巴一開像河水亂流。", deep: "典故由來：出自元雜劇《爭報恩》：「那妮子一尺水翻騰做一丈波，怎當他只留支剌信口開合。」原作「信口開合」，後訛為「開河」。\n字面意思：隨口一開，話如河水氾濫。\n引申意思：不加思索地胡說（如：他慣會信口開河，聽聽就好）。貶義；近義：信口雌黃、胡說八道。" },
  { id: "i880", grade: 6, term: "進退兩難", zhuyin: "ㄐㄧㄣˋ ㄊㄨㄟˋ ㄌㄧㄤˇ ㄋㄢˊ", pinyin: "jìn tuì liǎng nán", meaning: "前進不行、後退也不行，處境非常為難。", example: "答應也不是、拒絕也不是，真是進退兩難。", wordExp: "進退＝前進與後退；兩難＝兩邊都困難。前後都是難處。", deep: "典故由來：語本《詩經．大雅．桑柔》「進退維谷」——前進後退都是山谷絕路；後演為口語化的「進退兩難」。\n字面意思：前進、後退都困難。\n引申意思：左右為難、不知如何是好（如：卡在兩位好友的爭執中，進退兩難）。近義：進退維谷、騎虎難下。" },
  { id: "i881", grade: 7, term: "捕風捉影", zhuyin: "ㄅㄨˇ ㄈㄥ ㄓㄨㄛ ㄧㄥˇ", pinyin: "bǔ fēng zhuō yǐng", meaning: "抓風捉影子，比喻說話做事毫無事實根據。", example: "這則報導捕風捉影，內容大多是臆測。", wordExp: "捕、捉＝抓取；風、影＝抓不到的東西。去抓抓不住的風和影。", deep: "典故由來：語本《漢書．郊祀志》：谷永勸漢成帝勿信方士，「聽其言，洋洋滿耳，若將可遇；求之，盪盪如係風捕景（影），終不可得」。\n字面意思：捕捉風和影子。\n引申意思：憑空猜測、沒有根據（如：別捕風捉影冤枉人）。近義：無中生有、道聽塗說。" },
  { id: "i882", grade: 7, term: "無中生有", zhuyin: "ㄨˊ ㄓㄨㄥ ㄕㄥ ㄧㄡˇ", pinyin: "wú zhōng shēng yǒu", meaning: "本來沒有的事硬說成有，憑空捏造。", example: "這純屬無中生有的謠言，請大家別轉傳。", wordExp: "無中＝從沒有之中；生有＝生出有來。憑空變出事情。", deep: "典故由來：語本《老子》「天下萬物生於有，有生於無」的哲學命題，後被借為捏造事實之義，並列入三十六計。\n字面意思：從「沒有」中生出「有」。\n引申意思：憑空捏造、造謠（如：他無中生有地指控同事）。貶義。" },
  { id: "i883", grade: 7, term: "三人成虎", zhuyin: "ㄙㄢ ㄖㄣˊ ㄔㄥˊ ㄏㄨˇ", pinyin: "sān rén chéng hǔ", meaning: "謠言重複多次，就會被信以為真。", example: "網路時代三人成虎，查證比轉發更重要。", wordExp: "三人＝多人接連地說；成虎＝把沒有的老虎說成真的。", deep: "典故由來：出自《戰國策．魏策》：龐蔥問魏王「三人言市有虎，王信之乎？」街市明明沒老虎，三個人都說有，君王就信了——他提醒魏王別聽信讒言，魏王終究還是中計。\n字面意思：三個人都說街上有虎，大家就信了。\n引申意思：謠言說的人多了便成「事實」（如：三人成虎，眾口鑠金）。提醒人查證與獨立思考。" },
  { id: "i884", grade: 7, term: "錯綜複雜", zhuyin: "ㄘㄨㄛˋ ㄗㄨㄥˋ ㄈㄨˋ ㄗㄚˊ", pinyin: "cuò zòng fù zá", meaning: "頭緒交錯繁雜，非常難以理清。", example: "這起案件牽涉多方，關係錯綜複雜。", wordExp: "錯＝交錯；綜＝總聚；複雜＝繁多混雜。線索交織難解。", deep: "典故由來：「錯綜」語出《易經．繫辭》「參伍以變，錯綜其數」，指交錯綜合演算卦數。\n字面意思：交錯聚合、重複雜亂。\n引申意思：情況或關係盤根錯節、極為複雜（如：兩家公司的恩怨錯綜複雜）。近義：盤根錯節、千頭萬緒。" },
  { id: "i885", grade: 7, term: "變本加厲", zhuyin: "ㄅㄧㄢˋ ㄅㄣˇ ㄐㄧㄚ ㄌㄧˋ", pinyin: "biàn běn jiā lì", meaning: "比原來更加嚴重、更加過分。", example: "勸了他好幾次，他反而變本加厲，越鬧越兇。", wordExp: "變本＝改變原樣；加厲＝更加猛烈。比本來更厲害。", deep: "典故由來：出自蕭統〈文選序〉：「蓋踵其事而增華，變其本而加厲。」原指後代文章比前代更華美，是中性義，後轉為貶義。\n字面意思：改變本來的樣子，更加激烈。\n引申意思：（多指壞行為）愈演愈烈（如：警告無效，噪音變本加厲）。貶義；注意「厲」不寫作「利」。" },
  { id: "i886", grade: 7, term: "有恃無恐", zhuyin: "ㄧㄡˇ ㄕˋ ㄨˊ ㄎㄨㄥˇ", pinyin: "yǒu shì wú kǒng", meaning: "因為有依靠而毫無顧忌、什麼都不怕。", example: "他仗著家裡有錢有勢，有恃無恐地欺負人。", wordExp: "恃＝依靠；恐＝害怕。有靠山所以不怕。", deep: "典故由來：出自《左傳．僖公二十六年》：齊侯攻魯，展喜犒師，齊侯問「魯人恐乎？」對曰「小人恐矣，君子則否」，因為魯國「恃先王之命」——有先王盟約可倚仗。\n字面意思：有所倚仗，無所畏懼。\n引申意思：仗著有後台或條件而肆無忌憚（如：有恃無恐地一再違規）。今多貶義。" },
  { id: "i887", grade: 7, term: "為所欲為", zhuyin: "ㄨㄟˊ ㄙㄨㄛˇ ㄩˋ ㄨㄟˊ", pinyin: "wéi suǒ yù wéi", meaning: "想做什麼就做什麼，任意妄為。", example: "規則之前人人平等，誰也不能為所欲為。", wordExp: "為＝做；所欲＝想要的。想怎麼做就怎麼做。", deep: "典故由來：語本《資治通鑑》：司馬光評豫讓「乃欲為所欲為，顧不易邪」；後多用於放縱行事。\n字面意思：做自己想做的一切。\n引申意思：不受約束、任意胡為（如：仗勢為所欲為，終會受到制裁）。貶義。" },
  { id: "i888", grade: 7, term: "橫行霸道", zhuyin: "ㄏㄥˊ ㄒㄧㄥˊ ㄅㄚˋ ㄉㄠˋ", pinyin: "héng xíng bà dào", meaning: "仗勢蠻橫作惡，不講道理。", example: "惡霸在鄉里橫行霸道，終於被繩之以法。", wordExp: "橫行＝不循正道亂走；霸道＝蠻橫不講理。像螃蟹橫著走還稱王稱霸。", deep: "典故由來：出自《紅樓夢》第九回：「一任薛蟠橫行霸道，他不但不去管約，反助著他。」\n字面意思：橫著走路、霸占道路。\n引申意思：倚仗權勢胡作非為（如：不容惡勢力橫行霸道）。貶義；「橫」讀ㄏㄥˊ。" },
  { id: "i889", grade: 7, term: "一丘之貉", zhuyin: "ㄧ ㄑㄧㄡ ㄓ ㄏㄜˊ", pinyin: "yī qiū zhī hé", meaning: "同一個山丘上的貉，比喻彼此同樣低劣、沒有差別。", example: "這兩個騙子一丘之貉，都不是好東西。", wordExp: "一丘＝同一座小山；貉＝一種像狐狸的野獸。同一窩的野獸。", deep: "典故由來：出自《漢書．楊惲傳》：楊惲議論古今昏君「古與今如一丘之貉」，因言獲罪。\n字面意思：同一座山丘上的貉。\n引申意思：譏諷對方是同一類的壞人（如：官商勾結，一丘之貉）。貶義；「貉」讀ㄏㄜˊ，易誤讀。" },
  { id: "i890", grade: 7, term: "腹背受敵", zhuyin: "ㄈㄨˋ ㄅㄟˋ ㄕㄡˋ ㄉㄧˊ", pinyin: "fù bèi shòu dí", meaning: "前面後面同時受到敵人攻擊。", example: "球隊內訌又逢強敵，簡直腹背受敵。", wordExp: "腹＝前方；背＝後方；受敵＝遭受攻擊。前後都有敵人。", deep: "典故由來：出自《魏書．崔浩傳》：崔浩分析局勢說「裕西入函谷，則進退路窮，腹背受敵」。\n字面意思：肚腹和背後都受到攻擊。\n引申意思：同時面臨來自多方的壓力或攻擊（如：公司腹背受敵，內外交困）。近義：四面楚歌、進退維谷。" },
  { id: "i891", grade: 7, term: "騎虎難下", zhuyin: "ㄑㄧˊ ㄏㄨˇ ㄋㄢˊ ㄒㄧㄚˋ", pinyin: "qí hǔ nán xià", meaning: "騎上老虎背就難以下來，比喻事情做到一半，迫於形勢無法停止。", example: "活動已宣傳出去，如今騎虎難下，只能辦到底。", wordExp: "騎虎＝騎在虎背上；難下＝下不來。跳下來會被虎咬，只好硬著頭皮騎下去。", deep: "典故由來：語本《晉書．溫嶠傳》：「今之事勢，義無旋踵，騎猛獸安可中下哉！」蘇峻之亂中，溫嶠以騎猛獸勸眾人堅持討逆到底。\n字面意思：騎在老虎背上，難以下來。\n引申意思：迫於情勢只能繼續、無法中止（如：投資越陷越深，騎虎難下）。近義：進退兩難。" },
  { id: "i892", grade: 7, term: "束手無策", zhuyin: "ㄕㄨˋ ㄕㄡˇ ㄨˊ ㄘㄜˋ", pinyin: "shù shǒu wú cè", meaning: "雙手像被捆住一樣，一點辦法也沒有。", example: "面對突然當機的電腦，他束手無策。", wordExp: "束手＝綁住雙手；無策＝沒有對策。手被綁住又想不出辦法。", deep: "典故由來：宋代《宋史紀事本末》等已見「束手無策」，形容臨事無計可施。\n字面意思：捆住了手，拿不出計策。\n引申意思：毫無解決辦法（如：對這個難題大家都束手無策）。近義：一籌莫展、無計可施。" },
  { id: "i893", grade: 7, term: "一籌莫展", zhuyin: "ㄧ ㄔㄡˊ ㄇㄛˋ ㄓㄢˇ", pinyin: "yī chóu mò zhǎn", meaning: "一點計策也施展不出，毫無辦法。", example: "資金卡關，讓創業團隊一籌莫展。", wordExp: "籌＝計數的竹片，引申為計策；莫展＝無法施展。連一條計策都拿不出來。", deep: "典故由來：語本《宋史．蔡幼學傳》：「多士盈庭而一籌不吐。」滿朝人才卻提不出一條對策。\n字面意思：一根籌碼（一條計策）都施展不開。\n引申意思：面對困難毫無辦法（如：問題盤根錯節，令人一籌莫展）。「籌」是計策，不寫作「愁」。" },
  { id: "i894", grade: 7, term: "窮途末路", zhuyin: "ㄑㄩㄥˊ ㄊㄨˊ ㄇㄛˋ ㄌㄨˋ", pinyin: "qióng tú mò lù", meaning: "路走到了盡頭，形容陷入無路可走的絕境。", example: "詐騙集團被跨國追緝，已是窮途末路。", wordExp: "窮途＝走到盡頭的路；末路＝最後一段路。路已到頭、無處可去。", deep: "典故由來：「窮途」典出阮籍駕車獨行、路盡慟哭而返的故事（《晉書．阮籍傳》）；「末路」語出《戰國策》「行百里者半於九十，此言末路之難也」。\n字面意思：無路可走的最後關頭。\n引申意思：陷入絕境、瀕臨失敗（如：資金斷鏈，公司走到窮途末路）。近義：山窮水盡、日暮途窮。" },
  { id: "i895", grade: 7, term: "山窮水盡", zhuyin: "ㄕㄢ ㄑㄩㄥˊ ㄕㄨㄟˇ ㄐㄧㄣˋ", pinyin: "shān qióng shuǐ jìn", meaning: "山和水都到了盡頭，比喻陷入絕境。", example: "就在山窮水盡之際，一筆訂單救了這家小店。", wordExp: "山窮＝山到盡頭；水盡＝水到盡頭。山水都走到了盡頭。", deep: "典故由來：語本陸游〈遊山西村〉：「山重水複疑無路，柳暗花明又一村。」前句演為「山窮水盡」，與「柳暗花明」相對。\n字面意思：山到了盡頭，水也流到了盡頭。\n引申意思：處境艱難到極點、再無退路（如：即使山窮水盡也不放棄希望）。相對：柳暗花明、絕處逢生。" },
  { id: "i896", grade: 8, term: "苦口婆心", zhuyin: "ㄎㄨˇ ㄎㄡˇ ㄆㄛˊ ㄒㄧㄣ", pinyin: "kǔ kǒu pó xīn", meaning: "像老婆婆一樣慈愛、不厭其煩地懇切勸告。", example: "導師苦口婆心地勸他別放棄學業。", wordExp: "苦口＝不辭辛苦反覆地說；婆心＝老婆婆般的慈心。", deep: "典故由來：「苦口」語出《宋史．趙普傳》「忠言苦口」；「婆心」出自禪宗語錄「老婆心切」——老和尚像老婆婆一樣慈悲叮嚀。\n字面意思：說到口苦，懷著婆婆般的慈心。\n引申意思：懇切耐心地再三勸導（如：父母苦口婆心，全是為你好）。褒義。" },
  { id: "i897", grade: 8, term: "語重心長", zhuyin: "ㄩˇ ㄓㄨㄥˋ ㄒㄧㄣ ㄔㄤˊ", pinyin: "yǔ zhòng xīn cháng", meaning: "言辭懇切有分量，情意深長。", example: "校長語重心長地叮嚀畢業生莫忘初衷。", wordExp: "語重＝話說得懇切有分量；心長＝用心深遠。話重情深。", deep: "典故由來：清代小說《官場現形記》已見「語重心長」，形容長輩教誨。\n字面意思：言語鄭重，心意深長。\n引申意思：懇切而情深的囑咐（如：教練語重心長的一席話，讓他紅了眼眶）。褒義；多用於長輩對晚輩。" },
  { id: "i898", grade: 8, term: "千絲萬縷", zhuyin: "ㄑㄧㄢ ㄙ ㄨㄢˋ ㄌㄩˇ", pinyin: "qiān sī wàn lǚ", meaning: "千萬條絲線，形容關係緊密而複雜，難以理清。", example: "這兩家企業有千絲萬縷的關係。", wordExp: "千、萬＝極多；絲、縷＝細線。千萬條細線纏在一起。", deep: "典故由來：語本宋代戴石屏詞「愁似鰥魚知夜永，懶同蝴蝶為春忙，千絲萬縷織離腸」，原寫離愁如亂絲。\n字面意思：一千條絲、一萬條線。\n引申意思：彼此間關聯繁多複雜（如：文化與語言有千絲萬縷的聯繫）。" },
  { id: "i899", grade: 8, term: "千瘡百孔", zhuyin: "ㄑㄧㄢ ㄔㄨㄤ ㄅㄞˇ ㄎㄨㄥˇ", pinyin: "qiān chuāng bǎi kǒng", meaning: "到處是創傷和破洞，形容破壞嚴重或問題極多。", example: "老屋年久失修，千瘡百孔。", wordExp: "瘡＝創傷；孔＝破洞。上千處傷、上百個洞。", deep: "典故由來：語本唐代韓愈〈與孟尚書書〉：「漢室以來，群儒區區修補，百孔千瘡，隨亂隨失。」原形容儒學典籍殘缺。\n字面意思：千百個瘡口和孔洞。\n引申意思：破敗不堪或弊病叢生（如：制度千瘡百孔，亟待改革）。亦作「百孔千瘡」。" },
  { id: "i900", grade: 8, term: "遍體鱗傷", zhuyin: "ㄅㄧㄢˋ ㄊㄧˇ ㄌㄧㄣˊ ㄕㄤ", pinyin: "biàn tǐ lín shāng", meaning: "全身的傷痕像魚鱗一樣密，形容傷勢極重。", example: "流浪犬被救起時遍體鱗傷，令人不捨。", wordExp: "遍體＝全身；鱗傷＝像魚鱗一樣密的傷。滿身是傷。", deep: "典故由來：清代小說《醒世姻緣傳》等已見「遍體鱗傷」。\n字面意思：全身傷痕密如魚鱗。\n引申意思：受傷極重，也比喻心靈飽受創傷（如：官司纏身，公司信譽遍體鱗傷）。" },
  { id: "i901", grade: 8, term: "一敗塗地", zhuyin: "ㄧ ㄅㄞˋ ㄊㄨˊ ㄉㄧˋ", pinyin: "yī bài tú dì", meaning: "一旦失敗就肝腦塗地，形容敗得非常慘。", example: "輕敵的結果，就是這場比賽一敗塗地。", wordExp: "一敗＝一旦失敗；塗地＝（肝腦）塗在地上。敗得極慘。", deep: "典故由來：出自《史記．高祖本紀》：劉邦推辭沛令之位說「天下方擾，諸侯並起，今置將不善，壹敗塗地」——一旦用錯將領，就會肝腦塗地。\n字面意思：一旦戰敗，肝腦塗滿大地。\n引申意思：徹底失敗、不可收拾（如：投資失利，一敗塗地）。近義：潰不成軍、全軍覆沒。" },
  { id: "i902", grade: 8, term: "潰不成軍", zhuyin: "ㄎㄨㄟˋ ㄅㄨˋ ㄔㄥˊ ㄐㄩㄣ", pinyin: "kuì bù chéng jūn", meaning: "部隊潰散得不成隊伍，形容慘敗。", example: "下半場對手連進三球，我隊潰不成軍。", wordExp: "潰＝潰散；不成軍＝編制隊形全散了。兵敗如山倒。", deep: "典故由來：近代軍事用語演成的成語，「潰」指堤防崩決，借喻軍隊崩散。\n字面意思：潰散得不成一支軍隊。\n引申意思：被打得徹底崩潰（如：雜牌隊伍一觸即潰，潰不成軍）。近義：一敗塗地、丟盔棄甲。" },
  { id: "i903", grade: 8, term: "出奇制勝", zhuyin: "ㄔㄨ ㄑㄧˊ ㄓˋ ㄕㄥˋ", pinyin: "chū qí zhì shèng", meaning: "用出人意料的奇招取得勝利。", example: "教練變陣出奇制勝，逆轉了比賽。", wordExp: "出奇＝使出奇兵奇計；制勝＝取得勝利。用奇招贏。", deep: "典故由來：語本《孫子兵法．勢篇》：「凡戰者，以正合，以奇勝。」以正兵交鋒、以奇兵取勝。\n字面意思：出動奇兵，制伏敵人取勝。\n引申意思：以出人意料的方法致勝（如：行銷手法出奇制勝）。「制」不寫作「致」。" },
  { id: "i904", grade: 8, term: "聲東擊西", zhuyin: "ㄕㄥ ㄉㄨㄥ ㄐㄧˊ ㄒㄧ", pinyin: "shēng dōng jí xī", meaning: "故意放出攻東的風聲，實際攻打西邊。", example: "警方聲東擊西，讓歹徒誤判了包圍方向。", wordExp: "聲＝放出聲勢；擊＝攻擊。喊著打東邊，真正打西邊。", deep: "典故由來：語本《淮南子．兵略訓》：「故用兵之道，示之以柔而迎之以剛……將欲西而示之以東。」為三十六計之一。\n字面意思：製造攻東的聲勢，實際襲擊西方。\n引申意思：用假動作迷惑對方、攻其不備（如：球場上聲東擊西的假傳真射）。" },
  { id: "i905", grade: 8, term: "調虎離山", zhuyin: "ㄉㄧㄠˋ ㄏㄨˇ ㄌㄧˊ ㄕㄢ", pinyin: "diào hǔ lí shān", meaning: "設法引老虎離開山頭，比喻誘使對方離開有利位置再下手。", example: "歹徒調虎離山，把警衛引開後潛入倉庫。", wordExp: "調＝調動引誘；虎＝強敵；離山＝離開根據地。把老虎騙離牠的山。", deep: "典故由來：三十六計之一；《西遊記》第五十三回即有「我是個調虎離山計，哄你出來爭戰」的用法。\n字面意思：引誘老虎離開牠盤踞的山。\n引申意思：用計支開對方，趁虛而入（如：小心對手調虎離山）。「調」讀ㄉㄧㄠˋ。" },
  { id: "i906", grade: 8, term: "瞞天過海", zhuyin: "ㄇㄢˊ ㄊㄧㄢ ㄍㄨㄛˋ ㄏㄞˇ", pinyin: "mán tiān guò hǎi", meaning: "把天都瞞住去渡海，比喻用偽裝手段掩人耳目。", example: "走私集團瞞天過海，把貨藏在貨櫃夾層。", wordExp: "瞞天＝連天都欺瞞；過海＝渡過大海。瞞著所有人做大事。", deep: "典故由來：三十六計第一計。相傳唐太宗率軍至海邊不敢渡海，薛仁貴設計請他進入「海上人家」宴飲，實則屋在船上，不知不覺已航行過海。\n字面意思：瞞住上天，偷渡大海。\n引申意思：用巧妙偽裝掩蓋真實行動（如：假帳做得再好，也難瞞天過海）。貶義居多。" },
  { id: "i907", grade: 8, term: "移花接木", zhuyin: "ㄧˊ ㄏㄨㄚ ㄐㄧㄝ ㄇㄨˋ", pinyin: "yí huā jiē mù", meaning: "把花木嫁接到別的樹上，比喻暗中掉包、偷換人事物。", example: "這張照片是移花接木合成的假圖。", wordExp: "移花＝移植花枝；接木＝嫁接到別的樹。偷偷換掉本體。", deep: "典故由來：源自園藝的嫁接技術，明清小說借為偷換之計，《紅樓夢》中即有此語。\n字面意思：把花枝接到別的樹木上。\n引申意思：暗中以假換真、張冠李戴（如：合約被移花接木動了手腳）。近義：偷天換日、偷梁換柱。" },
  { id: "i908", grade: 8, term: "順手牽羊", zhuyin: "ㄕㄨㄣˋ ㄕㄡˇ ㄑㄧㄢ ㄧㄤˊ", pinyin: "shùn shǒu qiān yáng", meaning: "順手把人家的羊牽走，比喻趁機拿走別人的東西。", example: "他逛賣場順手牽羊，被監視器拍個正著。", wordExp: "順手＝順著手勢、順便；牽羊＝把羊牽走。路過順便偷走。", deep: "典故由來：語本《禮記．曲禮》「效馬效羊者右牽之」；三十六計收「順手牽羊」，指乘隙取利。\n字面意思：順著手就把羊牽走了。\n引申意思：趁人不備順勢偷竊，或乘機獲取利益（如：小偷順手牽羊偷了皮夾）。貶義。" },
  { id: "i909", grade: 8, term: "渾水摸魚", zhuyin: "ㄏㄨㄣˊ ㄕㄨㄟˇ ㄇㄛ ㄩˊ", pinyin: "hún shuǐ mō yú", meaning: "把水攪渾趁機摸魚，比喻趁混亂謀取利益。", example: "有人趁促銷人潮渾水摸魚，偷拿商品。", wordExp: "渾水＝混濁的水；摸魚＝趁魚看不清時抓魚。攪亂局面好下手。", deep: "典故由來：三十六計之一「混水摸魚」：把水攪濁，魚昏頭轉向，乘機捕捉；用兵則趁敵方混亂奪取勝利。\n字面意思：在攪渾的水中摸魚。\n引申意思：趁混亂占便宜（如：災後謹防有人渾水摸魚哄抬物價）；今口語也指上班偷懶「摸魚」。" },
  { id: "i910", grade: 8, term: "趁火打劫", zhuyin: "ㄔㄣˋ ㄏㄨㄛˇ ㄉㄚˇ ㄐㄧㄝˊ", pinyin: "chèn huǒ dǎ jié", meaning: "趁人家失火時搶劫，比喻趁人危難時撈取利益。", example: "地震後哄抬建材價格，無異趁火打劫。", wordExp: "趁火＝趁著失火混亂；打劫＝搶奪財物。人家遭災反去搶。", deep: "典故由來：三十六計之一，語本《孫子兵法》「亂而取之」的思想——敵方有難，正可乘機進取；民間借指乘人之危。\n字面意思：趁失火之亂搶劫財物。\n引申意思：乘人之危牟利（如：趁缺貨趁火打劫抬價）。貶義；近義：落井下石、雪上加霜。" },
  { id: "i911", grade: 8, term: "落井下石", zhuyin: "ㄌㄨㄛˋ ㄐㄧㄥˇ ㄒㄧㄚˋ ㄕˊ", pinyin: "luò jǐng xià shí", meaning: "人掉進井裡還往下丟石頭，比喻趁人危難時加以陷害。", example: "他失勢時牆倒眾人推，還有人落井下石。", wordExp: "落井＝掉進井中；下石＝往井裡扔石頭。不救人反害人。", deep: "典故由來：語本韓愈〈柳子厚墓誌銘〉：有些人平日稱兄道弟，一旦朋友落難，「落陷阱，不一引手救，反擠之，又下石焉者，皆是也」。\n字面意思：見人落井，反而投石。\n引申意思：乘人之危、加害於困境中的人（如：批評可以，但別落井下石）。貶義；相對：雪中送炭。" },
  { id: "i912", grade: 8, term: "引狼入室", zhuyin: "ㄧㄣˇ ㄌㄤˊ ㄖㄨˋ ㄕˋ", pinyin: "yǐn láng rù shì", meaning: "把狼引進屋裡，比喻自己招來壞人，禍害自身。", example: "隨意讓陌生人遠端連線電腦，等於引狼入室。", wordExp: "引＝招引；狼＝惡人；入室＝進到屋內。親手把禍害請進門。", deep: "典故由來：出自元代張國賓《羅李郎》：「我不是引的狼來屋裡窩，尋的蚰蜒鑽耳朵。」\n字面意思：把狼引進自己屋裡。\n引申意思：引進壞人或危險，自招禍患（如：誤信詐騙連結，引狼入室）。近義：開門揖盜、養虎遺患。" },
  { id: "i913", grade: 8, term: "監守自盜", zhuyin: "ㄐㄧㄢ ㄕㄡˇ ㄗˋ ㄉㄠˋ", pinyin: "jiān shǒu zì dào", meaning: "負責看守的人自己偷竊所保管的財物。", example: "出納監守自盜挪用公款，遭到起訴。", wordExp: "監守＝負責看管；自盜＝自己偷。看倉庫的偷倉庫。", deep: "典故由來：《漢書．刑法志》已有「守縣官財物而即盜之」加重治罪的規定，唐律稱「監臨主守自盜」，簡作「監守自盜」。\n字面意思：擔任看守，卻自己偷竊。\n引申意思：利用職務之便侵占經管的財物（如：保全監守自盜，形同家賊）。法律與道德的雙重譴責。" },
  { id: "i914", grade: 8, term: "大公無私", zhuyin: "ㄉㄚˋ ㄍㄨㄥ ㄨˊ ㄙ", pinyin: "dà gōng wú sī", meaning: "一切為公，毫無私心。", example: "包青天辦案大公無私，不畏權貴。", wordExp: "大公＝完全為公；無私＝沒有私心。公正到毫無私念。", deep: "典故由來：語本《漢書．賈誼傳》「為人主計者，莫如先審取舍」顏師古注引「至公無私」；春秋祁黃羊「外舉不避仇，內舉不避子」是著名例證。\n字面意思：極其公正，沒有私心。\n引申意思：處事公正、不偏私（如：裁判大公無私，雙方都服氣）。褒義；相對：假公濟私、徇私舞弊。" },
  { id: "i915", grade: 8, term: "中飽私囊", zhuyin: "ㄓㄨㄥ ㄅㄠˇ ㄙ ㄋㄤˊ", pinyin: "zhōng bǎo sī náng", meaning: "經手財物時暗中侵吞，塞滿自己的口袋。", example: "採購主管中飽私囊，虛報了大筆價差。", wordExp: "中飽＝中間經手的人先吃飽；私囊＝自己的口袋。", deep: "典故由來：出自《韓非子．外儲說右下》：簡主問稅吏輕重，薄疑答「府庫空虛於上，百姓貧餓於下，然而姦吏富矣」——上頭空、下面窮，錢都被中間的人吞了，謂之「中飽」。\n字面意思：中間人吃飽，塞滿私人口袋。\n引申意思：利用經手之便侵吞公款（如：善款豈容中飽私囊）。貶義。" },
  { id: "i916", grade: 8, term: "節衣縮食", zhuyin: "ㄐㄧㄝˊ ㄧ ㄙㄨㄛ ㄕˊ", pinyin: "jié yī suō shí", meaning: "省吃省穿，極力節約。", example: "母親節衣縮食，供三個孩子讀完大學。", wordExp: "節衣＝節省穿的；縮食＝減少吃的。衣食都省到最低。", deep: "典故由來：語本《史記．貨殖列傳》：「能薄飲食，忍嗜欲，節衣服。」白圭治生產以刻苦自持。\n字面意思：節省衣著、縮減飲食。\n引申意思：生活極度儉省（如：為了買房，小倆口節衣縮食）。褒義居多；近義：省吃儉用。" },
  { id: "i917", grade: 8, term: "粗茶淡飯", zhuyin: "ㄘㄨ ㄔㄚˊ ㄉㄢˋ ㄈㄢˋ", pinyin: "cū chá dàn fàn", meaning: "粗劣的茶、清淡的飯，形容簡樸的生活。", example: "退休後粗茶淡飯，日子過得清閒自在。", wordExp: "粗茶＝粗劣的茶；淡飯＝簡單的飯菜。最簡單的飲食。", deep: "典故由來：出自宋代黃庭堅〈四休導士詩序〉：「粗茶淡飯飽即休，補破遮寒暖即休。」四休居士的知足格言。\n字面意思：粗糙的茶水、清淡的飯食。\n引申意思：簡樸清貧的生活（如：他甘於粗茶淡飯，把積蓄捐作公益）。相對：山珍海味、錦衣玉食。" },
  { id: "i918", grade: 8, term: "山珍海味", zhuyin: "ㄕㄢ ㄓㄣ ㄏㄞˇ ㄨㄟˋ", pinyin: "shān zhēn hǎi wèi", meaning: "山裡海裡的珍貴食材，指豐盛名貴的菜餚。", example: "滿桌山珍海味，卻不及媽媽的家常菜。", wordExp: "山珍＝山產珍品；海味＝海產美味。山海的珍奇美食。", deep: "典故由來：語本唐代韋應物詩「山珍海錯棄藩籬」，「海錯」即海產眾多，後演為「山珍海味」。\n字面意思：山中珍品、海中美味。\n引申意思：極豐盛珍貴的酒席佳餚（如：宴會上山珍海味樣樣不缺）。相對：粗茶淡飯。" },
  { id: "i919", grade: 8, term: "錦衣玉食", zhuyin: "ㄐㄧㄣˇ ㄧ ㄩˋ ㄕˊ", pinyin: "jǐn yī yù shí", meaning: "穿錦繡衣裳、吃珍美食物，形容奢華的生活。", example: "他生於豪門，自幼錦衣玉食。", wordExp: "錦衣＝華美的衣服；玉食＝珍美如玉的食物。穿好吃好。", deep: "典故由來：出自《魏書．常景傳》：「錦衣玉食，可頤其形。」\n字面意思：穿錦繡的衣、吃如玉的食。\n引申意思：生活豪奢富貴（如：錦衣玉食的日子未必快樂）。中性偏貶；相對：粗茶淡飯、節衣縮食。" },
  { id: "i920", grade: 8, term: "左右為難", zhuyin: "ㄗㄨㄛˇ ㄧㄡˋ ㄨㄟˊ ㄋㄢˊ", pinyin: "zuǒ yòu wéi nán", meaning: "偏向哪一邊都不好辦，處境尷尬難以抉擇。", example: "母親和妻子同時要他表態，讓他左右為難。", wordExp: "左右＝兩邊；為難＝難以應付。往左往右都是難題。", deep: "典故由來：元雜劇《蝴蝶夢》已見「左右為難」，形容兩頭不討好的處境。\n字面意思：向左向右都感到為難。\n引申意思：夾在中間難以取捨（如：兩位好友吵架都找他評理，令他左右為難）。近義：進退兩難、動輒得咎。" }
];
